  return *l.lower_bound(c);
}
char getSmaller(char c) {
  if (l.upper_bound(c) == l.begin()) return 'z' + 5;
  return *(--l.upper_bound(c));
}
bool isOk(char c) { return c != 'z' + 5; }
bool tryLow() {
