      if (!ga && isOk(getLarger(c + 1)) && a[i] < getLarger(c + 1) &&
          (sb || getLarger(c + 1) < b[i]))
        c = getLarger(c + 1);
      if (!isOk(c)) return false;
      p[s[i]] = c;
      l.erase(c);
