#include <bits/stdc++.h>
using namespace std;
int t;
int n, k;
char s[1000111];
char a[1000111];
char b[1000111];
bool mapped[31];
int mapping[31];
int coremap[31];
bool coremapped[31];
void backUp() {
  int i;
  for (i = 0; i <= 26; i++) {
    coremap[i] = mapping[i];
    coremapped[i] = mapped[i];
  }
}
void restore() {
  int i;
  for (i = 0; i <= 26; i++) {
    mapping[i] = coremap[i];
    mapped[i] = coremapped[i];
  }
}
void fillTemplate() {
  int i, j;
  for (i = 0; i < k; i++) {
    if (mapping[i] == -1) {
      for (j = 0; j < k; j++) {
        if (!mapped[j]) {
          mapped[j] = true;
          mapping[i] = j;
          break;
        }
      }
    }
  }
  return;
}
bool verifyTemplate() {
  bool larger = false, smaller = false;
  int i;
  for (i = 1; i <= n; i++) {
    int real = mapping[s[i] - 'a'];
    if (!larger) {
      if (real > a[i] - 'a')
        larger = true;
      else if (real < a[i] - 'a')
        return false;
    }
    if (!smaller) {
      if (real < b[i] - 'a')
        smaller = true;
      else if (real > b[i] - 'a')
        return false;
    }
  }
  return true;
}
bool smallTemplate(int ind) {
  int i, j;
  for (i = ind; i <= n; i++) {
    if (mapping[s[i] - 'a'] == -1) {
      for (j = 0; j < k; j++) {
        if (!mapped[j]) {
          mapping[s[i] - 'a'] = j;
          mapped[j] = true;
          break;
        }
      }
    }
  }
  fillTemplate();
  return verifyTemplate();
}
bool largeTemplate(int ind) {
  int i, j;
  for (i = ind; i <= n; i++) {
    if (mapping[s[i] - 'a'] == -1) {
      for (j = k - 1; j >= 0; j--) {
        if (!mapped[j]) {
          mapped[j] = true;
          mapping[s[i] - 'a'] = j;
          break;
        }
      }
    }
  }
  fillTemplate();
  return verifyTemplate();
}
