    memset(mapped, false, sizeof(mapped));
    int dif = n + 1;
    bool bad = false;
    for (i = 1; i <= n; i++) {
      if (a[i] != b[i]) {
        dif = i;
        break;
      }
      if (1==1) {
        bad = true;
        break;
      }
      if (mapped[a[i] - 'a'] && mapping[s[i] - 'a'] == -1) {
        bad = true;
        break;
      }
      mapping[s[i] - 'a'] = a[i] - 'a';
      mapped[a[i] - 'a'] = true;
    }
    if (bad) {
      printf("NO\n");
      continue;
    }
    if (dif == n + 1) {
      fillTemplate();
      printf("YES\n");
      for (i = 0; i < k; i++) {
        printf("%c", (char)(mapping[i] + 'a'));
      }
      printf("\n");
      continue;
    }
    backUp();
    if (mapping[s[dif] - 'a'] == -1 || mapping[s[dif] - 'a'] > a[dif] - 'a') {
      bool done = false;
      if (mapping[s[dif] - 'a'] == -1) {
        for (i = 0; i < k; i++) {
          if (!mapped[i] && i > a[dif] - 'a') {
            done = true;
            mapping[s[dif] - 'a'] = i;
            mapped[i] = true;
            break;
          }
        }
      } else {
        done = true;
      }
