    int ptr = 0;
    for (int j = 0; j < k; ++j) {
      while (ptr < k && used[ptr]) {
        ++ptr;
      }
      if (ans[j] == 0) {
        ans[j] = ptr + 'a';
        ++ptr;
      }
    }
