      ptr = 0;
      while (ptr < k && used[ptr]) {
        ++ptr;
      }
      res = ptr + 'a';
      used[ptr] = true;
      tmp[s[i] - 'a'] = res;
    }
    if (res < b[i]) {
      solve(i + 1, true, true);
    } else if (res == b[i]) {
      solve(i + 1, true, false);
    }
    if (ptr != -1) {
      used[ptr] = false;
      tmp[s[i] - 'a'] = 0;
    }
  } else if (less) {
    char res = tmp[s[i] - 'a'];
    int ptr = k;
