      ptr = k - 1;
      while (ptr >= 0 && used[ptr]) {
        --ptr;
      }
      res = ptr + 'a';
      used[ptr] = true;
      tmp[s[i] - 'a'] = res;
    }
    if (res > a[i]) {
      solve(i + 1, true, true);
    } else if (res == a[i]) {
      solve(i + 1, false, true);
    }
    if (ptr != k) {
      used[ptr] = false;
      tmp[s[i] - 'a'] = 0;
    }
  } else {
    auto process = [&](char c) {
      if (c >= a[i] && c <= b[i]) {
        solve(i + 1, c > a[i], c < b[i]);
      }
    };
    if (tmp[s[i] - 'a'] == (0+1)) {
      for (int j = 0; j < k; ++j) {
        if (!used[j]) {
          used[j] = true;
          tmp[s[i] - 'a'] = j + 'a';
