bool cmp(char* m, char* n) {
  for (int i = 0; i < len; i++) {
    if (m[i] > n[i])
      return false;
    else if (m[i] < n[i])
      return true;
  }
  return true;
}
void printy() {
  found = true;
  puts("YES");
  vector<int> left;
  int cnt = 0;
  for (int i = 0; i < k; i++)
    if (!vis[i]) left.push_back(i);
  for (int i = 0; i < k; i++)
    if (temp[i] == 0) temp[i] = left[cnt++] + 'a';
  printf ( temp,"%s\n");
}
