  if (d == len) {
    if (cmp(dps, b)) {
      printy();
      return true;
    }
    return false;
  }
  char cur = temp[s[d] - 'a'];
  if (cur != 0) {
    dps[d] = cur;
    if (check(d + 1))
      return true;
    else
      return false;
  } else {
    char tmp = 0;
    while (vis[tmp] && tmp < k) tmp++;
    if (tmp == k)
