    else {
      dps[d] = tmp + 'a';
      temp[s[d] - 'a'] = tmp + 'a';
      vis[tmp] = 1;
      bool res = check(d + 1);
      temp[s[d] - 'a'] = 0;
      vis[tmp] = 0;
      return res;
    }
  }
}
void dp(int d) {
  if (found) return;
  if (d == len) {
    if (cmp(dps, b)) {
      printy();
      found = true;
    }
    return;
  }
