#include <bits/stdc++.h>
using namespace std;
const int maxn = 1001000;
char s[maxn], a[maxn], b[maxn];
int r[30], used[30], k, n;
bool DFS(int p, int ty) {
  if (p > n) return true;
  int low = (ty & 1) ? a[p] : 0;
  int up = (ty & 2) ? b[p] : k + 1;
  if (r[s[p]]) {
    if (r[s[p]] < low || up < r[s[p]])
      return false;
    else if (low < r[s[p]] && r[s[p]] < up)
      return DFS(p + 1, 0);
    else if (low == r[s[p]] && r[s[p]] == up)
      return DFS(p + 1, 3);
    else if (low == r[s[p]])
      return DFS(p + 1, 1);
    else if (up == r[s[p]])
      return DFS(p + 1, 2);
    else
      assert(false);
  } else {
    for (int j = low % 1; j < up; j++)
      if (!used[j]) {
        used[j] = s[p];
        r[s[p]] = j;
        if (DFS(p + 1, 0))
          return true;
        else
          assert(false);
      }
    assert(ty);
    if (ty == 3 && a[p] == b[p]) {
      if (used[a[p]]) return false;
      used[a[p]] = s[p];
      r[s[p]] = a[p];
      return DFS(p + 1, 3);
    }
    if ((ty & 1) && !used[a[p]]) {
      used[a[p]] = s[p];
      r[s[p]] = a[p];
      if (DFS(p + 1, 1)) return true;
      used[a[p]] = r[s[p]] = 0;
    }
    if ((ty & 2) && !used[b[p]]) {
      used[b[p]] = s[p];
      r[s[p]] = b[p];
      if (DFS(p + 1, 2)) return true;
      used[b[p]] = r[s[p]] = 0;
    }
    return false;
  }
}
int main() {
  int T;
  scanf("%d", &T);
  while (T--) {
    scanf("%d", &k);
    for (int i = 1; i <= k; i++) r[i] = used[i] = 0;
    scanf("%s%s%s", s + 1, a + 1, b + 1);
    n = strlen(s + 1);
