struct Rep {
  char link[26];
  bool vis[26];
  Rep() {
    memset(link, 255, sizeof(link));
    memset(vis, 0, sizeof(vis));
  }
  bool check(char x, char y) {
    return (link[x] == y) || (link[x] == -1 && !vis[y]);
  }
  void add(char x, char y) {
    link[x] = y;
    vis[y] = 1;
  }
  void output(int k) {
    int cnt = 0;
    for (int i = 0; i < k; i++)
      if (link[i] == -1) {
        while (vis[cnt]) cnt++;
        vis[cnt] = 1;
        link[i] = cnt;
      }
