        ok = 0;
        break;
      }
      now.add(s3[i], s1[i]);
    }
    if (ok) {
      now.output(k);
      return 1;
    }
  }
  if (fir.check(s3[d], s2[d])) {
    Rep now = fir;
    now.add(s3[d], s2[d]);
