  for (int i = diffPos + 1; i < n; i++) {
    int cs = s[i] - 'a';
    int ca = a[i] - 'a';
    if (out[cs] != -1) {
      if (out[cs] > ca) {
        cout << "YES\n";
        build();
        return true;
      }
      if (out[cs] < ca) {
        return false;
      }
    } else {
      for (int ta = ca + 1; ta < k; ta++) {
        if (in[ta] == -1) {
          in[ta] = cs;
          out[cs] = ta;
          cout << "YES\n";
          build();
          return true;
        }
      }
      if (in[ca] != -1) return false;
      in[ca] = cs;
      out[cs] = ca;
    }
  }
  cout << "YES\n";
  build();
  return true;
}
bool solveLess() {
  for (int i = diffPos + 1; i < n; i++) {
    int cs = s[i] - 'a';
    int cb = b[i] - 'a';
    if (out[cs] != -1) {
      if (out[cs] < cb) {
        cout << "YES\n";
        build();
        return true;
      }
      if (out[cs] > cb) return false;
    } else {
      for (int tb = cb - 1; tb >= 0; tb--) {
        if (in[tb] == -1) {
          in[tb] = cs;
          out[cs] = tb;
          cout << "YES\n";
          build();
          return true;
        }
      }
      if (in[cb] != -1) return false;
      in[cb] = cs;
      out[cs] = cb;
    }
  }
