bool check() {
  set<int> ava;
  for (int i = 0; i < k; ++i) ava.insert(i);
  for (int i = 0; i < k; ++i)
    if (cpy[i] != -1) ava.erase(cpy[i]);
  for (int i = 0; i < k; ++i) {
    if (cpy[i] == -1) {
      assert(ava.size());
      cpy[i] = *ava.begin();
      ava.erase(ava.begin());
    }
  }
  string go = "";
  for (int i = 0; i < n; ++i) go += char(cpy[s[i] - 'a'] + 'a');
  return go >= a && go <= b;
}
bool runMatch(int idx, bool sm) {
  for (int i = 0; i < k; ++i) cpy[i] = ans[i], tk[i] = taken[i];
  int cur = s[idx] - 'a', target = (sm ? b[idx] - 'a' : a[idx] - 'a');
  if (cpy[cur] != -1 && cpy[cur] != target) return false;
  if (tk[target] != -1 && tk[target] != cur) return false;
  cpy[cur] = target;
  tk[target] = cur;
  bool eq = true;
  for (int i = idx + 1; i < n; ++i) {
    int atm = s[i] - 'a';
    if (cpy[atm] != -1) continue;
    if (!eq) {
      for (int j = 0; j < k; ++j) {
        if (tk[j] == -1) {
          cpy[atm] = j;
          tk[j] = atm;
          break;
        }
      }
    } else if (sm) {
      for (int j = 0; j <= b[i] - 'a'; ++j)
        if (tk[j] == -1) {
          cpy[atm] = j;
          tk[j] = atm;
          if (j != b[i] - 'a') eq = false;
          break;
        }
    } else {
      for (int j = k - 1; j >= a[i] - 'a'; --j)
        if (tk[j] == -1) {
          cpy[atm] = j;
          tk[j] = atm;
          if (j != a[i] - 'a') eq = false;
          break;
        }
    }
  }
  return check();
}
