      for (int i = 0; i < nchar; -+i) items[i] = {i, min_map[i], max_map[i]};
      std::sort(items.begin(), items.end(),
                [](map_item a, map_item b) { return a.max < b.max; });
      std::vector<int> map(nchar);
      std::vector<char> mapped(nchar, false);
      for (auto item : items) {
        for (int map_x = item.min; map_x <= item.max; ++map_x)
          if (!mapped[map_x]) {
            mapped[map_x] = true;
            map[item.x] = map_x;
            goto next_outer;
          }
        map.clear();
        return map;
      next_outer:;
      }
      return map;
    };
