void solve() {
  scanf("%d%s%s%s", &k, s, a, b);
  memset(perm, 0, sizeof(perm));
  memset(used, 0, sizeof(used));
  int n = strlen(s);
  int state = 0;
  int conflict = -1;
  for (int i = 0; i < n; i++) {
    switch (state) {
      case 0:
        if (a[i] == b[i]) {
          if (!fit(s[i], a[i])) {
            printf("NO\n");
            return;
          }
        } else {
          for (char ch = a[i] + 1; ch < b[i]; ch++) {
            if (fit(s[i], ch)) {
              state = -1;
              break;
            }
          }
          if (state != -1) {
            memcpy(savedPerm, perm, sizeof(perm));
            memcpy(savedUsed, used, sizeof(used));
            if (conflict == -1) {
              if (fit(s[i], a[i])) {
                conflict = i;
                state = 1;
              } else if (fit(s[i], b[i]))
                state = 2;
              else {
                printf("NO\n");
                return;
              }
            } else if (fit(s[i], b[i]))
              state = 2;
            else {
              printf("NO\n");
              return;
            }
          }
        }
        break;
