        for (char ch = a[i] + 1; ch < 'a' + k; ch++) {
          if (fit(s[i], ch)) {
            state = -1;
            break;
          }
        }
        if (state != -1) {
          if (fit(s[i], a[i])) {
            state = 0;
            i = conflict - 1;
            memcpy(perm, savedPerm, sizeof(perm));
            memcpy(used, savedUsed, sizeof(used));
            break;
          }
        }
        break;
      case 2:
        for (char ch = 'a'; ch < b[i]; ch++) {
          if (fit(s[i], ch)) {
            state = -1;
            break;
          }
        }
        if (state != -1) {
          if (!fit(s[i], b[i])) {
            printf("NO\n");
            return;
          }
        }
        break;
    }
    if (state == -1) break;
  }
  fillUnused();
  printf("YES\n");
  for (int i = 'a'; i < 'a' + k; i++) printf("%c", perm[i]);
  printf("\n");
}
