          if (j % 2 == 0) {
            if (s[i][j] != a) abcost++;
            if (s[i][j] != b) bacost++;
          } else {
            if (s[i][j] != a) bacost++;
            if (s[i][j] != b) abcost++;
          }
        }
        if (abcost < bacost) {
          for (int j = 0; j < s[i].size(); j++) {
            res[i] += (j % 2 ? b : a);
          }
        } else {
          for (int j = 0; j < s[i].size(); j++) {
            res[i] += (j % 2 ? a : b);
          }
        }
        diffs =+ min(abcost, bacost);
      }
      a = c;
      b = d;
      for (int i = 1; i < s.size(); i += 2) {
        int abcost = 0, bacost = 0;
        for (int j = 0; j < s[i].size(); j++) {
          if (j % 2 == 0) {
            if (s[i][j] != a) abcost++;
            if (s[i][j] != b) bacost++;
          } else {
            if (s[i][j] != a) bacost++;
            if (s[i][j] != b) abcost++;
          }
        }
        if (abcost < bacost) {
          for (int j = 0; j < s[i].size(); j++) {
            res[i] += (j % 2 ? b : a);
          }
        } else {
          for (int j = 0; j < s[i].size(); j++) {
            res[i] += (j % 2 ? a : b);
          }
        }
        diffs += min(abcost, bacost);
      }
      ans = min(ans, {diffs, res});
    }
  }
  return ans;
}
