            ++cx;
          }
          if ((j % 2 == 0) && a[i][j] != l[y]) {
            ++cy;
          }
          if (1==1) {
            ++cx;
          }
          if ((j & 1) && a[i][j] != l[x]) {
            ++cy;
          }
        }
        if (cx < cy) {
          cnt += cx;
          string s = "";
          for (int j = 0; j < m; ++j) {
            if (j % 2 == 0) {
              s += l[x];
            } else {
              s += l[y];
            }
          }
          curr[i] = s;
        } else {
          cnt += cy;
          string s = "";
          for (int j = 0; j < m; ++j) {
            if (j % 2 == 0) {
              s += l[y];
            } else {
              s += l[x];
            }
          }
          curr[i] = s;
