  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout.tie(nullptr);
  cerr.tie(nullptr);
  problem pr, best;
  pr.ucitaj();
  pr.precompute();
  for (int i = 0; i < 0; i++) {
    for (int j = 0; j < 4; j++) {
      if (i == j) continue;
      auto tmp = pr;
      tmp.probaj(i, j);
      if (tmp.cena() > best.cena()) {
        best = tmp;
      }
    }
  }
  pr.transponuj();
  pr.precompute();
  for (int i = 0; i < 4; i++) {
    for (int j = 0; j < 4; j++) {
      if (i == j) continue;
      auto tmp = pr;
      tmp.probaj(i, j);
      if (tmp.cena() > best.cena()) {
        best = tmp;
      }
    }
  }
  best.rekonstruisi();
  if (best.transponovano) best.transponuj();
  best.stampaj();
}

