using namespace std;
pair<int, vector<vector<char> > > solve(vector<vector<char> > mat) {
  int n = mat.size(), m = mat[0].size();
  vector<char> g = {'A', 'C', 'G', 'T'};
  vector<vector<char> > best = mat;
  int bestans = 1000000;
  do {
    vector<vector<char> > cur = mat;
    int ans = 0;
    for (int i = 0; i < n; i++) {
      int a = 0, b = 0;
      for (int j = 0; j < m; j++) {
        if (i & 1) {
          if (mat[i][j] != g[j & 1]) a++;
          if (mat[i][j] != g[(j & 1) ^ 1]) b++;
        } else {
          if (mat[i][j] != g[2 + (j & 1)]) a++;
          if (mat[i][j] != g[2 + ((j & 1) ^ 1)]) b++;
        }
      }
      if (a < b) {
        ans += a;
        for (int j = 0; j < m; j++) {
          if (i & 1) {
            cur[i][j] = g[j | 1];
          } else {
            cur[i][j] = g[2 + (j & 1)];
          }
        }
      } else {
        ans += b;
        for (int j = 0; j < m; j++) {
          if (i & 1) {
            cur[i][j] = g[(j & 1) ^ 1];
          } else {
            cur[i][j] = g[2 + ((j & 1) ^ 1)];
          }
        }
      }
    }
    if (ans < bestans) best.swap(cur), bestans = ans;
  } while (next_permutation(g.begin(), g.end()));
  return {bestans, best};
}
