    int cnt = 0;
    for (int j = 0; j < m; j++) cnt += a[0][j] != p[k2][j & 1];
    f[0][k2] = cnt;
  }
  for (int i = 1; i < n; i++) {
    memset(f[i], 0x3f, sizeof(f[i]));
