          if (f[i][k2] > f[i - 1][k1] + cnt)
            f[i][k2] = f[i - 1][k1] + cnt, pre[i][k2] = k1;
        }
  }
  int mk = 0;
  for (int k2 = 0; k2 < 12; k2++)
    if (f[n - 1][k2] < f[n - 1][mk]) mk = k2;
  for (int i = n - 1, t = mk; i >= 0; t = pre[i][t], i--) {
    for (int j = 0; j < m; j++) c[i].push_back(p[t][j & 1]);
  }
  return f[n - 1][mk];
}
