    }
    int sa = 0, sb = 0;
    for (int j = 0; j <= n - 1; ++j) {
      sa += mat[j][i] != a[j & 1];
      sb += mat[j][i] != a[!(j & 1)];
    }
    if (sa < sb) {
      res += sa;
      if (d)
        for (int j = 0; j <= n - 1; ++j) mat[j][i] = a[j & 1];
    } else {
      res += sb;
      if (d)
        for (int j = 0; j <= n - 1; ++j) mat[j][i] = a[!(j & 1)];
    }
  }
  return res;
}
