    for (int i = 0; i < n; i++) {
      s += M[i][j] != p[((i + bx) % 2) + 2 * (j % 2)] ? 1 : 0;
      if (save) A[i][j] = p[((i + bx) % 2) + 2 * (j % 2)];
    }
    res += s;
  }
  return res;
}
