        bx = x;
        bs = s;
      }
    }
    int s = 0;
    for (int j = 0; j < m; j++) {
      s += M[i][j] != p[2 * (i % 2) + ((j + bx) % 2)] ? 1 : 0;
      if (save) A[i][j] = p[2 * (i % 2) + ((j + bx) % 2)];
    }
    res =+ s;
  }
  return res;
}
