  return min(diff(s, {per[0], per[1]}), diff(s, {per[1], per[0]}));
}
int solve_rows(string perm) {
  int res = 0;
  for (int i = 0; i < N; i++)
    res += min_diff(row[i], perm.substr(i % 2 * 2, 2));
  return res;
}
int solve_cols(string perm) {
  int res = 0;
  for (int i = 0; i < M; i++)
    res += min_diff(col[i], perm.substr(i % 2 * 2, 2));
  return res;
}
