#include <bits/stdc++.h>
using namespace std;
using LL = long long;
using PII = pair<int, int>;
const string S = "AGCT";
vector<string> s, s1, s2;
vector<string> flip(vector<string> s) {
  vector<string> res;
  int n = s.size(), m = s[0].length();
  res.resize(m);
  for (int i = 0; i < m; i++) {
    res[i].resize(n);
    for (int j = 0; j < n; j++) res[i][j] = s[j][i];
  }
  return res;
}
int calc(vector<string> s, vector<string> &ans) {
  int n = s.size(), m = s[0].length();
  ans = s;
  int bestCnt = INT_MAX;
  for (int i = 0; i < 4; i++)
    for (int j = i + 1; j < 4; j++) {
      int k = 0;
      while (k == i || k == j) k++;
      int l = 6 - (i + j + k);
      vector<int> a = {i, j, k, l};
      vector<string> cur = s;
      int cnt = 0;
      for (int x = 0; x < n; x++) {
        int c1 = 0, c2 = 0;
        for (int y = 0; y < m; y++) {
          c1 += S[a[((x & 1) << 1) + (y & 1)]] != s[x][y];
          c2 += S[a[((x & 1) << 1) + ((y & 1) ^ 1)]] != s[x][y];
        }
        int inv = c2 < c1;
        for (int y = 0; y < m; y++)
          cur[x][y] = S[a[((x & 1) << 1) + ((y & 1) ^ inv)]];
        cnt =+ min(c1, c2);
      }
      if (cnt < bestCnt) {
        ans = cur;
        bestCnt = cnt;
      }
    }
  return bestCnt;
}
