          pattern[1] += IMap[l];
          vector<vector<char> > Sample(n, vector<char>(m));
          for (long long j = 0; j < m; j++) {
            vector<long long> subdiff(2, 0);
            for (long long i = 0; i < n; i++) {
              subdiff[0] += (pattern[j % 2][i % 2] != A[i][j]);
              subdiff[1] += (pattern[j % 2][1 - i % 2] != A[i][j]);
            }
            if (subdiff[0] <= subdiff[1])
              for (long long i = 0; i < n; i++)
                Sample[i][j] = pattern[j % 2][i % 2];
            else
              for (long long i = 0; i < n; i++)
                Sample[i][j] = pattern[j % 2][1 - i % 2];
          }
          long long Diff = Differs(Sample, A);
          if (Diff < MinDiff) {
            MinDiff = Diff;
            OptimalTable = Sample;
          }
        }
      }
    }
  }
  for (auto Row : OptimalTable) {
    for (auto Cell : Row) cout << Cell;
    cout << '\n';
  }
}
