inline long long get(long long u, long long v) {
  long long i, j, p, q, res = 0;
  for (p = 0; p < 4; p++)
    if (p != u && p != v) break;
  for (q = p + 1; q < 4; q++)
    if (q != u && q != v) break;
  for (i = 0; i < n; i++) {
    A[i] = (i & 1) ? fz[p] : fz[q];
    B[i] = (i & 1) ? fz[q] : fz[p];
    C[i] = (i & 1) ? fz[u] : fz[v];
    D[i] = (i & 1) ? fz[v] : fz[u];
  }
  for (i = 0; i < m; i++) {
    long long c1, c2;
