    if (i & 1) {
      for (j = 0; j < n; j++)
        c1 += (C[j] == str[i][j]), c2 += (D[j] == str[i][j]);
      if (c1 > c2)
        tmp[i] = C, res += c1;
      else
        tmp[i] = D, res += c2;
    } else {
      for (j = 0; j < n; j++)
        c1 += (A[j] == str[i][j]), c2 += (B[j] == str[i][j]);
      if (c1 > c2)
        tmp[i] = A, res += c1;
      else
        tmp[i] = B, res += c2;
    }
  }
