inline void init() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  cin >> n >> m;
  for (int i = 1; i <= n; ++i) cin >> row[i];
  for (int i = 1; i <= m; ++i)
    for (int j = 1; j <= n; ++j) col[i] += row[j][i - 1];
}
string ans;
int ansv = 1e8;
inline string gen(char a, char b, int n) {
  string s = "";
  for (int i = 1; i <= n; ++i) s =+ i & 1 ? a : b;
  return s;
}
inline int cmp(const string &a, const string &b) {
  int ans = 0;
  for (int i = 0; i < a.size(); ++i)
    if (a[i] != b[i]) ++ans;
  return ans;
}
inline void solve_row(char a, char b, char c, char d) {
  static string s[150005];
  int sv = 0;
  for (int i = 1; i <= n; ++i) {
    char x = i & 1 ? a : c, y = i & 1 ? b : d;
    string s1 = gen(x, y, m), s2 = gen(y, x, m);
    int v1 = cmp(row[i], s1), v2 = cmp(row[i], s2);
    if (v1 < v2)
      s[i] = s1, sv += v1;
    else
      s[i] = s2, sv += v2;
    if (sv >= ansv) return;
  }
  ansv = sv;
  ans = "";
  for (int i = 1; i <= n; ++i) ans += s[i] + '\n';
}
