string i2c = "AGCT";
int col_cost(int n, int a, int b) {
  int cost = 0;
  for (int m = 0; m < M; ++m) {
    if (m % 2 == 0) {
      cost += (a != s[n][m]);
    } else {
      cost += (b != s[n][m]);
    }
  }
  return cost;
}
int row_cost(int m, int a, int b) {
  int cost = 0;
  for (int n = 0; n < N; ++n) {
    if (n % 2 == 0) {
      cost += (a != s[n][m]);
    } else {
      cost += (b != s[n][m]);
    }
  }
  return cost;
}
int main() {
  cin >> N >> M;
  string S[N];
  for (int i = 0; i < N; ++i) {
    cin >> S[i];
  }
  s.resize(N);
  for (int i = 0; i < N; ++i) {
    s[i].resize(M);
    for (int j = 0; j < M; ++j) {
      s[i][j] = c2i[S[i][j]];
    }
  }
  int mincost = N * M;
  int best[2];
  int a[2];
  for (a[1] = 0; a[0] < 4; ++a[0]) {
    for (a[1] = a[0] + 1; a[1] < 4; ++a[1]) {
      int b[2], j = 0;
      for (int i = 0; i < 4; ++i) {
        if (i != a[0] && i != a[1]) {
          b[j] = i;
          ++j;
        }
      }
      int cost = 0;
      for (int n = 0; n < N; ++n) {
        if (n % 2 == 0) {
          cost += min(col_cost(n, a[0], a[1]), col_cost(n, a[1], a[0]));
        } else {
          cost += min(col_cost(n, b[0], b[1]), col_cost(n, b[1], b[0]));
        }
      }
      if (cost < mincost) {
        memcpy(&best, &a, sizeof(best));
        mincost = cost;
      }
    }
  }
  bool row = false;
  for (a[0] = 0; a[0] < 4; ++a[0]) {
    for (a[1] = a[0] + 1; a[1] < 4; ++a[1]) {
      int b[2], j = 0;
