          cost += min(row_cost(m, a[0], a[1]), row_cost(m, a[1], a[0]));
        } else {
          cost += min(row_cost(m, b[0], b[1]), row_cost(m, b[1], b[0]));
        }
      }
      if (cost < mincost) {
        memcpy(&best, &a, sizeof(best));
        mincost = cost;
        row = true;
      }
    }
  }
