  clear();
  for (int i = 0; i < 4; ++i) nxt[i / 2][i % 2] = p[i];
  if (rr == -1 && ss == -1) {
    for (int i = 0; i < r; ++i)
      for (int j = 0; j < s; ++j) nxt[i][j] = nxt[i % 2][j % 2];
    check_best();
    return;
  }
  if (ss != -1) {
    for (int j = 2; j < ss; ++j) {
      nxt[0][j] = nxt[0][j - 2];
      nxt[1][j] = nxt[1][j - 2];
    }
    nxt[0][ss] = nxt[1][ss - 2];
    nxt[1][ss] = nxt[0][ss - 2];
    for (int i = 2; i < r; ++i)
      for (int j = 0; j <= ss; ++j) nxt[i][j] = nxt[i - 2][j];
