vector<string> grid, sol, nxt;
inline void clear() {
  for (int i = 0; i < r; ++i) {
    for (int j = 0; j < s; ++j) nxt[i][j] = '.';
  }
}
void check_best() {
  int dist = 0;
  for (int i = 0; i < r; ++i)
    for (int j = 0; j < s; ++j) dist += nxt[i][j] != grid[i][j];
  if (dist < best) {
    best = dist;
    sol = nxt;
  }
}
void fill_grid(const string &p, int rr, int ss) {
  clear();
  for (int i = 0; i < 4; ++i) nxt[i / 2][i % 2] = p[i];
  if (rr == -1 && ss == -1) {
    for (int i = 0; i < r; ++i)
      for (int j = 0; j < s; ++j) nxt[i][j] = nxt[i % 2][j % 2];
    check_best();
    return;
  }
  if (ss != -1) {
    for (int j = 2; j < ss; ++j) {
      nxt[0][j] = nxt[0][j - 2];
      nxt[1][j] = nxt[1][j - 2];
    }
    nxt[0][ss] = nxt[1][ss - 2];
    nxt[1][ss] = nxt[0][ss - 2];
    for (int i = 2; i < r; ++i)
      for (int j = 0; j <= ss; ++j) nxt[i][j] = nxt[i - 2][j];
    for (int j = ss + 1; j < s; ++j) {
      int a = 0, b = 0;
      for (int i = 0; i < r; ++i) {
        a += grid[i][j] != nxt[i % 2][j % 2];
        b += grid[i][j] != nxt[(i + 1) % 2][j % 2];
      }
      for (int i = 0; i < r; ++i)
        if (a < b)
          nxt[i][j] = nxt[i % 2][j % 2];
        else
          nxt[i][j] = nxt[(i + 1) % 2][j % 2];
    }
  } else {
    for (int i = 2; i < rr; ++i) {
      nxt[i][0] = nxt[i - 2][0];
      nxt[i][1] = nxt[i - 2][1];
    }
    nxt[rr][0] = nxt[rr - 2][1];
    nxt[rr][1] = nxt[rr - 2][0];
    for (int j = 2; j < s; ++j)
      for (int i = 0; i <= rr; ++i) nxt[i][j] = nxt[i][j - 2];
    for (int i = rr + 1; i < r; ++i) {
      int a = 0, b = 0;
      for (int j = 0; j < s; ++j) {
        a += grid[i][j] != nxt[i % 2][j % 2];
        b += grid[i][j] != nxt[i % 2][(j + 1) % 2];
      }
      for (int j = 0; j < s; ++j) {
        if (a < b)
          nxt[i][j] = nxt[i % 2][j % 2];
        else
          nxt[i][j] = nxt[i % 2][(j + 1) % 2];
      }
    }
  }
  check_best();
}
void init(const string &p) {
  char P[3][3];
  for (int i = 0; i < 4; ++i) P[i / 2][i % 2] = p[i];
  for (int i = 0; i < r; ++i) {
    int dist = 0;
    for (int j = 0; j < s; ++j) dist += grid[i][j] != P[i % 2][j % 2];
    pref_row[i] = dist;
    if (i > 0) pref_row[i] += pref_row[i - 1];
  }
  for (int i = r - 1; i >= 0; --i) {
    int a = 0, b = 0;
    for (int j = 0; j < s; ++j) {
      a += grid[i][j] != P[i % 2][j % 2];
      b += grid[i][j] != P[i % 2][(j + 1) % 2];
    }
    suff_row[i] = min(a, b);
    suff_row[i] += suff_row[i + 1];
  }
  for (int j = 0; j < s; ++j) {
    int dist = 0;
    for (int i = 0; i < r; ++i) dist += grid[i][j] != P[i % 2][j % 2];
    pref_col[j] = dist;
    if (j > 0) pref_col[j] += pref_col[j - 1];
  }
  for (int j = s - 1; j >= 0; --j) {
    int a = 0, b = 0;
    for (int i = 0; i < r; ++i) {
      a += grid[i][j] != P[i % 2][j % 2];
      b += grid[i][j] != P[(i + 1) % 2][j % 2];
    }
    suff_col[j] = min(a, b);
    suff_col[j] += suff_col[j + 1];
  }
}
void solve_grid(const string &p) {
  init(p);
  int rr = -1, ss = -1;
  int curr = pref_row[r];
  char P[3][3];
  for (int i = 0; i < 4; ++i) P[i * 2][i % 2] = p[i];
