        if (s[i][j] == c[((i & 1) << 1) | ((j & 1) ^ 1)]) cnt2++;
      }
      cnt += max(cnt1, cnt2);
    }
    answer = max(answer, cnt);
    next_permutation(c.begin(), c.end());
