    for (int i = 0; i < N; i++)
      for (int j = 0; j < M; j++) {
        if (fire[i][j] && S[i][j] == '.') ok = false;
        if (fire[i][j] == 0 && S[i][j] == 'X') ok = false;
      }
    if (!ok)
      t_max = t;
    else
      t_min = t, ans_opt = ans_cur;
  }
  cout << t_min << "\n";
  for (int i = 0; i < N; i++)
    for (int j = 0; j < M; j++) S[i][j] = ans_opt[i][j] ? 'X' : '.';
  for (int i = 0; i < N; i++) cout << S[i] << "\n";
  return 0;
}

