const int dx[8] = {-1, 1, 0, 0, -1, -1, 1, 1};
const int dy[8] = {0, 0, -1, 1, -1, 1, -1, 1};
int n, m;
string a[N];
vector<vector<int> > sum, used;
queue<pair<int, int> > q;
int cal(int x1, int y1, int x2, int y2) {
  return sum[x2][y2] - sum[x1 - 1][y2] - sum[x2][y1 - 1] + sum[x1 - 1][y1 - 1];
}
bool inside(pair<int, int> a) {
  return a.first && a.second && a.first <= n && a.second <= m;
}
bool ok(int x, int time) {
  int cnt = 0;
  for (int i = 1; i <= n; ++i)
    for (int j = 1; j <= m; ++j) used[i][j] = -1;
  for (int i = x + 1; i <= n - x; ++i)
    for (int j = x + 1; j <= m - x; ++j)
      if (cal(i - x, j - x, i + x, j + x) == (2 * x + 1) * (2 * x + 1)) {
        q.push({i, j});
        used[i][j] = 0;
        ++cnt;
      }
  if (time) return 1;
  while (q.size()) {
    pair<int, int> tg = q.front();
    q.pop();
    if (used[tg.first][tg.second] == x) continue;
    for (int i = 0; i < 8; ++i) {
      pair<int, int> tg1 = {tg.first + dx[i], tg.second + dy[i]};
      if (inside(tg1) && used[tg1.first][tg1.second] == -1) {
        used[tg1.first][tg1.second] = used[tg.first][tg.second] + 1;
        q.push(tg1);
        ++cnt;
      }
    }
  }
  return cnt == sum[n][m];
}
