      sum[i + 1][j + 1] =
          sum[i][j + 1] + sum[i + 1][j] - sum[i][j] + (a[i][j] == 'X');
  }
  int l = 0, r = min(m, n) - 1;
  while (l <= r) {
    int mid = (l + r) / 2;
    if (!ok(mid, 0))
      r = mid - 1;
    else
      l = mid + 1;
  }
  cout << r << '\n';
