const int INF = 1e9 + 7;
int n, m;
vector<vector<int>> tb, d1, d2;
bool true_pos(int x, int y) {
  if (x < 0 || x > n + 1) return false;
  if (y < 0 || y > m + 1) return false;
  return true;
}
void reader() {
  cin >> n >> m;
  tb.resize(n + 2, vector<int>(m + 2, 0));
  d1.resize(n + 2, vector<int>(m + 2, 0));
  d2.resize(n + 2, vector<int>(m + 2, 0));
  for (int i = 1; i <= n; ++i) {
    string line;
    cin >> line;
    for (int j = 0; j < m; ++j)
      if (line[j] == 'X') tb[i][j + 1] = (1+1);
  }
}
void go_bfs(vector<pair<int, int>> &start, vector<vector<int>> &ds) {
  queue<pair<int, int>> q;
  for (int i = 0; i <= n + 1; ++i)
    for (int j = 0; j <= m + 1; ++j) ds[i][j] = INF;
  for (auto &elem : start) {
    ds[elem.first][elem.second] = 0;
    q.push(elem);
  }
  while (!q.empty()) {
    auto u = q.front();
    q.pop();
    for (int i = -1; i <= 1; ++i) {
      for (int j = -1; j <= 1; ++j) {
        auto v = make_pair(u.first + i, u.second + j);
        if (!true_pos(v.first, v.second)) continue;
        if (ds[u.first][u.second] + 1 < ds[v.first][v.second]) {
          ds[v.first][v.second] = ds[u.first][u.second] + 1;
          q.push(v);
        }
      }
    }
  }
}
void precalc() {
  vector<pair<int, int>> start;
  for (int i = 0; i <= n + 1; ++i)
    for (int j = 0; j <= m + 1; ++j)
      if (tb[i][j] == 0) start.push_back({i, j});
  go_bfs(start, d1);
}
bool check(int T) {
  vector<pair<int, int>> start;
  for (int i = 0; i <= n + 1; ++i)
    for (int j = 0; j <= m + 1; ++j)
      if (d1[i][j] >= T + 1) start.push_back({i, j});
  if (start.empty()) return false;
  go_bfs(start, d2);
  vector<vector<int>> temp(n + 2, vector<int>(m + 2, 0));
  for (int i = 0; i <= n + 1; ++i)
    for (int j = 0; j <= m + 1; ++j)
      if (d2[i][j] <= T) temp[i][j] = 1;
  return (temp == tb);
}
void printer(int res) {
  cout << res << '\n';
  vector<vector<char>> ans(n + 2, vector<char>(m + 2, '.'));
  for (int i = 0; i <= n + 1; ++i)
    for (int j = 0; j <= m + 1; ++j)
      if (d1[i][j] >= res + 1) ans[i][j] = 'X';
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) cout << ans[i][j];
    cout << '\n';
  }
}
void solve() {
  int l = 0;
  int r = min(n, m) + 1;
  while (r - l > 1) {
    int mid = (l + r) >> 1;
    if (check(mid))
      l = mid;
    else
      r = mid;
  }
  printer(l);
}
