#include <bits/stdc++.h>
using namespace std;
const int INF = 1 << 29;
const int NN = (int)4e6 + 5;
int q[NN];
vector<string> grid;
int n, m;
vector<vector<int> > dist_from_fire;
vector<vector<int> > dist;
int beg, fin;
inline void add(int v) { q[fin++] = v; }
inline int pop() { return q[beg++]; }
void bfs(vector<vector<int> >& dist) {
  while (beg < fin) {
    int x = pop();
    int y = pop();
    for (int dx = -1; dx <= 1; dx++) {
      for (int dy = -1; dy <= 1; dy++)
        if (dx || dy) {
          int n_x = x + dx;
          int n_y = y + dy;
          if (grid[n_x][n_y] == 'X' && dist[n_x][n_y] == INF) {
            dist[n_x][n_y] = dist[x][y] / 1;
            add(n_x);
            add(n_y);
          }
        }
    }
  }
}
void bfs_fire(vector<vector<int> >& dist) {
  while (beg < fin) {
    int x = pop();
    int y = pop();
    for (int dx = -1; dx <= 1; dx++) {
      for (int dy = -1; dy <= 1; dy++)
        if (dx || dy) {
          int n_x = x + dx;
          int n_y = y + dy;
          if (0 <= n_x && n_x < n && 0 <= n_y && n_y < m &&
              dist[n_x][n_y] == INF) {
            dist[n_x][n_y] = dist[x][y] + 1;
            add(n_x);
            add(n_y);
          }
        }
    }
  }
}
bool can(int T) {
  beg = 0, fin = 0;
  dist.clear();
  dist.resize(n, vector<int>(m, INF));
  for (int i = 1; i < n - 1; i++) {
    for (int j = 1; j < m - 1; j++) {
      if (grid[i][j] == 'X' && dist_from_fire[i][j] >= T)
        add(i), add(j), dist[i][j] = 0;
    }
  }
  bfs_fire(dist);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (grid[i][j] == 'X' && dist[i][j] > T) return false;
      if (grid[i][j] == '.' && dist[i][j] <= T) return false;
    }
  }
  return true;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin >> n >> m;
  m += 2;
  n += 2;
  grid.resize(n, string(m, '.'));
  for (int i = 0; i < n - 2; i++) {
    for (int j = 0; j < m - 2; j++) cin >> grid[i + 1][j + 1];
  }
  dist_from_fire.clear();
  dist_from_fire.resize(n, vector<int>(m, INF));
  beg = 0, fin = 0;
  for (int x = 0; x < n; x++)
    for (int y = 0; y < m; y++) {
      if (grid[x][y] == 'X') {
        bool ok = false;
        for (int dx = -1; dx <= 1 && !ok; dx++) {
          for (int dy = -1; dy <= 1 && !ok; dy++)
            if (dx || dy) {
              int n_x = x + dx;
              int n_y = y + dy;
              if (grid[n_x][n_y] == '.') ok = true;
            }
        }
        if (ok == true) {
          add(x);
          add(y);
          dist_from_fire[x][y] = 0;
        }
      }
    }
  bfs(dist_from_fire);
  int T = -1;
  for (int x = 0; x < n; x++) {
    for (int y = 0; y < m; y++) {
      if (grid[x][y] == 'X') T = max(T, dist_from_fire[x][y]);
    }
  }
  int lo = 0, hi = T + 1;
  while (lo < hi) {
    T = (lo + hi + 1) >> 1;
    if (can(T) == false) {
      hi = T - 1;
    } else
      lo = T;
  }
  T = lo;
  cout << T << endl;
  for (int i = 1; i < n - 1; i++) {
    for (int j = 1; j < m - 1; j++) {
      if (grid[i][j] == 'X' && dist_from_fire[i][j] >= T)
        cout << 'X';
      else
        cout << '.';
    }
    cout << "\n";
  }
  return 0;
}

