inline bool bfs_2d_move_to_cell(int xx, int yy) {
  if (xx <= 0 || xx > bfs_total_row || yy <= 0 || yy > bfs_total_column ||
      bfs_2d_color[xx][yy])
    return 0;
  return 1;
}
void init_bfs_2d(int row, int column, int edges) {
  bfs_total_row = row;
  bfs_total_column = column;
  no_of_edges = edges;
  for (int i = 0; i <= bfs_total_row + 2; i++) {
    bfs_2d_color[i].clear();
    bfs_2d_component[i].clear();
    bfs_2d_dis[i].clear();
    bfs_2d_nodes_by_component[i].clear();
    for (int j = 0; j <= bfs_total_column + 2; j++) {
      bfs_2d_color[i].push_back(0);
      bfs_2d_component[i].push_back(0);
      bfs_2d_dis[i].push_back(0);
    }
  }
  while (!bfs_2d_queue.empty()) bfs_2d_queue.pop();
  bfs_2d_moves.clear();
  if (no_of_edges == 8) {
    for (int i = -1; i <= 1; i++) {
      for (int j = -1; j <= 1; j++) {
        if (i || j) bfs_2d_moves.push_back(make_pair(i, j));
      }
    }
  }
  if (no_of_edges == 4) {
    for (int i = -1; i <= 1; i++) {
      for (int j = -1; j <= 1; j++) {
        if (((abs(i)) ^ abs(j))) bfs_2d_moves.push_back(make_pair(i, j));
      }
    }
  }
}
void bfs_2d_with_source(int component_count) {
  int x, y, xx, yy, i;
  while (!bfs_2d_queue.empty()) {
    x = bfs_2d_queue.front().first;
    y = bfs_2d_queue.front().second;
    bfs_2d_queue.pop();
    bfs_2d_component[x][y] = component_count;
    bfs_2d_nodes_by_component[component_count].push_back(make_pair(x, y));
    for (i = 0; i < bfs_2d_moves.size(); i++) {
      xx = x + bfs_2d_moves[i].first;
      yy = y + bfs_2d_moves[i].second;
      if (bfs_2d_move_to_cell(xx, yy)) {
        bfs_2d_queue.push(make_pair(xx, yy));
        bfs_2d_dis[xx][yy] = bfs_2d_dis[x][y] + 1;
        bfs_2d_color[xx][yy] = 1;
      }
    }
  }
