        y = j;
        for (k = 0; k < no_of_edges; k++) {
          xx = x + bfs_2d_moves[k].first;
          yy = y + bfs_2d_moves[k].second;
          if (xx <= 0 || xx > n || yy <= 0 || yy > m) continue;
          if (CELL[xx][yy] == 0) flag = 1;
        }
        if (flag) {
          bfs_2d_queue.push(make_pair(i, j));
          bfs_2d_color[i][j] = 1;
        }
      }
    }
  }
  bfs_2d_with_source(1);
  for (i = 1; i <= n; i++) {
    for (j = 1; j <= m; j++) {
      if (CELL[i][j] && bfs_2d_dis[i][j] >= curr) {
        TEMP.push_back(make_pair(i, j));
      }
    }
  }
  init_bfs_2d(n, m, no_of_edges);
  for (i = 0; i < TEMP.size(); i++) bfs_2d_queue.push(TEMP[i]);
  for (i = 0; i < TEMP.size(); i++)
    bfs_2d_color[TEMP[i].first][TEMP[i].second] = 1;
  bfs_2d_with_source(1);
  for (i = 1; i <= n; i++) {
    for (j = 1; j <= m; j++) {
      if (CELL[i][j] && bfs_2d_dis[i][j] > curr) return 0;
      if (CELL[i][j] && bfs_2d_color[i][j] == 0) return 0;
      if (CELL[i][j] == 0 && bfs_2d_color[i][j] && bfs_2d_dis[i][j] <= curr)
        return 0;
    }
  }
  return 1;
}
int BS(int l, int r, int n, int m) {
  int mid = l + r;
  mid /= 2;
  if (abs(r - l) <= 1) {
    if (check(r, n, m)) return r;
    return l;
  }
  if (check(mid, n, m)) return BS(mid, r, n, m);
  return BS(l, mid, n, m);
}
