    bfs_2d_component[x][y] = component_count;
    bfs_2d_nodes_by_component[component_count].push_back(make_pair(x, y));
    for (i = 0; i < bfs_2d_moves.size(); i++) {
      xx = x + bfs_2d_moves[i].first;
      yy = y + bfs_2d_moves[i].second;
