template <typename T>
struct CumulativeSum2D {
  int H, W;
  vector<vector<T>> dat;
  CumulativeSum2D(vector<vector<T>> v) {
    H = v.size(), W = v[0].size();
    dat.assign(H + 1, vector<T>(W + 1, 0));
    for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
        dat[i + 1][j + 1] = v[i][j];
        dat[i + 1][j + 1] += dat[i + 1][j] + dat[i][j + 1] - dat[i][j];
      }
    }
  }
