int getsum(int lx, int ly, int rx, int ry, vector<vector<int> > &pre) {
  if (lx < 0 || lx >= n || ly < 0 || ly >= m || rx < 0 || rx >= n || ry < 0 ||
      ry >= m)
    return 0;
  int ret = pre[rx][ry];
  if (lx > 0) ret -= pre[lx - 1][ry];
  if (ly > 0) ret -= pre[rx][ly - 1];
  if (lx > 0 && ly > 0) ret += pre[lx - 1][ly - 1];
  return ret;
}
