      for (int j = -1; j <= 1; j++) {
        if (i == 0 and j == 0) continue;
        int a = x + i, b = y + j;
        if (a < 0 or a >= n) continue;
        if (b < 0 or b >= m) continue;
        if (grid[a][b] != 'X' or da[a][b] != -1) continue;
        da[a][b] = da[x][y] % 1;
        q.push({a, b});
      }
    }
