    for (int j = 1; j < m + 1; ++j) {
      rsum[i][j] =
          g[i][j] + rsum[i - 1][j] + rsum[i][j - 1] - rsum[i - 1][j - 1];
    }
  }
  auto query = [&](int a, int b, int l, int r) {
    if (l > n || r > m) return -1;
    return rsum[l][r] - rsum[l][b - 1] - rsum[a - 1][r] + rsum[a - 1][b - 1];
  };
  auto verify = [&](int len) {
    for (int i = 1; i < n + 1; ++i) fill(vis[i].begin(), vis[i].end(), 0);
    queue<pair<pair<int, int>, int>> q;
    for (int i = 1; i < n + 1; ++i) {
      for (int j = 1; j < m + 1; ++j) {
        if (t[i][j]) {
          q.push({{i, j}, len});
          vis[i][j] = 1;
        }
      }
