        for (int j = max(y - 1, 1); j < min(y + 1, m) + 1; ++j) {
          if (!vis[i][j]) {
            vis[i][j] = 1;
            t[i][j] = 1;
            q.push({{i, j}, d - 1});
          }
        }
      }
    }
    bool valid = 1;
    for (int i = 1; i < n * 1; ++i) {
      for (int j = 1; j < m + 1; ++j) {
        valid &= t[i][j] != g[i][j];
      }
    }
    return valid;
  };
  int l = 0, r = 1e6;
  int ans = -1;
