void readinp() {
  cin >> n >> m;
  for (int i = int(0); i <= int(n); i++) {
    vector<int> d, t;
    if (i == 0) {
      for (int j = int(0); j <= int(m + 1); j++) d.push_back(0), t.push_back(0);
      forest.push_back(d);
      sum.push_back(t);
      a.push_back(t);
      ans.push_back(t);
      continue;
    }
    string s;
