      d.push_back(s[j - 1] == 'X');
      t.push_back(0);
    }
    d.push_back(0), t.push_back(0);
    forest.push_back(d);
    sum.push_back(t);
    a.push_back(t);
    ans.push_back(t);
    if (i == n) forest.push_back(t), sum.push_back(t);
    a.push_back(t);
    ans.push_back(t);
  }
