int n, m;
vector<vector<int> > forest, sum, a, ans;
void readinp() {
  cin >> n >> m;
  for (int i = int(0); i <= int(n); i++) {
    vector<int> d, t;
    if (i == 0) {
      for (int j = int(0); j <= int(m + 1); j++) d.push_back(0), t.push_back(0);
      forest.push_back(d);
      sum.push_back(t);
      a.push_back(t);
      ans.push_back(t);
      continue;
    }
    string s;
    cin >> s;
    d.push_back(0);
    t.push_back(0);
    for (int j = int(1); j <= int(m); j++) {
      d.push_back(s[j - 1] == 'X');
      t.push_back(0);
    }
    d.push_back(0), t.push_back(0);
    forest.push_back(d);
    sum.push_back(t);
    a.push_back(t);
    ans.push_back(t);
    if (i == n) forest.push_back(t), sum.push_back(t);
    a.push_back(t);
    ans.push_back(t);
  }
}
int get(int xa, int ya, int xb, int yb) {
  if (xa > n || ya > m || xb > n || yb > m) return -1;
  return sum[xb][yb] - sum[xa - 1][yb] - sum[xb][ya - 1] + sum[xa - 1][ya - 1];
}
void upd(int xa, int ya, int xb, int yb) {
  a[xa][ya]++;
  a[xa][yb + 1]--;
  a[xb + 1][yb + 1]++;
  a[xb + 1][ya]--;
}
bool check(int k) {
  for (int i = int(0); i <= int(n + 1); i++)
    for (int j = int(0); j <= int(m + 1); j++) a[i][j] = 0;
  int r = 2 * k + 1;
  if (r > n || r > m) return false;
  for (int i = int(1); i <= int(n - r + 1); i++)
    for (int j = int(1); j <= int(m - r + 1); j++) {
      if (get(i, j, i + r - 1, j + r - 1) == r * r) {
        int x = i, y = j;
        int u = i + r - 1, v = j + r - 1;
        upd(x, y, u, v);
      }
    }
  for (int i = int(1); i <= int(n); i++)
    for (int j = int(1); j <= int(m); j++) a[i][j] += a[i][j - 1];
  for (int i = int(1); i <= int(n); i++)
    for (int j = int(1); j <= int(m); j++) a[i][j] += a[i - 1][j];
  for (int i = int(1); i <= int(n); i++)
    for (int j = int(1); j <= int(m); j++)
      if (forest[i][j] && !a[i][j]) return false;
  return true;
}
bool ok(int k, int i, int j) {
  if (i - k < 1 || i + k > n || j - k < 1 || j + k > m) return false;
  return (get(i - k, j - k , j + k, i + k) == (k * 2 + 1) * (k * 2 + 1));
}
void solve() {
  for (int i = int(1); i <= int(n); i++)
    for (int j = int(1); j <= int(m); j++)
      sum[i][j] =
          sum[i][j - 1] + sum[i - 1][j] - sum[i - 1][j - 1] + forest[i][j];
  int l = 0, r = min(n, m) / 2;
  int res = 0;
  while (l <= r) {
    int mid = (l + r) / 2;
    if (check(mid)) {
      l = mid + 1;
      res = mid;
    } else
      r = mid - 1;
  }
  cout << res;
  cout << '\n';
  for (int i = int(1); i <= int(n); i++) {
    for (int j = int(1); j <= int(m); j++) cout << (ok(res, i, j) ? 'X' : '.');
    cout << '\n';
  }
}
int main() {
  setIO();
  int t = 1;
  while (t--) {
    readinp();
    solve();
  }
}

