        for (int dy = -1; dy <= 1; dy++) {
          if (dx == 0 && dy == 0) {
            continue;
          }
          int nx = x + dx;
          int ny = y + dy;
          if (0 <= nx && nx < n && 0 <= ny && ny < m && ds[nx][ny] == -1) {
            ds[nx][ny] = d + 1;
            q.push(make_pair(nx, ny));
          }
        }
      }
    }
    if (ok) {
      l = md;
    } else {
      r = md - 1;
    }
  }
  cout << l - 1 << endl;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (c[i][j] == '.' || dst[i][j] < l) {
        printf(".");
      } else {
        printf("X");
      }
    }
    printf("\n");
  }
}

