    vis[u.first][u.second] = 1;
  }
  while (!q.empty()) {
    pair<int, int> top = q.front();
    q.pop();
    ++cnt;
    if (vis[top.first][top.second] == x) continue;
    for (int i = (-1); i <= (signed)(1); i++) {
