bool checkLine(vector<vector<char> >& v, pair<int, int> start,
               pair<int, int> end) {
  bool isLine = true;
  for (int i = start.first; i <= end.first; i++)
    if (v[i][start.second] != 'A') {
      isLine = false;
      break;
    }
  for (int i = start.second; i <= end.second; i++)
    if (v[start.first][i] != 'A') {
      isLine = false;
      break;
    }
  return isLine;
}
