    for (int j = 1; j <= m; j++)
      for (int i = n; i >= 0; i--)
        if (mp[i][j] != 'A' && ext[i]) {
          if (ext[i] == 2)
            ans = min(ans, 2);
          else
            ans = min(ans, 3);
