  int n, m;
  cin >> n >> m;
  vector<string> one(n);
  for (auto& it : one) {
    cin >> it;
  }
  vector<string> two(m);
  for (int j = 0; j < m; j++) {
    string cur;
    for (int i = 0; i < n; i++) {
      cur += one[i][j];
    }
    two[j] = cur;
  }
  int o = solve(one);
  int t = solve(two);
  vector<int> res = {o, t};
  sort(res.begin(), res.end());
  for (int i : res) {
    if (i != -1) {
      cout << i << endl;
      return;
    }
  }
  cout << "MORTAL" << endl;
}
