vector<vector<int>> get_components2(int n, vector<pair<int, int>> edges) {
  vector<vector<int>> adj(n);
  for (auto e : edges) {
    adj[e.first].push_back(e.second);
    adj[e.second].push_back(e.first);
  }
  vector<vector<int>> ret;
  vector<bool> visited(n, false);
  for (int v = 0; v < n; ++v) {
    if (visited[v]) continue;
    vector<int> comp;
    queue<int> queue;
    queue.push(v);
    while (not queue.empty()) {
      int _v = queue.front();
      queue.pop();
      visited[_v] = true;
      comp.push_back(_v);
      for (auto __v : adj[_v]) {
        if (visited[__v]) continue;
        queue.push(__v);
      }
    }
    ret.push_back(comp);
  }
  return ret;
}
vector<vector<int>> get_components(int n, vector<pair<int, int>> edges) {
  vector<int> v_to_c;
  unordered_map<int, vector<int>> c_to_v;
  for (int v = 0; v < n; ++v) {
    v_to_c.push_back(v);
    c_to_v[v] = {v};
  }
  for (auto e : edges) {
    int c_0 = v_to_c[e.first], c_1 = v_to_c[e.second];
    if (c_0 == c_1) continue;
    if (c_to_v[c_0].size() < c_to_v[c_1].size()) {
      int tmp = c_0;
      c_0 = c_1;
      c_1 = tmp;
    }
    for (auto v : c_to_v[c_1]) {
      c_to_v[c_0].push_back(v);
      v_to_c[v] = c_0;
    }
    c_to_v.erase(c_1);
  }
  vector<vector<int>> ret;
  for (auto it : c_to_v) {
    ret.push_back(it.second);
  }
  return ret;
}
long long choose(int n, int m) {
  if (n == m) return 1;
  if (n < m) return 0;
  long long ret = 1;
  for (int _n = n; _n >= n - m + 1; --_n) {
    ret *= _n;
  }
  for (int _m = 2; _m <= m; ++_m) {
    ret /= _m;
  }
  return ret;
}
