    int x, y, c;
    scanf("%d%d%d", &x, &y, &c);
    maxn = max(maxn, c);
    if (b[x][y] != c) {
      op[b[x][y]].push_back(Operation(x, y, -1, i));
      op[c].push_back(Operation(x, y, 1, i));
    }
    b[x][y] = c;
  }
  for (int i = 0; i <= maxn; i++) {
    solve(i, n, m);
  }
  int ans = 1;
  for (int i = 1; i <= q; i++) {
    ans += count[i];
    printf("%d\n", ans);
  }
  return 0;
}

