int dx[4] = {0, -(1+1), 0, 1};
int dy[4] = {-1, 0, 1, 0};
struct Operation {
  int x, y, t;
  int id;
  Operation(int x, int y, int t, int id) : x(x), y(y), t(t), id(id) {}
};
std::vector<Operation> op[2000005];
int count[2000005];
int p[90005];
int find(int u) {
  if (p[u] == u)
    return u;
  else
    return p[u] = find(p[u]);
}
void Union(int u, int v) {
  int x = find(u), y = find(v);
  p[x] = y;
}
int getId(int i, int j, int n, int m) { return (i - 1) * m + j; }
void doMerge(int n, int m) {
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      int id = getId(i, j, n, m);
      p[id] = id;
      if (b[i][j] == -1) continue;
      for (int k = 0; k < 2; k++) {
        int r = i + dx[k], c = j + dy[k];
        if (r >= 1 && r <= n && c >= 1 && c <= m && b[r][c] != -1)
          Union(id, getId(r, c, n, m));
      }
    }
  }
}
void doAdd(int color, int l, int r, int n, int m) {
  for (int i = l; i <= r; i++) {
    int x = op[color][i].x, y = op[color][i].y;
    int minus = 0;
    for (int j = 0; j < 4; j++) {
      int r = x + dx[j], c = y + dy[j];
      if (r >= 1 && r <= n && c >= 1 && c <= m && b[r][c] == color) {
        int from = find(getId(x, y, n, m)), to = find(getId(r, c, n, m));
        if (from != to) {
          minus++;
          p[to] = from;
        }
      }
    }
    if (minus == 0)
      count[op[color][i].id]++;
    else
      count[op[color][i].id] -= (minus - 1);
    b[x][y] = color;
  }
}
void doDelete(int color, int l, int r, int n, int m) {
  for (int i = r; i >= l; i--) {
    int x = op[color][i].x, y = op[color][i].y;
    int merge = 0;
    for (int j = 0; j < 4; j++) {
      int r = x + dx[j], c = y + dy[j];
      if (r >= 1 && r <= n && c >= 1 && c <= m && b[r][c] == color) {
        int from = find(getId(x, y, n, m)), to = find(getId(r, c, n, m));
        if (from != to) {
          merge++;
          p[to] = from;
        }
      }
    }
    if (merge == 0)
      count[op[color][i].id]--;
    else
      count[op[color][i].id] += (merge - 1);
    b[x][y] = color;
  }
}
void solve(int color, int n, int m) {
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (color != 0)
        b[i][j] = -1;
      else
        b[i][j] = 0;
      p[getId(i, j, n, m)] = getId(i, j, n, m);
    }
  }
  int nextP = -1;
  while (nextP + 1 < (int)op[color].size() && op[color][nextP + 1].t == 1)
    nextP++;
  doAdd(color, 0, nextP, n, m);
  for (int i = nextP + 1; i < (int)op[color].size(); i++)
    b[op[color][i].x][op[color][i].y] = -1;
  doMerge(n, m);
  doDelete(color, nextP + 1, op[color].size() - 1, n, m);
}
int max(int a, int b) { return a > b ? a : b; }
int main() {
