#include <bits/stdc++.h>
using namespace std;
const int N = 305;
const int K = 2e6 + 5;
int n, m, q;
int p[N * N];
int sz[N * N];
int a[N][N];
int save[K][(3-1)];
int ans[K];
int cnt;
int o[K];
bool b[K];
int id(int x, int y) { return (x - 1) * m + y - 1; }
int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
bool ok(int x, int y) { return 1 <= x && x <= n && 1 <= y && y <= m; }
void upd(int x, int y, int* v) {
  int dx[4] = {-1, 1, 0, 0};
  int dy[4] = {0, 0, -1, 1};
  (*v)++;
  for (int k = 0; k < 4; k++) {
    int tx = dx[k] + x;
    int ty = dy[k] + y;
    if (!ok(tx, ty)) continue;
    int idx = id(x, y), tidx = id(tx, ty);
    int fa = find(idx), tfa = find(tidx);
    if (a[x][y] == a[tx][ty] && fa != tfa) {
      (*v)--;
      if (sz[fa] >= sz[tfa]) {
        sz[fa] += sz[tfa];
        p[tfa] = fa;
      } else {
        sz[tfa] += sz[fa];
        p[fa] = tfa;
      }
    }
  }
}
int fall(int v) {
  int re = 0;
  for (int x = 1; x <= n; x++)
    for (int y = 1; y <= m; y++) {
      int idx = id(x, y);
      p[idx] = idx, sz[idx] = 1;
    }
  for (int x = 1; x <= n; x++)
    for (int y = 1; y <= m; y++) {
      if (a[x][y] <= v) {
        upd(x, y, &re);
      }
    }
  return re;
}
void test() {
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) cout << a[i][j] << ' ';
    cout << endl;
  }
}
