  scanf("%d%d%d", &n, &m, &q);
  int now = 0;
  for (int x = 1; x <= n; x++)
    for (int y = 1; y <= m; y++) {
      int idx = id(x, y);
      p[idx] = idx, sz[idx] = 1;
    }
  for (int i = 1; i <= q; i++) {
    int x, y, c;
    scanf("%d%d%d", &x, &y, &c);
    if (o[cnt] != c) {
      now = 0;
      o[++cnt] = c;
    }
    if (a[x][y] == cnt) {
      b[i] = 1;
      continue;
    }
    save[i][0] = x;
    save[i][1] = y;
    save[i][2] = a[x][y];
    int idx = id(x, y);
    p[idx] = idx, sz[idx] = 1;
    a[x][y] = cnt;
    upd(x, y, &now);
    ans[i] = now;
  }
  for (int i = q; i >= 1; i--) {
    if (b[i]) continue;
    int x = save[i][0], y = save[i][1], c = save[i][2];
    if (cnt == a[x][y]) {
      now = fall(--cnt);
    }
    ans[i] += now;
    int idx = id(x, y);
    p[idx] = idx, sz[idx] = 1;
    a[x][y] = c;
    upd(x, y, &now);
  }
  for (int i = 1; i <= q; i++)
    if (b[i]) ans[i] = ans[i - 1];
  for (int i = 1; i <= q; i++) printf("%d\n", ans[i]);
  return 0;
}

