  us[x][y] = 1;
  for (int i = 0; i < 4; i++) {
    int nx = x + go[i][0], ny = y + go[i][1];
    if (nx >= 0 and nx < n and ny >= 0 and ny < m and us[nx][ny]) {
      int u = find_pr(x * m + y), v = find_pr(nx * m + ny);
      if (u != v) {
        re--;
        if (si[u] < si[v]) swap(u, v);
        si[u] += si[v], pr[v] = u;
      }
    }
  }
  return re;
}
