class UnionFind {
 private:
  vec<int> p, s;
  int cnt;

 public:
  UnionFind() {}
  UnionFind(int N) : cnt(N), s(N, 1), p(N) { iota(p.begin(), p.end(), 0); }
  void init() {
    int N = s.size();
    cnt = N;
    fill(s.begin(), s.end(), 1);
    iota(p.begin(), p.end(), 0);
  }
  int find(int x) {
    if (p[x] == x)
      return x;
    else
      return p[x] = find(p[x]);
  }
  int unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return 0;
    if (s[x] > s[y]) swap(x, y);
    p[x] = y;
    s[y] += s[x];
    cnt--;
    return -1;
  }
