  }
  if (a[x][y] == a[x][y + 1]) {
    Merge(id[x][y], id[x][y + 1]);
  }
  if (a[x][y] == a[x - 1][y]) {
    Merge(id[x][y], id[x - 1][y]);
  }
  if (a[x][y] == a[x + 1][y]) {
    Merge(id[x][y], id[x + 1][y]);
  }
