  if (a[x][y] == a[x][y - 1] && id[x][y - 1]) Union(id[x][y], id[x][y - 1]);
  if (a[x][y] == a[x][y + 1] && id[x][y + 1]) Union(id[x][y], id[x][y + 1]);
}
void Update(int i, int x, int y, int c, int f) {
  id[x][y] = ++tot;
  a[x][y] = c;
  num = 1;
  update(x, y);
  Ans[i] += num * f;
}
