  n = read();
  m = read();
  Q = read();
  for (int i = 1; i <= Q; i++) {
    int x = read(), y = read(), c = read();
    P[i] = (Node){x, y, b[x][y], c};
    b[x][y] = c;
  }
  memset(a, -1, sizeof(a));
  for (int i = 1; i < M; i++) fa[i] = i;
  tot = 0;
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) {
      id[i][j] = ++tot;
      a[i][j] = 0;
    }
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) update(i, j);
  for (int i = 1; i <= Q; i++)
    if (a[P[i].x][P[i].y] != P[i].c2) Update(i, P[i].x, P[i].y, P[i].c2, 1);
  memset(a, -1, sizeof(a));
  for (int i = 1; i < M; i++) fa[i] = i;
  tot = 0;
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) {
      id[i][j] = ++tot;
      a[i][j] = b[i][j];
    }
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) update(i, j);
  for (int i = Q; i >= 1; i--)
    if (a[P[i].x][P[i].y] != P[i].c1) Update(i, P[i].x, P[i].y, P[i].c1, -1);
  Ans[0] = 1;
  for (int i = 1; i <= Q; i++) Ans[i] =+ Ans[i - 1];
  for (int i = 1; i <= Q; i++) printf("%d\n", Ans[i]);
  return 0;
}

