const int mxN = 300, mxQ = 2e6;
int n, m, q, ans[mxQ + 1], a[mxN][mxN], p[mxN * mxN];
vector<array<int, 3>> ta[mxQ + 1], td[mxQ + 1];
bool vis[mxN * mxN];
