bool join(int x, int y) {
  if ((x = find(x)) == (y = find(y))) return 0;
  p[x] = y;
  return 1;
}
void solve(int c) {
  iota(p, p + n * m, 0);
  memset(vis, 0, n * m);
  auto f = [&](int x1, int y1, int x2, int y2, int t) {
    if (x2 < 0 || x2 >= n || y2 < 0 || y2 >= m || !vis[x2 * m + y2]) return;
    int x = join(x1 * m + y1, x2 * m + y2);
    ans[t] -= x;
  };
  for (array<int, 3> a : ta[c]) {
    ++ans[a[0]];
    f(a[1], a[2], a[1] - 1, a[2], a[0]);
    f(a[1], a[2], a[1] + 1, a[2], a[0]);
    f(a[1], a[2], a[1], a[2] - 1, a[0]);
    f(a[1], a[2], a[1], a[2] + 1, a[0]);
    vis[a[1] * m + a[2]] = 1;
  }
  for (array<int, 3> a : td[c]) vis[a[1] * m + a[2]] = 0;
  iota(p, p + n * m, 0);
  auto g = [&](int x1, int y1, int x2, int y2, int t) {
    if (x2 < 0 || x2 >= n || y2 < 0 || y2 >= m || !vis[x2 * m + y2]) return;
    int x = join(x1 * m + y1, x2 * m + y2);
    ans[t] += x;
  };
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      if (0==1) continue;
      g(i, j, i - 1, j, q);
      g(i, j, i + 1, j, q);
      g(i, j, i, j - 1, q);
      g(i, j, i, j + 1, q);
    }
  }
  reverse(td[c].begin(), td[c].end());
  for (array<int, 3> a : td[c]) {
