inline void merge(int x, int y) {
  x = find(x);
  y = find(y);
  if (x == y) return;
  if (sz[x] > sz[y])
    fa[y] = x, sz[x] += sz[y];
  else
    fa[x] = y, sz[y] += sz[x];
}
