int f[N * N];
int dx[] = {0, 0, -1, 1}, dy[] = {1, -1, 0, 0};
int ch[Q], off[Q];
int ans[Q];
inline int gid(int i, int j) { return i * m + j; }
int find(int x) { return f[x] == x ? x : f[x] = find(f[x]); }
int cur;
void unite(int x, int y) {
  x = find(x), y = find(y);
  if (x != y) cur--;
  f[x] = y;
}
bool in_bound(int x, int y) { return x >= 0 && x < n && y >= 0 && y < m; }
void dfs(int u, int v, int val) {
  f[u * m + v] = val;
  for (int d = 0; d < 4; d++) {
    int nx = u + dx[d], ny = v + dy[d];
    if (in_bound(nx, ny) && mp[nx][ny] == mp[u][v] && f[nx * m + ny] == -1)
      dfs(nx, ny, val);
  }
}
int build(int val, int ig) {
  for (int k = 0; k < n * m; k++) {
    f[k] = -1;
  }
  int ccnt = 0;
  for (int ki = 0; ki < n; ki++) {
    for (int kj = 0; kj < m; kj++) {
      if (ig != -1 && (!((mp[ki][kj] == val) ^ ig))) {
        f[ki * m + kj] = ki * m + kj;
        continue;
      }
      if (f[ki * m + kj] != -1) continue;
      dfs(ki, kj, ki * m + kj);
      ccnt++;
    }
  }
  return ccnt;
}
