using namespace std;
const int M = 301;
const int N = 2e6 + 7;
const vector<int> dx = {0, 0, 1, -1};
const vector<int> dy = {1, -1, 0, 0};
namespace DSU {
vector<pair<int *, int>> mods;
int cnt = 0;
int p[N];
int rank[N];
int get(int v) {
  if (p[v] != v) {
    mods.emplace_back(&p[v], p[v]);
    p[v] = get(p[v]);
  }
  return p[v];
}
void merge(int a, int b) {
  a = get(a);
  b = get(b);
  if (a == b) return;
  cnt--;
  if (rank[a] < rank[b]) swap(a, b);
  mods.emplace_back(&p[b], p[b]);
  p[b] = a;
  if (rank[a] == rank[b]) {
    mods.emplace_back(&rank[a], rank[a]);
    rank[a]++;
  }
}
void make(int v) {
  mods.emplace_back(&p[v], p[v]);
  mods.emplace_back(&rank[v], rank[v]);
  p[v] = v;
  rank[v] = 1;
  cnt++;
}
void init() {
  cnt = 0;
  fill(p, p + N, -1);
  fill(rank, rank + N, -1);
}
void clear() {
  cnt = 0;
  while (!mods.empty()) {
    *mods.back().first = mods.back().second;
    mods.pop_back();
  }
}
}  
