  int last = 0;
  for (auto q : qr) {
    if (q.tp == 0) {
      int i, j;
      i = q.who / m;
      j = q.who % m;
      a[i][j] = 1;
      DSU::make(q.who);
      for (int k = 0; k < 4; k++) {
        int ni = i + dx[k];
        int nj = j + dy[k];
        if (ok(ni, nj) && a[ni][nj]) {
          DSU::merge(q.who, ni * m + nj);
        }
      }
      add[q.pos] += (DSU::cnt - last);
      last = DSU::cnt;
    } else {
      break;
    }
  }
  for (auto q : qr) {
    if (q.tp == 0) {
    } else {
      int i, j;
      i = q.who / m;
      j = q.who % m;
      a[i][j] = 0;
    }
  }
