#include <bits/stdc++.h>
struct DSU {
  std::vector<int> parent, sizes;
  DSU(int size) : parent(size + 1), sizes(size + 1) {
    for (int i = 0; i <= size; i++) {
      parent[i] = i;
      sizes[i] = 1;
    }
  }
  int findParent(int x) {
    if (x != parent[x]) {
      parent[x] = findParent(parent[x]);
    }
    return parent[x];
  }
  void merge(int a, int b) {
    int pa = findParent(a);
    int pb = findParent(b);
    if (pa == pb) return;
    if (sizes[pa] < sizes[pb]) std::swap(pa, pb);
    parent[pb] = parent[pa];
    sizes[pa] += sizes[pb];
  }
  int getSize(int x) { return sizes[findParent(x)]; }
};
struct Point {
  int x, y, time;
};
int w, h, q;
std::vector<int> diff;
std::vector<std::vector<Point>> cAdd, cRem;
std::vector<std::vector<int>> mat;
int countComp(int x, int y, DSU &dsu) {
  std::vector<Point> p;
  if (x > 0) p.push_back({x - 1, y});
  if (x < w - 1) p.push_back({x + 1, y});
  if (y > 0) p.push_back({x, y - 1});
  if (y < h - 1) p.push_back({x, y + 1});
  for (int i1 = 0; i1 < p.size(); i1++) {
    auto &p1 = p[i1];
    for (int i2 = i1 + 1; i2 < p.size(); i2++) {
      auto &p2 = p[i2];
      if (dsu.findParent(p1.x + p1.y * w) == dsu.findParent(p2.x + p2.y * w)) {
        std::swap(p2, p.back());
        p.pop_back();
        i2--;
      }
    }
  }
  return p.size();
}
int main() {
  scanf("%d %d %d", &w, &h, &q);
  mat.resize(h, std::vector<int>(w));
  diff.resize(q + 1);
  for (int i = 0; i < q; i++) {
    int x, y, c;
    scanf("%d %d %d", &x, &y, &c);
    x--;
    y--;
    while (cAdd.size() <= c) {
      cAdd.push_back({});
      cRem.push_back({});
    }
    int pc = mat[y][x];
    if (c == pc) continue;
    cAdd[c].push_back({x, y, i});
    cRem[pc].push_back({x, y, i});
    mat[y][x] = c;
  }
  for (int y = 0; y < h; y++) {
    for (int x = 0; x < w; x++) {
      mat[y][x] = 0;
    }
  }
  for (int i = 0; i < cAdd.size(); i++) {
    DSU dsu(w * h);
    for (auto &p : cAdd[i]) {
      mat[p.y][p.x] = i;
      int pc = countComp(p.x, p.y, dsu);
      int adj = 0;
      if (p.x > 0 && mat[p.y][p.x - 1] == i) {
        dsu.merge(p.x + p.y * w, p.x - 1 + p.y * w);
        adj++;
      }
      if (p.x < w - 1 && mat[p.y][p.x + 1] == i) {
        dsu.merge(p.x + p.y * w, p.x + 1 + p.y * w);
