      for (int x = 0; x < w; x++) {
        if (m[y][x] == i && m[y + 1][x] == i)
          dsu.merge(x + y * w, x + (y + 1) * w);
      }
    }
    for (int y = 0; y < h; y++) {
      for (int x = 0; x < w - 1; x++) {
        if (m[y][x] == i && m[y][x + 1] == i)
          dsu.merge(x + y * w, x + 1 + y * w);
      }
    }
    for (int i2 = cRem[i].size() - 1; i2 >= 0; i2--) {
      auto &p = cRem[i][i2];
      m[p.y][p.x] = i;
      int pc = countComp(p.x, p.y, dsu);
      int adj = 0;
      if (p.x > 0 && m[p.y][p.x - 1] == i) {
        dsu.merge(p.x + p.y * w, p.x - 1 + p.y * w);
        adj++;
      }
      if (p.x < w - 1 && m[p.y][p.x + 1] == i) {
        dsu.merge(p.x + p.y * w, p.x + 1 + p.y * w);
