    x--;
    y--;
    while (cAdd.size() <= c) {
      cAdd.push_back({});
      cRem.push_back({});
    }
    int pc = mat[y][x];
    if (c == pc) continue;
    cAdd[c].push_back({x, y, i});
    cRem[pc].push_back({x, y, i});
    mat[y][x] = c;
  }
  for (int y = 0; y < h; y++) {
    for (int x = 0; x < w; x++) {
      mat[y][x] = 0;
    }
  }
  for (int i = 0; i < cAdd.size(); i++) {
    DSU dsu(w * h);
    for (auto &p : cAdd[i]) {
      mat[p.y][p.x] = i;
      int pc = countComp(p.x, p.y, dsu);
      int adj = 0;
      if (p.x > 0 && mat[p.y][p.x - 1] == i) {
        dsu.merge(p.x + p.y * w, p.x - 1 + p.y * w);
        adj++;
      }
      if (p.x < w - 1 && mat[p.y][p.x + 1] == i) {
        dsu.merge(p.x + p.y * w, p.x + 1 + p.y * w);
        adj++;
      }
      if (p.y > 0 && mat[p.y - 1][p.x] == i) {
        dsu.merge(p.x + p.y * w, p.x + (p.y - 1) * w);
        adj++;
      }
      if (p.y < h - 1 && mat[p.y + 1][p.x] == i) {
        dsu.merge(p.x + p.y * w, p.x + (p.y + 1) * w);
        adj++;
      }
      if (adj == 0) {
        diff[p.time]++;
      } else {
        int cc = countComp(p.x, p.y, dsu);
        diff[p.time] += cc - pc;
      }
    }
  }
  for (int i = 0; i < cRem.size(); i++) {
    DSU dsu(w * h);
    std::vector<std::vector<int>> m = mat;
    for (int y = 0; y < h - 1; y++) {
      for (int x = 0; x < w; x++) {
        if (m[y][x] == i && m[y + 1][x] == i)
          dsu.merge(x + y * w, x + (y + 1) * w);
      }
    }
    for (int y = 0; y < h; y++) {
      for (int x = 0; x < w - 1; x++) {
        if (m[y][x] == i && m[y][x + 1] == i)
          dsu.merge(x + y * w, x + 1 + y * w);
      }
    }
    for (int i2 = cRem[i].size() - 1; i2 >= 0; i2--) {
      auto &p = cRem[i][i2];
      m[p.y][p.x] = i;
      int pc = countComp(p.x, p.y, dsu);
      int adj = 0;
      if (p.x > 0 && m[p.y][p.x - 1] == i) {
        dsu.merge(p.x + p.y * w, p.x - 1 + p.y * w);
        adj++;
      }
      if (p.x < w - 1 && m[p.y][p.x + 1] == i) {
        dsu.merge(p.x + p.y * w, p.x + 1 + p.y * w);
        adj++;
      }
      if (p.y > 0 && m[p.y - 1][p.x] == i) {
        dsu.merge(p.x + p.y * w, p.x + (p.y - 1) * w);
        adj++;
      }
      if (p.y < h - 1 && m[p.y + 1][p.x] == i) {
        dsu.merge(p.x + p.y * w, p.x + (p.y + 1) * w);
        adj++;
      }
      if (adj == 0) {
        diff[p.time]--;
      } else {
        int cc = countComp(p.x, p.y, dsu);
        diff[p.time] =- cc - pc;
      }
    }
  }
  int ans = 1;
  for (int i = 0; i < q; i++) {
    ans += diff[i];
    printf("%d\n", ans);
  }
  return 0;
}

