      if (ki + 1 < n && mp[ki + 1][kj] == mp[ki][kj])
        unite(gid(ki + 1, kj), gid(ki, kj));
      if (kj + 1 < m && mp[ki][kj + 1] == mp[ki][kj])
        unite(gid(ki, kj + 1), gid(ki, kj));
    }
