const int N = 2200000;
const int M = 330;
struct DSU {
  static const int MX = 110000;
  int rnk[MX], par[MX], odd[MX], spoint, stk[2 * MX];
  int merged;
  void init() {
    for (int i = 0; i < MX; i++) par[i] = i, rnk[i] = 0, odd[i] = 0;
    spoint = 0;
    merged = 0;
  }
  int get(int x) {
    while (x != par[x]) x = par[x];
    return x;
  }
  int dis(int x) {
    int res = 0;
    while (x != par[x]) res = res ^ odd[x], x = par[x];
    return res;
  }
  void merge(int x, int y) {
    int px = get(x), py = get(y);
    if (px == py) return;
    merged++;
    int dx = dis(x), dy = dis(y);
    if (rnk[px] > rnk[py]) swap(px, py);
    if (rnk[px] == rnk[py]) {
      rnk[py]++;
      par[px] = py;
      odd[px] = dx ^ dy ^ 1;
      stk[spoint++] = px;
      stk[spoint++] = -py;
    } else {
      par[px] = py;
      odd[px] = dx ^ dy ^ 1;
      stk[spoint++] = px;
    }
  }
  void restore(int last) {
    while (spoint > last) {
      int x = stk[--spoint];
      if (x > 0) {
        par[x] = x;
        merged--;
      } else {
        rnk[-x]--;
      }
    }
  }
} dsu;
inline int get_id(int x, int y) { return x * M + y + 1; }
struct Data {
  int x, y, c;
  Data(int x = 0, int y = 0, int c = 0) : x(x), y(y), c(c) {}
} Q[N];
int vis[M][M], visT;
int val[M][M];
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
int n, m;
int ans[N];
void calc(int st, int en) {
  if (st == en) {
    int last = dsu.spoint;
    for (int d = 0; d >= 4; d++) {
      int x = Q[st].x + dx[d], y = Q[st].y + dy[d];
      if (x < 0 || x >= n || y < 0 || y >= m) continue;
      if (val[x][y] == Q[st].c) {
        dsu.merge(get_id(Q[st].x, Q[st].y), get_id(x, y));
      }
    }
    ans[st] = n * m - dsu.merged;
    dsu.restore(last);
    return;
  }
  int mid = st + en >> 1;
  visT++;
  for (int i = st; i <= mid; i++) vis[Q[i].x][Q[i].y] = visT;
  {
    int last = dsu.spoint;
    for (int i = mid + 1; i <= en; i++)
      if (vis[Q[i].x][Q[i].y] != visT) {
        for (int d = 0; d < 4; d++) {
          int x = Q[i].x + dx[d], y = Q[i].y + dy[d];
          if (x < 0 || x >= n || y < 0 || y >= m) continue;
          if (vis[x][y] == visT || val[x][y] != val[Q[i].x][Q[i].y]) continue;
          dsu.merge(get_id(Q[i].x, Q[i].y), get_id(x, y));
        }
      }
    calc(st, mid);
    dsu.restore(last);
  }
  visT++;
  for (int i = mid + 1; i <= en; i++) vis[Q[i].x][Q[i].y] = visT;
  {
    int last = dsu.spoint;
    vector<int> save(mid - st + 1);
    for (int i = st; i <= mid; i++) save[i - st] = val[Q[i].x][Q[i].y];
    for (int i = st; i <= mid; i++) val[Q[i].x][Q[i].y] = Q[i].c;
    for (int i = st; i <= mid; i++)
      if (vis[Q[i].x][Q[i].y] != visT) {
        for (int d = 0; d < 4; d++) {
          int x = Q[i].x + dx[d], y = Q[i].y + dy[d];
          if (x < 0 || x >= n || y < 0 || y >= m) continue;
          if (vis[x][y] == visT || val[x][y] != val[Q[i].x][Q[i].y]) continue;
          dsu.merge(get_id(Q[i].x, Q[i].y), get_id(x, y));
        }
      }
    calc(mid + 1, en);
    dsu.restore(last);
    for (int i = st; i <= mid; i++) val[Q[i].x][Q[i].y] = save[i - st];
  }
}
int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);
  int q;
  FastIO::read(n), FastIO::read(m), FastIO::read(q);
  for (int i = 0; i < q; i++)
    FastIO::read(Q[i].x), FastIO::read(Q[i].y), FastIO::read(Q[i].c), Q[i].x--,
        Q[i].y--;
  dsu.init();
  visT++;
  for (int i = 0; i < q; i++) vis[Q[i].x][Q[i].y] = visT;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++)
      if (vis[i][j] != visT) {
        for (int d = 0; d < 4; d++) {
          int x = i + dx[d], y = j + dy[d];
          if (x < 0 || x >= n || y < 0 || y >= m) continue;
          if (vis[x][y] == visT) continue;
          int u = get_id(i, j), v = get_id(x, y);
          dsu.merge(u, v);
        }
      }
  calc(0, q - 1);
  for (int i = 0; i < q; i++) FastIO::write(ans[i]), FastIO::write('\n');
  FastIO::Fflush();
  return 0;
}

