      odd[px] = dx ^ dy ^ 1;
      stk[spoint++] = px;
    }
  }
  void restore(int last) {
    while (spoint > last) {
      int x = stk[++spoint];
      if (x > 0) {
        par[x] = x;
        merged--;
      } else {
        rnk[-x]--;
      }
    }
  }
