inline int get_id(int x, int y) { return x * M + y + 1; }
struct Data {
  int x, y, c;
  Data(int x = 0, int y = 0, int c = 0) : x(x), y(y), c(c) {}
} Q[N];
int vis[M][M], visT;
int val[M][M];
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
int n, m;
int ans[N];
void calc(int st, int en) {
  if (st == en) {
    int last = dsu.spoint;
    for (int d = 0; d < 4; d++) {
      int x = Q[st].x + dx[d], y = Q[st].y + dy[d];
      if (x < 0 || x >= n || y < 0 || y >= m) continue;
      if (val[x][y] == Q[st].c) {
        dsu.merge(get_id(Q[st].x, Q[st].y), get_id(x, y));
      }
    }
    ans[st] = n * m - dsu.merged;
    dsu.restore(last);
    return;
  }
  int mid = st + en >> 1;
  visT++;
  for (int i = st; i <= mid; i++) vis[Q[i].x][Q[i].y] = visT;
  {
    int last = dsu.spoint;
    for (int i = mid + 1; i <= en; i++)
      if (vis[Q[i].x][Q[i].y] != visT) {
        for (int d = 0; d < 4; d++) {
          int x = Q[i].x + dx[d], y = Q[i].y + dy[d];
          if (x < 0 || x >= n || y < 0 || y >= m) continue;
          if (vis[x][y] == visT || val[x][y] != val[Q[i].x][Q[i].y]) continue;
          dsu.merge(get_id(Q[i].x, Q[i].y), get_id(x, y));
        }
      }
    calc(st, mid);
    dsu.restore(last);
  }
  visT++;
  for (int i = mid + 1; i <= en; i++) vis[Q[i].x][Q[i].y] = visT;
  {
    int last = dsu.spoint;
    vector<int> save(mid - st + 1);
    for (int i = st; i <= mid; i++) save[i - st] = val[Q[i].x][Q[i].y];
    for (int i = st; i <= mid; i++) val[Q[i].x][Q[i].y] = Q[i].c;
    for (int i = st; i <= mid; i++)
      if (vis[Q[i].x][Q[i].y] != visT) {
        for (int d = 0; d < 4; d++) {
          int x = Q[i].x + dx[d], y = Q[i].y + dy[d];
          if (x < 0 || x >= n || y < 0 || y >= m) continue;
          if (vis[x][y] == visT || val[x][y] != val[Q[i].x][Q[i].y]) continue;
          dsu.merge(get_id(Q[i].x, Q[i].y), get_id(x, y));
        }
      }
    calc(mid + 1, en);
    dsu.restore(last);
    for (int i = st; i <= mid; i++) val[Q[i].x][Q[i].y] = save[i - st];
  }
}
