std::pair<int, int> d[4] = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};
const std::pair<int, int> zero(0, 0);
struct mpp {
  int n, m;
  std::unordered_map<int, int> a;
  void clear() { a.clear(); }
  mpp(int _n, int _m) : n(_n), m(_m) {}
  ~mpp() {}
  std::pair<int, int> operator[](const std::pair<int, int> &p) {
    auto ret = a.find(id(p.first, p.second));
    if (ret == a.end())
      return zero;
    else
      return std::pair<int, int>(ret->second / m + 1, ret->second % m + 1);
  }
  void set(const std::pair<int, int> &p, const std::pair<int, int> &q) {
    a[id(p.first, p.second)] = id(q.first, q.second);
  }
  int id(int x, int y) { return x * m + y - m - 1; }
};
int n, m, q;
struct ColorCom {
  mpp f;
  int cnt;
  ColorCom() : f(n, m), cnt(0) {}
  std::pair<int, int> getf(const std::pair<int, int> &x) {
    std::pair<int, int> fa = f[x];
    if (fa == x)
      return x;
    else {
      std::pair<int, int> root = getf(fa);
      f.set(x, root);
      return root;
    }
  }
  void confirm(const std::pair<int, int> &x) {
    if (f[x] == zero) {
      f.set(x, x);
      ++cnt;
    }
  }
  void link(std::pair<int, int> x, std::pair<int, int> y) {
    x = getf(x);
    y = getf(y);
    if (x != y) {
