    if (i > 1 && c[i] != c[i - 1]) cur.clear();
    cur.confirm(std::pair<int, int>(x[i], y[i]));
    for (std::pair<int, int> mov : d) {
      std::pair<int, int> nxt(x[i] + mov.first, y[i] + mov.second);
      if (legal(nxt) && a[nxt.first][nxt.second] == c[i])
        cur.link(std::pair<int, int>(x[i], y[i]), nxt);
    }
    active[i] = cur.cnt;
  }
  active[0] = 1;
  ColorCom *colors = new ColorCom[c[q] + 1];
  for (int i = 1; i <= n; ++i)
    for (int j = 1; j <= m; ++j)
      colors[a[i][j]].confirm(std::pair<int, int>(i, j));
