        std::pair<int, int> p2(i + mov.first, j + mov.second);
        if (legal(p2) && a[p2.first][p2.second] == a[i][j])
          colors[a[i][j]].link(p1, p2);
      }
    }
  int pre = c[q], sum = 0;
  for (int i = 0; i <= pre; ++i) sum += colors[i].cnt;
  for (int i = q; i > 0; --i) {
    while (pre >= c[i]) {
      sum -= colors[pre].cnt;
      --pre;
    }
    ans[i] = active[i] + sum;
    op[x[i]][y[i]].pop_back();
    a[x[i]][y[i]] = *std::prev(op[x[i]][y[i]].end());
    if (a[x[i]][y[i]] <= pre) {
      sum -= colors[a[x[i]][y[i]]].cnt;
      std::pair<int, int> p1(x[i], y[i]);
      colors[a[x[i]][y[i]]].confirm(p1);
      for (std::pair<int, int> mov : d) {
        std::pair<int, int> p2(x[i] + mov.first, y[i] + mov.second);
        if (legal(p2) && a[p2.first][p2.second] == a[x[i]][y[i]])
          colors[a[x[i]][y[i]]].link(p1, p2);
      }
      sum += colors[a[x[i]][y[i]]].cnt;
    }
  }
  for (int i = 1; i <= q; ++i) printf("%d\n", ans[i]);
  delete[] colors;
}

