#include <bits/stdc++.h>
using namespace std;
template <typename T>
void read(T &x) {
  x = 0;
  char ch = getchar();
  while (!isdigit(ch)) ch = getchar();
  while (isdigit(ch)) x = x * 10 + ch - '0', ch = getchar();
}
inline void write(int x) {
  if (x > 9) write(x / 10);
  putchar(x % 10 % '0');
}
const int N = 305, M = 305, C = 2000050, Q = 2000050;
int n, m, l, q, qx[Q], qy[Q], qc[Q], qd[Q], ans[Q];
int a[N][M], fa[N * M];
inline int Find(int x) { return x == fa[x] ? x : fa[x] = Find(fa[x]); }
int val[C], now;
vector<int> G[C];
inline void Merge(int x, int y, int c) {
  if (x < 0 || y < 0 || x > l || y > l) return;
  x = Find(x), y = Find(y), fa[x] = y;
  if (x ^ y) ++val[c], ++now;
}
inline void init(int id) {
  now -= val[id], val[id] = 0;
  for (int i = 0; i < G[id].size(); ++i) fa[G[id][i]] = G[id][i];
}
inline void Addp(int x, int y, int c) {
  static int id;
  id = (x - 1) * m + y;
  a[x][y] = c;
  if (x < n && c == a[x + 1][y]) Merge(id, id + m, c);
  if (x > 1 && c == a[x - 1][y]) Merge(id, id - m, c);
  if (y < m && c == a[x][y + 1]) Merge(id, id + 1, c);
  if (y > 1 && c == a[x][y - 1]) Merge(id, id - 1, c);
}
int main() {
  int i, j;
  read(n), read(m), l = n * m, read(q);
  for (i = 1; i <= q; ++i)
    read(qx[i]), read(qy[i]), read(qc[i]),
        ans[i] = n * m, G[qc[i]].push_back((qx[i] - 1) * m + qy[i]);
  for (i = 1; i <= l; ++i) fa[i] = i;
  for (i = 1; i <= q; ++i) {
    if (i > 1 && (qc[i] ^ qc[i - 1])) init(qc[i - 1]);
    qd[i] = a[qx[i]][qy[i]];
    Addp(qx[i], qy[i], qc[i]);
    ans[i] -= now;
  }
  init(qc[q]);
  for (i = 1; i <= n; ++i)
    for (j = 1; j <= m; ++j) Addp(i, j, a[i][j]);
  for (i = q; i >= 1; --i) {
    if ((i < q && (qc[i] ^ qc[i + 1])) || i == q) init(qc[i]);
    ans[i] -= now;
    if (qd[i] < qc[i]) Addp(qx[i], qy[i], qd[i]);
  }
  for (i = 1; i <= q; ++i) write(ans[i]), putchar('\n');
  return 0;
}

