inline int getI(int x, int y) { return x * M + y; }
struct DisjointSet {
  int comps = 0;
  int V[MAXG];
  void reset() {
    for (int i = (0); i < (N * M); i++) V[i] = -INF;
    comps = 0;
  }
  int find(int i) {
    if (V[i] < 0) return i;
    int res = find(V[i]);
    V[i] = res;
    return res;
  }
  void merge(int a, int b) {
    a = find(a), b = find(b);
    if (a == b || V[a] == -INF || V[b] == -INF) return;
    comps--;
    if (V[a] < V[b]) {
      V[a] += V[b];
      V[b] = a;
    } else {
      V[b] += V[a];
      V[a] = b;
    }
  }
  void activate(int x, int y) {
