    if (q[i].col == q[i].org) continue;
    int x = q[i].x;
    int y = q[i].y;
    num = 1;
    a[x][y] = q[i].col;
    id[x][y] = ++tot;
    f[tot] = tot;
    change(x, y);
    ans[i] += num;
  }
}
