              dfs(row + 1, col, valrow, valcol);
  if (valid(row, col + 1) && !vis[row][col + 1] && p == mat[row][col + 1])
    vis[row][col + 1] = 1, ans[row][col + 1] = 'L',
                   dfs(row, col + 1, valrow, valcol);
  if (valid(row, col - 1) && !vis[row][col - 1] && p == mat[row][col - 1])
    vis[row][col - 1] = 1, ans[row][col - 1] = 'R',
                   dfs(row, col - 1, valrow, valcol);
  if (valid(row - 1, col) && !vis[row - 1][col] && p == mat[row - 1][col])
    vis[row - 1][col] = 1, ans[row - 1][col] = 'D',
              dfs(row - 1, col, valrow, valcol);
