ll n;
ll jmpx[] = {-1, 1, 0, 0};
ll jmpy[] = {0, 0, -1, 1};
char forw[] = "UDLR";
bool help_bfs(ll x, ll y) {
  for (ll i = 0; i < 4; i++)
    if (ans[x + jmpx[i]][y + jmpy[i]] != '+' and
        g[x][y].first == g[x + jmpx[i]][y + jmpy[i]].first and
        g[x][y].second == g[x + jmpx[i]][y + jmpy[i]].second) {
      ans[x][y] = forw[i];
      return 1;
    }
  return 0;
}
bool bfs(ll x, ll y) {
  queue<pair<ll, ll>> q;
  for (ll i = 0; i < 4; i++) q.emplace(x + jmpx[i], y + jmpy[i]);
  while (q.size()) {
    auto now = q.front();
    q.pop();
    if (now.first <= 0 or now.second <= 0 or now.first > n or now.second > n or
        ans[now.first][now.second] != '+')
      continue;
    if (help_bfs(now.first, now.second))
      for (ll i = 0; i < 4; i++)
        q.emplace(now.first + jmpx[i], now.second + jmpy[i]);
  }
  return 1;
}
