              ans[i][k] = forw[t];
              if (ans[i + jmpx[t]][k + jmpy[t]] == '+')
                ans[i + jmpx[t]][k + jmpy[t]] = forw[t ^ 1];
              break;
            }
          if (isok == 0) return puts("INVALID") * 0;
        }
      }
  for (ll i = 1; i <= n; i++)
    for (ll k = 1; k <= n; k++)
