  cell a;
  a.x = xx;
  a.y = yy;
  a.ex = x;
  a.ey = y;
  return a;
}
cell mcell(int xx, int yy) {
  cell a;
  a.x = xx;
  a.y = yy;
  return a;
}
const int mx = 1e3 + 10;
int n;
char d[mx][mx];
bool checked[mx][mx];
cell c[mx][mx];
vector<cell> adj[mx][mx];
stack<cell> xs;
void maketheGraph();
void dfs(int x, int y);
void TCOXs();
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++) {
      cin >> c[i][j].ey >> c[i][j].ex;
      c[i][j].ex--;
      c[i][j].ey--;
      if (c[i][j].ey == i && c[i][j].ex == j) xs.push(mcell(i, j));
    }
  maketheGraph();
  while (xs.size()) {
    checked[xs.top().x][xs.top().y] = 1;
    d[xs.top().x][xs.top().y] = 'X';
    dfs(xs.top().x, xs.top().y);
    xs.pop();
  }
  TCOXs();
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      if (!checked[i][j]) {
        cout << "INVALID";
        return 0;
      }
  cout << "VALID\n";
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) cout << d[i][j];
    cout << endl;
  }
  return 0;
}
void dfs(int x, int y) {
  for (int i = 0; i <= adj[x][y].size(); i++) {
    if (c[adj[x][y][i].x][adj[x][y][i].y].ex == c[x][y].ex &&
        c[adj[x][y][i].x][adj[x][y][i].y].ey == c[x][y].ey &&
        !checked[adj[x][y][i].x][adj[x][y][i].y]) {
      checked[adj[x][y][i].x][adj[x][y][i].y] = 1;
      if (adj[x][y][i].x == x)
        if (adj[x][y][i].y == y - 1) d[adj[x][y][i].x][adj[x][y][i].y] = 'R';
      if (adj[x][y][i].y == y + 1) d[adj[x][y][i].x][adj[x][y][i].y] = 'L';
      if (adj[x][y][i].x == x - 1) d[adj[x][y][i].x][adj[x][y][i].y] = 'D';
      if (adj[x][y][i].x == x + 1) d[adj[x][y][i].x][adj[x][y][i].y] = 'U';
      dfs(adj[x][y][i].x, adj[x][y][i].y);
    }
  }
}
void TCOXs() {
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n - 1; j++)
      if (c[i][j].ex == -2 && c[i][j + 1].ex == -2)
        (d[i][j] = 'R', d[i][j + 1] = 'L',
         checked[i][j] = checked[i][j + 1] = 1);
  for (int j = 0; j < n; j++)
    for (int i = 0; i < n - 1; i++)
      if (c[i][j].ex == -2 && c[i + 1][j].ex == -2)
        (d[i][j] = 'D', d[i + 1][j] = 'U',
         checked[i][j] = checked[i + 1][j] = 1);
}
void maketheGraph() {
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++) {
      if (i == 0) {
        adj[i][j].push_back(mcell(i + 1, j));
        if (j == 0)
          adj[i][j].push_back(mcell(i, j + 1));
        else if (j == n - 1)
          adj[i][j].push_back(mcell(i, j - 1));
        else {
          adj[i][j].push_back(mcell(i, j + 1));
          adj[i][j].push_back(mcell(i, j - 1));
        }
      } else if (i == n - 1) {
        adj[i][j].push_back(mcell(i - 1, j));
        if (j == 0)
          adj[i][j].push_back(mcell(i, j + 1));
        else if (j == n - 1)
          adj[i][j].push_back(mcell(i, j - 1));
        else {
          adj[i][j].push_back(mcell(i, j + 1));
          adj[i][j].push_back(mcell(i, j - 1));
        }
      } else {
        adj[i][j].push_back(mcell(i + 1, j));
        adj[i][j].push_back(mcell(i - 1, j));
        if (j == 0)
          adj[i][j].push_back(mcell(i, j + 1));
        else if (j == n - 1)
          adj[i][j].push_back(mcell(i, j - 1));
        else {
          adj[i][j].push_back(mcell(i, j + 1));
          adj[i][j].push_back(mcell(i, j - 1));
        }
      }
    }
}

