int vis[N][N];
int dir[N][N];
vector<pair<int, int>> nodes;
void dfs(int x, int y, int sx, int sy) {
  vis[x][y] = 1;
  for (int k = 0; k < 4; k++) {
    int xx = x + dx[k], yy = y + dy[k];
    if (xx >= 1 && xx <= n && yy >= 1 && yy <= n && X[xx][yy] == sx &&
        Y[xx][yy] == sy && vis[xx][yy] == 0) {
      dir[xx][yy] = k;
      dfs(xx, yy, sx, sy);
    }
  }
}
void cycle_dfs(int x, int y) {
  vis[x][y] = 1;
  nodes.push_back({x, y});
  for (int k = 0; k < 4; k++) {
    int xx = x + dx[k], yy = y + dy[k];
    if (xx >= 1 && xx <= n && yy >= 1 && yy <= n && X[xx][yy] == -1 &&
        vis[xx][yy] == 0) {
      dir[xx][yy] = k;
      cycle_dfs(xx, yy);
    }
  }
}
