      for (int k = 0; k < 4; k++) {
        int xx = t1.first + dx[k], yy = t1.second + dy[k];
        if (make_pair(xx, yy) == t2) {
          dir[t1.first][t1.second] = k;
          dir[t1.first][t1.second] = (k + 2) % 4;
          break;
        }
