#include <bits/stdc++.h>
using namespace std;
char dp[1002][1002];
int v[1002][2002];
int n;
void dfs(int x, int y) {
  if (x - 1 >= 0 && v[x - 1][2 * y] == v[x][2 * y] &&
      v[x - 1][2 * y + 1] == v[x][2 * y + 1] && dp[x - 1][y] == 'Y') {
    dp[x - 1][y] = 'D';
    dfs(x - 1, y);
  }
  if (x + 1 < n && v[x][2 * y] == v[x + 1][2 * y] &&
      v[x][2 * y + 1] == v[x + 1][2 * y + 1] && dp[x + 1][y] == 'Y') {
    dp[x + 1][y] = 'U';
    dfs(x + 1, y);
  }
  if (y - 1 >= 0 && v[x][2 * y] == v[x][2 * y - 2] &&
      v[x][2 * y - 1] == v[x][2 * y + 1] && dp[x][y - 1] == 'Y') {
    dp[x][y - 1] = 'R';
    dfs(x, y - 1);
  }
  if (y + 1 < n && v[x][2 * y] == v[x][2 * y + 2] &&
      v[x][2 * y + 1] == v[x][2 * y + 3] && dp[x][y + 1] == 'Y') {
    dp[x][y + 1] = 'L';
    dfs(x, y + 1);
  }
  return;
}
bool solve(int x, int y, int a, int b) {
  if (x < 0 || x >= n || y < 0 || y >= 2 * n)
    return true;
  else if (dp[x][y] != 'Y') {
    return true;
  } else if (((a - 1 >= 0 && v[a - 1][2 * b] != -1) || a - 1 < 0) &&
             ((a + 1 < n && v[a + 1][2 * b] != -1) || a + 1 >= n) &&
             ((b - 1 >= 0 && v[a][2 * b - 2] != -1) || b - 1 < 0) &&
             ((b + 1 < n && v[a][2 * b + 2] != -1) || b + 1 >= n)) {
    return false;
  } else if (x + 1 < n && v[x + 1][2 * y] == -1) {
    dp[x][y] = 'D';
    return solve(x + 1, y, a, b);
  } else if (x - 1 >= 0 && v[x - 1][2 * y] == -1) {
    dp[x][y] = 'U';
    return solve(x - 1, y, a, b);
  } else if (2 * y - 2 >= 0 && v[x][2 * y - 2] == -1) {
    dp[x][y] = 'L';
    return solve(x, y - 1, a, b);
  } else if (2 * y + 2 < 2 * n && v[x][2 * y + 2] == -1) {
    dp[x][y] = 'R';
    return solve(x, y + 1, a, b);
  }
  return true;
}
