        x--, y--;
        v[i][2 * j] = x;
        v[i][2 * j + 1] = y;
        help.insert({x, y});
        dp[x][y] = 'X';
      } else {
        v[i][2 * j] = x;
        v[i][2 * j + 1] = y;
      }
    }
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (v[i][2 * j] == -1 && dp[i][j] == 'Y') {
