        if (d[i][j] == 0) printf("L");
        if (d[i][j] == 1) printf("R");
        if (d[i][j] == 2) printf("U");
        if (d[i][j] == 3) printf("D");
      }
    }
    printf("\n");
  }
  return 0;
}

