      cur.second == inMatrix[a - 1][b].second) {
    dfs(a - 1, b, 'D');
  }
  if (a + 1 <= n && cur.first == inMatrix[a + 1][b].first &&
      cur.second == inMatrix[a + 1][b].second) {
