const int MAXN = 1e3 / 5;
int ans[MAXN][MAXN];
bool suc;
int dirs[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
int n;
void solve_Normal(pair<int, int> tag, vector<pair<int, int>>& nodes) {
  if (suc == false) return;
  unordered_map<int, int> has;
  for (auto ele : nodes) {
    has[ele.first * n + ele.second] = 0;
  }
  if (has.find(tag.first * n + tag.second) == has.end()) {
    suc = false;
    return;
  }
  queue<pair<int, int>> Q;
  has[tag.first * n + tag.second] = 1;
  Q.push(tag);
  ans[tag.first][tag.second] = 0;
  int cnt = 0;
  while (!Q.empty()) {
    auto ele = Q.front();
    Q.pop();
    cnt++;
    for (int i = 0; i < 4; ++i) {
      int xx = ele.first + dirs[i][0];
      int yy = ele.second + dirs[i][1];
      int id = xx * n + yy;
      if (xx >= 0 && xx < n && yy >= 0 && yy < n && has.find(id) != has.end() &&
          has[id] == 0) {
        has[id]++;
        ans[xx][yy] = i + 1;
        Q.push({xx, yy});
      }
    }
  }
  if (cnt != nodes.size()) {
    suc = false;
    return;
  }
}
void solve_Circle(pair<int, int> tag, vector<pair<int, int>>& nodes) {
  if (suc == false) return;
  if (nodes.size() == 1) {
    suc = false;
    return;
  }
  unordered_set<int> chooseList;
  unordered_map<int, int> has;
  for (auto ele : nodes) {
    has[ele.first * n + ele.second] = 0;
    chooseList.insert(ele.first * n + ele.second);
  }
  int allCnt = 0;
  queue<pair<int, int>> Q;
  while (!chooseList.empty()) {
    int firstNode = *chooseList.begin();
    has[firstNode] = 1;
    Q.push({firstNode / n, firstNode % n});
    int cnt = 1;
    while (!Q.empty()) {
      auto ele = Q.front();
      Q.pop();
      chooseList.erase(ele.first * n + ele.second);
      for (int i = 0; i < 4; ++i) {
        int xx = ele.first + dirs[i][0];
        int yy = ele.second + dirs[i][1];
        int id = xx * n + yy;
        if (xx >= 0 && xx < n && yy >= 0 && yy < n &&
            has.find(id) != has.end() && has[id] == 0) {
          has[id]++;
          ans[xx][yy] = i + 1;
          Q.push({xx, yy});
          cnt++;
          if (cnt == 2) {
            ans[ele.first][ele.second] = (i ^ 1) + 1;
          }
        }
      }
    }
    if (cnt < 2) {
      suc = false;
      return;
    }
    allCnt += cnt;
  }
  if (allCnt != nodes.size()) {
    suc = false;
    return;
  }
}
int main() {
  while (~scanf("%d", &n)) {
    map<pair<int, int>, vector<pair<int, int>>> mp;
    suc = true;
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        ans[i][j] = -1;
        int t1, t2;
        scanf("%d %d", &t1, &t2);
        t1--;
        t2--;
        mp[{t1, t2}].push_back({i, j});
      }
    }
    for (auto it : mp) {
      pair<int, int> tag = it.first;
      vector<pair<int, int>>& nodes = it.second;
      if (tag.first != -2)
        solve_Normal(tag, nodes);
      else
        solve_Circle(tag, nodes);
    }
    if (suc == true) {
      printf("VALID\n");
      for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
          if (ans[i][j] == 0)
            printf("X");
          else if (ans[i][j] == 1)
            printf("L");
          else if (ans[i][j] == 2)
            printf("R");
          else if (ans[i][j] == 3)
            printf("U");
          else if (ans[i][j] == 4)
            printf("D");
          else
            printf("S");
        }
        printf("\n");
      }
    } else {
      printf("INVALID\n");
    }
  }
  return 0;
}

