int n;
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
bool isvalid(int i, int j) {
  if (i < 0 || j < 0 || i >= n || j >= n) return 0;
  return 1;
}
void color(int i, int j) {
  if (i < 0 || j < 0 || i >= n || j >= n || ans[i][j] == 'Z' || x[i][j] != -1 ||
      y[i][j] != -1)
    return;
  ans[i][j] = 'Z';
  for (int k = 0; k < 4; k++) color(i + dx[k], j + dy[k]);
}
void DFS(int i, int j, char ch, int ka, int kh) {
  if (i < 0 || j < 0 || i >= n || j >= n || x[i][j] == -1 || ans[i][j] != 'K')
    return;
  ans[i][j] = ch;
  if (isvalid(i + 1, j) && x[i + 1][j] == ka && y[i + 1][j] == kh) {
    DFS(i + 1, j, 'U', ka, kh);
  }
  if (isvalid(i - 1, j) && x[i - 1][j] == ka && y[i - 1][j] == kh) {
    DFS(i - 1, j, 'D', ka, kh);
  }
  if (isvalid(i, j + 1) && x[i][j + 1] == ka && y[i][j + 1] == kh) {
    DFS(i, j + 1, 'L', ka, kh);
  }
  if (isvalid(i, j - 1) && x[i][j - 1] == ka && y[i][j - 1] == kh) {
    DFS(i, j - 1, 'R', ka, kh);
  }
}
