      ans[i][j] = 'K';
    }
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (x[i][j] == -1 && y[i][j] == -1)
        color(i, j);
      else if (x[i][j] == i + 1 && y[i][j] == j + 1)
        DFS(i, j, 'X', i + 1, j + 1);
    }
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (ans[i][j] == 'Z') {
        if (isvalid(i + 1, j) && x[i + 1][j] == -1) {
          ans[i][j] = 'D';
          ans[i + 1][j] = 'U';
        } else if (isvalid(i - 1, j) && x[i - 1][j] == -1) {
          ans[i][j] = 'U';
          ans[i - 1][j] = 'D';
        } else if (isvalid(i, j + 1) && x[i][j + 1] == -1) {
          ans[i][j] = 'R';
          ans[i][j + 1] = 'L';
        } else if (isvalid(i, j - 1) && x[i][j - 1] == -1) {
          ans[i][j] = 'L';
          ans[i][j - 1] = 'R';
        }
