long long dy[] = {0, 0, -1, 1};
bool vis[MX][MX];
pair<long long, long long> cel[MX][MX];
char ans[MX][MX];
void bfs(long long x, long long y) {
  deque<pair<long long, long long> > q;
  q.push_back(make_pair(x, y));
  while (!q.empty()) {
    x = q.front().first;
    y = q.front().second;
    q.pop_front();
    for (long long i = 0; i < 4; i++) {
      long long u = x + dx[i];
      long long v = y + dy[i];
      if (0 <= u && u < n && 0 <= v && v < n && !vis[u][v] &&
          cel[u][v] == cel[x][y]) {
        vis[u][v] = true;
        ans[u][v] = dir[i ^ 1];
        q.push_back(make_pair(u, v));
      }
    }
  }
  return;
}
