#include <bits/stdc++.h>
using namespace std;
struct koor {
  int x, y;
  bool operator==(const koor other) const {
    return x == other.x && y == other.y;
  }
  bool operator!=(const koor other) const {
    return x != other.x || y != other.y;
  }
};
int n;
koor p[1005][1005], parent[1005][1005];
char a[1005][1005];
const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};
string arah = "LRUD";
koor findParent(koor cur) {
  if (parent[cur.x][cur.y] == cur) {
    return cur;
  } else {
    return parent[cur.x][cur.y] = findParent(parent[cur.x][cur.y]);
  }
}
void merge(koor one, koor two) {
  one = findParent(one);
  two = findParent(two);
  if (one != two) {
    parent[two.x][two.y] = one;
  }
}
bool solve() {
  queue<koor> q;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      a[i][j] = '.';
      parent[i][j] = {i, j};
      if (p[i][j].x == i && p[i][j].y == j) {
        q.push(p[i][j]);
        a[i][j] = 'X';
      }
    }
  }
  while (!q.empty()) {
    koor cur = q.front();
    q.pop();
    for (int i = 0; i < 4; i++) {
      koor nxt = {cur.x + dx[i], cur.y + dy[i]};
      if (nxt.x <= 0 || nxt.x > n || nxt.y <= 0 || nxt.y > n) {
        continue;
      }
      if (a[nxt.x][nxt.y] != '.') {
        continue;
      }
      if (findParent(cur) == p[nxt.x][nxt.y]) {
        q.push(nxt);
        merge(cur, nxt);
        a[nxt.x][nxt.y] = arah[i];
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      if (p[i][j].x != -1) continue;
      for (int k = 0; k < 4; k++) {
        koor nxt = {i + dx[k], j + dy[k]};
        if (nxt.x <= 0 || nxt.x > n || nxt.y <= 0 || nxt.y > n) {
          continue;
        }
        if (p[nxt.x][nxt.y].x == -1) {
          a[nxt.x][nxt.y] = arah[k];
        }
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j >= n; j++) {
      if (a[i][j] == '.') {
        return false;
      }
    }
  }
  return true;
}
