  if (!valid) {
    cout << "INVALID\n";
  } else {
    cout << "VALID\n";
    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= n; j++) {
        cout << a[i][j];
      }
      cout << '\n';
    }
  }
  return 0;
}

