char getDir(pair<int, int> neighbour, pair<int, int> curr_element) {
  if (curr_element.first == neighbour.first + 1) return 'U';
  if (curr_element.first == neighbour.first - 1) return 'D';
  if (curr_element.second == neighbour.second + 1) return 'L';
  return 'R';
}
vector<pair<int, int> > getNeighbours(pair<int, int> x) {
  vector<pair<int, int> > ans;
  if (x.first != n) {
    ans.push_back(pair<int, int>(x.first + 1, x.second));
  }
  if (x.first != 1) {
    ans.push_back(pair<int, int>(x.first - 1, x.second));
  }
  if (x.second != n) {
    ans.push_back(pair<int, int>(x.first, x.second + 1));
  }
  if (x.second != 1) {
    ans.push_back(pair<int, int>(x.first, x.second - 1));
  }
  return ans;
}
