bool edge(int x, int y) { return (x == 1 || y == 1 || x == n || y == m); }
void ngang() {
  for (int i = 1; i <= n; ++i) {
    int cnt = 0;
    for (int j = 1; j <= m; ++j) {
      if (grid[i][j] == '#') {
        if (grid[i][j - 1] != '#') ++cnt;
      }
      if (cnt > 1) {
        cout << -1;
        cerr << "\nngang";
        exit(0);
      }
    }
    if (cnt == 0) {
      fullrow = true;
    }
  }
}
void doc() {
  for (int j = 1; j <= m; ++j) {
    int cnt = 0;
    for (int i = 1; i <= n; ++i) {
      if (grid[i][j] == '#') {
        if (grid[i - 1][j] != '#') ++cnt;
      }
      if (cnt > 1) {
        cout << -1;
        cerr << "\ndoc";
        exit(0);
      }
    }
    if (cnt == 0) {
      fullcol = true;
    }
  }
