  visited[i][j] = true;
  for (int d = 0; d <= 3; ++d) {
    int x = i + drow[d];
    int y = j + dcol[d];
    if (!inside(x, y)) continue;
    if (grid[x][y] == '#') {
      if (!visited[x][y]) dfs(x, y);
    }
  }
}
