  while (s.empty()) {
    count++;
    pair<long long int, long long int> node = *s.begin();
    queue<pair<long long int, long long int> > q;
    q.push(node);
    s.erase(node);
    while (!q.empty()) {
      pair<long long int, long long int> x = q.front();
      q.pop();
      long long int i = x.first;
      long long int j = x.second;
      if (s.find(make_pair(i + 1, j)) != s.end()) {
        q.push(make_pair(i + 1, j));
        s.erase(make_pair(i + 1, j));
      }
      if (s.find(make_pair(i - 1, j)) != s.end()) {
        q.push(make_pair(i - 1, j));
        s.erase(make_pair(i - 1, j));
