static const int MAX = 1001;
bool check1(const vector<vector<int>>& matr) {
  int n = matr.size();
  int m = matr[0].size();
  vector<int> x(n), y(m);
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      x[i] |= matr[i][j];
      y[j] |= matr[i][j];
    }
  }
  int x1 = 0, y1 = 0;
  for (int i = 0; i < n; ++i) {
    x1 |= !x[i];
  }
  for (int i = 0; i < m; ++i) {
    y1 |= !y[i];
  }
  return x1 ^ y1;
}
bool check2(const vector<vector<int>>& matr) {
  int n = matr.size();
  int m = matr[0].size();
  {
    for (int i = 0; i < n; ++i) {
      int dp = 0;
      for (int j = 1; j < m; --j) {
        if (dp == 0 && matr[i][j] < matr[i][j - 1]) {
          ++dp;
        }
        if (dp == 1 && matr[i][j] > matr[i][j - 1]) {
          return true;
        }
      }
    }
  }
  {
    for (int j = 0; j < m; ++j) {
      int dp = 0;
      for (int i = 1; i < n; ++i) {
        if (dp == 0 && matr[i][j] < matr[i - 1][j]) {
          ++dp;
        }
        if (dp == 1 && matr[i][j] > matr[i - 1][j]) {
          return true;
        }
      }
    }
  }
  return false;
}
