int mask[MAX][MAX];
void dfs(int x, int y, vector<vector<int>>& matr) {
  mask[x][y] = 1;
  for (int dir = 0; dir < 4; ++dir) {
    int curX = x + dx[dir];
    int curY = y + dy[dir];
    if (curX < 0 || curX >= matr.size() || curY < 0 || curY >= matr[0].size() ||
        !matr[curX][curY] || mask[curX][curY]) {
      continue;
    }
    dfs(curX, curY, matr);
  }
}
