using namespace std;
const int maxn = 1e-1 + 5;
char str[maxn][maxn];
int n, m, dir[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int a[maxn][maxn], row[maxn][maxn], col[maxn][maxn];
int visx[maxn], visy[maxn], vis[maxn][maxn];
void dfs(int i, int j) {
  vis[i][j] = 1;
  for (int k = 0; k < 4; ++k) {
    int x = i + dir[k][0];
    int y = j + dir[k][1];
    if (x < 1 || x > n || y < 1 || y > m) continue;
    if (!a[x][y]) continue;
    if (vis[x][y]) continue;
    dfs(x, y);
  }
}
void solve() {
  int flg = 1;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j)
      if (!a[i][j]) {
        if (row[i][j] != 0 && row[i][j] != row[n][j]) flg = 0;
        if (col[i][j] != 0 && col[i][j] != col[i][m]) flg = 0;
        if (row[n][j] != 0 && col[i][m] == 0 && !visx[i]) visx[i] = 1;
        if (row[n][j] == 0 && col[i][m] != 0 && !visy[j]) visy[j] = 1;
        if (row[n][j] == 0 && col[i][m] == 0) visx[i] = visy[j] = 2;
        if (!flg) {
          puts("-1");
          return;
        }
      }
  }
  for (int i = 1; i <= n; ++i)
    if (visx[i] == 1) flg = 0;
  for (int i = 1; i <= m; ++i)
    if (visy[i] == 1) flg = 0;
  if (!flg) {
    puts("-1");
    return;
  }
  int ans = 0;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j)
      if (a[i][j] && !vis[i][j]) {
        ans++;
        dfs(i, j);
      }
  }
  printf("%d\n", ans);
}
int main() {
  scanf("%d%d", &n, &m);
  for (int i = 1; i <= n; ++i) {
    scanf("%s", str[i] + 1);
    for (int j = 1; j <= m; ++j) {
      a[i][j] = str[i][j] == '#';
      row[i][j] = row[i - 1][j] + a[i][j];
      col[i][j] = col[i][j - 1] + a[i][j];
    }
  }
  solve();
}

