  return x < 0 ? -x : x;
}
template <typename T>
T sqr(T x) {
  return x * x;
}
int n, m, pai[((int)1e3 + 123) * ((int)1e3 + 123)], last[((int)1e3 + 123)],
    pode, row, col;
int valor(int i, int j) { return i * m + j; }
void inicia() {
  for (int i = 0; i <= n * m; i++) pai[i] = i;
}
int id(int u) { return pai[u] = (u == pai[u] ? u : id(pai[u])); }
