#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct DSU {
  int nbElem;
  vector<int> repr, weight;
  DSU(int ta) : nbElem(ta), repr(ta), weight(ta, 1) {
    iota(repr.begin(), repr.end(), 0);
  }
  int get(int x) {
    if (repr[x] != x) repr[x] = get(repr[x]);
    return repr[x];
  }
  bool unite(int a, int b) {
    a = get(a);
    b = get(b);
    if (a == b) return false;
    if (weight[a] < weight[b]) swap(a, b);
    repr[b] = a;
    weight[a] += weight[b];
    return true;
  }
};
const int lim = 1000;
char raw[lim][lim];
int nbLig, nbCol;
inline int conv(int mode, int lig, int col) {
  if (mode) swap(lig, col);
  return lig * nbCol + col;
}
inline char &get(int mode, int c1, int c2) {
  return (mode == 0 ? raw[c1][c2] : raw[c2][c1]);
}
bool emp[2];
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> nbLig >> nbCol;
  for (int lig = 0; lig < nbLig; ++lig) {
    for (int col = 0; col < nbCol; ++col) {
      cin >> raw[lig][col];
    }
  }
  DSU uf(nbLig * nbCol);
  for (int mode = 0; mode < 2; ++mode) {
    int k1 = nbLig, k2 = nbCol;
    if (mode) swap(k1, k2);
    for (int c1 = 0; c1 < k1; ++c1) {
      int prev = -1;
      for (int c2 = 0; c2 < k2; ++c2) {
        if (get(mode , c2, c1) == '#') {
          if (prev != -1) {
            if (prev + 1 < c2) {
              cout << "-1\n";
              return 0;
            }
            uf.unite(conv(mode, c1, c2), conv(mode, c1, prev));
          }
          prev = c2;
        }
      }
      emp[mode] |= (prev == -1);
    }
  }
  int rep = 0;
  for (int lig = 0; lig < nbLig; ++lig) {
    for (int col = 0; col < nbCol; ++col) {
      int cc = conv(0, lig, col);
      if (raw[lig][col] == '#' && cc == uf.repr[cc]) {
        ++rep;
      }
    }
  }
  if (emp[0] ^ emp[1]) {
    rep = -1;
  }
  cout << rep << "\n";
  return 0;
}

