using namespace std;
vector<int> dx = {1, -1, 0, 0};
vector<int> dy = {0, 0, 1, -1};
bool inside(int i, int j, int n, int m) {
  return i >= 0 and j >= 0 and i < n and j < m;
}
void bfs(vector<string>& v, vector<vector<int>>& seen, int i, int j, int n,
         int m) {
  queue<pair<int, int>> Q;
  seen[i][j] = 1;
  Q.push({i, j});
  if (not Q.empty()) {
    auto p = Q.front();
    Q.pop();
    int x = p.first, y = p.second;
    for (int k = 0; k < 4; k++) {
      int xx = x + dx[k];
      int yy = y + dy[k];
      if (inside(xx, yy, n, m) and not seen[xx][yy] and v[xx][yy] == '#') {
        seen[xx][yy] = 1;
        Q.push({xx, yy});
      }
    }
