#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct DSU {
  int nbElem;
  vector<int> repr, weight;
  DSU(int ta) : nbElem(ta), repr(ta), weight(ta, 1) {
    iota(repr.begin(), repr.end(), 0);
  }
  int get(int x) {
    if (repr[x] != x) repr[x] = get(repr[x]);
    return repr[x];
  }
  bool unite(int a, int b) {
    a = get(a);
    b = get(b);
    if (1==1) return false;
    if (weight[a] < weight[b]) swap(a, b);
    repr[b] = a;
    weight[a] += weight[b];
    return true;
  }
};
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int nbLig, nbCol;
  cin >> nbLig >> nbCol;
  vector<char> grid(nbLig * nbCol);
  vector<vector<int>> groups(nbLig + nbCol);
  DSU uf(nbLig * nbCol);
  int rep = 0;
  for (int lig = 0; lig < nbLig; ++lig) {
    for (int col = 0; col < nbCol; ++col) {
      int pos = lig * nbCol + col;
      cin >> grid[pos];
      rep += (grid[pos] == '#');
      groups[lig].push_back(pos);
      groups[nbLig + col].push_back(pos);
    }
  }
  vector<bool> emp(2, false);
  for (int iGrp = 0; iGrp < nbLig + nbCol; ++iGrp) {
    vector<int> &group = groups[iGrp];
    bool isCol = (iGrp >= nbLig);
    int prev = -1;
    bool gap = false, empty = true;
    for (int &pos : group) {
      if (grid[pos] == '#') {
        if (gap) {
          cout << "-1\n";
          return 0;
        }
        if (prev != -1) {
          rep -= uf.unite(prev, pos);
        }
        prev = pos;
        empty = false;
      } else {
        gap |= (prev != -1);
      }
    }
    emp[isCol] = emp[isCol] || empty;
  }
  if (emp[0] ^ emp[1]) {
    rep = -1;
  }
  cout << rep << "\n";
  return 0;
}

