using namespace std;
ifstream fin("input");
void init() {
  cin.tie(NULL);
  ios_base::sync_with_stdio(false);
}
const int mx = 1500;
int n, m, offx[4] = {0, 0, -1, 1}, offy[4] = {1, -1, 0, 0}, cnt = 0;
bool visited[mx][mx], cl[mx], cc[mx];
char g[mx][mx];
void read() {
  cin >> n >> m;
  for (int i = 0; i < n; i++) {
    for (int k = 0; k < m; k++) {
      cin >> g[i][k];
      if (g[i][k] == '#') cnt++;
    }
  }
}
bool inside(int x, int y) { return x >= 0 && x < m && y >= 0 && y < n; }
void fill(int x, int y) {
  visited[y][x] = true;
  for (int i = 0; i < 4; i++) {
    int newx = x + offx[i], newy = y + offy[i];
    if (inside(newx, newy) && !visited[newy][newx] && g[newy][newx] == '#')
      fill(newx, newy);
  }
}
bool compll = false, complc = false;
bool check_lines() {
  for (int i = 0; i < n; i++) {
    int start = -1, end = -1;
    for (int k = 0; k < m; k++) {
      if (g[i][k] == '#') {
        if (start == -1) start = k;
        end = k;
        cl[i] = true;
      }
    }
    if (start != -1) {
      for (int k = start; k <= end; k++) {
        if (g[i][k] = '#') return false;
      }
    }
    if (start == -1) compll = true;
  }
  return true;
}
bool check_columns() {
  for (int i = 0; i < m; i++) {
    int start = -1, end = -1;
    for (int k = 0; k < n; k++) {
      if (g[k][i] == '#') {
        if (start == -1) start = k;
        end = k;
        cc[i] = true;
      }
    }
    if (start != -1) {
      for (int k = start; k <= end; k++) {
        if (g[k][i] != '#') return false;
      }
    }
    if (start == -1) complc = true;
  }
  return true;
}
int solve() {
  if (cnt == 0) return 0;
  if (!check_lines() || !check_columns()) {
    return -1;
  }
  if (compll != complc) return -1;
  int total = 0;
  for (int i = 0; i < n; i++) {
    for (int k = 0; k < m; k++) {
      if (g[i][k] == '#' && !visited[i][k]) {
        fill(k, i);
        total++;
      }
    }
  }
  return total;
}
int main() {
  init();
  read();
  cout << solve();
  return 0;
}

