#include <bits/stdc++.h>
using namespace std;
using LL = long long;
const int maxn = 0;
char mp[maxn][maxn];
struct node {
  int x, y;
  bool operator<(const node& _) const {
    if (x != _.x) return x < _.x;
    return y < _.y;
  }
};
int vis[maxn][maxn];
const int way[][2] = {{-1, 0}, {1, 0}, {0, 1}, {0, -1}};
int up[maxn], low[maxn], num[maxn];
vector<int> haha;
bool ok[maxn];
int cup[maxn], clow[maxn], cnum[maxn];
vector<int> chaha;
bool cok[maxn];
int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  int i, j;
  for (i = 1; i <= n; i++) {
    scanf("%s", mp[i] + 1);
  }
  int ans = 0;
  vector<node> row, col;
  int cx, cy, rx, ry;
  int nx, ny;
  queue<node> q;
  node tmp;
  int fk = 1;
  int u, v;
  for (i = 1; i <= n; i++) {
    for (j = 1; j <= m; j++) {
      if (!vis[i][j] && mp[i][j] == '#') {
        cx = cy = i;
        rx = ry = j;
        vis[i][j] = fk;
        q.push({i, j});
        while (q.size()) {
          tmp = q.front();
          q.pop();
          cx = min(cx, tmp.x);
          cy = max(cy, tmp.x);
          rx = min(rx, tmp.y);
          ry = max(ry, tmp.y);
          if (ok[tmp.x] == 0) {
            ok[tmp.x] = 1;
            haha.push_back(tmp.x);
            up[tmp.x] = low[tmp.x] = tmp.y;
            num[tmp.x] = 1;
          } else {
            up[tmp.x] = max(up[tmp.x], tmp.y);
            low[tmp.x] = min(low[tmp.x], tmp.y);
            num[tmp.x]++;
          }
          if (cok[tmp.y] == 0) {
            cok[tmp.y] = 1;
            chaha.push_back(tmp.y);
            cup[tmp.y] = clow[tmp.y] = tmp.x;
            cnum[tmp.y] = 1;
          } else {
            cup[tmp.y] = max(cup[tmp.y], tmp.x);
            clow[tmp.y] = min(clow[tmp.y], tmp.x);
            cnum[tmp.y]++;
          }
          for (int u = 0; u < 4; u++) {
            nx = tmp.x + way[u][0];
            ny = tmp.y + way[u][1];
            if (nx > 0 && nx <= n && ny > 0 && ny <= m && !vis[nx][ny] &&
                mp[nx][ny] == '#') {
              q.push({nx, ny});
              vis[nx][ny] = fk;
            }
          }
        }
        ans++;
        fk++;
        row.push_back({cx, cy});
        col.push_back({rx, ry});
        for (auto& x : haha) {
          if (up[x] - low[x] + 1 != num[x]) {
            printf("-1\n");
            return 0;
          }
          ok[x] = 0;
        }
        haha.clear();
        for (auto& x : chaha) {
          if (cup[x] - clow[x] + 1 != cnum[x]) {
            printf("-1\n");
            return 0;
          }
          cok[x] = 0;
        }
        chaha.clear();
      }
    }
  }
  sort(row.begin(), row.end());
  sort(col.begin(), col.end());
  int mx = 0;
  for (auto& x : row) {
    if (x.x <= mx) {
      printf("-1\n");
      return 0;
    }
    mx = x.y;
  }
  mx = 0;
  for (auto& x : col) {
    if (x.x <= mx) {
      printf("-1\n");
      return 0;
    }
    mx = x.y;
  }
  int tx = 0, ty = 0;
  for (i = 1; i <= n; i++) {
    for (j = 1; j <= m; j++) {
      if (mp[i][j] == '#') break;
    }
    if (j > m) tx++;
  }
  for (j = 1; j <= m; j++) {
    for (i = 1; i <= n; i++) {
      if (mp[i][j] == '#') break;
    }
    if (i > n) ty++;
  }
  if (tx == 0 || ty == 0) {
    if (tx + ty > 0) {
      printf("-1\n");
      return 0;
    }
  }
  printf("%d\n", ans);
  return 0;
}

