  for (int i = 0; i < m; i++) {
    bool judge = false;
    for (int j = 0; j < n; j++) {
      if (g[j][i] != 'z') judge = true;
    }
    if (!judge) {
      cout << -1 << "\n";
      return;
    }
  }
  vector<vector<bool>> visited = vect(n, vect(m, false));
  vector<int> dx = {0, 1, 0, -1};
  vector<int> dy = {1, 0, -1, 0};
  function<void(int, int)> dfs = [&](int x, int y) {
    visited[x][y] = true;
    for (int i = 0; i < 4; i++) {
      int nx = x + dx[i];
      int ny = y + dy[i];
      if (nx < 0 || ny < 0 || nx >= n || ny >= m) continue;
      if (f[nx][ny] != '#') continue;
      if (visited[nx][ny]) continue;
      dfs(nx, ny);
    }
  };
  int cmp = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (f[i][j] == '#' && !visited[i][j]) {
        dfs(i, j);
        cmp++;
      }
    }
  }
  cout << cmp << "\n";
