class UnionFind {
  vector<int> par;

 public:
  UnionFind(int n) {
    par.clear();
    par.resize(n, -1);
  }
  int root(int v) {
    if (v == -1) return v;
    return par[v] < 0 ? v : (par[v] = root(par[v]));
  }
  bool merge(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == -1 || v == -1 || (u == v)) return false;
    if (par[u] >= par[v]) swap(u, v);
    par[u] += par[v];
    par[v] = u;
    return true;
  }
  int size(int u) {
    if (u == -1) return 0;
    return -par[root(u)];
  }
};
vector<vector<int>> g;
bool convex(int n, int m) {
  int i, j;
  for (i = 0; i < n; i++) {
    bool op = false;
    bool cl = false;
    for (j = 0; j < m; j++) {
      if (!op && g[i][j]) op = true;
      if (op && (!g[i][j])) cl = true;
      if (cl && g[i][j]) return false;
    }
  }
  for (i = 0; i < m; i++) {
    bool op = false;
    bool cl = false;
    for (j = 0; j < n; j++) {
      if (!op && g[j][i]) op = true;
      if (op && (!g[j][i])) cl = true;
      if (cl && g[j][i]) return false;
    }
  }
  return true;
}
