    for (j = 0; j < m; j++) {
      g[i][j] = s[j] == '.' ? 0 : 1;
    }
  }
  if (!convex(n, m)) {
    cout << -1 << endl;
    return 0;
  }
  auto uf = UnionFind(n * m);
  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      if (!g[i][j]) continue;
      int u = i * m + j;
      int v;
      if (j > 0 && g[i][j - 1]) {
        v = i * m + (j - 1);
