    bool ok = false;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if ((a[i][j] == 'G' && !vis[i][j]) || (a[i][j] == 'B' && vis[i][j])) {
          ok = true;
