        vis[r][c + 1] = true;
      }
    }
  }
  for (ll i = 0; i < n; i++) {
    for (ll j = 0; j < m; j++) {
      if (s[i][j] == 'G' && vis[i][j] == false) {
        cout << "No\n";
        return;
      }
    }
  }
  cout << "Yes\n";
  return;
