bool Solve1() {
  int res = 0;
  for (int i = (1); i <= (H); ++i) {
    G[i][1] = 0;
    for (int j = (2); j <= (W); ++j)
      G[i][j] = (hor[i][j - 1] == 'E') ? G[i][j - 1] : G[i][j - 1] ^ 1;
    if (i == 1) continue;
    int cnt = 0;
    for (int j = (1); j <= (W); ++j)
      if (ver[i - 1][j] == 'E')
        cnt += (G[i - 1][j] == G[i][j]);
      else
        cnt += (G[i - 1][j] != G[i][j]);
    if (cnt >= W - cnt) {
      res += W - cnt;
      continue;
    }
    for (int j = (1); j <= (W); ++j) G[i][j] ^= 1;
    res += cnt;
  }
  if (tot >= res * 4) {
    puts("YES");
    for (int i = (1); i <= (H); ++i)
      for (int j = (1); j <= (W); ++j)
        printf("%d%c", G[i][j] + 1, j == W ? '\n' : ' ');
    return true;
  }
  return false;
}
