    for (int j = 1; j <= M; j++) X += (B[i][j] == 'E');
  return X;
}
inline int getOpposite(const int &val) { return 3 - val; }
void completeMatrix() {
  for (int i = 1; i <= N; i++) {
    val[i][1] = 1;
    for (int j = 2; j <= M; j++)
      if (R[i][j - 1] == 'N')
        val[i][j] = getOpposite(val[i][j - 1]);
      else
        val[i][j] = val[i][j - 1];
