  ans[0][i] = 1;
  for (int j = 1; j < h; j++)
    if (s[j * 2 - 1][i] == 'E')
      ans[j][i] = ans[j - 1][i];
    else
      ans[j][i] = (ans[j - 1][i]) % 2 + 1;
}
