  for (int i = w - 1; i >= 0; i--)
    for (int j = 1; j < 2 * h - 1; j += 2) c[(w - 1 - i) * 2][j / 2] = s[j][i];
  for (int i = w - 2; i >= 0; i--)
    for (int j = 0; j < 2 * h - 1; j += 2)
      c[(w - 2 - i) * 2 + 1][(j / 2)] = s[j][i];
  swap(h, w);
  for (int i = 0; i < 2 * h - 1; i++) {
    s[i].clear();
    for (int j = 0; j < w; j++) s[i].push_back(c[i][j]);
  }
}
