  for (int i = 0; i < h; i++)
    for (int j = 0; j < w; j++) t[j][h - i - 1] = ans[i][j];
  swap(h, w);
  for (int i = 0; i < h; i++)
    for (int j = 0; j < w; j++) ans[i][j] = t[i][j];
}
