  if (k == 1) {
    bal = 0;
    for (i = 0; i <= 2 * n - 2; i++)
      for (j = 0; j < m - 1 + (i & 1); j++)
        (s[i][j] == 'E') ? (bal++) : (bal -= 3);
    if (bal < 0) {
      puts("NO");
      return 0;
    }
    puts("YES");
    for (i = 0; i < n; i++, printf("\n"))
      for (j = 0; j < m; j++) printf("1 ");
    return 0;
  }
  if (n * (m - 1) < m * (n - 1)) {
    inv = 1, memcpy(ss, s, sizeof(s)), memset(s, 0, sizeof(s));
    for (i = 0; i <= 2 * n - 2; i++)
      for (j = 0; j < m - 1 + (i & 1); j++) {
        if ((i & 1) == 0) {
          s[2 * j + 1][i >> 1] = ss[i][j];
          continue;
        }
        s[2 * j][i >> 1] = ss[i][j];
      }
    swap(n, m);
  }
  for (i = 0; i < n; i++) {
    for (j = 1; j < m; j++)
      (s[2 * i][j - 1] == 'E') ? (C[i][j] = C[i][j - 1])
                               : (C[i][j] = C[i][j - 1] ^ 1);
    if (i == 0) continue;
    bal = 0;
