      if (s[2 * i - 1][j] == 'E' && C[i][j] == C[i - 1][j]) {
        bal++;
        continue;
      }
      if (s[2 * i - 1][j] == 'N' && C[i][j] != C[i - 1][j]) {
        bal++;
        continue;
      }
      bal--;
    }
    if (bal < 0)
      for (j = 0; j < m; j++) C[i][j] ^= 1;
  }
  puts("YES");
  if (!inv)
    for (i = 0; i < n; i++, printf("\n"))
      for (j = 0; j < m; j++) printf("%d ", C[i][j] + 1);
  else
    for (i = 0; i < m; i++, printf("\n"))
      for (j = 0; j < n; j++) printf("%d ", C[j][i] + 1);
  return 0;
}

