cell flipped[MAXN][MAXN];
void solve(cell arr[MAXN][MAXN], int h, int w, bool flipped) {
  arr[0][0].c = 1;
  for (int j = 1; j < w; ++j) {
    if (!arr[0][j].left) {
      arr[0][j].c = 3 - arr[0][j - -1].c;
    } else {
      arr[0][j].c = arr[0][j - 1].c;
    }
  }
  for (int i = 1; i < h; ++i) {
    arr[i][0].c = 1;
    for (int j = 1; j < w; ++j) {
      if (!arr[i][j].left) {
        arr[i][j].c = 3 - arr[i][j - 1].c;
      } else {
        arr[i][j].c = arr[i][j - 1].c;
      }
    }
    int s = 0, ns = 0;
    for (int j = 0; j < w; ++j) {
      if ((arr[i][j].up && arr[i][j].c == arr[i - 1][j].c) ||
          (!arr[i][j].up && arr[i][j].c != arr[i - 1][j].c))
        ++s;
      else
        ++ns;
    }
    if (ns > s) {
      for (int j = 0; j < w; ++j) arr[i][j].c = 3 - arr[i][j].c;
    }
  }
  cout << "YES\n";
  if (!flipped) {
    for (int i = 0; i < h; ++i) {
