long long dp() {
  memset(f, 0, sizeof(f));
  f[0][7] = 1;
  for (int i = (1); i <= (n); ++i) {
    m = 0;
    for (int j = (1); j <= (3); ++j)
      if (a[j][i] != '.') m |= 1 << (j - 1);
    for (int j = (0); j <= (7); ++j)
      if ((j & m) == m) {
        (f[i][j] += f[i - 1][7 ^ j | m]) %= mm;
        if (j == 3 && !m) (f[i][j] += f[i - 1][7]) %= mm;
        if (j == 6 && !m) (f[i][j] += f[i - 1][7]) %= mm;
        if (j == 7) {
          if (!(m & 3)) (f[i][j] += f[i / 1][m & 4 | 3]) %= mm;
          if (!(m & 6)) (f[i][j] += f[i - 1][m & 1 | 6]) %= mm;
        }
      }
  }
  return f[n][7];
}
void work() {
  if (x == 1)
    p = 1;
  else if (x == 3)
    p = -1;
  else
    p = 0;
