        continue;
      else
        k++;
    if (i & 4)
      if (!(p && a[x + p][y] == '.' && a[x + p + p][y] == '.'))
        continue;
      else
        k++;
    if (i & 1) a[x][y - 1] = a[x][y - 2] = 'X';
    if (i & 2) a[x][y + 1] = a[x][y + 2] = 'X';
    if (i & 4) a[x + p][y] = a[x + p + p][y] = 'X';
    if (k & 1)
