    if (i & 1) a[x][y - 1] = a[x][y - 2] = '.';
    if (i & 2) a[x][y + 1] = a[x][y + 2] = '.';
    if (i & 4) a[x + p][y] = a[x + p + p][y] = '.';
  }
  (ans += mm) %= mm;
  cout << ans;
}
