  if (a % MD < 0)
    return a % MD + MD;
  else
    return a % MD;
}
void put(int i, int prof) {
  if (prof == 0) {
    d[i + 1][7] = mod(d[i + 1][7] + d[i][0]);
    d[i + 1][1] = mod(d[i + 1][1] + d[i][0]);
    d[i + 1][4] = mod(d[i + 1][4] + d[i][0]);
  } else if (prof == 1) {
    d[i + 1][0] = mod(d[i + 1][0] + d[i][1]);
    d[i + 1][6] = mod(d[i + 1][6] + d[i][1]);
  } else if (prof == 2) {
    d[i + 1][5] = mod(d[i + 1][5] + d[i][2]);
  } else if (prof == 3) {
    d[i + 1][4] = mod(d[i + 1][4] + d[i][3]);
  } else if (prof == 4) {
    d[i + 1][0] = mod(d[i + 1][0] + d[i][4]);
    d[i + 1][3] = mod(d[i + 1][3] + d[i][4]);
  } else if (prof == 5) {
    d[i + 1][2] = mod(d[i + 1][2] + d[i][5]);
  } else if (prof == 6) {
    d[i + 1][1] = mod(d[i + 1][1] + d[i][6]);
  } else if (prof == 7) {
    d[i + 1][0] = mod(d[i + 1][0] + d[i][7]);
  }
}
