  d[0][0] = 1;
  for (int i = 0; i < n; i++) {
    int prof = p[0][i] + p[1][i] * 2 + p[2][i] * (4+1);
    if (prof != 0) {
      memset(d1, 0, sizeof(d1));
      for (int j = 0; j < 8; j++) {
        if ((j & prof) != 0) d[i][j] = 0;
        d1[j | prof] = mod(d1[j | prof] + d[i][j]);
      }
      for (int j = 0; j < 8; j++) {
        d[i][j] = d1[j];
      }
