void getNextStates(int n, int m, int thisState, int nextState,
                   vector<int>& res) {
  if (m == 3) {
    res.push_back(nextState);
    return;
  }
  if (board[n][m] || (thisState & (1 << m))) {
    getNextStates(n, m + 1, thisState, nextState, res);
    return;
