      getNextStates(n, m + 1, thisState, nextState | (1 << m), res);
  }
  if (m < 2) {
    if (!board[n][m + 1] && !(thisState & (1 << (m + 1))))
      getNextStates(n, m + 2, thisState, nextState, res);
  }
}
