char valid[1 << 6];
void init() {
  int b;
  for (b = 0; b < 1 << 6; b++) {
    int a = b;
    if ((a & 1 << 0) != 0) {
      if ((a | 1 << 3) == 0) continue;
      a ^= 1 << 3;
    }
    if ((a & 1 << 1) != 0) {
      if ((a & 1 << 4) == 0) continue;
      a ^= 1 << 4;
    }
    if ((a & 1 << 2) != 0) {
      if ((a & 1 << 5) == 0) continue;
      a ^= 1 << 5;
    }
    if (a >> 3 == 0 || (a >> 3 & 1) != (a >> 5 & 1) && (a >> 4 & 1) != 0)
      valid[b] = 1;
  }
}
int solve(char cc[][10000 + 1], int n) {
  static int dp[10000 + 1][1 << 3];
  int i, a, b;
  for (i = 0; i <= n; i++) memset(dp[i], 0, sizeof dp[i]);
  dp[0][0] = 1;
  for (i = 0; i < n; i++)
    for (b = 0; b < 1 << 3; b++) {
      int a_;
      if ((b & 1 << 0) != 0 && cc[0][i] == 'X') continue;
      if ((b & 1 << 1) != 0 && cc[1][i] == 'X') continue;
      if ((b & 1 << 2) != 0 && cc[2][i] == 'X') continue;
      a_ = 0;
      if ((b & 1 << 0) == 0 && cc[0][i] != 'X') a_ |= 1 << 0;
      if ((b & 1 << 1) == 0 && cc[1][i] != 'X') a_ |= 1 << 1;
      if ((b & 1 << 2) == 0 && cc[2][i] != 'X') a_ |= 1 << 2;
      a_ <<= 3;
      for (a = 0; a < 1 << 3; a++) {
        int x = dp[i][a];
        if (x != 0 && valid[a | a_])
          dp[i + 1][b] = (dp[i + 1][b] + x) % 1000000007;
      }
    }
  return dp[n][0];
}
int main() {
  static char cc[3][10000 + 1];
  int n, i, j, io, jo, ans;
  init();
  scanf("%d", &n);
  for (i = 0; i < 3; i++) scanf("%s", cc[i]);
  io = jo = -1;
  for (i = 0; i < 3; i++)
    for (j = 0; j < n; j++)
      if (cc[i][j] == 'O') {
        cc[i][j] = 'X';
        io = i, jo = j;
