  ans = solve(cc, n);
  if (io == 1 && jo - 1 >= 0 && jo + 1 < n) {
    for (i = 0; i < 3; i++)
      for (j = jo - 1; j <= jo + 1; j++) cc[i][j] = 'X';
    ans = (ans - solve(cc, n) * 2) % 1000000007;
    if (ans < 0) ans += 1000000007;
  }
  printf("%d\n", ans);
  return 0;
}

