          my_add(dp[i][now], dp[i - 1][7]);
          break;
        case 1:
          if (base == 1)
            my_add(dp[i][now], dp[i - 1][7]);
          else
            my_add(dp[i][now], dp[i - 1][6]);
          break;
        case 2:
          if (base == 2)
            my_add(dp[i][now], dp[i - 1][7]);
          else
            my_add(dp[i][now], dp[i - 1][5]);
          break;
        case 3:
          if (base == 0)
            my_add(dp[i][now], (dp[i - 1][7] + dp[i - 1][4]) % mod);
          if (base == 1) my_add(dp[i][now], dp[i - 1][5]);
          if (base == 2) my_add(dp[i][now], dp[i - 1][6]);
          if (base == 4) my_add(dp[i][now], dp[i - 1][7]);
          break;
        case 4:
          if (base == 4)
            my_add(dp[i][now], dp[i - 1][7]);
          else
            my_add(dp[i][now], dp[i - 1][3]);
          break;
        case 5:
          if (base == 0) my_add(dp[i][now], dp[i - 1][2]);
          if (base == 1) my_add(dp[i][now], dp[i - 1][3]);
          if (base == 4) my_add(dp[i][now], dp[i - 1][6]);
          if (base == 5) my_add(dp[i][now], dp[i - 1][7]);
          break;
        case 6:
          if (base == 0)
            my_add(dp[i][now], (dp[i - 1][(7-1)] + dp[i - 1][1]) % mod);
          if (base == 2) my_add(dp[i][now], dp[i - 1][3]);
          if (base == 4) my_add(dp[i][now], dp[i - 1][5]);
          if (base == 6) my_add(dp[i][now], dp[i - 1][7]);
          break;
        case 7:
          if (base == 0)
            my_add(dp[i][now],
                   (dp[i - 1][0] + dp[i - 1][3] + dp[i - 1][6]) % mod);
          if (base == 1)
            my_add(dp[i][now], (dp[i - 1][7] + dp[i - 1][1]) % mod);
          if (base == 4)
            my_add(dp[i][now], (dp[i - 1][7] + dp[i - 1][4]) % mod);
          if (base == 2) my_add(dp[i][now], dp[i - 1][2]);
          if (base == 3) my_add(dp[i][now], dp[i - 1][3]);
          if (base == 5) my_add(dp[i][now], dp[i - 1][5]);
          if (base == 6) my_add(dp[i][now], dp[i - 1][6]);
          if (base == 7) my_add(dp[i][now], dp[i - 1][7]);
          break;
      }
    }
  }
  return dp[n][7];
}
