#include <bits/stdc++.h>
const int N = 10500;
const int T = 1;
const int MOD = 1000000007;
const int dir[4][2] = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
int dp[N][T];
bool map[N][5];
int ans = 0;
int zx, zy;
int n;
int Do() {
  memset(dp, 0, sizeof dp);
  dp[0][7] = 1;
  int i, j;
  for (i = 1; i <= n; i++) {
    int has = 7;
    if (map[i][1]) has ^= 1;
    if (map[i][2]) has ^= 2;
    if (map[i][3]) has ^= 4;
    for (j = 0; j < 8; j++) {
      if ((j & has) == has) {
        int add = j ^ has;
        dp[i][j] = dp[i - 1][7 ^ add];
        if ((add & 3) == 3) {
          dp[i][j] += dp[i - 1][7 ^ add ^ 3];
          if (dp[i][j] >= MOD) dp[i][j] -= MOD;
        }
        if ((add & 6) == 6) {
          dp[i][j] += dp[i - 1][7 ^ add ^ 6];
          if (dp[i][j] >= MOD) dp[i][j] -= MOD;
        }
      }
    }
  }
  return dp[n][7];
}
void dfs(int x, int has) {
  if (x > 3) {
    if (!has) return;
    if (has & 1) {
      ans += Do();
      if (ans >= MOD) ans -= MOD;
    } else {
      ans -= Do();
      if (ans < 0) ans += MOD;
    }
    return;
  }
  dfs(x + 1, has);
  int tx = dir[x][0];
  int ty = dir[x][1];
  if (map[zx + tx][zy + ty] && map[zx + tx + tx][zy + ty + ty]) {
    map[zx + tx][zy + ty] = 0;
    map[zx + tx + tx][zy + ty + ty] = 0;
    dfs(x + 1, has + 1);
    map[zx + tx][zy + ty] = 1;
    map[zx + tx + tx][zy + ty + ty] = 1;
  }
}
int main() {
  int i, j;
  scanf("%d", &n);
  for (j = 1; j <= 3; j++) {
    for (i = 1; i <= n; i++) {
      char t;
      scanf(" %c", &t);
      if (t == 'O') {
        zx = i;
        zy = j;
      }
      if (t == '.') map[i][j] = 1;
    }
  }
  dfs(0, 0);
  printf("%d\n", ans);
  return 0;
}

