  scanf("%d", &n);
  for (int i = 0; i < 3; ++i) scanf("%s", g[i]);
  for (int j = 0; j < n; ++j)
    for (int i = 0; i < 3; ++i) {
      if (g[i][j] == '.') emp[j + 1] |= 1 << (2 - i);
      if (g[i][j] == 'O') cx = j + 1, cy = 2 - i;
    }
  dfs(0, 0, 0);
  int all = dp1();
  int neg = dp2();
  printf("%d\n", sub(all, neg));
  return 0;
}

