            toggle.emplace_back(x, y + 1);
            toggle.emplace_back(x, y + 2);
          } else {
            can = 0;
          }
        }
      }
    }
    if (!can) {
      continue;
    }
    for (auto j : toggle) {
      A[j.first][j.second] = 'X';
    }
    if (__builtin_popcount(mask) & 1) {
      ans += Count();
    } else {
      ans -= Count();
    }
    ans = ((ans % MOD) + MOD) % MOD;
    for (auto j : toggle) {
      A[j.first][j.second] = '.';
    }
  }
  cout << ans << '\n';
  return 0;
}

