  d.resize(9);
  for (int i = 0; i < 9; i++) {
    d[i] = vector<int>(p[0].size() + 1, 0);
  }
  d[(p[0][0] * 1 + p[1][0] * 2 + p[2][0] * 4)][0] = 1;
  for (unsigned int i = 0; i < d[0].size() - 1; i++) {
    int t = 0;
    if (i + 1 < p[0].size())
      t = (p[0][i + 1] * 1 + p[1][i + 1] * 2 + p[2][i + 1] * 4);
