        dp[x + 1][0] += dp[x][pm];
      } else if (ma == 3)
        dp[x + 1][4] += dp[x][pm];
      else if (ma == 5)
        dp[x + 1][2] += dp[x][pm];
      else if (ma == 6)
        dp[x + 1][1] += dp[x][pm];
      else if (ma == 7)
        dp[x + 1][0] += dp[x][pm];
    }
    for (ma = 0; ma < 8; ma++) dp[x + 1][ma] %= mo;
  }
  return dp[N][0];
}
void solve() {
  int f, i, j, k, l, x, y;
  int sx, sy;
  cin >> N;
  for (i = 0; i < 3; i++) cin >> S[i];
  for (y = 0; y < 3; y++)
    for (x = 0; x < N; x++)
      if (S[y][x] == 'O') S[y][x] = 'X', sy = y, sx = x;
  signed long long ret = 0;
  for (i = 0; i < 4 * 4 * 4 * 4; i++) {
    int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
    int LM = i % 4, RM = (i / 4) % 4;
    int TM = (i / 16) % 4, BM = (i / 64) % 4;
    if (LM != 0 && RM != 1 && TM != 2 && BM != 3) continue;
    if (sx == 0 && LM != 0) continue;
    if (sx == N - 1 && RM != 0) continue;
    if (sy == 0 && TM != 0) continue;
