    if (sy > 0) ng += pt(sx, sy - 1), ng += pt(sx + dx[TM], sy - 1 + dy[TM]);
    if (sy < 2) ng += pt(sx, sy + 1), ng += pt(sx + dx[BM], sy + 1 + dy[BM]);
    if (ng) continue;
    ret = (ret + dodo()) % mo;
  }
  (void)printf("%d\n", ret);
}
