        int k_state = build_state(i + 1);
        if ((k | k_state) ^ k_state) continue;
        if (j == 0)
          dp[i + 1][k][build_state(i + 2)] =
              (dp[i + 1][k][build_state(i + 2)] + dp[i][j][k]) % mod;
        if ((j & 3) == 3)
