int dp[10005][8];
long long solve() {
  for (int i = 0; i <= n; ++i)
    for (int j = 0; j < 8; ++j) dp[i][j] = 0;
  dp[0][0] = 1;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < 8; ++j) {
      int e[2][3];
      for (int k = 0; k < 2; ++k)
        for (int m = 0; m < 3; ++m) {
          if (i == n - 1 && k == 1)
            e[k][m] = 0;
          else
            e[k][m] = field[m][i + k] == '.' ? 1 : 0;
        }
      if (j & 1) e[0][0] = 0;
      if (j & 2) e[0][1] = 0;
      if (j & 4) e[0][2] = 0;
      if (e[0][0] && e[0][1])
        dp[i][j + 3] = (dp[i][j + 3] + dp[i][j]) % 1000000007;
      if (e[0][2] && e[0][1])
        dp[i][j + 6] = (dp[i][j + 6] + dp[i][j]) % 1000000007;
      if (e[0][0] && !e[1][0]) continue;
      if (e[0][1] && !e[1][1]) continue;
      if (e[0][2] && !e[1][2]) continue;
      int k = e[0][0] + e[0][1] * 2 + e[0][2] * 4;
      dp[i + 1][k] = (dp[i + 1][k] + dp[i][j]) % 1000000007;
    }
