  for (int i = 1; i <= t; i++) A[i] = 'B';
  A[1] = a + 'A';
  A[t] = b + 'A';
  if (c > 0) {
    int p = 1;
    if (A[1] != 'A') p++;
    int l = p;
    for (int i = 1; i <= c; i++, l += 2) A[l] = 'A', A[l + 1] = 'C';
    if (l - 2 >= t) return 0;
  }
  if (A[1] != a + 'A' || A[t] != b + 'A') return 0;
  return 1;
}
