int const UNDEF = -1;
int const MAXCNT = 1000000000;
enum Chr { O = 0, A = 1, C = 2 };
int const SZ = 3;
struct Str {
  Chr begin;
  Chr end;
  int cnt;
  Str( Chr end = O,Chr begin = O, int cnt = 0)
      : begin(begin), end(end), cnt(cnt) {}
};
int calcMaxCnt(Chr b, Chr e, int n) {
  if (n == 1) return 0;
  if (n == 2) return b == A && e == C;
  n -= 2;
  int res = 0;
  if (b == A) {
    res = 1;
    --n;
  }
  res += n / 2;
  res += n % 2 == 1 && e == C;
  return res;
}
int calcMinCnt(Chr b, Chr e, int n) {
  if (b == A && e == C && n == 2) return 1;
  return 0;
}
int calcCnt(Str s, Str t, int k) {
  for (int i = 0; i < int(k - 2); ++i) {
    Str q(s.begin, t.end, s.cnt + t.cnt);
    q.cnt += s.end == A && t.begin == C;
    if (q.cnt > MAXCNT) return UNDEF;
    s = t;
    t = q;
  }
  return t.cnt;
}
string const makeString(Str s, int n) {
  string res(n, 'X');
  int l = 0;
  int r = n - 1;
  if (s.begin == A) res[l++] = 'A';
  if (s.begin == C) res[l++] = 'C';
  if (s.end == A) res[r--] = 'A';
  if (s.end == C) res[r--] = 'C';
  if (n == 2 || s.cnt == 0) return res;
  if (s.begin == A) {
    res[l++] = 'C';
    --s.cnt;
  }
  if (s.cnt > 0 && s.end == C) {
    res[r--] = 'A';
    --s.cnt;
  }
  while (s.cnt--) {
    res[l++] = 'A';
    res[l++] = 'C';
  }
  return res;
}
