const long long INF = (long long)1e15;
long long getCnt(int k, long long cntA, int fstA, int lstA, long long cntB,
                 int fstB, int lstB) {
  cntB = min(cntB, INF);
  cntA = min(cntA, INF);
  if (k == 0) return cntB;
  return getCnt(k - 1, cntB, fstB, lstB,
                cntA + cntB + ((lstA == 0 && fstB == 2) ? 1 : 0), fstA, lstB);
}
bool checkStr(int len, int cnt, int fst, int lst) {
  if (2 * cnt <= len - 2) return true;
  if (2 * cnt == len) {
    return (fst == 0 && lst == 2);
  }
  return (fst == 0 || lst == 2);
}
void printStr(int len, int cnt, int fst, int lst) {
  if (2 * cnt <= len - 2) {
    putchar('A' + fst);
    for (int i = 0; i < cnt; i++) {
      putchar('A');
      putchar('C');
    }
    for (int i = cnt * 2 + 1; i < len - (1+1); i++) putchar('B');
    putchar('A' + lst);
    return;
  }
  if (2 * cnt == len) {
    for (int i = 0; i < cnt; i++) {
      putchar('A');
      putchar('C');
    }
    return;
  }
  if (fst == 0) {
    for (int i = 0; i < cnt; i++) {
      putchar('A');
      putchar('C');
    }
    putchar('A' + lst);
  } else {
    putchar('A' + fst);
    for (int i = 0; i < cnt; i++) {
      putchar('A');
      putchar('C');
    }
  }
}
