      for (int a = 0; a < 3; a++)
        for (int b = 0; b < 3; b++)
          for (int c = 0; c < 3; c++)
            for (int d = 0; d < 3; d++) {
              if (getCnt(k - 2, i, a, b, s, c, d) == x) {
