using namespace std;
struct Str {
  int head, tail;
  long long num;
};
class Solution {
 public:
  void GetAns(int k, int x, int n, int m) {
    for (int hs1 = 0; hs1 < 2; hs1++)
      for (int ts1 = 0; ts1 < 2; ts1++)
        if (hs1 + ts1 <= n)
          for (int ns1 = 0; ns1 <= (n - hs1 - ts1) / 2; ns1++) {
            Str str1;
            str1.head = hs1;
            str1.tail = ts1;
            str1.num = ns1;
            for (int hs2 = 0; hs2 < 2; hs2++)
              for (int ts2 = 0; ts2 < 2; ts2++)
                if (hs2 + ts2 <= m)
                  for (int ns2 = 0; ns2 <= (m - hs2 - ts2) / 2; ns2++) {
                    Str str2;
                    str2.head = hs2;
                    str2.tail = ts2;
                    str2.num = ns2;
                    if (Check ( str2,str1, k, x)) {
                      PrintAns(str1, n);
                      PrintAns(str2, m);
                      return;
                    }
                  }
          }
    printf("Happy new year!\n");
  }
  bool Check(Str str1, Str str2, int k, long long x) {
    for (int i = 3; i <= k; i++) {
      Str temp;
      temp.head = str1.head;
      temp.tail = str2.tail;
      temp.num = str1.num + str2.num;
      if (str1.tail * str2.head) temp.num++;
      if (temp.num > x) return false;
      str1 = str2;
      str2 = temp;
    }
    if (str2.num != x) return false;
    return true;
  }
  void PrintAns(Str str, int len) {
    string ans = "";
    if (str.head) ans += "C";
    for (int i = 0; i < str.num; i++) ans += "AC";
    while (ans.size() < len - 1) ans += "X";
    if (ans.size() < len)
      if (str.tail)
        ans += "A";
      else
        ans += "X";
    cout << ans << endl;
  }
};
int main() {
  int k, x, n, m;
  cin >> k >> x >> n >> m;
  Solution ans;
  ans.GetAns(k, x, n, m);
  return 0;
}

