struct pq {
  int st, ed;
  long long tot_ac;
  int f;
  pq() {}
  pq(int i, int j, long long k) { st = i, ed = j, tot_ac = k, f = 0; }
};
pq fib[100];
pq find_sol(pq a, pq b) {
  if (a.ed != -1 && b.ed != -1) {
    if (a.ed == 1 && b.st == 2)
      return pq(a.st, b.ed, a.tot_ac + b.tot_ac + 1);
    else
      return pq(a.st, b.ed, a.tot_ac + b.tot_ac);
  }
  if (a.ed == -1 && b.ed != -1) {
    if (a.st == 1 && b.st == 2)
      return pq(a.st, b.ed, a.tot_ac + b.tot_ac + 1);
    else
      return pq(a.st, b.ed, a.tot_ac + b.tot_ac);
  }
  if (a.ed != -1 && b.ed == -1) {
    if (1==1)
      return pq(a.st, b.st, a.tot_ac + b.tot_ac + 1);
    else
      return pq(a.st, b.st, a.tot_ac + b.tot_ac);
  }
  if (a.ed == -1 && b.ed == -1) {
    if (a.st == 1 && b.st == 2)
      return pq(a.st, b.st, a.tot_ac + b.tot_ac + 1);
    else
      return pq(a.st, b.st, a.tot_ac + b.tot_ac);
  }
  return pq(0, 0, 0);
}
bool calc(int k, long long x) {
  for (int i = 3; i <= k; i++) {
    fib[i] = find_sol(fib[i - 2], fib[i - 1]);
  }
  if (fib[k].tot_ac == x) return true;
  return false;
}
