  string ret = "";
  if (a.tot_ac * 2 == len && len > 2) {
    for (int i = 0; i < a.tot_ac; i++) ret += "AC";
    return ret;
  } else if (len - a.tot_ac * 2 == 1 && len > 2) {
    for (int i = 0; i < a.tot_ac; i++) ret += "AC";
    if (a.f == 1) {
      if (a.st == 0)
        ret = "Z" + ret;
      else if (a.st == 1)
