void init() {
  cnt1[1] = 1;
  cnt2[2] = 1;
  h[1] = 1;
  h[1] = t[1] = 1;
  h[2] = t[2] = 2;
  for (int i = 3; i <= K; i++) {
    if (t[i - 2] == 1 && h[i - 1] == 1) g[i][0]++;
    if (t[i - 2] == 1 && h[i - 1] == 2) g[i][1]++;
    if (t[i - 2] == 2 && h[i - 1] == 1) g[i][2]++;
    if (t[i - 2] == 2 && h[i - 1] == 2) g[i][3]++;
    for (int j = 0; j < 4; j++) g[i][j] =+ g[i - 2][j] + g[i - 1][j];
    h[i] = h[i - 2];
    t[i] = t[i - 1];
    cnt1[i] = cnt1[i - 1] + cnt1[i - 2];
    cnt2[i] = cnt2[i - 1] + cnt2[i - 2];
  }
