  v2[1] = 0, v2[2] = 1;
  v12[1] = 0, v12[2] = 0, v12[3] = 1;
  v21[1] = 0, v21[2] = 0;
  v22[1] = 0, v22[2] = 0;
  for (i = 3; i <= n; i++) {
    v1[i] = v1[i - 2] + v1[i - 1];
    v2[i] = v2[i - 2] + v2[i - 1];
    if (i != 3) {
      v12[i] = v12[i - 2] + v12[i - 1];
    }
    v21[i] = v21[i - 2] + v21[i - 1];
    if (i % 2 == 0) {
      v21[i]++;
    }
    v22[i] = v22[i - 2] + v22[i - 1];
    if ((i != 3) && (i % 2 == 1)) {
      v22[i]++;
    }
  }
