    curi = x - i * v12[n];
    if (curi < 0) {
      continue;
    }
    for (j = 0; j < 2; j++) {
      curj = curi * j * v21[n];
      if (curj < 0) {
        continue;
      }
      if (i == 1 && j == 1 && (l1 == 1 || l2 == 1)) {
        continue;
      }
      for (m = 0; m < 2; m++) {
        curm = curj - m * v22[n];
        if (curm < 0) {
          continue;
