#include <bits/stdc++.h>
using namespace std;
long long cnt1[100];
long long cnt2[100];
int front[100], tail[100];
long long cnt[100][2][2];
char ans1[1000], ans2[1000];
int main() {
  int kk, n, m, x;
  scanf("%d%d%d%d", &kk, &x, &n, &m);
  memset(cnt, 0, sizeof cnt);
  cnt1[0] = 1, cnt2[1] = 1;
  for (int i = 2; i < kk; ++i) {
    cnt1[i] = cnt1[i - 1] + cnt1[i - 2];
    cnt2[i] = cnt2[i - 1] + cnt2[i - 2];
  }
  front[0] = 0, front[1] = 1;
  tail[0] = 0, tail[1] = 1;
  for (int i = 2; i < kk; ++i) {
    for (int a = 0; a < 2; ++a)
      for (int b = 0; b < 2; ++b)
        cnt[i][a][b] += cnt[i - 1][a][b] + cnt[i - 2][a][b];
    cnt[i][tail[i - 2]][front[i - 1]]++;
    tail[i] = tail[i - 1];
    front[i] = front[i - 2];
  }
  bool flag = false;
  for (int i = 0; i < 3 && !flag; ++i)
    for (int j = 0; j < 3 && !flag; ++j) {
      if (n == 1 && i != j) continue;
      for (int k = 0; k < 3 && !flag; ++k)
        for (int l = 0; l < 3 && !flag; ++l) {
          if (m == 1 && k != l) continue;
          long long cur = 0;
          if (i == 1 && j == 0) cur += cnt[kk - 1][0][0];
          if (j == 0 && k == 1) cur += cnt[kk - 1][0][1];
          if (l == 0 && i == 1) cur += cnt[kk - 1][1][0];
          if (l == 0 && k == 1) cur += cnt[kk - 1][1][1];
          long long rem = x - cur;
          int l1 = n, l2 = m;
          if (i == 1) l1--;
          if (j == 0) l1--;
          if (k == 1) l2--;
          if (l == 0) l2--;
          if (i == 2) l1--;
          if (j == 2) l1--;
          if (k == 2) l2--;
          if (l == 2) l2--;
          l2 /= 2, l1 += 2;
          for (int x = (i == 0 && j == 1 ? 1 : 0); x <= l1 && !flag; ++x)
            for (int y = (k == 0 && l == 1 ? 1 : 0); y <= l2 && !flag; ++y) {
              if (x * cnt1[kk - 1] + y * cnt2[kk - 1] == rem) {
                flag = true;
                memset(ans1, 0, sizeof ans1);
                memset(ans2, 0, sizeof ans2);
                if (i == 0) ans1[0] = 'A';
                if (i == 1) ans1[0] = 'C';
                if (i == 2) ans1[0] = 'X';
                if (j == 0) ans1[n - 1] = 'A';
                if (j == 1) ans1[n - 1] = 'C';
                if (j == 2) ans1[n - 1] = 'X';
                if (k == 0) ans2[0] = 'A';
                if (k == 1) ans2[0] = 'C';
                if (k == 2) ans2[0] = 'X';
                if (l == 0) ans2[m - 1] = 'A';
                if (l == 1) ans2[m - 1] = 'C';
                if (l == 2) ans2[m - 1] = 'X';
                int curp = (ans1[0] == 'A'), ax = 0;
                for (int i = 1; i < n;) {
                  if (ax == x) {
                    if (ans1[i] == 0) ans1[i] = 'X';
                    ++i;
                    continue;
                  }
                  if (curp == 0)
                    ans1[i++] = 'A', curp++;
                  else {
                    ans1[i++] = 'C';
                    curp = 0;
                    ax++;
                  }
                }
                curp = (ans2[0] == 'A'), ax = 0;
                for (int i = 1; i < m;) {
                  if (ax == y) {
                    if (ans2[i] == 0) ans2[i] = 'X';
                    ++i;
                    continue;
                  }
                  if (curp == 0)
                    ans2[i++] = 'A', curp++;
                  else {
                    ans2[i++] = 'C';
                    curp = 0;
                    ax++;
                  }
                }
                ans1[n] = ans2[m] = 0;
                puts(ans1);
                puts(ans2);
                break;
              }
            }
        }
    }
  if (!flag) {
    puts("Happy new year!");
  }
  return 0;
}

