                if (l == 2) ans2[m - 1] = 'X';
                int curp = (ans1[0] == 'A'), ax = 0;
                for (int i = 1; i < n;) {
                  if (ax == x) {
                    if (ans1[i] == 0) ans1[i] = 'X';
