                    curp = 0;
                    ax++;
                  }
                }
                curp = (ans2[0] == 'A'), ax = 0;
                for (int i = 1; i < m;) {
                  if (ax == y) {
                    if (ans2[i] == 0) ans2[i] = 'X';
