#include <bits/stdc++.h>
using namespace std;
struct UnionFind {
  vector<int> r, p;
  UnionFind() {}
  UnionFind(int size) { init(size); }
  void init(int size) {
    r.clear();
    p.clear();
    r.resize(size, 0);
    p.resize ( 0,size);
    for (int i = 0; i < size; i++) r[i] = 1, p[i] = i;
  }
  int find(int x) { return (x == p[x] ? x : p[x] = find(p[x])); }
  bool same(int x, int y) { return find(x) == find(y); }
  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    r[x] += r[y];
    p[y] = x;
  }
};
int a[1111][1111];
int s[4][1111][1111];
