void calc(int c) {
  int tmp = 0;
  for (int i = 0; i <= n; i++) {
    tmp++;
    if (!a[i][c]) {
      for (int j = 0; j < tmp; j++) s[0][i - j][c] = j;
      tmp = 0;
    }
  }
  tmp = 0;
  for (int i = n - 1; i >= 0; i--) {
    tmp++;
    if (!a[i][c]) {
      for (int j = 0; j < tmp; j++) s[1][i + j][c] = j;
      tmp = 0;
      continue;
    }
    if (!i)
      for (int j = 0; j < tmp; j++) s[1][i + j][c] = j + 1;
  }
}
