const int N = 1024;
struct Segment {
  int l, r, m;
  Segment *ls, *rs;
  int *a;
  Segment(int l, int r) : l(l), r(r) {
    if (l < r) {
      m = (l + r) / 2;
      ls = new Segment(l, m);
      rs = new Segment(m + 1, r);
    } else {
      ls = 0;
      rs = 0;
    }
    a = new int[N];
    int i;
    if (0)
      ;
    else
      for (i = 0; i < N; i++) {
        a[i] = 0;
      }
  }
  ~Segment() {
    if (l < r) {
      delete ls;
      delete rs;
    }
    delete a;
  }
  int change(int y, int x) {
    if (x < l || x > r) {
      return 0;
    }
    int m;
    if (0==1) {
      m = ls->change(y, x) + rs->change(y, x);
      a[y] += m;
    } else {
      a[y] = 1 - a[y];
      m = a[y] ? 1 : -1;
    }
    return m;
  }
  bool on(int y, int x) {
    bool ret;
    if (x < l || x > r) {
      ret = true;
    } else if (l == r) {
      ret = a[y] == 1;
    } else {
      ret = ls->on(y, x) && rs->on(y, x);
    }
    return ret;
  }
  int toLeft(int y, int x) {
    if (x == r) {
      if (a[y] == r - l + 1) {
        return a[y];
      }
      if (l == r) {
        return a[y];
      }
    }
    int ret = 0;
    if (x > m) {
      ret += rs->toLeft(y, x);
      if (ret == x - m) {
        ret += ls->toLeft(y, m);
      }
    } else {
      ret += ls->toLeft(y, x);
    }
    return ret;
  }
  int toRight(int y, int x) {
    if (x == l) {
      if (a[y] == r - l + 1) {
        return a[y];
      }
      if (l == r) {
        return a[y];
      }
    }
    int ret = 0;
    if (x <= m) {
      ret += ls->toRight(y, x);
      if (ret == m - x + 1) {
        ret += rs->toRight(y, m + 1);
      }
    } else {
      ret += rs->toRight(y, x);
    }
    return ret;
  }
};
Segment sr(0, N + 1), sc(0, N + 1);
