  switch (d) {
    case 0:
      return sr.toRight(y, x);
    case 1:
      return sc.toLeft(x, y);
    case 2:
      return sr.toLeft(y, x);
    case 3:
      return sc.toRight(x, y);
    default:
      return -1;
  }
}
