  int x[1001];
  BIT() { memset(x, 0, sizeof(x)); }
  void update(int pos, int val) {
    while (pos <= 1000) {
      x[pos] += val;
      pos += lowbit(pos);
    }
  }
  int query(int pos) {
    int ret = 0;
    while (pos) {
      ret += x[pos];
      pos -= lowbit(pos);
    }
    return ret;
  }
} row[1001], col[1001];
int mat[1001][1001];
bool horzHaveAll(int r, int c1, int c2) {
  return (row[r].query(c2) - row[r].query(c1 - 1)) == (c2 - c1 + 1);
}
bool vertHaveAll(int c, int r1, int r2) {
  return (col[c].query(r2) - col[c].query(r1 - 1)) == (r2 - r1 + 1);
}
int maxUp(int x, int y) {
  if (mat[x][y] == 0) return 0;
  int L = 1, R = x + 1, M;
  while (R - L > 1) {
    M = (L + R) / 2;
    if (vertHaveAll(y, x - M + 1, x))
      L = M;
    else
      R = M;
  }
  return L;
}
int maxDown(int x, int y) {
  if (mat[x][y] == 0) return 0;
  int L = 1, R = n - x + 2, M;
  while (R - L > 1) {
    M = (L + R) / 2;
    if (vertHaveAll(y, x, x + M - 1))
      L = M;
    else
      R = M;
  }
  return L;
}
int maxLeft(int x, int y) {
  if (mat[x][y] == 0) return 0;
  int L = 1, R = y + 1, M;
  while (R - L > 1) {
    M = (L + R) / 2;
    if (horzHaveAll(x, y - M + 1, y))
      L = M;
    else
      R = M;
  }
  return L;
}
int maxRight(int x, int y) {
  if (mat[x][y] == 0) return 0;
  int L = 1, R = m - y + 2, M;
  while (R - L > 1) {
