    if (horzHaveAll(x, y, y + M - 1))
      L = M;
    else
      R = M;
  }
  return L;
}
int calc(vector<int> A, vector<int> B) {
  int nA = A.size(), nB = B.size();
  int ret = A[0];
  for (int i = 1; i < nA; i++) A[i] = min(A[i], A[i - 1]);
  for (int i = 1; i < nB; i++) B[i] = min(B[i], B[i - 1]);
  int p1 = 0, p2 = 0;
  while (p1 + 1 < nA || p2 + 1 < nB) {
    int choice = 1;
    if (p1 + 1 >= nA)
      choice = 2;
    else if (p2 + 1 >= nB)
      choice = 1;
    else if (A[p1 + 1] > B[p2 + 1])
      choice = 1;
