void buildUp() {
  for (int i(0); i < m; ++i) up[0][i] = board[0][i];
  for (int r(1); r < n; ++r) {
    for (int i(0); i < m; ++i)
      if (board[r][i])
        up[r][i] = up[r - 1][i] + 1;
      else
        up[r][i] = 0;
  }
}
void buildDown() {
  for (int i(0); i < m; ++i) down[n - 1][i] = board[n - 1][i];
  for (int r(n - 1 - 1); r >= 0; --r)
    for (int i(0); i < m; ++i)
      if (board[r][i])
        down[r][i] = down[r + 1][i] + 1;
      else
        down[r][i] = 0;
}
void buildLeft() {
  for (int i(0); i < n; ++i) lft[0][i] = board[i][0];
  for (int c(1); c < m; ++c)
    for (int i(0); i < n; ++i)
      if (board[i][c])
        lft[c][i] = 1 + lft[c - 1][i];
      else
