  board[x][y] = 1 - board[x][y];
  for (int i(0); i < n; ++i) {
    if (i == 0)
      up[i][y] = board[i][y];
    else
      up[i][y] = board[i][y] * (1 + up[i - 1][y]);
  }
  for (int i(n - 1); i >= 0; --i) {
    if (i == n - 1)
      down[i][y] = board[i][y];
    else
      down[i][y] = board[i][y] * (1 + down[i + 1][y]);
  }
