  int i = x, j = x, area, maxarea = -1;
  for (int y = h[x]; y >= 0; --y) {
    while (i >= 0 && h[i] >= y) --i;
    while (j < N && h[j] >= y) ++j;
    area = y * (j - i - 1);
    maxarea = max(maxarea, area);
  }
  return maxarea;
}
