#include <bits/stdc++.h>
using namespace std;
const int size = 1024;
int ans = 0;
struct sta {
  vector<vector<int> > a;
  int T[1010][size * 2 + 1];
  int h[1010];
  int n, m;
  sta() { memset(T, 0, sizeof(T)); }
  void upd(int i, int v, int x) {
    v += size;
    T[i][v] = x;
    while (v > 1) {
      v /= 2;
      T[i][v] = T[i][v + v] + T[i][v + v + 1];
    }
  }
  void invert(int x, int y) {
    a[x][y] = 1 - a[x][y];
    upd(x, y, !a[x][y]);
  }
  void init() {
    n = a.size();
    m = a[0].size();
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < m; ++j) upd(i, j, !a[i][j]);
      upd(i, m, 1);
    }
  }
  int findSum(int i, int l, int r) {
    l += size;
    r += size;
    int res = 0;
    while (l <= r) {
      if (l & 1) res += T[i][l];
      if (!(r & 1)) res += T[i][r];
      l = (l + 1) / 2;
      r = (r - 1) / 2;
    }
    return res;
  }
  int findKth(int i, int k) {
    int v = 1;
    while (v < size) {
      if (T[i][v + v] >= k)
        v += v;
       {
        k -= T[i][v + v];
        v += v + 1;
      }
    }
    return v - size;
  }
  void solve(int x, int y) {
    if (!a[x][y]) return;
    for (int i = 0; i < n; ++i) {
      int pos = findKth(i, findSum(i, 0, y - 1) + 1);
      h[i] = pos - y;
    }
    stack<int> st;
    vector<int> d1(n), d2(n);
    for (int j = 0; j < n; ++j) {
      while (!st.empty() && h[st.top()] >= h[j]) st.pop();
      d1[j] = st.empty() ? -1 : st.top();
      st.push(j);
    }
    while (!st.empty()) st.pop();
    for (int j = n - 1; j >= 0; --j) {
      while (!st.empty() && h[st.top()] >= h[j]) st.pop();
      d2[j] = st.empty() ? n : st.top();
      st.push(j);
    }
    for (int j = 0; j < n; ++j) {
      if (d1[j] < x && x < d2[j]) ans = max(ans, h[j] * (d2[j] - d1[j] - 1));
    }
