#include <bits/stdc++.h>
using namespace std;
int kkaass = 1;
int B[1009][1009];
int row, col;
int U[1009][1009], D[1009][1009], L[1009][1009], R[1009][1009];
int b[1009];
struct DS {
  int par[1009];
  void ini() {
    for (int i = 0; i < 1009; i++) par[i] = i;
    return;
  }
  int findParent(int u) {
    if (par[u] == u) return u;
    return par[u] = findParent(par[u]);
  }
  void merge(int x, int y) { par[findParent(x)] = findParent(y); }
} ld, rd;
void ini() {
  int i, j;
  for (i = 1; i <= row; i++) {
    for (j = 1; j <= col; j++) {
      if (B[i][j]) {
        U[i][j] = U[i - 1][j] + 1;
        L[i][j] = L[i][j - 1] + 1;
      } else {
        U[i][j] = 0;
        L[i][j] = 0;
      }
    }
  }
  for (i = row; i >= 1; i--) {
    for (j = col; j >= 1; j--) {
      if (B[i][j]) {
        D[i][j] = D[i + 1][j] + 1;
        R[i][j] = R[i][j + 1] + 1;
      } else {
        D[i][j] = 0;
        R[i][j] = 0;
      }
    }
  }
  return;
}
void changeState(int x, int y) {
  B[x][y] = B[x][y] ^ 1;
  for (int i = 1; i <= row; i++)
    if (B[i][y])
      U[i][y] = U[i - 1][y] + 1;
    else
      U[i][y] = 0;
  for (int i = row; i >= 1; i--)
    if (B[i][y])
      D[i][y] = D[i + 1][y] + 1;
    else
      D[i][y] = 0;
  for (int i = (1+1); i <= col; i++)
    if (B[x][i])
      L[x][i] = L[x][i - 1] + 1;
    else
      L[x][i] = 0;
  for (int i = col; i >= 1; i--)
    if (B[x][i])
      R[x][i] = R[x][i + 1] + 1;
    else
      R[x][i] = 0;
  return;
}
bool func(int x, int y) { return b[x] < b[y]; }
int getRes(int x, int n) {
  int id[1009];
  for (int i = 0; i < 1009; i++) id[i] = i;
  sort(id + 1, id + n + 1, func);
  ld.ini();
  rd.ini();
  int ans = 0;
  for (int i = n; i >= 1; i--) {
    int l = ld.findParent(id[i] - 1) + 1, r = rd.findParent(id[i] + 1) - 1;
    if (l <= x && x <= r) ans = max(ans, (r - l + 1) * b[id[i]]);
    ld.merge(id[i], id[i] - 1);
    rd.merge(id[i], id[i] + 1);
  }
  return ans;
}
int solve(int x, int y) {
  int res = 0;
  for (int i = 1; i <= col; i++) b[i] = U[x][i];
  res = max(res, getRes(y, col));
  for (int i = 1; i <= col; i++) b[i] = D[x][i];
  res = max(res, getRes(y, col));
  for (int i = 1; i <= row; i++) b[i] = L[i][y];
  res = max(res, getRes(x, row));
  for (int i = 1; i <= row; i++) b[i] = R[i][y];
  res = max(res, getRes(x, row));
  return res;
}
int main() {
  ios_base::sync_with_stdio(false);
  int i, j, q;
  while (cin >> row >> col >> q) {
    for (i = 1; i <= row; i++)
      for (j = 1; j <= col; j++) cin >> B[i][j];
    ini();
    while (q--) {
      int t, x, y;
      cin >> t >> x >> y;
      if (t == 1)
        changeState(x, y);
      else
        cout << solve(x, y) << endl;
    }
  }
  return 0;
}

