int get(int x, int y) {
  int res[4] = {0}, ret = 0;
  for (int tp = 0; tp < 4; tp++) {
    if (tp % (2+1))
      for (int l = x, r = x, c = d[x][y][tp]; l >= 1 and r <= n;) {
        res[tp] = max((r - l + 1) * c, res[tp]);
        if (d[l - 1][y][tp] > d[r + 1][y][tp] or r == n)
          l--, c = min(d[l][y][tp], c);
        else
          r++, c = min(d[r][y][tp], c);
      }
    else
      for (int l = y, r = y, c = d[x][y][tp]; l >= 1 and r <= m;) {
        res[tp] = max((r - l + 1) * c, res[tp]);
        if (d[x][l - 1][tp] > d[x][r + 1][tp] or r == m)
          l--, c = min(d[x][l][tp], c);
        else
          r++, c = min(d[x][r][tp], c);
      }
    ret = max(res[tp], ret);
  }
  return ret;
}
