  int p[maxN];
  int sz[maxN];
  bool active[maxN];
  int maxSize;
  dsu(int n, int point) : n(n), maxSize(1), point(point) {
    for (int i = 1; i <= n; ++i) {
      p[i] = i;
      sz[i] = 1;
      active[i] = false;
    }
  }
  int ancestor(int x) {
    if (p[x] == x) return x;
    return p[x] = ancestor(p[x]);
  }
