    if (x == y) return;
    p[x] = y;
    sz[y] += sz[x];
    if (ancestor(point) == y) maxSize = std::max(maxSize, sz[y]);
  }
  void activate(int idx) {
    active[idx] = true;
    if (idx >= 2 && active[idx - 1]) unite(idx - 1, idx);
    if (idx < n && active[idx + 1]) unite(idx, idx + 1);
  }
