void input() {
  scanf("%d-d%d", &N, &M, &Q);
  for (int i = 1; i <= N; i++)
    for (int j = 1; j <= M; j++) {
      scanf("%d", &tab[i][j]);
    }
}
void proc_row(int i) {
  prefRow[i][0] = 0;
  for (int j = 1; j <= M; j++) {
    prefRow[i][j] = prefRow[i][j - 1] + tab[i][j];
  }
}
void proc_col(int j) {
  prefCol[0][j] = 0;
  for (int i = 1; i <= N; i++) {
    prefCol[i][j] = prefCol[i - 1][j] + tab[i][j];
  }
}
void proc_query() {
  int type, r, c;
  scanf("%d%d%d", &type, &r, &c);
  if (type == 1) {
    tab[r][c] = 1 - tab[r][c];
    proc_row(r);
    proc_col(c);
  } else {
    if (!tab[r][c]) {
      printf("0\n");
      return;
