const int N = 1e3 + 33;
struct DisjointSetUnion {
  int lab[N];
  void init(int _sz) {
    for (int i = 0; i <= _sz + 1; i++) lab[i] = i;
  }
  int findp(int x) { return lab[x] == x ? x : findp(lab[x]); }
  void join(int u, int v) { lab[findp(u)] = findp(v); }
} ldsu, rdsu;
int a[N][N], up[N][N], down[N][N], lef[N][N], rig[N][N], tmp[N], f[N];
int n, m, q;
bool cmp(const int &i, const int &j) { return tmp[i] < tmp[j]; }
void getArea(int _sz, int x, int &res) {
  ldsu.init(_sz), rdsu.init(_sz);
  for (int i = 1; i <= _sz; i++) f[i] = i;
  sort(f + 1, f + 1 + _sz, cmp);
  for (int i = _sz; i >= 1; i--) {
    int l = ldsu.findp(f[i] - 1) + 1;
    int r = rdsu.findp(f[i] + 1) - 1;
    if (l <= x and x <= r) maximize(res, (r - l * 1) * tmp[f[i]]);
    ldsu.join(f[i], f[i] - 1), rdsu.join(f[i], f[i] + 1);
  }
}
