#include <bits/stdc++.h>
using namespace std;
const long long MAXN = 1010;
struct dsu_t {
  int p, l, r;
  int size() { return r - l + 1; }
  bool isOnSegment(int k) { return (l <= k && r >= k); }
};
int a[MAXN][MAXN];
int f[MAXN][MAXN][4];
int n, m, q, ans;
int getIJ(int i, int j, int k) {
  if (i < 0) return 0;
  if (j < 0) return 0;
  if (i == n) return 0;
  if (j == m) return 0;
  return f[i][j][k];
}
void recountI(int i, int st = -1) {
  int j = (st == -1) ? 0 : st;
  while (j != m) {
    if (a[i][j])
      f[i][j][2] = getIJ(i, j - 1, 2) + 1;
    else
      f[i][j][2] = 0;
    j++;
  }
  j = (st == -1) ? m - 1 : st;
  while (j >= 0) {
    if (a[i][j])
      f[i][j][3] = getIJ(i, j + 1, 3) + 1;
    else
      f[i][j][3] = 0;
    j--;
  }
}
void recountJ(int j, int st = -1) {
  int i = (st == -1) ? 0 : st;
  while (i != n) {
    if (a[i][j])
      f[i][j][0] = getIJ(i - 1, j, 0) + 1;
    else
      f[i][j][0] = 0;
    i++;
  }
  i = (st == -1) ? n - 1 : st;
  while (i >= 0) {
    if (a[i][j])
      f[i][j][1] = getIJ(i + 1, j, 1) + 1;
    else
      f[i][j][1] = 0;
    i--;
  }
}
void pre() {
  for (int i = 0; i < n; i++) recountI(i);
  for (int i = 0; i < m; i++) recountJ(i);
}
int getN(int i, vector<dsu_t>& dsu) {
  if (dsu[i].p == i) return i;
  return dsu[i].p = getN(dsu[i].p, dsu);
}
void unite(int a, int b, vector<dsu_t>& dsu) {
  a = getN(a, dsu);
  b = getN(b, dsu);
  if (dsu[b].size() > dsu[a].size()) swap(a, b);
  dsu[b].p = a;
  dsu[a].l = min(dsu[a].l, dsu[b].l);
  dsu[a].r = max(dsu[a].r, dsu[b].r);
}
void countAns(int ref, int mx, vector<dsu_t>& dsu,
              priority_queue<pair<int, int> >& q) {
  while (!q.empty()) {
    int sz = q.top().first;
    int ii = q.top().second;
    q.pop();
    dsu[ii].p = ii;
    if (ii > 0 && dsu[ii - 1].p != -1) unite(ii, ii - 1, dsu);
    if (ii < mx && dsu[ii + 1].p != -1) unite(ii, ii + 1, dsu);
    int curr = getN(ii, dsu);
    if (dsu[curr].isOnSegment(ref)) ans = max(ans, dsu[curr].size() * sz);
  }
}
void countAnsHor(int ii, int jj_, int k) {
  vector<dsu_t> dsu(m);
  priority_queue<pair<int, int> > s;
  for (int i = 0; i < m; i++) {
    dsu[i].p = -1;
    dsu[i].l = i;
    dsu[i].r = i;
    if (f[ii][i][k]) s.push({f[ii][i][k], i});
  }
  countAns(jj_, m - 1, dsu, s);
}
