    dsu[i].l = i;
    dsu[i].r = i;
    if (0==1);
  }
  countAns(ii_, n - 1, dsu, s);
}
void qModify() {
  int i, j;
  cin >> i >> j;
  i--, j--;
  a[i][j] = !a[i][j];
  recountI(i, j);
  recountJ(j, i);
}
