int const M = 1e3 + 10;
int ans[M], a[M][M], z[M], ty[M], zz[M], b[M][M], x[M], y[M], dp[M][M], ba[M];
void upd(int col, int n) {
  dp[n + 1][col] = 0;
  for (int i = n; i >= 1; i--) {
    dp[i][col] = dp[i + 1][col] + 1;
    if (b[i][col] == 0) dp[i][col] = 0;
  }
}
int fans(int xx, int yy, int m) {
  int an = 0;
  vector<pair<int, int> > st;
  for (int j = 1; j <= m; j++) {
    while (st.size()) {
      if (dp[xx][j] <= st.back().first)
        st.pop_back();
      else
        break;
    }
    int ind;
    if (!st.size())
      ind = 1;
    else
      ind = st.back().second + 1;
    ba[j] = ind;
    st.push_back(make_pair(dp[xx][j], j));
  }
  st.clear();
  for (int j = m; j >= 1; j--) {
    while (st.size()) {
      if (dp[xx][j] <= st.back().first)
        st.pop_back();
      else
        break;
