}
void solve(int hlp, int n, int m, int q) {
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (hlp == 1) b[i][j] = a[i][j];
      if (hlp == 2) b[j][i] = a[i][j];
      if (hlp == 3) b[n - i + 1][j] = a[i][j];
      if (hlp == 4) b[m - j + 1][i] = a[i][j];
    }
  }
  if (hlp / 2 == 0) swap(n, m);
  for (int i = 1; i <= m; i++) upd(i, n);
  for (int i = 1; i <= q; i++) {
    if (hlp == 1) x[i] = z[i], y[i] = zz[i];
