    if (hlp == 3) x[i] = n - z[i] + 1, y[i] = zz[i];
    if (hlp == 4) x[i] = n - zz[i] + 1, y[i] = z[i];
    if (ty[i] == 1) {
      b[x[i]][y[i]] = 1 - b[x[i]][y[i]];
      upd(y[i], n);
    } else {
      ans[i] = max(fans(x[i], y[i], m), ans[i]);
    }
  }
}
