void row_update(int x) {
  for (int j = m - 1; j >= 0; j--) {
    if (board[x][j] == 0)
      rightt[x][j] = 0;
    else
      rightt[x][j] = 1 + rightt[x][j + 1];
  }
  for (int j = 0; j < m; j++) {
    if (board[x][j] == 0)
      leftt[x][j] = 0;
    else
      leftt[x][j] = 1 + (j - 1 >= 0 ? leftt[x][j - 1] : 0);
  }
}
void col_update(int y) {
  for (int i = n - 1; i >= 0; i--) {
    if (board[i][y] == 0)
      down[i][y] = 0;
    else
      down[i][y] = 1 + down[i + 1][y];
  }
  for (int i = 0; i < n; i++) {
    if (board[i][y] == 0)
      up[i][y] = 0;
    else
      up[i][y] = 1 + (i - 1 >= 0 ? up[i - 1][y] : 0);
  }
}
