        while (RP <= M && U[X[k]][RP] >= CrtH) RP++;
        Ans[k] = min(Ans[k], CrtH * (RP - LP - 1));
      }
      LP = RP = Y[k];
      for (int CrtH = D[X[k]][Y[k]]; CrtH >= 1; --CrtH) {
        while (1 <= LP && D[X[k]][LP] >= CrtH) LP--;
