    if (Op[i] == 1) A[X[i]][Y[i]] ^= 1;
}
void Rotate() {
  for (int i = 1; i <= max(N, M); ++i)
    for (int j = 1; j <= i; ++j) swap(A[i][j], A[j][i]);
  swap(N, M);
  for (int i = 1; i <= Q; ++i) swap(X[i], Y[i]);
}
