inline void calc_hor(int x) {
  int q = -1;
  for (int i = 0; i < m; ++i) {
    if (!a[x][i]) q = i;
    lsfgn[x][i] = i - q;
  }
  q = m;
  for (int i = m - 1; i >= 0; --i) {
    if (!a[x][i]) q = i;
    lsfgnejogn[x][i] = q - i;
  }
}
inline void calc_ver(int y) {
  int q = -1;
  for (int i = 0; i < n; ++i) {
    if (!a[i][y]) q = i;
    up[i][y] = i - q;
  }
  q = n;
  for (int i = n - 1; i >= 0; --i) {
    if (!a[i][y]) q = i;
    down[i][y] = q - i;
  }
}
vector<int> s;
int nx[1001];
int pr[1001];
int h[1001];
inline int ans_stack(int y, int m) {
  s.clear();
  for (int i = 0; i < m; ++i) {
    while (!s.empty() && h[s.back()] > h[i]) {
      nx[s.back()] = i;
      s.pop_back();
    }
    s.push_back(i);
  }
  while (!s.empty()) {
    nx[s.back()] = m;
    s.pop_back();
  }
  for (int i = m - 1; i >= 0; --i) {
    while (!s.empty() && h[s.back()] > h[i]) {
      pr[s.back()] = i + 1;
      s.pop_back();
    }
    s.push_back(i);
  }
  while (!s.empty()) {
    pr[s.back()] = 0;
    s.pop_back();
  }
  int ans = 0;
  for (int i = 0; i < m; ++i)
    if (pr[i] <= y && y < nx[i]) ans = max(ans, (nx[i] - pr[i]) * h[i]);
  return ans;
}
inline int answer(int x, int y) {
  int ans = 0;
  for (int i = 0; i < m; ++i) h[i] = up[x][i];
  ans = max(ans, ans_stack(y, m));
  for (int i = 0; i < m; ++i) h[i] = down[x][i];
  ans = max(ans, ans_stack(y, m));
  for (int i = 0; i < n; ++i) h[i] = lsfgn[i][y];
  ans = max(ans, ans_stack(x, n));
  for (int i = 0; i < n; ++i) h[i] = lsfgnejogn[i][y];
  ans = max(ans, ans_stack(x, n));
  return ans;
}
