  int ret = f[pos];
  int min_height = f[pos];
  while (l > 1 || r < bound) {
    if (r == bound || f[l - 1] > f[r + 1]) {
      l--;
      min_height = min(min_height, f[l]);
    } else {
      r++;
      min_height = min(min_height, f[r]);
    }
    ret = max(ret, (r - l + 1) * min_height);
  }
  return ret;
}
