template <typename T, typename U>
bool ckmin(T &a, U b) {
  return b < a ? a = b, true : false;
}
template <typename T, typename U>
bool ckmax(T &a, U b) {
  return b > a ? a = b, true : false;
}
const int INF = 2e4;
struct DSU {
  int SZ;
  vector<int> p, r, second, hi, lo;
  DSU(int sz) : SZ(sz) {
    p.assign(SZ, 0);
    hi.assign(SZ, 0);
    lo.assign(SZ, 0);
    iota(p.begin(), p.end(), 0);
    iota(hi.begin(), hi.end(), 0);
    iota(lo.begin(), lo.end(), 0);
    r.assign(SZ, 0);
    second.assign(SZ, 1);
  }
  int find(int u) {
    if (p[u] != u) p[u] = find(p[u]);
    return p[u];
  }
  void merge(int u, int v) {
    u = find(u);
    v = find(v);
    if (u == v) return;
    if (r[u] < r[v]) swap(u, v);
    r[u]++, second[u] += second[v], p[v] = u;
    ckmax(hi[u], hi[v]);
    ckmin(lo[u], lo[v]);
  }
  void apply(vector<bool> &v) {
    assert(SZ == (int)(v).size());
    for (int i = 0; i < SZ; ++i) {
      if (!v[i]) lo[i] = INF, hi[i] = -INF;
    }
  }
};
