using namespace std;
const int N = 1001;
struct Maze {
  bool maze[N][N];
  bool _swap, _flip;
  int n, m, upto[N][N];
  Maze() {}
  void init(bool s, bool f, int a, int b) {
    _swap = s;
    _flip = f;
    n = a, m = b;
    if (_swap) swap(n, m);
  }
  void process(int c) {
    for (int i = 1; i <= n; i++) {
      if (maze[i][c]) {
        if (maze[i - 1][c]) {
          upto[i][c] = upto[i - 1][c];
        } else {
          upto[i][c] = i;
        }
      } else {
        upto[i][c] = 0;
      }
    }
  }
  void tr(int &a, int &b) {
    if (_swap) swap(a, b);
    if (_flip) a = n + 1 - a;
  }
  void flip(int r, int c) {
    tr(r, c);
    maze[r][c] = 1 - maze[r][c];
    process(c);
  }
  int query(int r, int c) {
    tr(r, c);
    if (!maze[r][c]) return 0;
    int neck[N];
    neck[c] = upto[r][c];
    for (int i = c - 1; i > 0; i--) {
      if (!maze[r][i]) break;
      neck[i] = max(neck[i + 1], upto[r][i]);
    }
    for (int i = c + 1; i <= m; i++) {
      if (!maze[r][i]) break;
      neck[i] = max(neck[i - 1], upto[r][i]);
    }
    int ans = 0;
    int L = c, R = c;
    do {
      while (R + 1 <= m && maze[r][R + 1] == true && neck[R + 1] <= neck[L]) {
        R++;
      }
      ans = max(ans, (R - L + 1) * (r - neck[L] + 1));
      L--;
    } while (L > 0 && R <= m && maze[r][L] && maze[r][R]);
    L = c, R = c;
    do {
      while (L - 1 > 0 && maze[r][L - 1] == true && neck[L - 1] <= neck[R]) {
        L--;
      }
      ans = max(ans, (R - L + 1) * (r - neck[R] + 1));
      R++;
    } while (L > 0 && R <= m && maze[r][L] && maze[r][R]);
    return ans;
  }
} data[4];
