int getint() {
  unsigned int c;
  int x = 0;
  while (((c = getchar()) - '0') >= 10) {
    if (c == '-') return -getint();
    if (!~c) exit(0);
  }
  do {
    x = (x << 3) + (x << 1) + (c - '0');
  } while (((c = getchar()) - '0') < 10);
  return x;
}
pair<int, int> rotate(int x, int y, int h, int w, int k) {
  pair<int, int> res;
  if (k == 0) res.first = x, res.second = y;
  if (k == 1) res.first = y, res.second = h - x - 1;
  if (k == 2) res.first = h - x - 1, res.second = w - y - 1;
  if (k == 3) res.first = w - y - 1, res.second = x;
  return res;
}
template <class T>
T max_area(T *h, int n, int m) {
  int i, t;
  T res = 0;
  if (n < 1) return 0;
  vector<int> sideL(n, 0), sideR(n, n), stk(n);
  for (i = t = 0; i < n; i++) {
    while (t > 0 and h[i] <= h[stk[t - 1]]) t--;
    if (t) sideL[i] = stk[t - 1] + 1;
    stk[t++] = i;
  }
  for (i = n - 1, t = 0; ~i; --i) {
    while (t > 0 and h[i] <= h[stk[t - 1]]) t--;
    if (t) sideR[i] = stk[t - 1];
    stk[t++] = i;
  }
  for (i = 0; i < n; i++) {
    if (sideR[i] <= m) continue;
    if (sideL[i] > m) continue;
    res = max(res, h[i] * (sideR[i] - sideL[i]));
  }
  return res;
}
