    a = 0;
  else
    a = len[x - 1][y][0];
  if (x == W - 1)
    b = 0;
  else
    b = len[x + 1][y][2];
  for (p = x - a; p <= x + b; p++) {
    len[p][y][0] = p - (x - a) + 1;
    len[p][y][2] = (x + b) - p + 1;
  }
  if (y == 0)
    a = 0;
  else
    a = len[x][y - 1][1];
  if (y == H - 1)
    b = 0;
  else
    b = len[x][y + 1][3];
  for (p = y - a; p <= y + b; p++) {
    len[x][p][1] = p - (y - a) + 1;
    len[x][p][3] = (y + b) - p + 1;
  }
}
void dark(int x, int y) {
  cond[x][y] = false;
  int a, b, p;
  if (x == 0)
    a = 0;
  else
    a = len[x - 1][y][0];
  if (x == W - 1)
    b = 0;
  else
    b = len[x + 1][y][2];
  for (p = x - a; p < x; p++) len[p][y][2] = (x - 1) - p + 1;
  for (p = x + 1; p <= x + b; p++) len[p][y][0] = p - (x + 1) + 1;
  len[x][y][0] = 0;
  len[x][y][2] = 0;
  if (y == 0)
    a = 0;
  else
