  int n = h.size();
  static vector<int> big_left;
  static vector<int> big_right;
  static vector<pair<int, int>> s;
  s.clear();
  s.reserve(n);
  big_left.assign(n, -1);
  big_right.assign(n, n);
  for (int i = 0; i < n; i++) {
    while (!s.empty() && s.back().first >= h[i]) s.pop_back();
    if (!s.empty()) big_left[i] = s.back().second;
    s.push_back(make_pair(h[i], i));
  }
  s.clear();
