int min(int i1, int i2) {
  if (i1 > i2) return i2;
  return i1;
}
int max(int i1, int i2) {
  if (i1 < i2) return i2;
  return i1;
}
bool find(int x1, int y1, int x2, int y2) {
  if (x1 == x2) {
    if (y1 > y2) {
      return lx[x1][y1] - lx[x1][y2 - 1] == y1 - y2 + 1;
    } else {
      return lx[x1][y2] - lx[x1][y1 - 1] == y2 - y1 + 1;
    }
  }
  if (y1 == y2) {
    if (x1 > x2) {
      return ly[x1][y1] - ly[x2 - 1][y1] == x1 - x2 + 1;
    } else {
      return ly[x2][y1] - ly[x1 - 1][y1] == x2 - x1 + 1;
    }
  }
  return false;
}
void solve(int n) {
  int i, j, z, k, m, q, x, y, res, l, i1, i2, cmin, cmax;
