  for (i = 1; i <= n + 1; i++)
    for (j = 1; j <= m + 1; j++) {
      lx[i][j] = lx[i][j - 1] + c[i][j];
      ly[i][j] = ly[i - 1][j] + c[i][j];
    }
  for (i = 0; i < q; i++) {
    scanf("%d%d%d", &z, &x, &y);
