      for (j = x; j <= n; j++) ly[j][y] =+ 1 - 2 * c[x][y];
      for (j = y; j <= m; j++) lx[x][j] += 1 - 2 * c[x][y];
      c[x][y] = 1 - c[x][y];
    } else if (c[x][y] == 1) {
      res = 1;
