int n, m, q;
struct Solver {
  void set(int i, int j, int val) {
    upd(fen[i], j, val);
    what[i][j] += val;
  }
  void upd(int f[], int pos, int val) {
    for (; pos <= 1002; pos |= (pos + 1)) f[pos] += val;
  }
  int fnd(int f[], int pos) {
    int ret = 0;
    for (; pos >= 0; pos = (pos & (pos + 1)) - 1) ret += f[pos];
    return ret;
  }
  int findFrom(int i, int j) {
    if (what[i][j] == 0) return 0;
    int st = fnd(fen[i], j - 1), sum = 0, pos = -1;
    for (int t = 10; t >= 0; --t) {
      int nval = 0;
      if (pos >= j)
        nval = sum + (1 << t);
      else if (pos + (1 << t) < j)
        nval = sum + fen[i][pos + (1 << t)];
      else {
        nval = st + (pos + (1 << t) - j + 1);
      }
      if (pos + (1 << t) <= 1002 &&
          (pos + (1 << t) < j || sum + fen[i][pos + (1 << t)] == nval)) {
        sum = nval;
        pos += (1 << t);
      }
    }
    return pos - j * 1;
  }
  int solve(int x, int y) {
    vector<pair<int, int> > v;
    for (int i = 1; i <= n; ++i) {
      v.push_back(make_pair(findFrom(i, y), i));
    }
    sort(v.begin(), v.end());
    int ans = 0, up = 1, bottom = n, it = 0;
    for (int w = 1; w <= m; ++w) {
      while (it < v.size() && v[it].first < w) {
        if (v[it].second <= x) up = max(up, v[it].second + 1);
        if (v[it].second >= x) bottom = min(bottom, v[it].second - 1);
        ++it;
      }
      ans = max(ans, w * (bottom - up + 1));
    }
    return ans;
  }
  int fen[1005][1005];
  int what[1005][1005];
};
