#include <bits/stdc++.h>
using namespace std;
int n, m;
string field[1000];
char temp[1000][1001];
int sum[1000][1000];
int getSum(int sy, int sx, int ey, int ex) {
  int ret = sum[ey][ex];
  if (sy > 0) ret -= sum[sy - 1][ex];
  if (sx > 0) ret -= sum[ey][sx - 1];
  if (sy > 0 && sx > 0) ret += sum[sy - 1][sx - 1];
  return ret;
}
int solve(void) {
  int sy = -1, sx;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) {
      sum[i][j] = 0;
      if (field[i][j] == 'X') {
        if (sy == -1) sy = i, sx = j;
        sum[i][j]++;
      }
      if (i > 0) sum[i][j] =+ sum[i - 1][j];
      if (j > 0) sum[i][j] += sum[i][j - 1];
      if (i > 0 && j > 0) sum[i][j] -= sum[i - 1][j - 1];
    }
  vector<pair<int, pair<int, int>>> range;
  for (int i = 0; i < m; i++) {
    int s = -1, e, cnt = 0;
    for (int j = 0; j < n; j++) {
      if (field[j][i] == 'X') {
        e = j;
        cnt++;
        if (s == -1) s = j;
      }
    }
    if (s >= 0 && cnt != e - s + 1) return -1;
    range.push_back(make_pair(i, make_pair(s, e)));
  }
  int height = 0;
  for (int i = sy; i < n; i++) {
    if (field[i][sx] == 'X')
      height++;
    else
      break;
  }
  bool started = false;
  int width = 1, upper = -1, lower = -1;
  for (int i = 0; i < m; i++) {
    if (i > 0 && range[i].second.first >= 0 &&
        range[i - 1].second.first == -1 && started)
      return -1;
    if (range[i].second.first != -1) started = true;
    if (started) {
      if (lower == -1 && range[i].second.second != sy + height - 1)
        lower = range[i].first;
      if (upper == -1 && range[i].second.first != sy) upper = range[i].first;
      if (upper == -1 && i == m - 1) upper = m;
    }
  }
  if (upper >= 0 && lower >= 0) width = upper - lower;
  if (width <= 0) return -1;
  for (int i = 0; i < n; i++) {
    temp[i][m] = 0;
    for (int j = 0; j < m; j++) temp[i][j] = '.';
  }
  for (int i = 0; i < height; i++)
    for (int j = 0; j < width; j++) temp[sy + i][sx + j] = 'X';
  int cy = sy, cx = sx;
  while (true) {
    bool hor = false, ver = false;
    if (cx + width < m &&
        getSum(cy, cx + width, cy + height - 1, cx + width) == height)
      hor = true;
    if (cy + height < n &&
        getSum(cy + height, cx, cy + height, cx + width - 1) == width)
      ver = true;
    if (hor && ver)
      return -1;
    else if (hor) {
      for (int i = 0; i < height; i++) temp[cy + i][cx + width] = 'X';
      cx++;
    } else if (ver) {
      for (int i = 0; i < width; i++) temp[cy + height][cx + i] = 'X';
      cy++;
    } else
      break;
  }
  for (int i = 0; i < n; i++)
    if (field[i] != temp[i]) return -1;
  return width * height;
}
