#include <bits/stdc++.h>
using namespace std;
int n, m, i, j, x, y, X, Y, ver[2000][2000], gor[2000][2000], cx, cy,
    a[2000][2000], mn;
bool flag, flag1;
string s;
void init() {
  int i, j;
  for (i = 1; i <= n; i++)
    for (j = 1; j <= m; j++)
      if (a[i][j] == 2) a[i][j] = 1;
}
bool run() {
  int i, j, nx = x, ny = y;
  for (i = nx; i <= nx + X - 1; i++)
    for (j = ny; j <= ny + Y - 1; j++) {
      if (a[i][j] == 0) {
        init();
        return false;
      }
      a[i][j] = 2;
    }
  while (1) {
    if (a[nx + X][ny] == 1) {
      for (j = ny; j <= ny + Y - 1; j++) {
        if (a[nx + X][j] == 0) {
          init();
          return false;
        }
        a[nx + X][j] = 2;
      }
      nx++;
      continue;
    }
    if (a[nx][ny + Y] == 1) {
      for (i = nx; i <= nx + X - 1; i++) {
        if (a[i][ny + Y] == 0) {
          init();
          return false;
        }
        a[i][ny + Y] = 2;
      }
      ny++;
      continue;
    }
    break;
  }
  for (i = 1; i <= n; i++) {
    for (j = 1; j <= m; j++) {
      if (a[i][j] == 1) {
        init();
        return false;
      }
    }
  }
  init();
  return true;
}
