  ios_base::sync_with_stdio(false);
  cin >> n >> m;
  flag = false;
  for (i = 1; i <= n; i++) {
    cin >> s;
    for (j = 0; j < m; j++) {
      if (s[j] == 'X') {
        a[i][j + 1] = 1;
        if (!flag) {
          flag = true;
          x = i;
          y = j + 1;
        }
      } else
        a[i][j + 1] = 0;
    }
  }
  if (!flag) {
    cout << -1 << endl;
    return 0;
  }
  for (i = 1; i <= n; i++) {
    gor[i][1] = a[i][1];
    for (j = 2; j <= m; j++) {
      gor[i][j] = gor[i][j - 1] + a[i][j];
    }
  }
  for (j = 1; j <= m; j++) {
    ver[j][1] = a[1][j];
    for (i = 2; i <= n; i++) {
      ver[j][i] = ver[j][i - 1] + a[i][j];
    }
  }
  i = x;
  while (i <= n && a[i][y] == 1) i++;
  i--;
  j = y;
  while (j <= m && a[x][j] == 1) j++;
  j--;
  cx = i;
  cy = j;
