      goto l1;
    }
    if (ver[j][cx] - ver[j][x - 1] == cx - x + 1 && a[cx + 1][j] == 1) {
      flag = true;
      X = cx - x + 1;
      Y = cy - j + 1;
      break;
    }
  }
  if (flag) {
    if (run()) {
      mn = min(mn, X * Y);
    } else {
      goto l1;
    }
  }
