#include <bits/stdc++.h>
int IntMaxVal = (int)1e20;
using namespace std;
template <typename T>
vector<T> readVector(int n) {
  vector<T> res(n);
  for (int i = 0; i < n; i++) cin >> res[i];
  return res;
}
int solve(vector<string> field) {
  int n = field.size();
  int m = field[0].length();
  int minX = -1;
  int minY;
  for (int y = n - 1; y >= 0; y--)
    for (int x = m - 1; x >= 0; x++)
      if (field[y][x] == 'X') {
        minX = x;
        minY = y;
      }
  int w = 1;
  int x = minX;
  int y = minY;
  int h = 1;
  while (x + w < m && field[y][x + w] == 'X') w++;
  vector<char> moves;
  bool moved = true;
  while (moved) {
    moved = false;
    bool canGoDown = y + h < n;
    for (int j = 0; j < w; j++)
      if (canGoDown && field[y + h][x + j] != 'X') canGoDown = false;
    if (canGoDown) {
      moved = true;
      moves.push_back('D');
      y++;
    }
    while (true) {
      bool canMoveRight = x + w < m && field[y][x + w] == 'X';
      if (!canMoveRight)
        break;
      else {
        moved = true;
        moves.push_back('R');
        while (y + h < n && field[y + h][x] == 'X') h++;
        x++;
      }
    }
  }
  char actualPainting[n][m];
  for (int y = 0; y < n; y++)
    for (int x = 0; x < m; x++) actualPainting[y][x] = '.';
  x = minX;
  y = minY;
  if (x + w - 1 >= m || y + h - 1 >= n) return IntMaxVal;
  for (int i = 0; i < h; i++)
    for (int j = 0; j < w; j++) actualPainting[y + i][x + j] = 'X';
  for (auto move : moves) {
    if (move == 'R') {
      x++;
      if (x + w - 1 >= m || y + h - 1 >= n) return IntMaxVal;
      for (int i = 0; i < h; i++) actualPainting[y + i][x + w - 1] = 'X';
    } else {
      y++;
      if (x + w - 1 >= m || y + h - 1 >= n) return IntMaxVal;
      for (int j = 0; j < w; j++) actualPainting[y + h - 1][x + j] = 'X';
    }
  }
  for (int y = 0; y < n; y++)
    for (int x = 0; x < m; x++)
      if (actualPainting[y][x] != field[y][x]) return IntMaxVal;
  while (minX + w < m && field[minY][minX + w] == 'X') w++;
  return w * h;
}
int main() {
  int n;
  cin >> n;
  int m;
  cin >> m;
  auto field = readVector<string>(n);
  int result = solve(field);
  vector<string> field_mirrored(m);
  for (int y = 0; y < n; y++)
    for (int x = 0; x < m; x++) field_mirrored[x].push_back(field[y][x]);
