inline int all(int x1, int y1, int x2, int y2) {
  return num[x2][y2] - num[x2][y1 - 1] - num[x1 - 1][y2] +
             num[x1 - 1][y1 - 1] ==
         (x2 - x1 + 1) * (y2 - y1 + 1);
}
int bs1(int x1, int x2, int y, int d) {
  int l = y, r = m - d + 2;
  while (l < r - 1) {
    int mid = (l + r) >> 1;
    if (all(x1 , x2, y, mid + d - 1))
      l = mid;
    else
      r = mid;
  }
