  if (sx == fx && sy == fy) return 0;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) chtable[i][j] = '.';
  for (int i = sx; i < fx; i++)
    for (int j = sy; j < fy; j++) chtable[i][j] = 'X';
  while (true) {
    bool flag1 = (fx < n && table[fx][sy] == 'X');
    bool flag2 = (fy < m && table[sx][fy] == 'X');
    if (flag1 && flag2)
      return 0;
    else if (flag1) {
      for (int i = sy; i < fy; i++) chtable[fx][i] = 'X';
      fx++;
      sx++;
    } else if (flag2) {
      for (int i = sx; i < fx; i++) chtable[i][fy] = 'X';
      fy++;
      sy++;
    } else
      break;
  }
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++)
      if (chtable[i][j] != table[i][j]) return 0;
  return 1;
}
