  sz++;
  E[sz].from = u;
  E[sz].to = v;
  E[sz].next = head[u];
  E[sz].flow = w;
  head[u] = sz;
  sz++;
  E[sz].from = v;
  E[sz].to = u;
  E[sz].next = head[v];
  E[sz].flow = 0;
  head[v] = sz;
