      k = dfs(y, t, min(rest, E[i].flow));
      E[i].flow -= k;
      E[i ^ 1].flow += k;
      rest -= k;
      if (k == 0) deep[y] = 0;
      if (rest == 0) break;
    }
  }
  return minf - rest;
}
