using namespace std;
const int INT_INF = 2e9;
bool is_prime(int n) {
  for (int i = 0; i * i <= n; i++)
    if (n % i == 0) return false;
  return true;
}
void dfs(vector<vector<int> > &gr, vector<int> &path, vector<bool> &vis,
         int v) {
  if (vis[v]) return;
  path.push_back(v);
  vis[v] = true;
  for (auto u : gr[v]) dfs(gr, path, vis, u);
}
int maxflow_dfs(vector<vector<pair<int, int> > > &gr, vector<int> &path,
                vector<bool> &vis, int s, int t) {
  if (s == t) {
    path.push_back(s);
    return INT_INF;
  }
  if (vis[s]) return 0;
  vis[s] = true;
  int flow_size;
  for (auto e : gr[s]) {
    if (e.second > 0) {
      if (flow_size = maxflow_dfs(gr, path, vis, e.first, t)) {
        path.push_back(s);
        return min(flow_size, e.second);
      }
    }
  }
  return 0;
}
int maxflow(vector<vector<pair<int, int> > > &gr, int s, int t) {
  vector<int> path;
  vector<bool> vis(((int)gr.size()));
  int flow_size;
  int ans = 0;
  while (flow_size = maxflow_dfs(gr, path, vis, s, t)) {
    ans += flow_size;
    reverse(path.begin(), path.end());
    for (int i = 1; i < ((int)path.size()); i++) {
      for (auto &e : gr[path[i - 1]])
        if (e.first == path[i]) e.second -= flow_size;
      for (auto &e : gr[path[i]])
        if (e.first == path[i - 1]) e.second += flow_size;
    }
    path.clear();
    vis = vector<bool>(((int)gr.size()));
  }
  return ans;
}
