      gr[i].emplace_back(n + 1, 2);
    else
      gr[n].emplace_back(i, 2);
    for (int j = i + 1; j < n; j++) {
      if (a[i] % 2 != a[j] % 2 && is_prime(a[i] + a[j]))
        gr[i].emplace_back(j, a[i] % 2), gr[j].emplace_back(i, a[j] % 2);
    }
  }
  int mf = maxflow(gr, n, n + 1);
  if (mf == n) {
