template <int N, typename T>
struct flow {
  const bool SCALING = true;
  const T inf_T = numeric_limits<T>::max();
  struct flow_edge {
    int v, u;
    T f, w;
  };
  vector<flow_edge> adj[N];
  int l[N], p[N], s, t;
  T k;
  void edge(int i, int j, T w, bool directed = true) {
    adj[i].push_back({j, int(adj[j].size()), 0, w});
    adj[j].push_back({i, int(adj[i].size()) - 1, 0, directed ? 0 : w});
  }
  bool bfs() {
    queue<int> q({s});
    fill(l, l + N, -1), l[s] = 0;
    while (!q.empty() && l[t] == -1) {
      int v = q.front();
      q.pop();
      for (auto& e : adj[v])
        if (l[e.v] == -1 && e.f < e.w && (!SCALING || e.w - e.f >= k))
          q.push(e.v), l[e.v] = l[v] + 1;
    }
    return l[t] = -1;
  }
  T dfs(int v, T f) {
    if (v == t || !f) return f;
    for (; p[v] < adj[v].size(); p[v]++) {
      auto& e = adj[v][p[v]];
      if (l[e.v] != l[v] + 1) continue;
      if (T x = dfs(e.v, min(f, e.w - e.f))) {
        e.f += x, adj[e.v][e.u].f -= x;
        return x;
      }
    }
    return 0;
  }
  T solve(int _s, int _t) {
    s = _s, t = _t;
    T out = 0;
    for (k = SCALING ? 1 << 30 : 1; k > 0; k /= 2)
      while (bfs()) {
        fill(p, p + N, 0);
        while (T x = dfs(s, inf_T)) out += x;
      }
    return out;
  }
  vector<bool> cut() {
    vector<bool> out(N, 0);
    out[s] = 1;
    queue<int> q({s});
    while (!q.empty()) {
      int v = q.front();
      q.pop();
      for (auto& e : adj[v])
        if (e.f < e.w && !out[e.v]) out[e.v] = 1, q.push(e.v);
    }
    return out;
  }
};
