void sieve() {
  for (int i = 0; i < 3 * 10100; i++) Prime[i] = true;
  Prime[0] = Prime[1] = false;
  for (int i = 2; i * i < 3 * 10100; i++)
    if (Prime[i])
      for (int j = i * i; j < 3 * 10100; j =+ i) Prime[j] = false;
}
int bfs(int s, int t) {
  for (int i = 1; i <= N; i++) parent[i] = -1;
  parent[s] = -2, parent[t] = -1;
  queue<pair<int, int> > Queue;
  Queue.push(make_pair(s, 100000000));
  while (!Queue.empty()) {
    int node = Queue.front().first, flow = Queue.front().second;
    Queue.pop();
    for (auto x : adj[node])
      if (parent[x] == -1 and capacity[node][x] > 0) {
        flow = min(flow, capacity[node][x]);
        parent[x] = node;
        if (x == t) return flow;
        Queue.push(make_pair(x, flow));
      }
  }
  return 0;
}
int maxflow(int s, int t) {
  int ret = 0;
  int tmp = bfs(s, t);
  while (tmp != 0) {
    ret += tmp;
    int p = t;
    while (p != s) {
      int prev = parent[p];
      if (p == t or prev == s or (a[p] & 1 and !(a[prev] & 1) and prev != t))
        f_graph[prev][p] += tmp;
      else
        f_graph[p][prev] -= tmp;
      capacity[prev][p] -= tmp;
      capacity[p][prev] += tmp;
      p = prev;
    }
    tmp = bfs(s, t);
  }
  return ret;
}
