  if (p != -1 and s == original) return;
  vis[s] = true;
  v.push_back(s);
  for (auto x : adj[s])
    if (x != p and (f_graph[s][x] == 1 or f_graph[x][s] == 1)) {
      dfs(x, s, original, v);
      break;
    }
}
