      int x = q.front();
      q.pop();
      for (int i = 0; i < g[x].size(); i++) {
        Edge& e = edges[g[x][i]];
        if (!vis[e.to] && e.cap > e.flow) {
          vis[e.to] = 1;
          d[e.to] = d[x] + 1;
          q.push(e.to);
        }
      }
    }
    return vis[t];
