class Dinic {
 private:
  struct edge {
    int a, b, cap, flow;
  };
  int n, s, t, d[209], ptr[209], q[209];
  bool matrix[209][209];
  vector<edge> e;
  vector<int> g[209];

 public:
  Dinic(int a, int b, int c) : n(a), s(b), t(c) {}
  void create_adj_list() {
    for (__typeof(209) i = 0; i < 209; i++) {
      for (__typeof(209) j = 0; j < 209; j++) {
        matrix[i][j] = false;
      }
    }
    vector<int> odd, even;
    for (__typeof(N) i = 1; i <= N; i++) {
      if (arr[i] % 2 == 0) {
        even.push_back(i);
      } else {
        odd.push_back(i);
      }
    }
    for (__typeof(int(odd.size())) i = 0; i < int(odd.size()); i++) {
      add_edge(0, odd[i], 2);
    }
    for (__typeof(N) i = 1; i <= N; i++) {
      if (arr[i] % 2 == 0) continue;
      for (__typeof(N) j = 1; j <= N; j++) {
        if (arr[j] % 2 == 0 && is_prime[arr[i] + arr[j]]) {
          add_edge(i, j, 1);
        }
      }
    }
    for (__typeof(int(even.size())) i = 0; i < int(even.size()); i++) {
      add_edge(even[i], N + 1, 2);
    }
  }
  void add_edge(int a, int b, int cap) {
    edge e1 = {a, b, cap, 0};
    edge e2 = {b, a, 0, 0};
    g[a].push_back((int)e.size());
    e.push_back(e1);
    fwd_edge[a][b] = true;
    g[b].push_back((int)e.size());
    e.push_back(e2);
  }
  bool bfs() {
    int qh = 0, qt = 0;
    q[qt++] = s;
    memset(d, -1, n * sizeof d[0]);
    d[s] = 0;
    while (qh < qt && d[t] == -1) {
      int v = q[qh++];
      for (size_t i = 0; i < g[v].size(); ++i) {
        int id = g[v][i], to = e[id].b;
        if (d[to] == -1 && e[id].flow < e[id].cap) {
