      }
      cnt++;
    }
    cout << cnt << '\n';
    for (__typeof(cnt) i = 0; i < cnt; i++) {
      cout << int(tables[i].size()) << ' ';
      for (__typeof(int(tables[i].size())) j = 0; j < int(tables[i].size());
           j++) {
        cout << tables[i][j] << ' ';
      }
      cout << '\n';
    }
  }
};
