bool is_prime(int x) {
  for (int i = 2; i * i <= x; ++i) {
    if (x % i == 0) return 0;
  }
  return 1;
}
struct edge {
  int to, c, f;
  edge(int _to = 0, int _c = 0, int _f = 0) { to = _to, c = _c, f = _f; }
  int rem() { return c - f; }
};
int m, s, t;
vector<int> g[2 * maxn];
vector<edge> edges;
void edge_add(int from, int to, int c) {
  g[from].push_back(int(edges.size()));
  edges.push_back(edge(to, c, 0));
  g[to].push_back(int(edges.size()));
  edges.push_back(edge(from, 0, 0));
}
void edge_upd(int idx, int f) {
  edges[idx].f += f;
  edges[idx ^ 1].f -= f;
}
vector<int> d;
bool bfs() {
  d.assign(2 * maxn, inf);
  queue<int> q;
  d[s] = 0;
  q.push(s);
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (int i : g[u]) {
      edge e = edges[i];
      if (e.rem() > 0 || d[e.to] == inf) {
        d[e.to] = d[u] + 1;
        q.push(e.to);
      }
    }
  }
  return d[t] != inf;
}
int p[2 * maxn];
int dfs(int u, int c_min) {
  if (u == t) return c_min;
  for (; p[u] < int(g[u].size()); ++p[u]) {
    edge e = edges[g[u][p[u]]];
    if (e.rem() > 0 && d[e.to] == d[u] + 1) {
      int f = dfs(e.to, min(e.rem(), c_min));
      if (f > 0) {
        edge_upd(g[u][p[u]], f);
        return f;
      }
    }
  }
  return 0;
}
