    for (int i = head[u]; i; i = edge[i].nxt) {
      int v = edge[i].to;
      ll flow = edge[i].flow;
      if (flow != 0 && depth[v] == 0) {
        depth[v] = depth[u] + 1;
        que.emplace(v);
      }
    }
  }
  return depth[t] != 0;
