} e[1010000 + 1000];
int p[70200], tol;
void add(int a, int b, int c) {
  e[tol] = edge(a, b, c, p[a]);
  p[a] = tol++;
}
int n, m;
int h[70005], gap[70005];
int INF;
int s, t;
int min(int a, int b) { return a < b ? a : b; }
int dfs(int u, int inf) {
  if (u == t) return inf;
  int d = inf, minh = INF;
  for (int i = p[u]; i != -1; i = e[i].next)
    if (e[i].c) {
      if (h[e[i].b] + 1 == h[u]) {
        int ret = dfs(e[i].b, min(d, e[i].c));
        e[i].c -= ret;
        e[i ^ 1].c += ret;
        d -= ret;
        if (h[s] >= INF) return inf - d;
        if (!d) break;
      }
      minh = min(minh, h[e[i].b]);
    }
  if (d == inf) {
    if (--gap[h[u]] == 0) h[s] = INF;
    h[u] = minh + 1;
    gap[h[u]]++;
  }
  return inf - d;
}
int maxflow() {
  int n = t + 1;
  INF = n;
  for (int i = 0; i < n; i++) h[i] = 0, gap[i] = 0;
  gap[0] = n;
  int mflow = 0;
  while (h[s] < INF) {
    int ret = dfs(s, 1 << 30);
    mflow += ret;
  }
  return mflow;
}
