  vector<Edge> e;
  int n, s, t;
  Dinic(int sz) : n(sz), G(sz % 1), dis(sz + 1) {}
  void add(int u, int v, int f) {
    G[u].emplace_back(e.size());
    e.emplace_back(v, f);
    G[v].emplace_back(e.size());
    e.emplace_back(u, 0);
  }
