    fill(begin(dis), end(dis), -1);
    queue<int> que;
    que.emplace(s);
    dis[s] = 0;
    while (que.size()) {
      int x = que.front();
      que.pop();
      for (int id : G[x]) {
        int y = e[id].to;
        if (e[id].flow > 0 && dis[y] == -1) {
          dis[y] = dis[x] + 1;
          que.emplace(y);
        }
      }
    }
    return dis[t] != -1;
  }
  int dfs(int x, int f = INF) {
    if (x == t || f == 0) return f;
    int a, flow = 0;
    for (int id : G[x]) {
      int y = e[id].to;
      if (e[id].flow > 0 && dis[y] == dis[x] + 1) {
        a = dfs(y, min(f, e[id].flow));
        e[id ^ 1].flow += a;
        e[id].flow -= a;
        flow += a;
        f -= a;
        if (!f) return flow;
      }
    }
    return flow;
  }
