int dfs(int s, int t, int flow) {
  if (s == t) return flow;
  int ans = 0;
  for (int i = 0; i < edge[s].size(); i++) {
    node &tmp = edge[s][i];
    if (flow > ans && tmp.cap > 0 && level[tmp.to] == level[s] + 1) {
      int d = dfs(tmp.to, t, min(tmp.cap, flow - ans));
      if (d > 0) {
        tmp.cap -= d;
        edge[tmp.to][tmp.rev].cap += d;
        ans += d;
      }
    }
  }
  if (ans == 0) level[s] = -1;
  return ans;
}
