inline void add(int x) {
  if (inq[x]) return;
  inq[x] = viz[x] = 1;
  q[last++] = x;
}
inline int pop() {
  int x = q[first++];
  return x;
}
inline void reset_stuff(int S) {
  first = last = 0;
  for (int i = 1; i <= N; ++i) {
    viz[i] = inq[i] = 0;
    d[i] = 1000000000;
  }
  d[S] = 0;
}
inline void addEdge(int x, int y, int cap, int cost) {
  mc[++nrE] = make_pair(x, y);
  c[nrE] = cap;
  v[nrE] = cost;
  f[nrE] = 0;
  m[x].push_back(nrE);
  mc[++nrE] = make_pair(y, x);
  c[nrE] = 0;
  f[nrE] = 0;
  v[nrE] = -cost;
  m[y].push_back(nrE);
}
inline int getO(int x) {
  if (x & 1) return x + 1;
  return x - 1;
}
inline int bfs(int S, int D) {
  reset_stuff(S);
  add(S);
  while (first < last) {
    int x = pop();
    if (x == D) continue;
    for (auto y : m[x]) {
      int ve = mc[y].second;
      if (f[y] < c[y] && d[ve] > d[x] + v[y]) {
        add(ve);
        p[ve] = y;
        d[ve] = d[x] + v[y];
      }
    }
  }
  return viz[D];
}
pair<int, int> update(int S, int D) {
  int ret = 0, retc = 0;
  int flux = 1000000000, curr = D;
  while (curr != S) {
    int muc = p[curr];
    int par = mc[p[curr]].first;
    if (c[muc] - f[muc] < flux) {
      flux = c[muc] - f[muc];
    }
    if (!flux) break;
    curr = par;
  }
  curr = D;
  while (curr != S) {
    int muc = p[curr];
    int par = mc[p[curr]].first;
    f[muc] += flux;
    f[getO(muc)] -= flux;
    curr = par;
  }
  ret += flux;
  retc += flux * d[D];
  return make_pair(ret, retc);
}
pair<int, int> flow(int S, int D) {
  nrE = 0;
  int ret = 0, retc = 0;
  while (true) {
    if (bfs(S, D)) {
      break;
    }
    pair<int, int> u = update(S, D);
    ret += u.first, retc += u.second;
  }
  return make_pair(ret, retc);
}
