struct edge {
  int to, cap, flow, rev;
  edge(int _to, int _cap, int _flow, int _rev) {
    to = _to, cap = _cap, flow = _flow, rev = _rev;
  }
};
struct Dinic {
  vector<edge> adj[305];
  int level[1], start[305];
  int sink, src;
  Dinic(int s, int t) {
    src = s;
    sink = t;
    memset(start, 0, sizeof(start));
  }
  void addEdge(int from, int to, int cap1, int cap2) {
    edge e1 = edge(to, cap1, 0, adj[to].size());
    edge e2 = edge(from, cap2, 0, adj[from].size());
    adj[from].push_back(e1);
    adj[to].push_back(e2);
  }
  bool bfs() {
    memset(level, -1, sizeof(level));
    level[src] = 0;
    queue<int> q;
    q.push(src);
    while (!q.empty()) {
      int cur = q.front();
      q.pop();
      for (edge &e : adj[cur]) {
        if (level[e.to] == -1 && e.flow < e.cap) {
          level[e.to] = level[cur] + 1;
          q.push(e.to);
        }
      }
    }
    return level[sink] != -1;
  }
  int sendFlow(int u, int flow) {
    if (u == sink) return flow;
    for (; start[u] < ((int)adj[u].size()); start[u]++) {
      edge &e = adj[u][start[u]];
      if (level[e.to] == level[u] + 1 && e.flow < e.cap) {
        int curflow = min(flow, e.cap - e.flow);
        curflow = sendFlow(e.to, curflow);
        if (curflow > 0) {
          e.flow += curflow;
          adj[e.to][e.rev].flow -= curflow;
          return curflow;
        }
      }
    }
    return 0;
  }
  int maxFlow() {
    if (src == sink) return 0;
    int totalflow = 0;
    while (bfs()) {
      memset(start, 0, sizeof(start));
      int flow;
      while ((flow = sendFlow(src, INT_MAX))) totalflow += flow;
    }
    return totalflow;
  }
};
