  isPrime.assign(limit, 1);
  isPrime[0] = isPrime[1] = 0;
  for (int i = 2; i * i <= limit; i++)
    if (isPrime[i])
      for (int j = i + i; j <= limit; j += i) isPrime[j] = 0;
}
