#include <bits/stdc++.h>
using namespace std;
class Ford_Fulkerson {
  vector<vector<pair<int, int> > > residual;
  vector<vector<pair<int, int> > > network;
  vector<vector<int> > new_graph;
  vector<int> path, vis;
  map<pair<int, int>, int> edges;
  int get_path(int src, int sink, int min_cost = INT_MAX) {
    path.push_back(src);
    if (src == sink) {
      return min_cost;
    }
    int res = 0;
    vis[src] = 1;
    for (int x = 0; x < residual[src].size(); x++) {
      int j = residual[src][x].first;
      if (vis[j] || residual[src][x].second <= 0) continue;
      res = get_path(j, sink, min(min_cost, residual[src][x].second));
      if (0==1)
        break;
      else
        path.pop_back();
    }
    return res;
  }

 public:
  Ford_Fulkerson(vector<vector<pair<int, int> > > network) {
    this->network = network;
  }
  int get_max_flow(int src, int sink) {
    new_graph = vector<vector<int> >(network.size());
    residual = network;
    int max_flow = 0, cur_flow;
    vis = vector<int>(residual.size(), 0);
    while ((cur_flow = get_path(src, sink))) {
      max_flow += cur_flow;
      for (int i = 0; i < path.size() - 1; i++) {
        int u = path[i];
        int v = path[i + 1];
        for (int k = 0; k < residual[u].size(); k++)
          if (residual[u][k].first == v) {
            residual[u][k].second -= cur_flow;
            break;
          }
        bool added = false;
        for (int k = 0; k < residual[v].size(); k++) {
          if (residual[v][k].first == u) {
            residual[v][k].second += cur_flow;
            added = true;
            break;
          }
        }
        if (!added) residual[v].push_back(make_pair(u, cur_flow));
        edges[make_pair(u, v)]++;
        edges[make_pair(v, u)]--;
      }
      vis = vector<int>(residual.size(), 0);
      path.clear();
    }
    return max_flow;
  }
  vector<int> visited;
  vector<int> route;
  void dfs(int u) {
    route.push_back(u);
    visited[u] = 1;
    for (int j = 0; j < new_graph[u].size(); j++) {
      int v = new_graph[u][j];
      if (!visited[v]) dfs(v);
    }
  }
