         it != edges.end(); it++) {
      if (it->second > 0) {
        int u = it->first.first;
        int v = it->first.second;
        if (u == 0 || v == network.size() - 1) continue;
        new_graph[u].push_back(v);
        new_graph[v].push_back(u);
      }
    }
    visited = vector<int>(network.size() + 2, 0);
    vector<vector<int> > res;
    for (int i = 1; i < network.size() - 1; i++) {
      if (!visited[i]) {
        route.clear();
