#include <bits/stdc++.h>
using namespace std;
const int MAXN = 1000;
const int INF = 100000000;
struct MAXFLOW {
  struct edge {
    int a, b, cap, flow;
  };
  int n, s, t, d[MAXN], ptr[MAXN], q[MAXN];
  vector<edge> e;
  vector<int> g[MAXN];
  void add_edge(int a, int b, int cap) {
    edge e1 = {a, b, cap, 0};
    edge e2 = {b, a, 0, 0};
    g[a].push_back((int)e.size());
    e.push_back(e1);
    g[b].push_back((int)e.size());
    e.push_back(e2);
  }
  bool bfs() {
    int qh = 0, qt = 0;
    q[qt++] = s;
    memset(d, -1, n * sizeof d[0]);
    d[s] = 0;
    while (qh < qt && d[t] == -1) {
      int v = q[qh++];
      for (size_t i = 0; i < g[v].size(); ++i) {
        int id = g[v][i], to = e[id].b;
        if (d[to] == -1 && e[id].flow < e[id].cap) {
          q[qt++] = to;
          d[to] = d[v] + 1;
        }
      }
    }
    return d[t] != -1;
  }
  int dfs(int v, int flow) {
    if (!flow) return 0;
    if (v == t) return flow;
    for (; ptr[v] < (int)g[v].size(); ++ptr[v]) {
      int id = g[v][ptr[v]], to = e[id].b;
      if (d[to] != d[v] + 1) continue;
      int pushed = dfs(to, min(flow, e[id].cap - e[id].flow));
      if (pushed) {
        e[id].flow += pushed;
        e[id ^ 1].flow -= pushed;
        return pushed;
      }
    }
    return 0;
  }
  int dinic() {
    int flow = 0;
    for (;;) {
      if (!bfs()) break;
      memset(ptr, 0, n * sizeof ptr[0]);
      while (int pushed = dfs(s, INF)) flow += pushed;
    }
    return flow;
  }
  void reset() {
    e.clear();
    memset(d, -1, n * sizeof d[0]);
    memset(ptr, 0, n * sizeof ptr[0]);
    memset(q, 0, n * sizeof q[0]);
    for (int i = 0; i < n; i++) g[i].clear();
  }
} flow;
bool is_prime(int x) {
  for (int i = 2; i * i <= x; i++)
    if (x % i == 0) return false;
  return true;
}
vector<int> cur_ans;
vector<pair<int, int> > odds;
vector<pair<int, int> > evens;
bool vis[MAXN];
int n;
void build_ans(int i) {
  if (i < n / 2)
    cur_ans.push_back(evens[i].second);
  else
    cur_ans.push_back(odds[i - n / 2].second);
  vis[i] = true;
  for (int j = 0; j < (int)flow.g[i].size(); j++) {
    int id = flow.g[i][j], to = flow.e[id].b, f = flow.e[id].flow;
    if (((f > 0 && i < n / 2) || (f < 0 && i >= n / 2)) && !vis[to] &&
        to != flow.s && to != flow.t) {
      build_ans(to);
      return;
    }
  }
}
int main() {
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    int x;
    scanf("%d", &x);
    if (x & 1)
      odds.push_back({x, i});
    else
      evens.push_back({x, i});
  }
  if (odds.size() != evens.size()) return puts("Impossible"), -1;
  flow.n = n + 2;
  for (int i = 0; i < n / 2; i++)
    for (int j = 0; j < n / 2; j++) {
      if (is_prime(evens[i].first + odds[j].first)) {
        flow.add_edge(i, n / 2 + j, 1);
      }
    }
  flow.s = n;
  flow.t = flow.s + 1;
  for (int i = 0; i < n / 2; i++) {
