void augment(int u, int flow) {
  if (u == source) {
    f = flow;
  } else if (parent[u] != -1) {
    augment(parent[u], min(flow, residual[parent[u]][u]));
    residual[parent[u]][u] -= f;
    residual[u][parent[u]] += f;
  }
}
