    q.push(source);
    vis[source] = true;
    while (!q.empty()) {
      int u = q.front();
      q.pop();
      if (u == sink) {
        break;
      }
      for (int j = 0; j < (int)adj[u].size(); ++j) {
        int v = adj[u][j];
        if (!vis[v] && residual[u][v] > 0) {
          parent[v] = u;
          vis[v] = true;
          q.push(v);
        }
      }
    }
    f = 0;
    augment(sink, 1 << 30);
    ans += f;
  } while (f);
