struct TEdge {
  int from, to;
  long long capacity, flow;
  long long cost;
  TEdge* reverse;
};
TEdge edgePool[1000000];
int edgePoolPtr = 0;
typedef vector<TEdge*> ve;
vector<ve> edges;
int SOURCE, TARGET;
TEdge* AddEdge(int from, int to, long long capacity, long long cost = 0) {
  TEdge* e1 = &edgePool[edgePoolPtr++];
  TEdge* e2 = &edgePool[edgePoolPtr++];
  TEdge fw = {from, to, capacity, 0, cost, e2};
  TEdge bw = {to, from, 0, 0, cost, e1};
  *e1 = fw;
  *e2 = bw;
  edges[from].push_back(e1);
  edges[to].push_back(e2);
  return e1;
}
inline long long AvailableCapacity(const TEdge* p) {
  return (p->capacity - p->flow);
}
vector<int> Distances;
vector<size_t> Ptr;
int N;
void BFS() {
  deque<int> q;
  Distances.assign(N, -1);
  Distances[SOURCE] = 0;
  q.push_back(SOURCE);
  while (!q.empty()) {
    int p = q.front();
    q.pop_front();
    for (size_t i = 0; i < edges[p].size(); i++) {
      if (!AvailableCapacity(edges[p][i])) continue;
      int c = edges[p][i]->to;
      if (Distances[c] == -1) {
        Distances[c] = Distances[p] + 1;
        q.push_back(c);
      }
    }
  }
}
long long DFS(int p, long long fl) {
  if (fl == 0) return 0;
  if (p == TARGET) return fl;
  long long res = 0;
  for (size_t& i = Ptr[p]; Ptr[p] < edges[p].size() && fl != 0; ++i) {
    if (!AvailableCapacity(edges[p][i])) {
      continue;
    }
    if (Distances[edges[p][i]->from] + 1 != Distances[edges[p][i]->to])
      continue;
    long long pushed =
        DFS(edges[p][i]->to, min(fl, AvailableCapacity(edges[p][i])));
    fl -= pushed;
    res += pushed;
    edges[p][i]->flow += pushed;
    edges[p][i]->reverse->flow -= pushed;
    if (fl == 0) break;
  }
  return res;
}
long long GetMaxFlow() {
  N = (int)edges.size();
  long long res = 0;
  while (true) {
    BFS();
    Ptr.assign(N, 0);
    long long p = DFS(SOURCE, 1e18 / 2);
    if (!p) break;
    res += p;
  }
  return res;
}
