      Edge &ed = e[cur[x]];
      if (d[ed.to] == d[x] + 1 &&
          (f = dfs(ed.to, min(ed.cap - ed.flow, a))) > 0) {
        flow += f;
        ed.flow += f;
        e[cur[x] ^ 1].flow -= f;
        a -= f;
        if (a == 0) break;
      }
