  while (!Q.empty()) {
    int u = Q.front();
    Q.pop();
    for (auto i : g[u]) {
      Edge &e = es[i];
      if (level[e.v] < 0 && e.cap > e.flow) {
        level[e.v] = level[u] + 1;
        Q.push(e.v);
      }
    }
  }
  return level[t] > 0;
}
