#include <bits/stdc++.h>
using namespace std;
const int INF = (int)1E9;
int N, S, T, FN;
int L, adj[205], dst[205], pre[205], pret[205];
struct llist {
  int id, next, c, f, w;
  llist() {}
  llist(int _id, int _next, int _c, int _w) {
    id = _id;
    next = _next;
    c = _c;
    f = 0;
    w = _w;
  }
} lists[2 * 100005];
void init() {
  L = 0;
  memset(adj, -1, sizeof(adj));
}
inline void insertList(int &a, int b, int c, int w) {
  lists[L] = llist(b, a, c, w);
  a = L++;
}
inline void insertEdge(int a, int b, int c, int w) {
  insertList(adj[a], b, c, w);
  insertList(adj[b], a, 0, -w);
}
bool spfa() {
  for (int i = (0); i < (FN); i++) dst[i] = INF;
  dst[S] = 0;
  queue<int> que;
  que.push(S);
  while (!que.empty()) {
    int x = que.front();
    que.pop();
    int t = adj[x];
    while (t != -1) {
      int y = lists[t].id, nw = dst[x] + lists[t].w;
      if (lists[t].c != lists[t].f && nw < dst[y]) {
        dst[y] = nw;
        pre[y] = x;
        pret[y] = t;
        que.push(y);
      }
      t = lists[t].next;
    }
  }
  return dst[T] != INF;
}
pair<int, int> sap() {
  int totw = 0, totf = 0;
  while (1) {
    bool augable = spfa();
    if (!augable) break;
    int minflow = INF, x = T;
    while (x != S) {
      int flow = lists[pret[x]].c - lists[pret[x]].f;
      minflow = min(minflow, flow);
      x = pre[x];
    }
    x = T;
    while (x != S) {
      lists[pret[x]].f += minflow;
      lists[pret[x] ^ 1].f = -lists[pret[x]].f;
      x = pre[x];
    }
    totf += minflow;
    totw += minflow * dst[T];
  }
  return make_pair(totf, totw);
}
