queue<int> Q;
vector<vector<int> > ANS;
void input() {
  int i, j;
  scanf("%d", &n);
  for (i = 1; i <= n; i++) scanf("%d", &nums[i]);
}
void Sieve() {
  int i, j;
  for (i = 2; i <= 2 * 10000; i++) sieve[i] = true;
  for (i = 2; i < 141; i++) {
    if (sieve[i]) {
      for (j = i * i; j <= 20000; j += i) sieve[j] = false;
    }
  }
}
void addEdge(int u, int v, int cap) {
  Edges[cnt].from = u;
  Edges[cnt].to = v;
  Edges[cnt].prev = last[u];
  Edges[cnt].cap = cap;
  Edges[cnt].flow = 0;
  last[u] = cnt;
  cnt++;
  Edges[cnt].from = v;
  Edges[cnt].to = u;
  Edges[cnt].prev = last[v];
  Edges[cnt].cap = 0;
  Edges[cnt].flow = 0;
  last[v] = cnt;
  cnt++;
}
void build() {
  int i, j;
  src = 0;
  sink = n + 1;
  memset(last, -1, sizeof(last));
  cnt = 0;
  for (i = 1; i <= n; i++) {
    if (nums[i] % 2)
      addEdge(src, i, 2);
    else
      addEdge(i, sink, 2);
  }
  for (i = 1; i <= n; i++) {
    if (nums[i] % 2 == 0) continue;
    for (j = 1; j <= n; j++) {
      if (nums[j] % 2 == 0 && sieve[nums[i] + nums[j]]) addEdge(i, j, 1);
    }
  }
}
