  vis[src] = true;
  while (!Q.empty()) {
    u = Q.front();
    Q.pop();
    for (e = last[u]; e != -1; e = Edges[e].prev) {
      v = Edges[e].to;
      if (!vis[v] && Edges[e].cap - Edges[e].flow > 0) {
        vis[v] = true;
        Q.push(v);
        p[v] = e;
      }
    }
  }
  return vis[sink];
}
