      for (int j = 0; j < g[i].size(); j++) {
        if (e[g[i][j]].flow == 1 && e[g[i][j]].b > 0 && e[g[i][j]].b <= nn) {
          Ed[i].push_back(e[g[i][j]].b);
          Ed[e[g[i][j]].b].push_back(i);
        }
      }
    }
    return flow;
