  }
  for (int i = 0; i < Edgelist[s].size(); i++) {
    int v = Edgelist[s][i];
    fl[s][v] = cap[s][v];
    fl[v][s] = -1 * cap[s][v];
    e[v] += fl[s][v];
    e[s] -= fl[s][v];
    cf[s][v] = 0;
    cf[v][s] = cap[v][s] - fl[v][s];
  }
