      bits[Edgelist[s][i]] = 1;
    } else
      flow += cap[s][t];
  }
  int cnt = 0;
  while (!Q.empty()) {
    cnt++;
    int u = Q.front();
    m = -1;
    for (int i = 0; i < Edgelist[u].size() && e[u] > 0; i++) {
      v = Edgelist[u][i];
      if (cf[u][v] > 0) {
        if (h[u] > h[v]) {
          push(u, v);
          if (bits[v] == 0 && v != s && v != t) {
            bits[v] = 1;
            Q.push(v);
          }
        } else {
          if (m == -1)
            m = h[v];
          else
            m = min(h[v], m);
        }
      }
    }
    if (e[u] != 0)
