#include <bits/stdc++.h>
using namespace std;
int n;
struct EdmondsKarp {
  struct Edge {
    int dest;
    long long int cap;
    long long int flow;
    int back;
  };
  EdmondsKarp(int n) : G(n) {}
  void addEdge(int src, int dest, long long int cap) {
    if (src == dest) return;
    Edge e1 = {dest, cap, 0, (int)G[dest].size()};
    Edge e2 = {src, 0, 0, (int)G[src].size()};
    G[src].push_back(e1);
    G[dest].push_back(e2);
  }
  long long int maxFlow(int s, int t) {
    long long int ret = 0;
    vector<pair<int, int>> parent;
    while (true) {
      parent.clear();
      parent.resize(G.size(), pair<int, int>(-1, -1));
      queue<int> Q;
      Q.push(s);
      parent[s] = pair<int, int>(s, -1);
      while (!Q.empty()) {
        int v = Q.front();
        Q.pop();
        if (v == t) break;
        for (int i = 0; i < G[v].size(); ++i) {
          if (G[v][i].flow == G[v][i].cap) continue;
          int x = G[v][i].dest;
          if (parent[x].first != -1) continue;
          parent[x] = pair<int, int>(v, i);
          Q.push(x);
        }
      }
      if (parent[t].first == -1) break;
      long long int a = -1;
      int v = t;
      while (v != s) {
        pair<int, int> p = parent[v];
        long long int rem =
            G[p.first][p.second].cap - G[p.first][p.second].flow;
        if (a < 0 || rem < a) a = rem;
        v = p.first;
      }
      ret += a;
      v = t;
      while (v != s) {
        pair<int, int> p = parent[v];
        G[p.first][p.second].flow += a;
        G[v][G[p.first][p.second].back].flow -= a;
        v = p.first;
      }
    }
    return ret;
  }
  vector<vector<Edge>> G;
};
bool nonprime[30000];
int f[250];
vector<int> G2[250];
bool fund[250];
