  nonprime[0] = true;
  nonprime[1] = true;
  for (int i = 2; i < 30000; ++i) {
    for (int x = 2 * i; x < 30000; x += i) {
      nonprime[x] = true;
    }
  }
  cin.sync_with_stdio(false);
  cin >> n;
  EdmondsKarp ek(n - 2);
  for (int i = 0; i < n; ++i) {
    cin >> f[i];
    if (f[i] & 1) {
      ek.addEdge(n, i, 2);
    } else {
      ek.addEdge(i, n + 1, 2);
    }
  }
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      if (!(f[i] & 1)) continue;
      if (!nonprime[f[i] + f[j]]) {
        ek.addEdge(i, j, 1);
      }
    }
  }
  int flow = ek.maxFlow(n, n + 1);
  if (flow != n) {
    cout << "Impossible\n";
    return 0;
  }
  for (int i = 0; i < n; ++i) {
    if (!(f[i] & 1)) continue;
    for (EdmondsKarp::Edge e : ek.G[i]) {
      if (e.cap <= 0 || e.flow != 1) continue;
      G2[i].push_back(e.dest);
      G2[e.dest].push_back(i);
