    if (fund[i]) continue;
    int x = i;
    vector<int> cyc;
    cyc.push_back(x);
    int p = x;
    fund[p] = true;
    x = G2[p][0];
    while (!fund[x]) {
      cyc.push_back(x);
      if (G2[x][0] == p) {
        p = x;
        x = G2[x][1];
      } else {
        p = x;
        x = G2[x][0];
      }
      fund[p] = true;
    }
    cycs.push_back(cyc);
  }
  cout << cycs.size() << '\n';
  for (auto cyc : cycs) {
    cout << cyc.size();
    for (int s : cyc) {
      cout << ' ' << s + 1;
    }
    cout << '\n';
  }
  return 0;
}

