class DINIC {
 public:
  queue<int> Q;
  int n, source, sink;
  vector<int> cur, dis;
  vector<vector<int> > cap;
  vector<vector<int> > nei;
  bool bfs() {
    dis = vector<int>(n + 1, -1);
    dis[source] = 0;
    Q.push(source);
    while (!Q.empty()) {
      int u = Q.front();
      Q.pop();
      for (int v : nei[u])
        if (!~dis[v] && cap[u][v]) {
          dis[v] = dis[u] + 1;
          Q.push(v);
        }
    }
    return ~dis[sink];
  }
  int dfs(int u, int mincap) {
    if (!mincap || u == sink) return mincap;
    int res = 0;
