bool isPrime(int n) {
  for (int i = 2; i < n; i++) {
    if (n % i == 0) {
      return false;
    }
  }
  return true;
}
int edmondsKarp(int s, int t) {
  flow = vector<vector<int> >(N + 2, vector<int>(N + 2, 0));
  vector<int> pre, aug;
  while (true) {
    queue<int> q;
    q.push(s);
    pre = vector<int>(N + 2, -1);
    pre[s] = s;
    aug = vector<int>(N + 2, INT_MAX);
    bool augFound = false;
    while (!q.empty() && !augFound) {
      int u = q.front();
      q.pop();
      for (int i = 0; i < (int)(neigh[u].size()); ++i) {
        int v = neigh[u][i];
        if (C[u][v] - flow[u][v] > 0 && pre[v] == -1) {
          aug[v] = min(C[u][v] - flow[u][v], aug[u]);
          pre[v] = u;
          if (v != t) q.push(v);
          if (v == t) {
            while (pre[v] != v) {
              u = pre[v];
              flow[u][v] += aug[t];
              flow[v][u] -= aug[t];
              v = u;
            }
            augFound = true;
            break;
          }
        }
      }
    }
    if (pre[t] == -1) {
      int sum = 0;
      for (int i = 0; i < (int)(neigh[s].size()); ++i)
        sum += flow[s][neigh[s][i]];
      return sum;
    }
  }
  return 0;
}
