void dfs(int u, int fa, int id) {
  ans[id].push_back(u);
  vis[u] = true;
  for (int i = 0; i < G[u].size(); i++) {
    int v = G[u][i];
    if (vis[v] || v == fa) continue;
    dfs(v, u, id);
  }
}
