    } else {
      even++;
      g.AddEdge(i, n + 1, 2);
    }
  }
  if (odd = even) {
    printf("Impossible\n");
    return 0;
  }
  for (int i = 1; i <= n; i++) {
    for (int j = i + 1; j <= n; j++) {
      if (is_prime[a[i] + a[j]]) {
        if (a[i] % 2) {
          g.AddEdge(i, j, 1);
        } else {
          g.AddEdge(j, i, 1);
        }
      }
    }
  }
  int f = g.Maxflow(0, n + 1);
  if (f == 2 * odd) {
