template <class T>
T abs(T x) {
  return x > 0 ? x : -x;
}
const int maxn = 2100;
int n, m;
int mapp[maxn][maxn];
int mask[maxn][maxn];
int cnt[maxn * maxn];
inline bool valid(int r, int c) {
  if (r >= 0 && c >= 0 && r <= n - 1 && c <= m - 1 && mapp[r][c] == 0) {
    return true;
  }
  return false;
}
bool check() {
  int cmp = 1;
  memset(mask, 0, sizeof(mask));
  memset(cnt, 0, sizeof(cnt));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (mapp[i][j] == 0 && mask[i][j] == 0) {
        queue<pair<int, int> > q;
        q.push(make_pair(i, j));
        mask[i][j] = cmp;
        cnt[cmp]++;
        while (!q.empty()) {
          pair<int, int> cur = q.front();
          q.pop();
          int r = cur.first;
          int c = cur.second;
          if (r + 1 < n && mask[r + 1][c] == 0 && mapp[r + 1][c] == 0) {
            q.push(make_pair(r + 1, c));
            mask[r + 1][c] = cmp;
            cnt[cmp]++;
          }
          if (c + 1 < m && mask[r][c + 1] == 0 && mapp[r][c + 1] == 0) {
            q.push(make_pair(r, c + 1));
            mask[r][c + 1] = cmp;
            cnt[cmp]++;
          }
          if (r > 0 && mask[r - 1][c] == 0 && mapp[r - 1][c] == 0) {
            q.push(make_pair(r - 1, c));
            mask[r - 1][c] = cmp;
            cnt[cmp]++;
          }
          if (c > 0 && mask[r][c - 1] == 0 && mapp[r][c - 1] == 0) {
            q.push(make_pair(r, c - 1));
            mask[r][c - 1] = cmp;
            cnt[cmp]++;
          }
        }
        cmp++;
      }
    }
  }
  bool fail = false;
  for (int i = 1; i < cmp; i++) {
    if (cnt[i] % 2 == 1) {
      fail = true;
      break;
    }
  }
  return !fail;
}
