          (j == 0 || mapp[i][j - 1] != 0) &&
          (j == m - 1 || mapp[i][j + 1] != 0) && i > 0 && mapp[i - 1][j] == 0) {
        mapp[i][j] = 3;
        mapp[i - 1][j] = 2;
        for (int dx = -1; dx <= 1; dx++)
          for (int dy = -1; dy <= 1; dy++) {
            if (valid(i + dx, j + dy)) q.push(make_pair(i + dx, j + dy));
            if (valid(i - 1 + dx, j + dy))
