    if (used[x]) continue;
    int i = x / m, j = x % m;
    for (auto y : g[x])
      if (!used[y]) {
        int ni = y / m, nj = y % m;
        used[x] = 1;
        used[y] = 1;
        t += 2;
        if (ni - i == 1) mp[i][j] = '^', mp[ni][nj] = 'v';
        if (ni - i == -1) mp[i][j] = 'v', mp[ni][nj] = '^';
        if (nj - j == 1) mp[i][j] = '<', mp[ni][nj] = '>';
        if (nj - j == -1) mp[i][j] = '>', mp[ni][nj] = '<';
        for (auto y : g[y])
          if (--deg[y] == 1) q.push(y);
        break;
      }
  }
  int c = 0;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) c += mp[i][j] == '*';
  return t == n * m - c;
}
