  scanf("%d%d", &n, &m);
  for (i = 1; i <= n; i++) scanf("%s", g[i] + 1);
  Build();
  Topsort();
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 2e3 + 5;
const char* FAIL = "";
const int DN = 4;
const int D[DN][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
const int C[DN][2] = {{'<', '>'}, {'^', 'v'}, {'>', '<'}, {'v', '^'}};
int n, m;
char b[N][N];
bool IsValid(int x, int y) {
  return 0 <= x && x < n && 0 <= y && y < m && b[x][y] == '.';
}
bool Check(int x, int y, int* rx, int* ry) {
  int cnt = 0, ri = -1;
  for (int i = 0; i < DN; i++) {
    int tx = x + D[i][0];
    int ty = y + D[i][1];
    if (!IsValid(tx, ty)) {
      continue;
    }
    ri = i;
    cnt++;
    *rx = tx;
    *ry = ty;
    if (cnt > 1) {
      return false;
    }
  }
  if (ri == -1) {
    return false;
  }
  b[x][y] = C[ri][0];
  b[*rx][*ry] = C[ri][1];
  return true;
}
int main() {
  scanf("%d%d", &n, &m);
  deque<pair<int, int> > q;
  int nw = 0, nb = 0;
  for (int i = 0; i < n; i++) {
    scanf("%s", b[i]);
    for (int j = 0; j < m; j++) {
      if (b[i][j] == '*') {
        continue;
      }
      if ((i + j) % 2 == 0) {
        nw++;
      } else {
        nb++;
      }
      q.push_back(pair<int, int>(i, j));
    }
  }
  if (nw != nb) {
    puts(FAIL);
    return 0;
  }
  while (q.size() > 0) {
    pair<int, int> c = q.front();
    q.pop_front();
    int x, y;
    if (!IsValid(c.first, c.second) || !Check(c.first, c.second, &x, &y)) {
      continue;
    }
    for (int i = 0; i < DN; i++) {
      int tx = x + D[i][0];
      int ty = y + D[i][1];
      if (!IsValid(tx, ty)) {
        continue;
      }
      q.push_back(pair<int, int>(tx, ty));
    }
  }
  for (int i = 0; i < n; i++) {
    if (count(b[i], b[i] + m, '.') > 0) {
      puts(FAIL);
      return 0;
    }
  }
  for (int i = 0; i < n; i++) {
    puts(b[i]);
  }
  return 0;
}

