        if (d[nx][ny] == 1) {
          q.push(make_pair(nx, ny));
        }
      }
    }
  }
  for (int(i) = (0); (i) <= (n - 1); ++(i))
    for (int(j) = (0); (j) <= (m - 1); ++(j))
      if (mm[i][j] == '.' && d[i][j]) return 0;
  int sz = ans.size();
  for (int(i) = (0); (i) <= (sz - 1); ++(i)) go(ans[i]);
  for (int(i) = (0); (i) <= (n - 1); ++(i)) cout << mm[i] << endl;
  return 1;
}
