    g[r][c] = g[r + 1][c] = prop = 1;
  }
  if (g[r - 1][c] && !g[r][c - 1] && g[r + 1][c] && g[r][c + 1]) {
    ans[r][c] = 2;
    ans[r][c - 1] = 1;
    g[r][c] = g[r][c - 1] = prop = 1;
  }
