    a[r][c] = 'v';
    a[r - 1][c] = '^';
    return {r - 1, c};
  }
  if (c + 1 < m && a[r][c + 1] == '.') {
    a[r][c] = '<';
    a[r][c + 1] = '>';
    return {r, c + 1};
  }
  if (c - 1 >= 0 && a[r][c - 1] == '.') {
    a[r][c] = '>';
    a[r][c - 1] = '<';
