  if (c[x][y] != '.') return 0;
  int sum = 1;
  for (int i = 0; i < 4; ++i) {
    int tx = x + vx[i], ty = y + vy[i];
    if (tx >= 0 && ty >= 0 && tx < a && ty < b && c[tx][ty] == '.') ++sum;
  }
  return sum;
}
int udlr(int x, int y) {
  for (int i = 0; i < 4; ++i) {
    int tx = x + vx[i], ty = y + vy[i];
    if (tx >= 0 && ty >= 0 && tx < a && ty < b && c[tx][ty] == '.') return i;
  }
  return 4;
}
int tonew(std::queue<xy> &q, int x, int y) {
  if (x >= 0 && y >= 0 && x < a && y < b) {
    int t = find(x, y);
    if (t == 2) {
      q.push(xy(x, y));
      return 1;
    } else if (t != 0)
      return 1;
    else
      return 0;
  };
  return 0;
};
int play() {
  std::queue<xy> q;
  int all = 0;
  for (int i = 0; i < a; ++i)
    for (int j = 0; j < b; ++j) all += tonew(q, i, j);
  if (all % 2) return 0;
  while (q.size()) {
    xy now = q.front();
    q.pop();
    if (c[now.x][now.y] != '.') continue;
    all -= 2;
    switch (udlr(now.x, now.y)) {
      case 0:
        c[now.x][now.y] = 'v';
        --now.x;
        c[now.x][now.y] = '^';
