      case 3:
        c[now.x][now.y] = '<';
        ++now.y;
        c[now.x][now.y] = '>';
        break;
      case 4:
        return 0;
    }
    for (int i = 0; i < 4; ++i) tonew(q, now.x + vx[i], now.y + vy[i]);
  }
  if (all == 0)
    return 1;
