  return x >= 1 && x <= n && y >= 1 && y <= m;
}
void bfs(int a, int b) {
  queue<pair<int, int> > q;
  q.emplace(a, b);
  visited[a][b] = true;
  int total = 0;
  while (!q.empty()) {
    pair<int, int> cur = q.front();
    q.pop();
    int x, y;
    tie(x, y) = cur;
    total++;
    for (auto &each : dir) {
      int nx = x + each.first;
      int ny = y + each.second;
      if (inside(nx, ny) && !visited[nx][ny] && grid[nx][ny] == '.') {
        visited[nx][ny] = true;
        q.emplace(nx, ny);
      }
    }
  }
