int x[] = {0, 0, 1, -1};
int y[] = {1, -1, 0, 0};
int dp[3000][3000];
queue<int> qu;
char str[3000][3000];
int n, m;
int fun(int v, int w) {
  if (v >= 0 && v < n && w >= 0 && w < m && str[v][w] == '.') return 1;
  return 0;
}
void build(int v, int w, int p, int q) {
  if (v > p) swap(v, p);
  if (w > q) swap(w, q);
  if (v == p) {
    str[v][w] = '<';
    str[v][q] = '>';
    return;
  }
  str[v][w] = '^';
  str[p][w] = 'v';
}
void bfs() {
  int a, b, v, w, p, q, l;
  while (!qu.empty()) {
    v = qu.front(), qu.pop();
    w = qu.front(), qu.pop();
    if (str[v][w] != '.') continue;
    for (int i = 0; i < 4; i++) {
      p = v + x[i];
      q = w + y[i];
      l = fun(p, q);
      if (l == 1) {
        build(v, w, p, q);
        for (int j = 0; j < 4; j++) {
          a = p + x[j];
          b = q + y[j];
          l = fun(a, b);
          if (l == 1)
            dp[a][b]--;
          else
            continue;
          if (dp[a][b] == 1) {
            qu.push(a);
            qu.push(b);
          }
        }
        break;
      }
    }
  }
}
