#include <bits/stdc++.h>
using namespace std;
int n, m, val[2005][2005], x[4] =  { 1,0, 0, -1}, y[4] = {1, 0, -1, 0},
                           adjnum[2005][2005];
int ocnt, ecnt;
bool bad[2005][2005];
bool adj[2005][2005][4];
bool vis[2005][2005];
char chs[5] = {'<', '^', '>', 'v', '*'};
void dfs(int a, int b) {
  int i;
  for (i = 0; i < 4; i++) {
    if (adj[a][b][i]) break;
  }
  val[a][b] = i;
  int aa = a + x[i], bb = b + y[i];
  val[aa][bb] = (i + 2) % 4;
  vis[a][b] = true;
  vis[aa][bb] = true;
  for (int j = 0; j < 4; j++) {
    int aaa = aa + x[j], bbb = bb + y[j];
    if (adj[aaa][bbb][(j + 2) % 4]) {
      adj[aaa][bbb][(j + 2) % 4] = false;
      adjnum[aaa][bbb]--;
    }
    if (vis[aaa][bbb] || bad[aaa][bbb]) continue;
    if (adjnum[aaa][bbb] == 1) {
      dfs(aaa, bbb);
    }
  }
}
int main() {
  ios_base::sync_with_stdio(0);
  cin >> n >> m;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      val[i][j] = -1;
      char c;
      cin >> c;
      if (c == '.') {
        if ((i + j) % 2)
          ecnt++;
        else
          ocnt++;
        continue;
      }
      val[i][j] = 4;
      bad[i][j] = true;
    }
  }
  for (int i = 0; i <= n; i++) {
    bad[i][0] = true;
    bad[i][m + 1] = true;
  }
  for (int i = 0; i <= m; i++) {
    bad[0][i] = true;
    bad[n + 1][i] = true;
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      for (int k = 0; k < 4; k++) {
        if (!bad[i + x[k]][j + y[k]]) {
          adj[i][j][k] = true;
          adjnum[i][j]++;
        }
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (!vis[i][j] && !bad[i][j] && adjnum[i][j] == 1) {
        dfs(i, j);
      }
    }
  }
  if (ocnt != ecnt) {
    cout << "Not unique"
         << "\n";
    return 0;
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (val[i][j] == -1) {
        cout << "Not unique"
             << "\n";
        return 0;
      }
    }
  }
