vector<vector<char> > ans;
int N, M;
void put_ans(int v, int w) {
  int i = v / M;
  int j = v % M;
  int i1 = w / M;
  int j1 = w % M;
  if (i1 == i - 1) {
    ans[i][j] = 'v';
    ans[i1][j1] = '^';
  } else if (i1 == i + 1) {
    ans[i][j] = '^';
    ans[i1][j1] = 'v';
  } else if (j1 == j - 1) {
    ans[i][j] = '>';
    ans[i1][j1] = '<';
  } else {
    ans[i][j] = '<';
    ans[i1][j1] = '>';
  }
}
int add(int v, pair<int, int> z) {
  int i = v / M;
  int j = v % M;
  i += z.first;
  j += z.second;
  if (0 <= i and i < N and 0 <= j and j < M) {
    return i * M + j;
  }
  return -1;
}
bool can(int v) { return (v != -1); }
