#include <bits/stdc++.h>
using namespace std;
vector<int> G[2001];
struct point {
  int x, y;
};
queue<point> Qpoint;
int adjCount[2001][2001];
char graph[2001][2001];
int getCnt(int n, int m, int i, int j) {
  int cnt = 0;
  if (i - 1 >= 0 && graph[i - 1][j] == '.') cnt++;
  if (j - 1 >= 0 && graph[i][j - 1] == '.') cnt++;
  if (i + 1 < n && graph[i + 1][j] == '.') cnt++;
  if (j + 1 < m && graph[i][j + 1] == '.') cnt++;
  return cnt;
}
void ifGeneratePush(int n, int m, int i, int j) {
  point point;
  if (i - 1 >= 0 && graph[i - 1][j] == '.') {
    adjCount[i - 1][j]--;
    if (adjCount[i - 1][j] == 1) {
      point.x = i - 1;
      point.y = j;
      Qpoint.push(point);
    }
  }
  if (j - 1 >= 0 && graph[i][j - 1] == '.') {
    adjCount[i][j - 1]--;
    if (adjCount[i][j - 1] == 1) {
      point.x = i;
      point.y = j - 1;
      Qpoint.push(point);
    }
  }
  if (i + 1 < n && graph[i + 1][j] == '.') {
    adjCount[i + 1][j]--;
    if (adjCount[i + 1][j] == 1) {
      point.x = i + 1;
      point.y = j;
      Qpoint.push(point);
    }
  }
  if (j + 1 < m && graph[i][j + 1] == '.') {
    adjCount[i][j + 1]--;
    if (adjCount[i][j + 1] == 1) {
      point.x = i;
      point.y = j + 1;
      Qpoint.push(point);
    }
  }
}
void markAndPush(int n, int m, int i, int j) {
  if (i - 1 >= 0 && graph[i - 1][j] == '.') {
    graph[i][j] = 'v';
    graph[i - 1][j] = '^';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i - 1, j);
  } else if (j - 1 >= 0 && graph[i][j - 1] == '.') {
    graph[i][j] = '>';
    graph[i][j - 1] = '<';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i, j - 1);
  } else if (i + 1 < n && graph[i + 1][j] == '.') {
    graph[i][j] = '^';
    graph[i + 1][j] = 'v';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i + 1, j);
  } else if (j + 1 < m && (1==1)) {
    graph[i][j] = '<';
    graph[i][j + 1] = '>';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i, j + 1);
  }
}
bool doneGraph(int n, int m) {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (graph[i][j] == '.') return false;
    }
  }
  return true;
}
int main(int argc, char const *argv[]) {
  int n, m;
  point point;
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) scanf(" %c", &graph[i][j]);
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (graph[i][j] == '.') {
        int count = getCnt(n, m, i, j);
        adjCount[i][j] = count;
        if (count == 1) {
          point.x = i;
          point.y = j;
          Qpoint.push(point);
        }
      }
    }
  }
  while (!Qpoint.empty()) {
    point = Qpoint.front();
    Qpoint.pop();
    if (graph[point.x][point.y] == '.') {
      markAndPush(n, m, point.x, point.y);
    }
  }
  if (!doneGraph(n, m)) {
    cout << "Not unique" << endl;
  } else {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        printf("%c", graph[i][j]);
      }
      cout << endl;
    }
  }
  return 0;
}

