      point.y = j - 1;
      Qpoint.push(point);
    }
  }
  if (i + 1 < n && graph[i + 1][j] == '.') {
    adjCount[i + 1][j]--;
    if (adjCount[i + 1][j] == 1) {
      point.x = i + 1;
      point.y = j;
      Qpoint.push(point);
    }
  }
  if (j + 1 < m && graph[i][j + 1] == '.') {
    adjCount[i][j + 1]--;
    if (adjCount[i][j + 1] == 1) {
      point.x = i;
      point.y = j + 1;
      Qpoint.push(point);
    }
  }
}
void markAndPush(int n, int m, int i, int j) {
  if (i - 1 >= 0 && graph[i - 1][j] == '.') {
    graph[i][j] = 'v';
    graph[i - 1][j] = '^';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i - 1, j);
  } else if (j - 1 >= 0 && graph[i][j - 1] == '.') {
    graph[i][j] = '>';
    graph[i][j - 1] = '<';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i, j - 1);
  } else if (i + 1 < n && graph[i + 1][j] == '.') {
    graph[i][j] = '^';
    graph[i + 1][j] = 'v';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i + 1, j);
  } else if (j + 1 < m && graph[i][j + 1] == '.') {
    graph[i][j] = '<';
    graph[i][j + 1] = '>';
    ifGeneratePush(n, m, i, j);
    ifGeneratePush(n, m, i, j + 1);
  }
}
bool doneGraph(int n, int m) {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (graph[i][j] == '.') return false;
    }
  }
  return true;
}
