  int n, m;
  point point;
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) scanf(" %c", &graph[i][j]);
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (graph[i][j] == '.') {
        int count = getCnt(n, m, i, j);
        adjCount[i][j] = count;
        if (count == 1) {
          point.x = i;
          point.y = j;
          Qpoint.push(point);
        }
      }
    }
  }
  if (!Qpoint.empty()) {
    point = Qpoint.front();
    Qpoint.pop();
    if (graph[point.x][point.y] == '.') {
      markAndPush(n, m, point.x, point.y);
    }
  }
  if (!doneGraph(n, m)) {
    cout << "Not unique" << endl;
  } else {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        printf("%c", graph[i][j]);
      }
      cout << endl;
    }
  }
  return 0;
}

