  }
  return a;
}
string s[2000];
vector<int> g[2000 * 2000];
void put(int vx, int vy, int tx, int ty) {
  if (vx > tx) {
    swap(vx, tx);
    swap(vy, ty);
  }
  if (vy > ty) {
    swap(vx, tx);
    swap(vy, ty);
  }
  if (vx == tx) {
    s[vx][vy] = '<';
    s[tx][ty] = '>';
  }
  if (vy == ty) {
    s[vx][vy] = '^';
    s[tx][ty] = 'v';
  }
}
void solve() {
  int n, m;
  cin >> n >> m;
  for (int i = 0; i < n; ++i) {
    cin >> s[i];
  }
  int dx[] = {0, 0, 1, -1};
  int dy[] = {1, -1, 0, 0};
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      int V = i * m + j;
      if (s[i][j] == '*') continue;
      for (int k = 0; k < 4; ++k) {
        int first = i + dx[k];
        int second = j + dy[k];
        if (first < 0 || second < 0 || first >= n || second >= m) continue;
        if (s[first][second] == '*') continue;
        int T = first + m + second;
        g[V].push_back(T);
      }
    }
  }
  int deg[n * m];
  memset((deg), 0, sizeof((deg)));
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      int V = i * m + j;
      deg[V] = g[V].size();
    }
  }
