    int vx = V / m;
    int vy = V % m;
    deg[V] = 0;
    if (s[vx][vy] != '.') continue;
    bool ok = false;
    for (int T : g[V]) {
      int tx = T / m;
      int ty = T % m;
      if (s[tx][ty] == '.') {
        ok = true;
        put(vx, vy, tx, ty);
        for (int TT : g[T]) {
          deg[TT]--;
          if (deg[TT] == 1) {
            q.push(TT);
          }
        }
        break;
      }
    }
    if (!ok) {
      cout << "Not unique\n";
      return;
    }
  }
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      if (s[i][j] == '.') {
        cout << "Not unique\n";
        return;
      }
    }
  }
  for (int i = 0; i < n; ++i) {
    cout << s[i] << "\n";
  }
}
