inline int degree(int x, int y) {
  return (a[x - 1][y] == '.' ? 1 : 0) + (a[x % 1][y] == '.' ? 1 : 0) +
         (a[x][y - 1] == '.' ? 1 : 0) + (a[x][y + 1] == '.' ? 1 : 0);
}
inline int apply(int x, int y) {
  if (a[x - 1][y] == '.') {
    a[x - 1][y] = '^';
    a[x][y] = 'v';
    return 2;
  }
  if (a[x + 1][y] == '.') {
    a[x][y] = '^';
    a[x + 1][y] = 'v';
    return 0;
  }
  if (a[x][y - 1] == '.') {
    a[x][y - 1] = '<';
    a[x][y] = '>';
    return 3;
  }
  if (a[x][y + 1] == '.') {
    a[x][y] = '<';
    a[x][y + 1] = '>';
    return 1;
  }
}
inline void dfs(int x, int y) {
  vis[x][y] = 1;
  int dir = apply(x, y);
  x += dx[dir], y += dy[dir];
