  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      for (int k = 0; k < 4; k++) {
        int x = i + adj[k][0];
        int y = j + adj[k][1];
        cnt[i][j] += grid[x][y] == '.';
      }
      if (grid[i][j] == '.') {
        if (cnt[i][j] == 1) {
          Q.push(pair<int, int>(i, j));
        }
