        int x = i + dx[k];
        int y = j + dy[k];
        deg[x][y]++;
      }
    }
  }
  queue<pair<int, int>> q;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (a[i][j] != '.') continue;
      if (deg[i][j] == 1) q.push({i, j});
    }
  }
  while (!q.empty()) {
    pair<int, int> cur = q.front();
    q.pop();
    int i = cur.first;
    int j = cur.second;
    if (a[i][j] != '.') continue;
