      a[x][j] = '^';
      a[i][j] = 'v';
    } else if (i < x) {
      a[i][j] = '^';
      a[x][j] = 'v';
    } else if (j > y) {
      a[i][y] = '<';
      a[i][j] = '>';
    } else if (j < y) {
      a[i][j] = '<';
      a[i][y] = '>';
    }
    for (int k = 0; k < 4; k++) {
      int _x = x + dx[k];
      int _y = y + dy[k];
      if (a[_x][_y] != '.') continue;
      if (--deg[_x][_y] == 1) {
        q.push({_x, _y});
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
