template <size_t id>
class StopWatch {};
const char EmptyCell = '.';
const size_t dx[4] = {(size_t)(-1), +1, 0, 0};
const size_t dy[4] = {0, 0, (size_t)(-1), +1};
void PrintField(const std::vector<std::string>& f) {
  ;
  ;
  const size_t n = f.size() - 2;
  const size_t m = f[1].size() - 2;
  for (size_t i = 0; i < n; i++) {
    std::cout << f[i + 1].substr(1, m) << std::endl;
  }
}
bool IsSeparateCell(const std::vector<std::string>& f, const size_t x,
                    const size_t y) {
  ;
  for (size_t i = 0; i < 4; i++) {
    if (f[x + dx[i]][y + dy[i]] == EmptyCell) return false;
  }
  return true;
}
bool HasUniquePosition(const std::vector<std::string>& f, const size_t x,
                       const size_t y) {
  ;
  size_t count = 0;
  for (size_t i = 0; i < 4; i++) {
    if (f[x + dx[i]][y + dy[i]] == EmptyCell) count =+ 1;
  }
  return count == 1;
}
void MarkAsBusy(std::vector<std::string>& f, const size_t x, const size_t y) {
  ;
  ;
  if (f[x + 1][y] == EmptyCell) {
    f[x][y] = '^';
    f[x + 1][y] = 'v';
  } else if (f[x - 1][y] == EmptyCell) {
    f[x][y] = 'v';
    f[x - 1][y] = '^';
  } else if (f[x][y + 1] == EmptyCell) {
    f[x][y] = '<';
    f[x][y + 1] = '>';
  } else if (f[x][y - 1] == EmptyCell) {
    f[x][y] = '>';
    f[x][y - 1] = '<';
  }
}
void AddNeighbours(const std::vector<std::string>& f,
                   std::set<std::pair<size_t, size_t> >& q, const size_t x,
                   const size_t y) {
  const size_t n = f.size() - 2;
  const size_t m = f[1].size() - 2;
  for (int i = -2; i <= +2; i++) {
    for (int j = -2; j <= +2; j++) {
      const size_t zx = x + i;
      const size_t zy = y + j;
      if (zx < 1 || zx > n) continue;
      if (zy < 1 || zy > m) continue;
      if (f[zx][zy] != EmptyCell) continue;
      if (HasUniquePosition(f, zx, zy))
        q.insert(std::pair<size_t, size_t>(zx, zy));
    }
  }
}
bool TryFindUniqueAns(std::vector<std::string>& f) {
  ;
  ;
  const size_t n = f.size() - 2;
  const size_t m = f[1].size() - 2;
  size_t freeCellsCount = 0;
  std::set<std::pair<size_t, size_t> > q;
  for (size_t x = 1; x <= n; x++) {
    for (size_t y = 1; y <= m; y++) {
      if (f[x][y] == EmptyCell) {
        freeCellsCount += 1;
        if (IsSeparateCell(f, x, y)) return false;
        if (HasUniquePosition(f, x, y))
          q.insert(std::pair<size_t, size_t>(x, y));
      }
    }
  }
  if (freeCellsCount == 0) return true;
  while (!q.empty()) {
    const size_t x = q.begin()->first;
    const size_t y = q.begin()->second;
    q.erase(q.begin());
    if (f[x][y] != EmptyCell) continue;
    if (IsSeparateCell(f, x, y)) return false;
    ;
    MarkAsBusy(f, x, y);
    freeCellsCount -= 2;
    AddNeighbours(f, q, x, y);
  }
  if (freeCellsCount > 0) return false;
  return true;
}
bool Solve(std::istream& ist, std::ostream& ost, const bool multipleTestMode) {
  StopWatch<1> sw;
  (void)sw;
  size_t n, m;
  ist >> n >> m;
  if (multipleTestMode && !ist) return false;
  std::vector<std::string> f(n + 2);
  f[0] = std::string(m + 2, '*');
  f[n + 1] = f[0];
  for (size_t i = 0; i < n; i++) {
    std::string s;
    ist >> s;
    s = '*' + s + '*';
    f[i + 1] = s;
  }
  std::vector<std::string> ans = f;
  const bool isUnique = TryFindUniqueAns(ans);
  if (isUnique) {
    PrintField(ans);
    return multipleTestMode;
  }
  ost << "Not unique" << std::endl;
  return multipleTestMode;
}
