inline void Conv(int c, int &x, int &y) {
  x = c / m;
  y = c % m;
  if (y == 0)
    y = m;
  else
    ++x;
}
inline void Solve(const int c1, const int c2) {
  pair<int, int> x, y;
  Conv(c1, x.first, x.second);
  Conv(c2, y.first, y.second);
