      if (is(x - 2, y)) t.x = x - 2, t.y = y, q.push(t);
      if (is(x - 1, y - 1)) t.x = x - 1, t.y = y - 1, q.push(t);
      if (is(x - 1, y + 1)) t.x = x - 1, t.y = y + 1, q.push(t);
    }
  }
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++)
      if (c[i + 1][j + 1] == '.') {
