    FREE -= 2;
    for (int p = 0; p < 4; ++p)
      if (get(a.first + sft[p][0], a.second + sft[p][1]) == '.') {
        int x = a.first + sft[p][0];
        int y = a.second + sft[p][1];
        --deg[x][y];
        if (deg[x][y] == 1) Q[QR++] = make_pair(x, y);
      }
    for (int p = 0; p < 4; ++p)
      if (get(b.first + sft[p][0], b.second + sft[p][1]) == '.') {
        int x = b.first + sft[p][0];
        int y = b.second + sft[p][1];
        --deg[x][y];
        if (deg[x][y] == 1) Q[QR++] = make_pair(x, y);
      }
  }
