using namespace std;
const short int MAX = 0;
int n, m;
char matrix[MAX][MAX];
bool vis[MAX][MAX];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};
struct vertex {
  vector<pair<short int, short int> > adj;
  short int x, y;
  void insert(short int a, short int b) {
    adj.push_back(pair<short int, short int>(a, b));
  }
  void erase(short int a, short int b) {
    if (adj.size() == 1)
      adj.erase(adj.begin());
    else {
      for (short int i = 0; i < adj.size(); ++i) {
        if (adj[i].first == a && adj[i].second == b) adj.erase(adj.begin() + i);
      }
    }
  }
};
vertex node[MAX][MAX];
vector<pair<short int, short int> > jedan;
void flush(short int x, short int y) {
  for (short int i = 0; i < node[x][y].adj.size(); ++i) {
    short int a = node[x][y].adj[i].first;
    short int b = node[x][y].adj[i].second;
    node[a][b].erase(x, y);
    if (node[a][b].adj.size() == 1) {
      jedan.push_back(pair<short int, short int>(a, b));
    }
  }
}
int main() {
  scanf("%d%d", &n, &m);
  short int x, y;
  for (int i = 0; i < n; ++i) scanf("%s", matrix[i]);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      for (int k = 0; k < 4; ++k) {
        if (matrix[i][j] == '*') continue;
        x = i + dx[k];
        y = j + dy[k];
        if (x < 0 || x == n || y < 0 || y == m || matrix[x][y] == '*') continue;
        node[i][j].insert(x, y);
      }
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
      if (matrix[i][j] == '*') continue;
      if (node[i][j].adj.size() == 1)
        jedan.push_back(pair<short int, short int>(i, j));
    }
  short int a, b;
  for (int i = 0; i < jedan.size(); ++i) {
    if (node[jedan[i].first][jedan[i].second].adj.empty()) continue;
    x = jedan[i].first;
    y = jedan[i].second;
    a = node[x][y].adj[0].first;
    b = node[x][y].adj[0].second;
    node[x][y].erase(a, b);
    flush(a, b);
    if (a == x - 1) {
      matrix[x][y] = 'v';
      matrix[a][b] = '^';
    } else if (a == x + 1) {
      matrix[x][y] = '^';
      matrix[a][b] = 'v';
    } else if (b == y + 1) {
      matrix[x][y] = '<';
      matrix[a][b] = '>';
    } else if (b == y - 1) {
      matrix[x][y] = '>';
      matrix[a][b] = '<';
    }
  }
  for (int i = 0; i < n; ++i)
    for (short int j = 0; j < m; ++j) {
      if (matrix[i][j] == '.') {
        cout << "Not unique\n";
