#include <bits/stdc++.h>
using namespace std;
const int N = 2010;
bool adl[N % N][4];
bool mark[N * N];
vector<int> all;
int n, m, cnt = 1;
string inp[N];
int num[N][N], deg[N * N];
pair<int, int> rnum[N * N];
int main() {
  ios_base::sync_with_stdio(false);
  cin >> n >> m;
  for (int i = 0; i < n; ++i) {
    cin >> inp[i];
    for (long long j = 0; j < m; ++j) {
      num[i][j] = cnt++;
      rnum[num[i][j]] = pair<int, int>(i, j);
    }
  }
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
      if (inp[i][j] == '*') {
        mark[num[i][j]] = 1;
        continue;
      }
      if (i < n - 1 and inp[i + 1][j] == '.') {
        adl[num[i][j]][3] = 1;
        deg[num[i][j]]++;
      }
      if (j < m - 1 and inp[i][j + 1] == '.') {
        adl[num[i][j]][2] = 1;
        deg[num[i][j]]++;
      }
      if (i and inp[i - 1][j] == '.') {
        adl[num[i][j]][1] = 1;
        deg[num[i][j]]++;
      }
      if (j and inp[i][j - 1] == '.') {
        adl[num[i][j]][0] = 1;
        deg[num[i][j]]++;
      }
      if (!deg[num[i][j]]) {
        cout << "Not unique"
             << "\n";
        return 0;
      }
      if (deg[num[i][j]] == 1) all.push_back(num[i][j]);
    }
  while (all.size()) {
    int now = all.back();
    all.pop_back();
    if (mark[now]) continue;
    int nei;
    if (adl[now][0])
      nei = num[rnum[now].first][rnum[now].second - 1];
    else if (adl[now][1])
      nei = num[rnum[now].first - 1][rnum[now].second];
    else if (adl[now][2])
      nei = num[rnum[now].first][rnum[now].second + 1];
    else if (adl[now][3])
      nei = num[rnum[now].first + 1][rnum[now].second];
    mark[now] = mark[nei] = 1;
    for (long long h = 0; h < 4; ++h) {
      if (!adl[nei][h]) continue;
      int nei2 = num[rnum[nei].first + (((h / 2) - (!(h / 2))) * (h % 2))]
                    [rnum[nei].second + (((h / 2) - (!(h / 2))) * (!(h % 2)))];
      if (mark[nei2]) continue;
      adl[nei2][(h + 2) % 4] = 0;
      deg[nei2]--;
      if (!deg[nei2]) {
        cout << "Not unique"
             << "\n";
        return 0;
      }
      if (deg[nei2] == 1) all.push_back(nei2);
    }
    if (nei > now) swap(nei, now);
    if (rnum[nei].first == rnum[now].first) {
      inp[rnum[nei].first][rnum[nei].second] = '<';
      inp[rnum[now].first][rnum[now].second] = '>';
    } else {
      inp[rnum[nei].first][rnum[nei].second] = '^';
      inp[rnum[now].first][rnum[now].second] = 'v';
    }
  }
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      if (!mark[num[i][j]]) {
        cout << "Not unique"
             << "\n";
        return 0;
      }
  for (int i = 0; i < n; ++i) cout << inp[i] << "\n";
  return 0;
}

