int n, m, a[2015][2015];
int gr[2015][2015];
queue<pair<int, int> > q;
int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};
void border() {
  for (int i = 1; i <= n; i++) {
    a[i][0] = 1;
    a[i][m + 1] = 1;
  }
  for (int i = 1; i <= m; i++) {
    a[0][i] = 1;
    a[n + 1][i] = 1;
  }
}
void check_gr() {
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++)
      if (a[i][j] == 0) {
        for (int k = 0; k < 4; k++) gr[i][j] += (1 - a[i + dx[k]][j + dy[k]]);
        if (gr[i][j] == 1) q.push({i, j});
      }
}
void scad_grad(int first, int second) {
  for (int i = 0; i < 4; i++) {
    if (gr[first + dx[i]][second + dy[i]] > 0)
      gr[first + dx[i]][second + dy[i]]--;
    if (gr[first + dx[i]][second + dy[i]] == 1)
      q.push({first + dx[i], second + dy[i]});
  }
}
void fill_a(int first, int second, int i, int j) {
  if (first == i) {
    if (second < j)
      a[first][second] = 2, a[i][j] = 3;
    else
      a[first][second] = 3, a[i][j] = 2;
  }
  if (second == j) {
    if (first > i)
      a[first][second] = 4, a[i][j] = 5;
    else
      a[first][second] = 5, a[i][j] = 4;
  }
}
