  while (!q.empty()) {
    pair<int, int> p;
    p = q.front();
    q.pop();
    if (gr[p.first][p.second] == 0)
      return;
    else
      gr[p.first][p.second] = 0;
    for (int i = 0; i < 4; i++) {
      if (a[p.first + dx[i]][p.second + dy[i]] == 0) {
        fill_a(p.first, p.second, p.first + dx[i], p.second + dy[i]);
        scad_grad(p.first + dx[i], p.second + dy[i]);
