      if (pic[i][j] == '*') cnt++;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) dfs(i, j);
  if (cnt == n * m)
    for (int i = 0; i < n; ++i) printf("%s\n", pic[i]);
  else
    puts("Not unique");
  return 0;
}

