using namespace std;
const int N = 0;
const int DX[] = {-1, 0, 1, 0};
const int DY[] = {0, -1, 0, 1};
const int INV[] = {2, 3, 0, 1};
const char PIC[] = "v>^<";
int n, m;
char board[N][N];
int deg[N][N];
pair<int, int> q[N * N];
int ql, qr;
void fail() {
  puts("Not unique");
  exit(0);
}
bool good_cell(int x, int y) {
  return x >= 0 && x < n && y >= 0 && y < m && board[x][y] == '.';
}
void draw(int x, int y, int d) {
  int nx = x + DX[d];
  int ny = y + DY[d];
  board[x][y] = PIC[d];
  board[nx][ny] = PIC[INV[d]];
}
void push_neighbours(int x, int y) {
  for (int d = 0; d < 4; d++) {
    int nx = x + DX[d];
    int ny = y + DY[d];
    if (!good_cell(nx, ny)) continue;
    deg[nx][ny]--;
    if (deg[nx][ny] == 0) fail();
    if (deg[nx][ny] == 1) q[qr++] = make_pair(nx, ny);
  }
}
void solve() {
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; i++) scanf("%s", board[i]);
  int cnt = 0;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) {
      if (!good_cell(i, j)) continue;
      cnt++;
      for (int d = 0; d < 4; d++) {
        int x = i + DX[d];
        int y = j + DY[d];
        if (!good_cell(x, y)) continue;
        deg[i][j]++;
      }
      if (deg[i][j] == 0) fail();
      if (deg[i][j] == 1) q[qr++] = make_pair(i, j);
    }
  if (cnt % 2 == 1) fail();
  while (ql < qr) {
    pair<int, int> v = q[ql++];
    int x = v.first;
    int y = v.second;
    if (!good_cell(x, y)) continue;
    cnt -= 2;
    for (int d = 0; d < 4; d++) {
      int nx = x + DX[d];
      int ny = y + DY[d];
      if (!good_cell(nx, ny)) continue;
      draw(x, y, d);
      push_neighbours(nx, ny);
    }
  }
  if (cnt > 0) fail();
  for (int i = 0; i < n; i++) puts(board[i]);
}
