vector<pair<int, int> > moves = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};
vector<pair<int, int> > v;
int pos(int i, int j) { return m * i + j; }
bool can(int i, int j) {
  return 0 <= i && i < n && 0 <= j && j < m && s[i][j] == '.';
}
int get(int i, int j) {
  int res = 0;
  for (auto it : moves)
    if (can(i + it.first, j + it.second)) {
      res++;
      to[i][j] = pos(i + it.first, j + it.second);
    }
  return res;
}
void upd(int i, int j) {
  if (!can(i, j)) return;
  if (vis[i][j]) return;
  if (get(i, j) == 1) {
    vis[i][j] = 1;
    v.push_back({i, j});
  }
}
