using namespace std;
int n, m;
int a[2010][2010], vis[2010][2010];
char Ch[6] = {'*', '.', '<', '>', '^', 'v'};
int dir[4][2] = {1, 0, -1, 0, 0, 1, 0, -1};
int deg[2010][2010];
void dfs(int x, int y) {
  for (int i = 0; i < 4; i++) {
    int dx = x + dir[i][0], dy = y + dir[i][1];
    if ((1 <= dx && dx <= n && 1 <= dy && dy <= m && a[dx][dy] == 1)) {
      deg[x][y]++;
    }
  }
}
struct node {
  int x, y;
};
queue<node> q;
void solve(int x, int y) {
  for (int i = 0; i < 4; i++) {
    int dx = x + dir[i][0], dy = y + dir[i][1];
    if ((1 <= dx && dx <= n && 1 <= dy && dy <= m && a[dx][dy] == 1)) {
      deg[dx][dy]--;
      if (deg[dx][dy] == 1) q.push((node){dx, dy});
    }
  }
}
bool work(int x, int y) {
  for (int i = 0; i < 4; i++) {
    int dx = x + dir[i][0], dy = y + dir[i][1];
    if ((1 <= dx && dx <= n && 1 <= dy && dy <= m && a[dx][dy] == 1)) {
      if (i == 0) a[x][y] = 4, a[dx][dy] = 5;
      if (i == 1) a[x][y] = 5, a[dx][dy] = 4;
      if (i == 2) a[x][y] = 2, a[dx][dy] = 3;
      if (i == 3) a[x][y] = 3, a[dx][dy] = 2;
      solve(dx, dy);
      return 1;
    }
  }
  return 0;
}
