      a[i][j] = ch == '.';
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if ((1 <= i && i <= n && 1 <= j && j <= m && a[i][j] == 1)) dfs(i, j);
      if (deg[i][j] == 1) q.push((node){i, j});
    }
