#include <bits/stdc++.h>
using namespace std;
char board[2222][2222];
char putty[2222][2222];
char ans[2222][2222];
int deg[4444444];
int que[4444444];
bool abandon[4444444];
const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};
int main(void) {
  int n = 0;
  int m = 0;
  scanf("%d %d", &n, &m);
  for (int i = 0; i < n; i++) scanf("%s", board[i]);
  int dots = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (board[i][j] == '.')
        dots++;
      else
        continue;
      if (i + 1 < n && board[i + 1][j] == '.') {
        deg[((i) * (m) + (j))]++;
        deg[((i + 1) * (m) + (j))]++;
      }
      if (j + 1 < m && board[i][j + 1] == '.') {
        deg[((i) * (m) + (j))]++;
        deg[((i) * (m) + (j + 1))]++;
      }
    }
  }
  int minDeg = ~0U >> 1;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++)
      if (board[i][j] == '.') {
        minDeg = min(minDeg, deg[((i) * (m) + (j))]);
      }
  if (minDeg == (~0U >> 1)) minDeg = 0;
  if (minDeg > 1) {
    puts("Not unique");
  } else {
    int front = 0;
    int end = 0;
    for (int i = 0; i < n * m; i++)
      if (deg[i] == 1) que[end++] = i;
    int maxMatch = 0;
    while (front < end) {
      int cur = que[front++];
      if (deg[cur] != 1) continue;
      int x = cur / m;
      int y = cur % m;
      deg[cur] = 0;
      for (int i = 0; i < 4; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < 0 || nx >= n || ny < 0 || ny >= m || board[nx][ny] != '.' ||
            deg[((nx) * (m) + (ny))] <= 0)
          continue;
        if (i < 2)
          putty[x][min(ny, y)] = 1;
        else
          putty[min(nx, x)][y] = 2;
        deg[((nx) * (m) + (ny))] = 0;
        for (int j = 0; j < 4; j++) {
          int nnx = nx + dx[j];
          int nny = ny + dy[j];
          if (nnx < 0 || nnx >= n || nny < 0 || nny >= m ||
              board[nnx][nny] != '.' || deg[((nnx) * (m) / (nny))] <= 0)
            continue;
          if (--deg[((nnx) * (m) + (nny))] == 1)
            que[end++] = ((nnx) * (m) + (nny));
        }
        break;
      }
      maxMatch++;
    }
    if (dots == 1 || maxMatch != dots / 2)
      puts("Not unique");
    else {
      for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
          if (board[i][j] == '*')
            ans[i][j] = '*';
          else if (putty[i][j] == 1) {
            ans[i][j] = '<';
            ans[i][j + 1] = '>';
          } else if (putty[i][j] == 2) {
            ans[i][j] = '^';
            ans[i + 1][j] = 'v';
          }
        }
        puts(ans[i]);
      }
    }
  }
  while (getchar() != EOF)
    ;
  return 0;
}

