void solve() {
  cin >> n >> m;
  for (int i = 0; i < n; i++) {
    cin >> ss[i];
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (ss[i][j] == '.') {
        if (i && ss[i - 1][j] == '.') {
          cnt[i][j]++;
          neighbors[i][j].push_back(make_pair(i - 1, j));
        }
        if (j && ss[i][j - 1] == '.') {
          cnt[i][j]++;
          neighbors[i][j].push_back(make_pair(i, j - 1));
        }
        if (i < n - 1 && ss[i + 1][j] == '.') {
          cnt[i][j]++;
          neighbors[i][j].push_back(make_pair(i + 1, j));
        }
        if (j < m - 1 && ss[i][j + 1] == '.') {
          cnt[i][j]++;
          neighbors[i][j].push_back(make_pair(i, j + 1));
        }
      }
    }
  }
  vector<pair<int, int> > coors;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (cnt[i][j] == 1) {
        coors.push_back(make_pair(i, j));
      }
    }
  }
  while (true) {
    while (coors.empty() == false &&
           ss[coors.back().first][coors.back().second] != '.') {
      coors.pop_back();
    }
    if (coors.empty()) break;
    pair<int, int> pos = coors.back();
    coors.pop_back();
    int x = pos.first;
    int y = pos.second;
    cnt[x][y]--;
    if (x && ss[x - 1][y] == '.') {
      cnt[x - 1][y]--;
      ss[x][y] = 'v';
      ss[x - 1][y] = '^';
      if (cnt[x - 1][y] == 1) {
        coors.push_back(make_pair(x - 1, y));
      }
      for (auto p : neighbors[x - 1][y]) {
        if (ss[p.first][p.second] == '.') {
