void sh(int x1, int y1) {
  int toX, toY;
  int coun;
  int x, y;
  for (int i = 0; i < 4; i++) {
    toX = x1 + dx[i];
    toY = y1 + dy[i];
    if (toX < 0 || toX >= n || toY < 0 || toY >= m || grid[toX][toY] != '.')
      continue;
    coun = 0;
    for (int k = 0; k < 4; k++) {
      x = toX + dx[k];
      y = toY + dy[k];
      if (x < 0 || x >= n || y < 0 || y >= m) continue;
      if (grid[x][y] == '.') {
        coun++;
      }
    }
    if (coun == 1) {
      for (int k = 0; k < 4; k++) {
        x = toX + dx[k];
        y = toY + dy[k];
        if (x < 0 || x >= n || y < 0 || y >= m) continue;
        if (grid[x][y] == '.') {
          q.push(pair<pair<int, int>, pair<int, int> >(pair<int, int>(toX, toY),
                                                       pair<int, int>(x, y)));
        }
      }
    }
  }
}
