  if (i == ii) {
    if (j > jj)
      s[i][j] = '>', s[ii][jj] = '<';
    else
      s[i][j] = '<', s[ii][jj] = '>';
  } else {
    if (i > ii)
      s[i][j] = 'v', s[ii][jj] = '^';
    else
      s[i][j] = '^', s[ii][jj] = 'v';
  }
  cover[i][j] = cover[ii][jj] = 1;
  vector<pair<int, int> > tmp(2);
  tmp[0] = {i, j};
