  for (int kk = 0; kk < 2; ++kk) {
    int i = tmp[kk].first, j = tmp[kk].second;
    for (int di = -1; di < 2; ++di) {
      for (int dj = -1; dj < 2; ++dj) {
        if (abs(di) + abs(dj) < 2 && (di || dj)) {
          if (ok(i + di, j + dj)) tmp.push_back({i + di, j + dj});
        }
      }
    }
  }
  for (int kk = 0; kk < tmp.size(); ++kk) {
