    for (int j = 0; j < m; ++j) {
      int cnt = 0;
      for (int di = -1; di < 2; ++di) {
        for (int dj = -1; dj < 2; ++dj) {
          if (abs(di) + abs(dj) < 2 && (di || dj)) {
            if (okay(i, j, i + di, j + dj)) ++cnt;
          }
        }
      }
      if (cnt == 1) forced.push_back({i, j});
