bool isOk(int i, int j) {
  int deg = 0;
  deg += t[i][j + 1] == '.' ? 1 : 0;
  deg += t[i][j - 1] == '.' ? 1 : 0;
  deg += t[i + 1][j] == '.' ? 1 : 0;
  deg += t[i - 1][j] == '.' ? 1 : 0;
  return deg == 1;
}
void dfs(void) {
  while (!q.empty()) {
    int x = q.front().first, y = q.front().second;
    q.pop();
    if (t[x][y] != '.') {
      continue;
    }
    if (t[x][y] == t[x][y + 1]) {
      t[x][y] = '<', t[x][y + 1] = '>';
      if (t[x][y + 2] == '.' && isOk(x, y + 2)) q.push(make_pair(x, y + 2));
      if (t[x + 1][y + 1] == '.' && isOk(x + 1, y + 1))
        q.push(make_pair(x + 1, y + 1));
      if (t[x - 1][y + 1] == '.' && isOk(x - 1, y + 1))
        q.push(make_pair(x - 1, y + 1));
    } else if (t[x][y] == t[x][y - 1]) {
      t[x][y] = '>', t[x][y - 1] = '<';
      if (y > 1 && t[x][y - 2] == '.' && isOk(x, y - 2))
        q.push(make_pair(x, y - 2));
      if (t[x + 1][y - 1] == '.' && isOk(x + 1, y - 1))
        q.push(make_pair(x + 1, y - 1));
      if (t[x - 1][y - 1] == '.' && isOk(x - 1, y - 1))
        q.push(make_pair(x - 1, y - 1));
    } else if (t[x][y] == t[x + 1][y]) {
      t[x][y] = '^', t[x + 1][y] = 'v';
      if (t[x + 2][y] == '.' && isOk(x + 2, y)) q.push(make_pair(x + 2, y));
      if (t[x + 1][y + 1] == '.' && isOk(x + 1, y + 1))
        q.push(make_pair(x + 1, y + 1));
      if (t[x + 1][y - 1] == '.' && isOk(x + 1, y - 1))
        q.push(make_pair(x + 1, y - 1));
    } else if (t[x][y] == t[x - 1][y]) {
      t[x][y] = 'v', t[x - 1][y] = '^';
      if (x > 1 && t[x - 2][y] == '.' && isOk(x - 2, y))
        q.push(make_pair(x - 2, y));
