          if ((x >= 0) && (x < n) && (y >= 0) && (y < m) && (!a[x][y])) {
            c[num[i][j]]++;
          }
        }
        all++;
      }
    }
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if ((!a[i][j]) && (c[num[i][j]] == 1)) {
        tnode u;
        u.num = num[i][j];
        u.data = c[u.num];
        u.x = i;
        u.y = j;
        p.push(u);
      }
    }
  }
  int cnt = 0;
  while (!p.empty()) {
    tnode u = p.front();
    p.pop();
    for (int i = 0; i < 4; i++) {
      int x = u.x + xm[i], y = u.y + ym[i];
      if ((x >= 0) && (x < n) && (y >= 0) && (y < m) && (!a[x][y])) {
        if (i == 2) {
          a[u.x][u.y] = 4;
          a[x][y] = 5;
        } else if (i == 3) {
          a[u.x][u.y] = 5;
          a[x][y] = 4;
        } else if (i == 0) {
          a[u.x][u.y] = 2;
          a[x][y] = 3;
        } else if (i == 1) {
          a[u.x][u.y] = 3;
          a[x][y] = 2;
        }
        for (int j = 0; j < 4; j++) {
          int xl = x + xm[j], yl = y + ym[j];
          if ((xl >= 0) && (xl < n) && (yl >= 0) && (yl < m) && (!a[xl][yl]) &&
              (c[num[xl][yl]] > 1)) {
            tnode t;
            t.x = xl;
            t.y = yl;
            t.num = num[xl][yl];
            c[t.num]--;
            t.data = c[t.num];
            if (t.data == 1) p.push(t);
          }
        }
        cnt += 2;
        break;
      }
    }
  }
  if (cnt < all)
    printf("Not unique\n");
  else {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (a[i][j] == 0)
          printf(".");
        else if (a[i][j] == 1)
