        else if (a[i][j] == 2)
          printf("<");
        else if (a[i][j] == 3)
          printf(">");
        else if (a[i][j] == 4)
          printf("^");
        else if (a[i][j] == 5)
          printf("v");
      }
      printf("\n");
    }
  }
  return 0;
}

