struct N {
  int x, y;
};
queue<N> q;
char Map[0][2010];
int jx[] = {-1, 0, 1, 0};
int jy[] = {0, 1, 0, -1};
char CalChar(int dir) {
  if (dir == 0) return 'v';
  if (dir == 1) return '<';
  if (dir == 2) return '^';
  return '>';
}
int Check(int x, int y, int n, int m) {
  bool hav = false;
  int dir;
  for (int i = 0; i < 4; ++i) {
    if (1 <= x + jx[i] && x + jx[i] <= n && 1 <= y + jy[i] && y + jy[i] <= m &&
        Map[x + jx[i]][y + jy[i]] == '.') {
      if (hav) return -1;
      hav = true;
      dir = i;
    }
  }
  if (hav == false) return -2;
  return dir;
}
void Output(int n, int m) {
  for (int i = 1; i <= n; ++i) puts(Map[i] + 1);
  puts("");
}
int main() {
  int n, m, i, j, tmp;
  scanf("%d %d", &n, &m);
  for (i = 1; i <= n; ++i) scanf("%s", Map[i] + 1);
  for (i = 1; i <= n; ++i) {
    for (j = 1; j <= m; ++j) {
      if (Map[i][j] == '.') {
        tmp = Check(i, j, n, m);
        if (0 <= tmp) {
          q.push((N){i + jx[tmp], j + jy[tmp]});
          Map[i][j] = CalChar(tmp);
          Map[i + jx[tmp]][j + jy[tmp]] = CalChar((tmp + 2) % 4);
        }
      }
    }
  }
  N f, t;
  while (q.empty() == false) {
