      for (int k = 0; k < 4; k++) {
        int x = i + dx[k];
        int y = j + dy[k];
        if (x < 0 || x == N || y < 0 || y == M || grid[x][y] == '*') continue;
        deg[i][j]++;
      }
      if (grid[i][j] == '.' && deg[i][j] == 1) Q.push(make_pair(i, j));
    }
