  if (y > 0 && sc[y - 1][x] == '.') {
    ret++;
  }
  if (x < m - 1 && sc[y][x + 1] == '.') {
    ret++;
  }
  if (y < n - 1 && sc[y + 1][x] == '.') {
    ret++;
  }
