  if (sc[y][x] != '.') {
    return;
  }
  if (x > 0 && sc[y][x - 1] == '.') {
    sc[y][x] = '>';
    sc[y][x - 1] = '<';
    makeupd(x, y);
    makeupd(x - 1, y);
