#include <bits/stdc++.h>
using namespace std;
const int N = 222;
const int NN = N << 1;
string vow, word;
char buff[NN];
bool igraph[NN][NN], graph[NN][NN];
vector<vector<int> > sccs;
stack<int> st;
bool inst[NN];
int mini[NN], ti, ans[NN], comp[NN], nc[N], nv[N];
bool ok;
int n, m, k;
int tarjan(int u) {
  int cur = ++ti;
  st.push(u);
  inst[u] = true;
  mini[u] = cur;
  for (int v = (2); v <= (2 * n + 1); v++) {
    if (graph[u][v]) {
      if (!mini[v]) {
        mini[u] = min(mini[u], tarjan(v));
      } else if (inst[v]) {
        mini[u] = min(mini[u], mini[v]);
      }
    }
  }
  if (mini[u] == cur) {
    vector<int> scc;
    k++;
    while (1) {
      int x = st.top();
      st.pop();
      inst[x] = false;
      comp[x] = k;
      if (comp[x] == comp[x ^ 1]) {
        ok = false;
      }
      scc.push_back(x);
      if (x == u) {
        break;
      }
    }
    sccs.push_back(scc);
  }
  return mini[u];
}
bool twoSat() {
  k = 0;
  sccs.clear();
  ok = true;
  ti = 0;
  fill(mini + 1, mini + 2 * n + 2, 0);
  fill(comp + 1, comp + 2 * n + 2, 0);
  fill(inst + 1, inst + 2 * n + 2, false);
  for (int u = (2); u <= (2 * n + 1); u++) {
    if (!mini[u]) {
      tarjan(u);
    }
  }
  if (!ok) {
    return false;
  }
  return true;
}
bool rem;
