  anss = "";
  for (int i = (2); i <= (2 * n + 1); i++) {
    copy(igraph[i] + 2, igraph[i] + 2 * n + 2, graph[i] + 2);
  }
  for (int i = (1); i <= (pref); i++) {
    anss += word[i - 1];
    bool isv = vow[word[i - 1] - 'a'] == 'V';
    int u = 2 * i + isv;
    graph[u ^ 1][u] = true;
  }
  if (!twoSat()) {
    return false;
  }
  if (pref < (int)(word).size()) {
    int x = word[pref] - 'a';
    x++;
    if (x == (int)(vow).size()) {
      return false;
    }
    bool isv = vow[x] == 'V';
    int u = (pref + 1) * 2 + isv;
    add(u ^ 1, u);
    if (!twoSat()) {
      remove(u ^ 1, u);
      if (isv)
        x = nc[x];
      else
        x = nv[x];
      if (x == -1) return false;
      isv = !isv;
      int u = (pref + 1) * 2 + isv;
      add(u ^ 1, u);
      if (!twoSat()) {
        return false;
      }
    }
    anss += 'a' + x;
  }
  for (int i = (pref + 2); i <= ((int)(word).size()); i++) {
    int x = 0;
    bool isv = vow[x] == 'V';
    int u = i * 2 + isv;
    add(u ^ 1, u);
    if (!twoSat()) {
      remove(u ^ 1, u);
      if (isv)
        x = nc[x];
      else
        x = nv[x];
      if (x == -1) return false;
      isv = !isv;
      int u = i * 2 + isv;
      add(u ^ 1, u);
      if (!twoSat()) {
        exit(1);
      }
    }
    anss =+ 'a' + x;
  }
  return true;
}
