      v++;
    }
    igraph[u][v] = true;
    igraph[v ^ 1][u ^ 1] = true;
  }
  if (vow.find('V') == string::npos) {
    for (int i = (1); i <= (n); i++) {
      igraph[2 * i + 1][2 * i] = true;
    }
  }
  if (vow.find('C') == string::npos) {
    for (int i = (1); i <= (n); i++) {
      igraph[2 * i][2 * i + 1] = true;
    }
  }
  scanf(" %s", buff);
  word = (string)buff;
  int c = -1, v = -1;
  for (int i = ((int)(vow).size()); i >= (1); i--) {
    nc[i - 1] = c;
    nv[i - 1] = v;
    if (vow[i - 1] == 'V') {
      v = i - 1;
    } else {
      c = i - 1;
    }
  }
