template <typename T>
T min(T x, T y) {
  return x < y ? x : y;
}
template <typename T>
T max(T x, T y) {
  return x > y ? x : y;
};
const int MAXN = 405;
const int MAXM = 205 * 205 * 9;
namespace Graph {
int E[MAXN][MAXN];
void addedge(int u, int v) { E[u][v]++; }
int dfn[MAXN], low[MAXN];
int S[MAXN], sz;
int scc[MAXN], cnt;
int dfs_clock;
void clear() {
  memset(dfn, 0, sizeof(dfn));
  memset(low, 0, sizeof(low));
  memset(scc, 0, sizeof(scc));
  sz = cnt = dfs_clock = 0;
}
void dfs(int v) {
  low[v] = dfn[v] = ++dfs_clock;
  S[sz++] = v;
  for (int to = 1; to < MAXN; to++) {
