bitset<MASKSZ> closure[2][MAXN];
bool used[2][MAXN];
void dfs(int t, int v) {
  if (used[t][v]) return;
  closure[t][v].set(2 * v + t);
  used[t][v] = true;
  for (const rib &r : g[t][v]) {
    dfs(r.t, r.pos);
    closure[t][v] |= closure[r.t][r.pos];
  }
}
