#include <bits/stdc++.h>
using namespace std;
const int N = 1e3;
int n;
vector<int> g[N], gCopy[N];
int t, in[N], low[N];
vector<int> s;
bool stacked[N];
int scc[N], scc_n;
void tarjan(int u) {
  low[u] = in[u] = t++;
  s.push_back(u);
  stacked[u] = true;
  for (int v : g[u]) {
    if (in[v] == -1) {
      tarjan(v);
      low[u] = min(low[u], low[v]);
    } else if (stacked[v])
      low[u] = min(low[u], in[v]);
  }
  if (low[u] == in[u]) {
    for (;;) {
      int v = s.back();
      s.pop_back();
      stacked[v] = false;
      scc[v] = scc_n;
      if (v == u) break;
    }
    scc_n++;
  }
}
void tarjan_scc() {
  for (int i = 0; i < (n); ++i) {
    in[i] = low[i] = -1;
    stacked[i] = false;
  }
  scc_n = t = 0;
  for (int i = 0; i < (n); ++i)
    if (in[i] == -1) tarjan(i);
}
void add_constr(int a, bool neg_a, int b, bool neg_b) {
  g[2 * a + neg_a].push_back(2 * b + neg_b);
  g[2 * b + 1 - neg_b].push_back(2 * a + 1 - neg_a);
}
bool solve_2sat() {
  tarjan_scc();
  for (int i = 0; i < ((n / 2)); ++i)
    if (scc[2 * i] == scc[2 * i + 1]) return false;
  return true;
}
int m, alph;
string pattern, orig;
bool monoPattern;
void buildGraph(const string& s, int firstFree) {
  for (int i = 0; i < (n); ++i) g[i] = gCopy[i];
  for (int i = 0; i < (firstFree); ++i) {
    int id = s[i] - 'a';
    add_constr(i, (pattern[id] != 'V'), i, (pattern[id] == 'V'));
  }
  if (monoPattern) {
    for (int i = (firstFree); i <= ((int)(s).size() - 1); ++i) {
      add_constr(i, (pattern[0] != 'V'), i, (pattern[0] == 'V'));
    }
  }
}
int main() {
  ios_base::sync_with_stdio(0);
  int wordLen;
  cin >> pattern;
  alph = (int)(pattern).size();
  cin >> wordLen >> m;
  monoPattern = true;
  for (int i = 0; i < (alph); ++i)
    if (pattern[i] != pattern[0]) monoPattern = false;
  n = 2 + wordLen;
  for (int i = 0; i < (m); ++i) {
    int a, b;
    char t1, t2;
    cin >> a >> t1 >> b >> t2;
    a--;
    b--;
    add_constr(a, (t1 == 'V'), b, (t2 == 'V'));
  }
  cin >> orig;
  for (int i = 0; i < (n); ++i) gCopy[i] = g[i];
  buildGraph(orig, wordLen);
  if (solve_2sat()) {
    cout << orig << endl;
    return 0;
  }
  int chosenPos = -1;
  bool ok = false;
  for (int pos = wordLen - 1; pos >= 0 && !ok; pos--) {
    int id = orig[pos] - 'a';
    if (id == alph - 1) continue;
    int index[2] = {id + 1, id + 1};
    while (index[0] < alph && pattern[index[0]] != 'V') index[0]++;
    while (index[1] < alph && pattern[index[1]] != 'C') index[1]++;
    if (index[0] > index[1]) swap(index[0], index[1]);
    for (int i = 0; i < 2 && !ok; i++) {
      if (index[i] >= alph) continue;
      string s = orig;
      s[pos] = 'a' + index[i];
      buildGraph(s, pos + 1);
      if (solve_2sat()) {
        ok = true;
        orig = s;
        chosenPos = pos;
      }
    }
  }
  if (!ok) {
    cout << "-1\n";
    return 0;
  }
  for (int pos = (chosenPos + 1); pos <= (wordLen - 1); ++pos) {
    orig[pos] = 'a';
    int firstDiff = 0;
    while (firstDiff < alph && pattern[firstDiff] == pattern[0]) firstDiff++;
    buildGraph(orig, pos + 1);
    if (!solve_2sat()) {
      orig[pos] = 'a' + firstDiff;
    }
  }
  cout << orig << endl;
  return 0;
}

