      if (x == (int)c[j].size())
        nex[i][j] = -1;

        nex[i][j] = c[j][x];
    }
  }
}
int limit;
int line[maxm];
int top;
bool mark[maxn];
bool go(int cn) {
  if (mark[cn ^ 1]) return false;
  if (mark[cn]) return true;
  if ((cn >> 1) < limit) {
    if (type[str[cn >> 1]] != (cn & 1)) return false;
  } else if ((cn >> 1) == limit) {
    if (nex[str[limit]][cn & 1] == -1) return false;
  } else {
    if (c[cn & 1].size() == 0) return false;
  }
  mark[cn] = true;
  line[++top] = cn;
  for (int i = fst[cn]; i; i = nxt[i]) {
    if (!go(v[i])) {
      return false;
    }
  }
  return true;
}
bool check(int pos) {
  limit = pos;
  memset(mark, 0, sizeof(mark));
  if (str[limit] == l - 1) return false;
  for (int i = 0; i < n; i++) {
    if (i < limit) {
      if (!go((i << 1) + type[str[i]])) return false;
    } else if (i == limit) {
      top = 0;
      if (!go((i << 1) + type[str[i] + 1])) {
        while (top > 0) mark[line[top--]] = false;
        top = 0;
        if (!go((i << 1) + (type[str[i] + 1] ^ 1))) {
          while (top > 0) mark[line[top--]] = false;
          return false;
        }
      }
    } else {
      top = 0;
      if (!go((i << 1) + type[0])) {
        while (top > 0) mark[line[top--]] = false;
        top = 0;
        if (!go((i << 1) + (type[0] ^ 1))) {
          while (top > 0) mark[line[top--]] = false;
          return false;
        }
      }
    }
  }
  return true;
}
void solve() {
  str[n] = -1;
  for (int i = n; i >= 0; i--) {
    if (check(i)) {
      for (int j = 0; j < n; j++) {
        if (j < i)
          putchar('a' + str[j]);
        else if (j == i) {
          if (mark[j << 1])
            putchar('a' + nex[str[i]][0]);
          else
            putchar('a' + nex[str[i]][1]);
        } else {
          if (mark[j << 1])
            putchar('a' + c[0][0]);
          else
            putchar('a' + c[1][0]);
        }
      }
      putchar('\n');
      return;
    }
  }
  printf("-1\n");
}
