bool isgood(const vector<vector<char> > &graph, vector<char> choice) {
  int n = (int)graph.size() / 2;
  assert((int)graph[0].size() == 2 * n);
  assert((int)choice.size() == n);
  for (int i = 0; i < n; i++)
    if (choice[i] != -1)
      if (graph[2 * i + choice[i]][2 * i + 1 - choice[i]]) return false;
  for (int i = 0; i < n; i++)
    if (choice[i] == -1) {
      bool ok = false;
      for (int who = 2 * i; who <= 2 * i + 1; who++) {
        bool cur = true;
        for (int j = 0; j < n; j++)
          if (graph[who][2 * j] && graph[who][2 * j + 1]) cur = false;
        if (!cur) choice[i] = ((who + 1) % 2);
        ok |= cur;
      }
      if (!ok) return false;
    }
  vector<int> q(2 * n);
  vector<char> used(2 * n);
  int l = 0, r = 0;
  for (int i = 0; i < n; i++)
    if (choice[i] != -1)
      q[r++] = 2 * i + 1 - choice[i], used[2 * i + 1 - choice[i]] = 1;
  for (int i = 0; i < 2 * n; i++)
    if (!used[i] && graph[i][i ^ 1]) used[i] = 1, q[r++] = i;
  while (r > l) {
    int cur = q[l++];
    for (int i = 0; i < 2 * n; i++)
      if (!used[i] && graph[i][cur]) q[r++] = i, used[i] = 1;
  }
  for (int i = 0; i < 2 * n; i++)
    if (used[i] && used[i ^ 1]) return false;
  return true;
}
