  if (col_cpy[u] != -1) return col_cpy[u] == ty;
  col_cpy[u] = ty;
  for (int i = hd[ty * n + u]; ~i; i = e[i].net) {
    int v = e[i].v;
    if (!(v > n ? dfs(v - n, 1) : dfs(v, 0))) return 0;
