    if (c2[0] == 'V') t2 = -2;
    int u = x * 2 + t1, v = y * 2 + t2;
    E[u].push_back(v);
    E[v ^ 1].push_back(u ^ 1);
  }
  for (int i = 0; i < n * 2; i++) {
    h.push(i);
    vis[i][i] = 1;
    while (h.size()) {
      int u = h.front();
      for (int j = 0; j < E[u].size(); j++) {
        int v = E[u][j];
        if (!vis[i][v]) {
          vis[i][v] = 1;
          h.push(v);
        }
      }
      h.pop();
    }
    is[i] = 1;
    for (int j = 0; j < n * 2; j++)
      if (vis[i][j] && vis[i][j ^ 1]) {
        is[i] = 0;
        break;
      }
  }
  for (int i = 1; i <= n; i++)
    for (int j = 0; j < l; j++) {
      int u = Get(j + 'a', i);
      if (is[u]) {
        if (s[j] == 'V') MaxV[i] = j;
        if (s[j] == 'C') MaxC[i] = j;
      }
    }
  scanf("%s", T + 1);
  for (int fix = 1; fix <= n; fix++) {
    int u = Get(T[fix], fix);
    bool flag = 1;
    for (int i = 0; i < n * 2; i++) pre[i] = num[i];
    for (int i = 0; i < n * 2; i++) {
      num[i] += vis[u][i];
      if (num[i] && num[i ^ 1]) {
        flag = 0;
        break;
      }
    }
    if ((flag && check(fix))) {
      for (int i = 0; i < n * 2; i++) num[i] = pre[i];
      for (int j = 1; j < fix; j++) ans[j] = T[j];
      for (int i = fix; i <= n; i++) {
        int st = 'a';
        if (i == fix) st = T[i] + 1;
        for (int j = st; j < 'a' + l; j++) {
          for (int k = 0; k < 2 * n; k++) pre[k] = num[k];
          bool flag = 1;
          int u = Get(j, i);
          for (int k = 0; k < 2 * n; k++) {
            pre[k] += vis[u][k];
            if (pre[k] && pre[k ^ 1]) {
              flag = 0;
              break;
            }
          }
          if (flag) {
            for (int k = 0; k < 2 * n; k++) num[k] = pre[k];
            ans[i] = j;
            break;
          }
        }
        if (ans[i] == 0) {
          printf("-1\n");
          return 0;
        }
      }
      break;
    }
    if (flag && fix == n) {
      for (int i = 1; i <= n; i++) printf("%c", T[i]);
      printf("\n");
      return 0;
    }
  }
  for (int i = 1; i <= n; i++) printf("%c", ans[i]);
  printf("\n");
  return 0;
}

