} t[M];
inline int read() {
  int f = 1, x = 0;
  char s = getchar();
  while (s < '0' || s > '9') {
    if (s == '-') f = -1;
    s = getchar();
  }
  while (s >= '0' && s <= '9') {
    x = x * 10 + s - '0';
    s = getchar();
  }
  return x * f;
}
inline void add_edge(int x, int y) {
  nxt[++tot] = first[x];
  first[x] = tot;
  point[tot] = y;
}
inline int get(int x, int tp) {
  int ans = 0x3f3f3f3f;
  for (int i = 0; i < (int)p[tp].size(); i++)
    if (p[tp][i] >= ch[x] - 'a') ans = min(ans, p[tp][i]);
  return ans;
}
inline int getpos(int x, int tp) {
  int ans = 0x3f3f3f3f;
  for (int i = 0; i < (int)p[tp].size(); i++)
    if (p[tp][i] > ch[x] - 'a') ans = min(ans, p[tp][i]);
  return ans;
}
inline int top(int tp) {
  if (p[tp].empty()) return 0x3f3f3f3f;
  return p[tp][0];
}
void dfs(int x) {
  s.push(x);
  dfn[x] = low[x] = ++cnt;
  in[x] = 1;
  for (int i = first[x]; i != -1; i = nxt[i]) {
    int u = point[i];
    if (!dfn[u])
      dfs(u), low[x] = min(low[x], low[u]);
    else if (in[u])
      low[x] = min(low[x], dfn[u]);
  }
  if (dfn[x] == low[x]) {
    w++;
    while (s.top() != x) color[s.top()] = w, in[s.top()] = 0, s.pop();
    color[x] = w, in[x] = 0;
    s.pop();
  }
}
