struct Node {
  vector<Node *> edges;
  int dfn, low, scc;
  bool inq;
  Node();
  void tarjan() {
    dfn = low = ++dfs_tick;
    static Node *stk[MAX_N];
    static int top;
    int lvl = ++top;
    stk[lvl] = this;
    inq = true;
    for (Node *i : edges) {
