        i->tarjan();
        low = min(low, i->low);
      } else if (i->inq) {
        low = min(low, i->dfn);
      }
    }
    if (low >= dfn) {
      n_scc++;
      while (top >= lvl) {
        stk[top]->inq = false;
        stk[top--]->scc = n_scc;
      }
    }
  }
};
