  for (int i = 1; i <= N; i++) ans[i] = A[i];
  if (check(N)) {
    return output();
  }
  int diff;
  for (diff = N; diff; diff--) {
    for (int i = 1; i < diff; i++) ans[i] = A[i];
    if (A[diff] == L) continue;
    ans[diff] = A[diff] + 1;
    if (check(diff)) {
      break;
    } else {
      int c;
      for (c = A[diff] + 1; c <= L; c++) {
        if (is_vowel[c] != is_vowel[A[diff] + 1]) break;
      }
      if (c > L) continue;
      ans[diff] = c;
      if (check(diff)) {
        break;
      }
    }
  }
  if (!diff) {
    printf("-1\n");
    return;
  }
  for (int i = diff + 1; i <= N; i++) {
    ans[i] = 1;
    if (check(i))
      continue;
    else {
      while (is_vowel[ans[i]] == is_vowel[1]) ans[i]++;
    }
  }
  output();
}
