    isVowel[i] = (ch[i] == 'V');
  }
  for (int i = 0; i < L; i++) {
    nxtVowel[i] = ('z' + 1);
    nxtConsonant[i] = ('z' + 1);
    for (int j = i + 1; j < L; j++) {
      if (isVowel[j]) {
        nxtVowel[i] = 'a' + j;
        break;
      }
    }
    for (int j = i + 1; j < L; j++) {
      if (!isVowel[j]) {
        nxtConsonant[i] = 'a' + j;
        break;
      }
    }
  }
  first_C = ('z' + 1);
  first_V = ('z' + 1);
  for (int i = L - 1; i >= 0; i--) {
    if (isVowel[i])
      first_V = 'a' + i;
    else
      first_C = 'a' + i;
  }
}
