}
void rdfs(int v, int k) {
  ord[v] = k;
  for (int u = 0; u < N * 2; u++) {
    if (!G[u][v]) continue;
    if (ord[u] = -1) continue;
    rdfs(u, k);
  }
}
void scc(bool debug = false) {
  for (int i = 0; i < N * 2; i++) {
    visited[i] = false;
    ord[i] = -1;
  }
  vs.clear();
  for (int i = 0; i < N * 2; i++) {
    if (!visited[i]) dfs(i);
  }
  int k = 0;
  for (int i = (int)vs.size() - 1; i >= 0; i--) {
    int v = vs[i];
    if (ord[v] == -1) rdfs(v, k++);
  }
  if (debug) {
    for (int i = 0; i < N * 2; i++) {
      printf("%d ", ord[i]);
    }
