  }
  return true;
}
void addEdge(int pos, char ch) {
  if (isVowel[ch - 'a'])
    G[pos * 2 + 1][pos * 2] = true;
  else
    G[pos * 2][pos * 2 + 1] = true;
}
void delEdge(int pos) {
  G[pos * 2][pos * 2 + 1] = false;
  G[pos * 2 + 1][pos * 2] = false;
}
char ans[220];
void solve() {
  for (int i = 0; i < N; i++) {
    if (isVowel[S[i] - 'a'])
      G[i * 2 + 1][i * 2] = true;
    else
      G[i * 2][i * 2 + 1] = true;
  }
  bool flg = isValid();
  if (flg) {
    strcpy(ans, S);
    return;
  }
  strcpy(ans, S);
  int lcp = -1;
  for (int i = N - 1; i >= 0; i--) {
    delEdge(i);
    char cands[2];
    cands[0] = nxtConsonant[S[i] - 'a'];
    cands[1] = nxtVowel[S[i] - 'a'];
    if (cands[0] > cands[1]) swap(cands[0], cands[1]);
    bool suc = false;
    for (int j = 0; j < 2; j++) {
      if (cands[j] > 'z') continue;
      addEdge(i, cands[j]);
      bool flg = isValid();
      if (flg) {
        suc = true;
        ans[i] = cands[j];
        break;
      }
      delEdge(i);
    }
    if (suc) {
      lcp = i;
      break;
    }
  }
  if (lcp == -1) {
    ans[0] = '\0';
    return;
  }
  for (int i = lcp + 1; i < N; i++) {
    char cands[2];
    cands[0] = first_C;
    cands[1] = first_V;
    if (cands[0] > cands[1]) swap(cands[0], cands[1]);
    bool suc = false;
    for (int j = 0; j < 2; j++) {
      if (cands[j] > 'z') continue;
      addEdge(i, cands[j]);
      bool flg = isValid();
      if (flg) {
        suc = true;
        ans[i] = cands[j];
        break;
      }
      delEdge(i);
    }
    if (!suc) {
      ans[0] = '\0';
      return;
    }
  }
  ans[N] = '\0';
  return;
}
