int T1[N * N], T2[N * N], from[N * N], to[N * N], m;
inline bool check(int cur) {
  Clear(n * 2);
  ecnt = ecnt2, memcpy(e, e2, sizeof(edge) * (ecnt2 + 1));
  for (int i = 1; i <= n * 2; i++) head[i] = head2[i];
  for (int i = 1; i <= cur; i++) mark(vowel[t[i] - 'a'], i);
  return Just_DOIT(n * 2);
}
