  if (ehang > size || ecot > size) return 0;
  for (int i = hang; i <= ehang; i++)
    for (int j = cot; j <= ecot; j++)
      if (s[i][j] != 0) return 0;
  return 1;
}
void dien(int hang, int cot, int ehang, int ecot, int val) {
