using namespace std;
long long modpow(long long a, long long b) {
  long long res = 1;
  while (b) {
    if (b % 2) {
      res *= a;
    }
    a *= a;
    res %= mod;
    a %= mod;
    b /= 2;
  }
  return res;
}
