char def(int a) {
  if (a == 0) return 'A';
  if (a == 1) return 'B';
  return 'C';
}
void sol(int &first, int &second, int &a, int &b, int &c, int &d, int remain,
         int cur) {
  for (int i = 0; i < 3; ++i) {
    if (cur == i) continue;
    if (first == -1) {
      for (int j = 0; j < 2; ++j)
        if (arr[i][j] == remain) {
          a = remain;
          b = arr[i][1 - j];
          first = i;
          break;
        }
    } else {
      for (int j = 0; j < 2; ++j)
        if (arr[i][j] == remain) {
          c = remain;
          d = arr[i][1 - j];
          second = i;
          break;
        }
    }
  }
}
void f(int i, int j) {
  if (arr[i][j] != n) return;
  int last = n - arr[i][1 - j];
  int first = -1, second = -1, a = -1, b = -1, c = -1, d = -1;
  sol(first, second, a, b, c, d, last, i);
  if (second == -1) return;
  for (int k = 0; k < arr[i][1 - j]; ++k)
    for (int l = 0; l < n; ++l) ans[k][l] = def(i);
  int line = arr[i][1 - j];
  for (int m = 0; m < a; ++m)
    for (int k = 0; k < b; ++k) ans[line + m][k] = def(first);
  for (int m = 0; m < c; ++m)
    for (int k = 0; k < d; ++k) ans[line + m][b + k] = def(second);
}
