  ans.assign(n, vector<char>(n, '1'));
  int cnt_n = 0;
  for (int k = 0; k < 3; ++k) {
    cnt_n += (arr[k][0] == n || arr[k][1] == n ? 1 : 0);
  }
  if (cnt_n == 2) {
    cout << -1;
    return;
  }
  if (cnt_n == 3) {
    int line = 0;
    for (int i = 0; i < 3; ++i) {
