      line += arr[i][cur];
    }
  }
  for (int m = 0; m < 3; ++m) {
    for (int i = 0; i < 2 && ans[0][0] == '1'; ++i) {
      f(m, i);
    }
  }
  if (ans[0][0] == '1') {
