  }
  int n = sqrt(area) + 0.5;
  if (n * n != area) {
    cout << -1 << endl;
    return (0-1);
  }
  if (dfs(n, n, 0, 0, 1)) {
    cout << n << endl;
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        cout << mat[i][j];
      }
      cout << endl;
    }
  } else {
    cout << -1 << endl;
  }
  return 0;
}

