bool fillIt(int ind) {
  int r = -1, c = -1;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      if (st[i][j] == '*') {
        r = i;
        c = j;
        i = n;
        break;
      }
  if (c == -1 || x[ind] + r > n) return 0;
  if (y[ind] + c > n) return 0;
  for (int i = r; i - r < x[ind]; i++)
    for (int j = c; j - c < y[ind]; j++) {
      if (st[i][j] != '*') return 0;
      st[i][j] = 'A' + ind;
    }
  return 1;
}
bool check() {
  int a = 0, b = 0, c = 0;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++) {
      if (st[i][j] == 'A')
        a++;
      else if (st[i][j] == 'B')
        b++;
      else if (st[i][j] == 'C')
        c++;
      else
        return 0;
    }
  if (a != x[0] * y[0] || b != x[1] * y[1] || c != x[2] * y[2]) return 0;
  return 1;
}
bool rec(int msk) {
  if (msk == 7) {
    return check();
  }
  string tmp[0];
  for (int i = 0; i < n; i++) tmp[i] = st[i];
  for (int i = 0; i < 3; i++)
    if ((msk & (1 << i)) == 0) {
      if (fillIt(i)) {
        if (rec(msk | (1 << i))) return 1;
      }
      for (int i = 0; i < n; i++) st[i] = tmp[i];
      swap(x[i], y[i]);
      if (fillIt(i)) {
        if (rec(msk | (1 << i))) return 1;
      }
      swap(x[i], y[i]);
    }
  return 0;
}
