  for (int i = 0; i < 3; i++) cin >> x[i] >> y[i];
  for (n = 1; n < 101; n++) {
    for (int i = 0; i < n; i++) {
      st[i].clear();
      st[i].resize(n, '*');
    }
    bool ans = rec(0);
    if (ans == 1) {
      cout << n << endl;
      for (int i = 0; i < n; i++) cout << st[i] << endl;
