long long modinverse(long long a, long long m) {
  long long m0 = m;
  long long y = 0, x = 1;
  if (m == 1) return 0;
  while (a > 1) {
    long long q = a / m, t = m;
    m = a % m, a = t;
    t = y;
    y = x - q * y;
    x = t;
  }
  if (x < 0) x += m0;
  return x;
}
long long mod_pow(long long a, long long n, long long p) {
  long long ans = 1;
  while (n) {
    if (n & 1) ans = (ans * a) % p;
    a = (a * a) % p;
    n >>= 1;
  }
  return ans;
}
long long prime_mod_pow(long long a, long long n, long long p) {
  long long ans = 1;
  n %= p - 1;
  while (n) {
    if (n & 1) ans = (ans * a) % p;
    a = (a * a) % p;
    n >>= 1;
  }
  return ans;
}
long long gcd(long long a, long long b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}
long long ext_gcd(long long l, long long r, long long &x, long long &y) {
  if (l == 0) {
    x = 0;
    y = 1;
    return r;
  }
  long long x1, y1, g;
  g = ext_gcd(r % l, l, x1, y1);
  x = y1 - (r / l) * x1;
  y = x1;
  return g;
}
