long long ok(long long x, long long y, long long n, long long m) {
  return (x >= 0 and y >= 0 and x < n and y < m);
}
long long num_div;
map<long long, long long> pr_factor;
void factorise(long long n) {
  long long count = 0;
  while (!(n % 2)) {
    n >>= 1;
    count++;
  }
  if (count) num_div *= (count + 1);
  pr_factor[2] = count;
  for (long long i = 3; i <= sqrt(n); i += 2) {
    count = 0;
    while (n % i == 0) {
      count++;
      n /= i;
    }
    if (count) num_div *= (count + 1);
    pr_factor[i] = count;
  }
  if (n > 2) num_div *= 2;
  pr_factor[n] = 1;
}
