void DFS(int rt, int mask) {
  if (dp[rt][mask] >= 0) return;
  if (__builtin_popcount(mask) == 1) {
    dp[rt][mask] = 1;
    return;
  }
  dp[rt][mask] = 0;
  int sup = (mask ^ (1 << rt)), sub = sup;
  do {
    if ((sup & -sup) & sub) {
      int tsub = mask ^ sub;
      DFS(rt, mask ^ sub);
      for (int i = 0; i < N; i++) {
        if (!(sub & (1 << i))) continue;
        bool isok = true;
        for (int j = 0; j < M; j++) {
          if (!isok) break;
          if (((mask & (1 << u[j])) && (mask & (1 << v[j]))) &&
              (!((sub & (1 << u[j])) && (sub & (1 << v[j])))) &&
              (!((tsub & (1 << u[j])) && (tsub & (1 << v[j])))) &&
              (!((u[j] == rt) && (v[j] == i) || ((u[j] == i) && (v[j] == rt)))))
            isok = false;
        }
        for (int j = 0; j < Q; j++) {
          if (!isok) break;
          if (((mask & (1 << a[j])) && (mask & (1 << b[j])) &&
               (mask & (1 << c[j]))) &&
              (!((sub & (1 << a[j])) && (sub & (1 << b[j])) &&
                 (sub & (1 << c[j])))) &&
              (!((tsub & (1 << a[j])) && (tsub & (1 << b[j])) &&
