int n, m, q;
inline int getbit(int x, int i) { return (x >> i) & 1; }
void make_g(int s, int f = 0, int i = n - 1, bool ok = false) {
  if (i < 0) {
    if (f) G[s].emplace_back(f);
  } else if (getbit(s, i)) {
    make_g(s, f | (1 << i), i - 1, true);
    if (ok) make_g(s, f, i - 1, true);
  } else
    make_g(s, f, i - 1, ok);
}
long long cal(int x, int k, int s) {
  if (k) {
    if ((s | Lca[x]) != s) return 0;
    if (x != 1 && __builtin_popcount(Adj[x] - (Adj[x] & s)) > 1) return 0;
  }
  if (!(s == 0)) return 1;
  if (F[x][k][s] >= 0) return F[x][k][s];
  long long v = 0;
  for (int f : G[s])
    if (I[x][f] > n) {
      for (int y = 1; y <= n; ++y)
        if (getbit(f, y - 1)) {
          int yf = f - (1 << (y - 1));
          if ((yf | Adj[y]) == yf) v += cal(y, 1, yf) * cal(x, 0, s - f);
        }
    } else if (I[x][f] > 0)
      v += cal(I[x][f], 1, f - (1 << (I[x][f] - 1))) * cal(x, 0, s - f);
  return F[x][k][s] = v;
}
