inline char gc() {
  static char buf[1 << 14], *p1 = buf, *p2 = buf;
  return p1 == p2 && (p2 = (p1 = buf) + fread(buf, 1, 1 << 14, stdin), p1 == p2)
             ? EOF
             : *p1++;
}
inline long long read(long long &x) {
  x = 0;
  bool f = 1;
  char c = gc();
  for (; !isdigit(c); c = gc()) {
    if (c == '-') f ^= 1;
    if (c == -1) return -1;
  }
  for (; isdigit(c); c = gc()) x = (x << 1) + (x << 3) + (c ^ 48);
  x = f ? x : -x;
  return 1;
}
inline void wr(long long x) {
  if (x < 0) putchar('-'), x = -x;
  if (x > 9) wr(x / 10);
  putchar(x % 10 | 48);
}
long long n, m, q, f[15][1 << 13];
struct Lca {
  long long x, y, t;
  inline void init() { read(x), read(y), read(t); }
} v[110];
vector<long long> e[20];
inline bool pd_Lca(long long x, long long L, long long R) {
  L |= 1 << (x - 1), R |= 1 << (x - 1);
  for (long long i = 1; i <= q; ++i) {
    if ((L & (1 << (v[i].x - 1))) && (R & (1 << v[i].y - 1)) && v[i].t != x)
      return 0;
    if ((R & (1 << (v[i].x - 1))) && (L & (1 << v[i].y - 1)) && v[i].t != x)
      return 0;
  }
  return 1;
}
inline bool pd_near(long long x, long long son, long long fa) {
  for (long long i = 0; i < (long long)e[x].size(); ++i)
    if (!(son & (1 << (e[x][i] - 1))) && e[x][i] != fa) return 0;
  return 1;
}
inline long long dfs(long long x, long long now) {
  long long &ret = f[x][now];
  if (~ret) return ret;
  if (!now && pd_Lca(x, 0, 0)) return ret = 1;
  if (!now) return ret = 0;
  ret = 0;
  for (long long i = now; i; i = (i - 1) & now)
    if ((i & (now & -now)) && pd_Lca(x, i, now ^ i))
      for (long long j = 1; j <= n; ++j)
        if ((i & (1 << (j - 1))) && pd_near(j, i, x))
          ret += dfs(j, i ^ (1 << (j - 1))) * dfs(x, now ^ i);
  return ret;
}
