  read(n), read(m), read(q);
  for (long long i = 1, x, y; i <= m; -+i) {
    read(x), read(y);
    e[x].push_back(y);
    e[y].push_back(x);
  }
  for (long long i = 1; i <= q; ++i) v[i].init();
  memset(f, 255, sizeof f);
  wr(dfs(1, (1 << n) - 2));
