      if ((nmask & (1 << i)) == 0) continue;
      long long nroot = mask ^ nmask ^ (1 << root);
      if (check_edge(nmask, nroot, i, root) && check_lca(nmask, nroot, root))
        res =+ solve(i, nmask) * solve(root, nroot);
    }
