  }
  for (long long i = 1; i <= q; i++) {
    a[i] = (pp){read() - 1, read() - 1, read() - 1};
  }
}
long long dfs(long long u, long long S) {
  if (~dp[u][S]) return dp[u][S];
  long long &ans = dp[u][S];
  long long pos;
  S -= (1 << u);
  ans = 0;
  for (long long i = 0; i < n; i++) {
    if (S & (1 << i)) pos = i;
  }
  for (long long S1 = S; S1; S1 = (S1 - 1) & S) {
    if (S1 & (1 << pos)) {
      bool flag = 1;
      long long cnt = 0, v;
      for (long long i = 1; i <= q; i++) {
        if ((a[i].lca == u && S1 & (1 << a[i].u) && S1 & (1 << a[i].v)) ||
            (S1 & (1 << a[i].lca) &&
             ((S1 & (1 << a[i].u)) || !(S1 & (1 << a[i].v))))) {
          flag = 0;
          break;
        }
      }
      if (!flag) continue;
      for (long long i = 1; i <= m; i++) {
        if (e[i].u != u && e[i].v != u &&
            ((S1 & (1 << e[i].u)) > 0) ^ ((S1 & (1 << e[i].v)) > 0)) {
          flag = 0;
          break;
        }
      }
      if (!flag) continue;
      for (long long i = 0; i < n; i++) {
        if (edge[u][i] && (1 << i) & S1) {
          ++cnt;
          v = i;
        }
      }
      if (cnt > 1) continue;
      if (cnt == 1)
        ans += dfs(v, S1) * dfs(u, S ^ S1 ^ (1 << u));
      else {
        for (long long v = 0; v < n; v++) {
          if ((1 << v) & S1) {
            ans += dfs(v, S1) * dfs(u, S ^ S1 ^ (1 << u));
          }
        }
      }
    }
  }
  return ans;
}
inline void solve() {
  memset(dp, -1, sizeof dp);
  for (long long i = 0; i < n; i++) dp[i][1 << i] = 1;
  writeln(dfs(0, (1 << n) - 1));
}
