  for (int i = 0; i < 13; i++) lg[1 << i] = i;
  for (int mask = 0; mask < 1 << 13; mask++) {
    vector<int> v;
    v.clear();
    for (int i = 0; i < 13; i++)
      if ((mask >> i) & 1) v.push_back(i);
    for (int s = 0; s < (1 << v.size()); s++) {
      int newmask = 0;
      int tmp = s;
      while (tmp) {
        newmask |= (1 << v[lg[tmp & (-tmp)]]);
        tmp -= tmp & (-tmp);
      }
      submask[mask].push_back(newmask);
    }
  }
}
