  for (int i = 1; i <= m; i++) {
    scanf("%d%d", &u[i], &v[i]);
    u[i]--;
    v[i]--;
  }
  for (int i = 1; i <= q; i++) {
    scanf("%d%d%d", &a[i], &b[i], &c[i]);
    a[i]--;
    b[i]--;
    c[i]--;
  }
  for (int i = 0; i < n; i++) dp[1 << i][i] = 1;
  for (int mask = 1; mask < 1 << n; mask++) {
    for (int root = 0; root < n; root++)
      if ((mask >> root) & 1) {
        if ((1 << root) == mask) continue;
        int mn_pos = -1;
        for (int i = 0; i < n; i++)
          if ((mask >> i) & 1 && i != root) {
            mn_pos = i;
            break;
          }
