                  ((newmask >> u[i]) & 1) == 1 &&
                  (((mask ^ newmask) >> v[i]) & 1) == 1)
                ok = 0;
              if (u[i] != root && v[i] != root &&
                  ((newmask >> v[i]) & 1) == 1 &&
                  (((mask ^ newmask) >> u[i]) & 1) == 1)
                ok = 0;
              if (u[i] == root && (newmask >> v[i]) & 1)
                cnt++, paigulong = v[i];
              if (v[i] == root && (newmask >> u[i]) & 1)
