bool Get(int first, int i) { return (first >> i) & 1; }
bool Check(int sub, int child, int mask, int root) {
  for (int i = 0; i < m; ++i) {
    if (!Get(mask, u[i]) || !Get(mask, v[i])) continue;
    if (Get(sub, u[i]) == Get(sub, v[i])) continue;
    if (v[i] == root) swap(v[i], u[i]);
    if (v[i] != child || u[i] != root) return 0;
