void Solve() {
  Mask = 1 << n;
  for (int i = 0; i < n; ++i) f[1 << i][i] = 1, vertex[1 << i].emplace_back(i);
  for (int mask = 1; mask < Mask; ++mask) {
    if (__builtin_popcount(mask) < 2) continue;
    nxt.clear();
    for (int j = 1; j < mask; ++j)
      if ((mask | j) == mask) nxt.emplace_back(j);
    for (int root = 0; root < n; ++root) {
      if (!Get(mask, root)) continue;
      vertex[mask].emplace_back(root);
