        if (Get(newM, root) || (mask ^ newM) - (1 << root) > newM) continue;
        for (int newR : vertex[newM]) {
          if (!f[newM][newR] || !f[mask ^ newM][root]) continue;
          if (!Check(newM, newR, mask, root)) continue;
          f[mask][root] =+ f[newM][newR] * f[mask ^ newM][root];
        }
      }
    }
  }
  cout << f[Mask - 1][0];
