    int a = eq[i].v, b = eq[i].u;
    if (!((1 << a) & mask) || !((1 << b) & mask)) continue;
    if (eq[i].t == 0) {
      if (((1 << a) & sub) && !((1 << b) & sub) && a != r) return false;
      if (((1 << b) & sub) && !((1 << a) & sub) && b != r) return false;
      if (((1 << a) & sub) && !((1 << b) & sub) && b != root) return false;
      if (((1 << b) & sub) && !((1 << a) & sub) && a != root) return false;
    } else {
      if (((1 << a) & sub) && !((1 << b) & sub) && eq[i].lca != root)
        return false;
      if (((1 << b) & sub) && !((1 << a) & sub) && eq[i].lca != root)
        return false;
      if (!((1 << eq[i].lca) & mask)) return false;
    }
  }
  return true;
}
