    for (int i = 0; i < eq.size(); i++)
      if (eq[i].t == 1 && eq[i].v == root && eq[i].u == root &&
          eq[i].lca != root)
        return dp[root][mask];
    return dp[root][mask] = 1LL;
  }
  int cur;
  for (int i = 0; i < n; i++)
    if ((mask & (1 << i)) && i != root) {
      cur = i;
