      if (((1 << cur) & sub) && !(sub & (1 << root)))
        for (int r = 0; r < n; r++)
          if (((1 << r) & sub) && check(r, sub, root, mask))
            dp[root][mask] =+ mem(root, (mask ^ sub)) * mem(r, sub);
  return dp[root][mask];
}
