  long long &res = dp[root][mask];
  if (res != -1) return res;
  res = 0;
  for (int newMask = 0; newMask < (1 << n); newMask++) {
    if (lowbit[mask ^ (1 << root)] != lowbit[newMask]) continue;
    if ((mask & newMask) != newMask) continue;
    int otherMask = (mask ^ newMask);
    bool kt = true;
    int NonRoot = otherMask - (1 << root);
    for (int i = 0; i < n; i++) {
      if (i == root) continue;
      if (NonRoot >> i & 1) {
        for (auto &x : need_connect[i])
          if (newMask >> x & 1) kt = false;
      }
    }
    for (int i = 0; i < n; i++) {
      if (newMask >> i & 1) {
        for (int j = 0; j < n; j++) {
          if (otherMask >> j & 1)
            if (lca[i][j] != -1 && lca[i][j] != root) kt = false;
        }
      }
    }
    if (!kt) continue;
    for (int newRoot = 0; newRoot < n; newRoot++) {
      if (!(newMask >> newRoot & 1)) {
        bool ok = true;
        for (int other = 0; other < n; other++) {
          if ((newMask ^ (1 << newRoot)) >> other & 1)
            for (auto &x : need_connect[other])
              if (otherMask >> x & 1) ok = false;
        }
        if (ok) res = res + calc(root, otherMask) * calc(newRoot, newMask);
      }
    }
  }
  return res;
}
