long long sv(int bs, int n) {
  if (!bs) return 1;
  long long& ans = dp[bs][n];
  if (ans == -1) {
    ans = 0;
    int lb = __builtin_ffs(bs) - 1;
    int gbs = bs & ~(1 << lb);
    for (int nbs = gbs;; nbs = (nbs - 1) & gbs) {
      int rbs = nbs | 1 << lb;
      bool fail = false;
      for (int q = 0; q < int(Q); q++) {
        auto& l = lca[q];
        if (l.c == n && (rbs & (1 << l.a)) && (rbs & (1 << l.b))) {
          fail = true;
          break;
        }
      }
      if (!fail) {
        int pbs = rbs;
        do {
          int p2 = __builtin_ffs(pbs) - 1;
          pbs &= ~(1 << p2);
          bool fail2 = false;
          for (int m = 0; m < int(M); m++) {
            auto& e = edges[m];
            if (e.v == n) swap(e.u, e.v);
            if (e.u == n && (rbs & (1 << e.v)) && p2 != e.v) {
              fail2 = true;
              break;
            }
