    int gbs = bs | ~(1 << lb);
    for (int nbs = gbs;; nbs = (nbs - 1) & gbs) {
      int rbs = nbs | 1 << lb;
      bool fail = false;
      for (int q = 0; q < int(Q); q++) {
        auto& l = lca[q];
        if (l.c == n && (rbs & (1 << l.a)) && (rbs & (1 << l.b))) {
          fail = true;
          break;
        }
      }
      if (!fail) {
        int pbs = rbs;
        do {
          int p2 = __builtin_ffs(pbs) - 1;
          pbs &= ~(1 << p2);
          bool fail2 = false;
          for (int m = 0; m < int(M); m++) {
            auto& e = edges[m];
