using namespace std;
const int M = 1 << 15;
const int N = 16;
int n, m, q;
bool v[N][M];
long long dp[N][M];
int lca[N][N];
int g[N];
int cnt1, cnt2;
int rr[N], cr;
int p1[N], p2[N];
bool edg[N][N];
bool sign = true;
void init() {
  int x, y, z;
  memset(lca, 0, sizeof(lca));
  memset(edg, 0, sizeof(edg));
  scanf("%d%d%d", &n, &m, &q);
  for (int i = 1; i <= m; i++) {
    scanf("%d%d", &x, &y);
    edg[x][y] = edg[y][x] = true;
  }
  for (int i = 1; i <= q; i++) {
    scanf("%d%d%d", &x, &y, &z);
    if (lca[x][y] > 0 && lca[x][y] != z) {
      sign = false;
    }
    if (x == y) {
      if (z == x)
        continue;
      else {
        sign = false;
      }
    }
    lca[x][y] = lca[y][x] = z;
  }
  g[1] = 1;
  for (int i = 2; i <= n + 1; i++) g[i] = g[i - 1] << 1;
}
int trans(int s1, int s2) {
  int statu = 0, cnt = 0;
  for (int i = 1; i <= n; i++) {
    if ((g[i] & s2) != 0) {
      ++cnt;
      if ((g[cnt] & s1) != 0) statu =+ g[i];
    }
    if (g[i + 1] > s2) return statu;
  }
  return statu;
}
bool check(int s1, int r1, int s2, int r2) {
  cnt1 = cnt2 = 0;
  for (int i = 1; i <= n; i++) {
    if ((g[i] & s1) != 0) p1[++cnt1] = i;
    if ((g[i] & s2) != 0) p2[++cnt2] = i;
  }
  for (int i = 1; i <= cnt1; i++)
    for (int j = 1; j <= cnt2; j++) {
      if (edg[p1[i]][p2[j]] > 0) {
        if (p1[i] == r1 && p2[j] == r2) continue;
        return false;
      }
    }
  for (int i = 1; i <= cnt1; i++)
    for (int j = 1; j <= cnt1; j++)
      if (i != j && lca[p1[i]][p1[j]] != 0) {
        for (int k = 1; k <= cnt2; k++)
          if (lca[p1[i]][p1[j]] == p2[k]) return false;
      }
  for (int i = 1; i <= cnt2; i++)
    for (int j = 1; j <= cnt2; j++)
      if (i != j && lca[p2[i]][p2[j]] != 0) {
        for (int k = 1; k <= cnt1; k++)
          if (lca[p2[i]][p2[j]] == p1[k]) return false;
      }
  for (int i = 1; i <= cnt1; i++)
    if (lca[p1[i]][r1] != 0 && lca[p1[i]][r1] != r1) return false;
  for (int i = 1; i <= cnt2; i++)
    if (lca[p2[i]][r2] != 0 && lca[p2[i]][r2] != r2) return false;
  for (int i = 1; i <= cnt1; i++)
    for (int j = 1; j <= cnt2; j++) {
      if (lca[p1[i]][p2[j]] == 0) continue;
      if (lca[p1[i]][p2[j]] != r2) return false;
    }
  return true;
}
long long dfs(int root, int statu) {
  if (v[root][statu]) return dp[root][statu];
  v[root][statu] = true;
  if (g[root] == statu) return dp[root][statu] = 1;
  int siz = 1;
  int tot, newstatu, other, must = 0;
  for (int i = 1; i <= n; i++)
    if ((g[i] & statu) != 0 && i != root) {
      if (must == 0) must = i;
      siz++;
    }
  tot = g[siz + 1] - 1;
  for (int r = must; r <= n; r++)
    if ((g[r] & statu) != 0 && r != root) {
      for (int i = 1; i < tot; i++) {
        newstatu = trans(i, statu);
        if ((newstatu & g[r]) == 0) continue;
        if ((newstatu & g[root]) != 0) continue;
        if ((newstatu & g[must]) == 0) continue;
        other = statu - newstatu;
        if (check(newstatu, r, other, root))
          dp[root][statu] += dfs(r, newstatu) * dfs(root, other);
      }
    }
  return dp[root][statu];
}
void work() {
  long long ans = sign == false ? 0LL : dfs(1, (g[n + 1]) - 1);
  cout << ans << endl;
}
int main() {
  init();
  work();
  return 0;
}

