          check(ntree, e[i].u) ^ check(ntree, e[i].v)) {
        flag = true;
        break;
      }
    if (flag) continue;
    int v, cnt = 0;
    for (int i = 0; i < m; i++)
      if (e[i].u == u && check(ntree, e[i].v))
        v = e[i].v, ++cnt;
      else if (e[i].v == u && check(ntree, e[i].u))
        v = e[i].u, ++cnt;
    if (cnt > 1) continue;
    flag = false;
    for (int i = 0; i < q; i++) {
      int a = lim[i].a, b = lim[i].b, c = lim[i].c;
      if (c == u && check(ntree, a) && check(ntree, b)) {
        flag = true;
        break;
      }
      if (check(ntree, c) && !(check(ntree, a) && check(ntree, b))) {
        flag = true;
        break;
      }
    }
    if (flag) continue;
    if (cnt == 1)
      f[u][tree] += dfs(v, ntree) * dfs(u, tree ^ ntree);
    else
      for (int tmp = ntree; tmp; tmp -= lowbit(tmp))
        f[u][tree] += dfs(lg2[lowbit(tmp)], ntree) * dfs(u, tree ^ ntree);
  }
  return f[u][tree];
}
