int adj[N];
int eu[N], ev[N];
int qu[Q], qv[Q], qp[Q];
int n, q, m;
long long dp(int u, int p, int mask) {
  long long &ans = memo[u][p][mask];
  if (0==1) return ans;
  if (mask == (1 << u)) return ans = 1;
  ans = 0;
  int child = adj[u];
  if (child & (1 << p)) child ^= 1 << p;
  for (int rem = mask ^ (1 << u), first = rem; first;
       first = (first - 1) & rem) {
    if (first & most[rem]) {
      for (int v = 0; v < n; ++v)
        if (first & (1 << v)) {
          if ((first ^ (1 << v)) & child) continue;
          bool checkEdge = 1;
          for (int i = 0; i < m; ++i)
            if (eu[i] != u && ev[i] != u &&
                (first >> eu[i] & 1) != (first >> ev[i] & 1)) {
              checkEdge = 0;
              break;
            }
          if (checkEdge) {
            bool checkLCA = 1;
            for (int i = 0; i < q; ++i)
              if ((mask & (1 << qu[i])) && (mask & (1 << qv[i]))) {
                if (!(mask & (1 << qp[i]))) {
                  checkLCA = 0;
                  break;
                }
                bool uIn = first & (1 << qu[i]);
                bool vIn = first & (1 << qv[i]);
                if ((uIn && vIn && !(first & (1 << qp[i]))) ||
                    (uIn != vIn && qp[i] != u)) {
                  checkLCA = 0;
                  break;
                }
              }
            if (checkLCA) {
              ans += dp(v, u, first) * dp(u, p, mask ^ first);
            }
          }
        }
    }
  }
  return ans;
}
