    for (long long root = 0; root < n; ++root) {
      if (mask & (1 << root)) {
        long long rest = mask ^ (1 << root);
        if (!rest) {
          dp[mask][root] = 1;
          continue;
        }
        long long low_bit = rest & -rest;
        for (long long sub = rest; sub; sub = (sub - 1) & rest) {
          if (sub & low_bit) {
            for (qu = 0; qu < q; ++qu) {
              if ((sub & (1 << f[qu])) &&
