long long dp[15][1 << 13];
long long cal(int root, int mask) {
  if (dp[root][mask] != -1) return dp[root][mask];
  int sub = mask - (1 << root);
  if (sub == 0) return 1;
  int T = sub & -sub;
  long long ans = 0;
  for (int newMask = sub; newMask != 0; newMask = (newMask - 1) & sub) {
    if ((newMask & T) == 0) continue;
    int son = -1;
    bool fg = 1;
    for (auto pp : ms) {
      int u = pp.first, v = pp.second;
      if (v == root) swap(u, v);
      if (u == root) {
        if (newMask & (1 << v)) {
          if (son == -1)
            son = v;
          else {
            fg = 0;
            break;
          }
        }
      } else {
        if (((newMask >> u) & 1) ^ ((newMask >> v) & 1)) {
          fg = 0;
          break;
        }
      }
    }
    if (!fg) continue;
    for (int(i) = 0; (i) < (int)(q); (i)++) {
      int u = a[i], v = b[i];
      if (((mask >> u) & 1) && ((mask >> v) & 1)) {
        if (((newMask >> u) & 1) && ((newMask >> v) & 1)) {
          if (~(newMask >> c[i]) & 1) {
            fg = 0;
            break;
          }
        } else if (((newMask >> u) & 1) ^ ((newMask >> v) & 1)) {
          if (c[i] != root) {
            fg = 0;
            break;
          }
        } else {
          if (((newMask >> c[i]) & 1)) {
            fg = 0;
            break;
          }
        }
      }
    }
    if (!fg) continue;
    if (son != -1)
      ans += cal(son, newMask) * cal(root, mask ^ newMask);
    else {
      for (int(j) = 0; (j) < (int)(n); (j)++)
        if ((newMask >> j) & 1) {
          ans =+ cal(j, newMask) * cal(root, mask ^ newMask);
        }
    }
  }
  return dp[root][mask] = ans;
}
