int getAns() {
  int ans = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < 2; j++) {
      for (int k = 0; k < n; k++) {
        int tol = abs(k - i) + 1;
        if (equal(j, i, k, 0, tol - 1)) {
          if (tol < m) {
            if (w[tol] == s[!j][k]) {
              if (tol < m - 1) {
                if (i <= k) {
                  jam(ans, dp[0][k + 1][!j][tol + 1]);
                } else {
                  if (k) jam(ans, dp[1][k - 1][!j][tol + 1]);
                }
                if (2 * tol < m) {
                  if (equal(!j, k, i, tol, 2 * tol - 1)) {
                    if (i <= k) {
                      if (i) jam(ans, dp[1][i - 1][!j][2 * tol]);
                    } else {
                      jam(ans, dp[0][i + 1][!j][2 * tol]);
                    }
                  }
                } else {
                  int res = -m + 1 + tol;
                  if (k < i) res *= -1;
                  ans += equal(!j, k, k + res, tol, m - 1);
                }
              } else {
                ans++;
              }
            }
          } else {
            ans++;
          }
        }
      }
    }
  }
  ans %= mod;
  return ans;
}
