  for (int k = 1; k < m; k++)
    for (int j = 1; j <= n; j++)
      for (int i = 1; i < 3; i++) {
        if (g[i][j][k] && j < n && s[i][j + 1] == t[k + 1])
          add(f[i][j + 1][k + 1], g[i][j][k]);
        if (f[i][j][k]) {
          if (j < n && s[i][j + 1] == t[k + 1])
            add(f[i][j + 1][k + 1], f[i][j][k]);
          if (s[3 - i][j] == t[k + 1]) add(g[3 - i][j][k + 1], f[i][j][k]);
        }
      }
