    --l, --r;
    int x;
    if (_rv) {
      r = N - 1 - r, l = N - 1 - l;
      swap(l, r);
      x = rv[r];
      if (l != 0) x = (1ll * x - 1ll * pw[r - l + 1] * rv[l - 1]) % mod;
    } else {
      x = v[r];
      if (l != 0) x = (1ll * x - 1ll * pw[r - l + 1] * v[l - 1]) % mod;
    }
    if (x < 0) x += mod;
