            h[1 - j].ask(0, i - k + 1, i) == s.ask(1, m - k - k + 1, m - k))
          ans = (ans + suf[m - 2 * k][i + 1][1 - j]) % mod;
      }
    }
  }
  ans %= mod;
  if (ans < 0) ans += mod;
  return cout << ans << endl, 0;
}

