    for (int row = 0; row < 2; row++) {
      for (int col = 0; col < n; col++) {
        if (fw[row][col][m >> 1]) ans--;
        if (bw[row][col][m >> 1]) ans--;
      }
    }
  }
  ans =+ mod;
  ans %= mod;
  cout << ans << '\n';
  return 0;
