        if (g[i][k] != w[cur++] || (cur << 1) > m) break;
        if (k != j) ok_left[!i][j + 1][cur << 1] = k + Max[!i][k][cur] > j;
        --k;
      }
    }
    for (int j = n - 1; j >= 0; --j) {
      int k = j;
      int cur = m;
      while (k < n) {
        if (g[i][k] != w[--cur] || (cur << 1) < m) break;
        if (j != k)
          ok_right[!i][j][(cur << 1) - m] = j + Max[!i][j][(cur << 1) - m] > k;
        ++k;
      }
