  cin >> pat;
  m = pat.size();
  if (m == 1) {
    for (auto u : mat[0]) {
      if (u == pat[0]) {
        re = re + 1;
      }
    }
    for (auto u : mat[1]) {
      if (u == pat[0]) {
        re = re + 1;
      }
    }
    cout << re << '\n';
    return 0;
  }
  if (m == 2) {
    for (int r = 0; r < 2; ++r) {
      for (int i = 0; i < n; ++i) {
        if (i > 0 && mat[r][i] == pat[1] && mat[r][i - 1] == pat[0]) {
          re = re + 1;
        }
        if (i < n - 1 && mat[r][i] == pat[1] && mat[r][i + 1] == pat[0]) {
          re = re + 1;
        }
        if (mat[r][i] == pat[1] && mat[r ^ 1][i] == pat[0]) {
          re = re + 1;
        }
      }
    }
    cout << re << '\n';
    return 0;
  }
  solve();
  for (int r = 0; r < 2; ++r) {
    reverse(mat[r].begin(), mat[r].end());
  }
  solve();
  cout << re << '\n';
  return 0;
}

