#include <bits/stdc++.h>
char s[2][2010], p[2010];
int f[2][2010][2010], ans, n, k;
int HL[2][2010], HR[2][2010], _pow[2010], H[2010];
int hashL(int hash[], int l, int r) {
  return ((hash[r] - (long long)hash[l - 1] * _pow[r - l + 1] % 1000000007) +
          1000000007) %
         1000000007;
}
int hashR(int hash[], int l, int r) {
  return ((hash[l] - (long long)hash[r + 1] * _pow[r - l + 1] % 1000000007) +
          1000000007) %
         1000000007;
}
void solve() {
  memset(HL, 0, sizeof(HL));
  memset(HR, 0, sizeof(HR));
  memset(H, 0, sizeof(H));
  for (int d = 0; d <= 1; d++) {
    for (int i = 1; i <= n; i++)
      HL[d][i] = ((long long)HL[d][i - 1] * 29 + s[d][i] - 96) % 1000000007;
    for (int i = n; i >= 1; i--)
      HR[d][i] = ((long long)HR[d][i + 1] * 29 + s[d][i] - 96) % 1000000007;
  }
  for (int i = 1; i <= k; i++)
    H[i] = ((long long)H[i - 1] * 29 + p[i] - 96) % 1000000007;
  memset(f, 0, sizeof(f));
  f[0][0][0] = f[1][0][0] = 1;
  if ((!(k & 1)) && (k ^ 2)) {
    for (int d = 0; d <= 1; d++) {
      int h = k >> 1;
      if (hashR(HR[d], 1, h) == hashL(H, h + 1, k) &&
          hashL(HL[!d], 1, h) == hashL(H, 1, h))
        ans++;
    }
  }
  for (int i = 1; i <= n; i++) {
    f[0][i][0] = f[1][i][0] = 1;
    for (int d = 0; d <= 1; d++) {
      for (int j = 2; i - j + 1 > 0; j++) {
        if (hashR(HR[d], i - j + 1, i) == hashL(H, 1, j) &&
            hashL(HL[!d], i - j + 1, i) == hashL(H, j + 1, j << 1))
          f[!d][i][j << 1] = (f[!d][i][j << 1] + 1) % 1000000007;
      }
      for (int j = 1; j <= k; j++) {
        if (s[d][i] != p[j]) continue;
        f[d][i][j] = (f[d][i][j] + f[d][i - 1][j - 1]) % 1000000007;
        if (j < k && s[!d][i] == p[j + 1])
          f[!d][i][j + 1] = (f[!d][i][j + 1] + f[d][i - 1][j - 1]) % 1000000007;
      }
    }
    ans = (ans + f[0][i][k]) % 1000000007;
    ans = (ans + f[1][i][k]) % 1000000007;
    for (int d = 0; d <= 1; d++) {
      for (int b = 2; (b << 1) <= k && i + b <= n; b++) {
        if (hashR(HR[d], i + 1, i + b) == hashL(H, k - b + 1, k) &&
            hashL(HL[!d], i + 1, i + b) == hashL(H, k - (b << 1) + 1, k - b))
          ans = (ans + f[!d][i][k - (b << 1)]) % 1000000007;
      }
    }
  }
}
