    for (int i = n; i >= 1; i--)
      HR[d][i] = ((long long)HR[d][i + 1] * 29 + s[d][i] - 96) % 1000000007;
  }
  for (int i = 1; i <= k; i++)
    H[i] = ((long long)H[i - 1] * 29 + p[i] - 96) % 1000000007;
  int cnt = 0;
  if (!(k & 1)) {
    for (int i = 1; i <= n; i++)
      for (int j = 0; j <= 1; j++) {
        if (i - (k >> 1) + 1 > 0 &&
            hashR(HR[j], i - (k >> 1) + 1, i) == hashL(H, 1, k >> 1) &&
            hashL(HL[!j], i - (k >> 1) + 1, i) == hashL(H, (k >> 1) + 1, k))
          cnt++;
        if (k ^ 2 && hashL(HL[j], i, i + (k >> 1) - 1) == hashL(H, 1, k >> 1) &&
            hashR(HR[!j], i, i + (k >> 1) - 1) == hashL(H, (k >> 1) + 1, k))
          cnt++;
      }
  }
  printf("%d\n", (ans - cnt + 1000000007) % 1000000007);
  return 0;
}

