  for (int i = 0; i < n; ++i) {
    dp[i][0][0] = dp[i][1][0] = 1;
    for (int j = 1; j <= m; ++j) {
      dp[i][0][j] = f[i][0][j];
      dp[i][1][j] = f[i][1][j];
    }
  }
  long long ans = 0;
  if (s[0][0] == t[0]) {
