      long long del = ((por(29ll, totlen1) * (por(29ll, len[st]) - 1)) % p) *
                      (chr[st] - 'a' + 1);
      del %= p;
      hsh1 = (hsh1 - del + p) % p;
      hsh1 += p;
      hsh1 %= p;
    }
    if (totlen1 == totlen && hsh == hsh1) {
      if (chr[st] == chr1[0] && chr[en] == chr1.back()) {
        if (len[st] >= len1[0] && len[en] >= len1.back()) ++ans;
      }
    }
  }
