    for (const auto& pr : a)
      if (pr.first == c) out += max((int64_t)0, pr.second - k + 1);
    return out;
  }
  if (b.size() == 2) {
    const auto c0 = b[0].first;
    const auto k0 = b[0].second;
    const auto c1 = b[1].first;
    const auto k1 = b[1].second;
    int64_t out = 0;
    for (size_t i = 0; i + 1 < a.size(); ++i)
      if (a[i].first == c0 && a[i + 1].first == c1 && k0 < 1 + a[i].second &&
          k1 < 1 + a[i + 1].second)
        ++out;
    return out;
  }
  const int64_t mod = 1000000007;
  const int64_t prime = 29;
  const int64_t denom = modinv(prime - 1, mod);
