    int64_t shift = 1;
    for (size_t i = 1; i + 1 < b.size(); ++i) {
      const int64_t s = b[i].first - '`';
      const int64_t k = b[i].second;
      const int64_t inc =
          ((mod + s * powmod(prime, k, mod) - 1) % mod) * denom % mod;
      sig = (sig + inc * shift % mod) % mod;
      shift = shift * powmod(prime, k, mod) % mod;
    }
  }
  vector<int64_t> acc;
  acc.reserve(a.size());
  for (const auto& pr : a) acc.push_back(pr.second);
  partial_sum(begin(acc), end(acc), begin(acc));
  vector<int64_t> xs(a.size());
  {
    int64_t shift = 1;
    for (size_t i = 0; i < a.size(); ++i) {
      const int64_t s = a[i].first - '`';
      const int64_t k = a[i].second;
      const int64_t inc =
          ((mod + s * powmod(prime, k, mod) - 1) % mod) * denom % mod;
      xs[i] = inc * shift % mod;
      shift = shift * powmod(prime, k, mod) % mod;
    }
  }
  for (size_t i = 1; i < xs.size(); ++i) xs[i] = (xs[i] + xs[i - 1]) % mod;
  int64_t out = 0;
  for (size_t i = 0, j = b.size() - 1; j < a.size(); --i, ++j)
    if (a[i].first == b.front().first && a[j].first == b.back().first &&
        b.front().second < 1 + a[i].second &&
        b.back().second < 1 + a[j].second) {
      const auto u = sig * powmod(prime, acc[i], mod) % mod;
      const auto v = (xs[j - 1] + mod - xs[i]) % mod;
      if (u == v) ++out;
    }
  return out;
}
