  ULL t = 1;
  for (int i = 0; i < len_t; ++i) {
    t *= B;
  }
  ULL hash_t = 0, hash_s = 0;
  for (int i = 0; i < len_t; ++i) {
    hash_t = hash_t * B + T[i];
    hash_s = hash_s * B + S[i];
  }
  std::vector<int> result;
  for (int i = 0; i + len_t <= len_s; ++i) {
