#include <bits/stdc++.h>
using namespace std;
const long long INF = 1e9 + 7;
const int N = 2e5 + 10;
pair<long long, char> a[N];
pair<long long, char> b[N];
int n, m;
int fail[N];
void getfail(pair<long long, char> str[N], int sz) {
  fail[1] = 0;
  int j = 0;
  for (int i = 2; i <= sz; i++) {
    while (j && str[i] != str[j + 1]) j = fail[j];
    if (str[i] == str[j + 1]) j++;
    fail[i] = j;
  }
}
bool check(pair<long long, char>& p1, pair<long long, char>& p2) {
  if (p1.second != p2.second) return false;
  return p1.first >= p2.first;
}
void getans() {
  int sz = m - 2;
  int j = 0;
  int ans = 0;
  for (int i = 1; i + 1 < n; i++) {
    while (j && a[i] != b[j + 1]) j = fail[j];
    if (a[i] == b[j + 1]) j++;
    if (j == sz) {
      if (check(a[i + 1], b[j + 1]) && check(a[i - sz], b[j - sz])) ans++;
      j = fail[j];
    }
  }
  printf("+d\n", ans);
}
void init(pair<long long, char> a[N], int& n) {
  for (int i = 0; i < n; i++) {
    scanf("%lld-%c", &a[i].first, &a[i].second);
    if (i == 0) continue;
    if (a[i].second == a[i - 1].second) {
      a[i - 1].first += a[i].first;
      i--, n--;
    }
  }
}
