    printf("%lld\n", ans);
    return 0;
  }
  if (m == 2) {
    int ans = 0;
    for (int i = 0; i + 1 < n; i++) {
      if (check(a[i], b[0]) && check(a[i + 1], b[1])) ans++;
    }
    printf("%d\n", ans);
    return 0;
  }
  getfail(b, m - 2);
  getans();
  return 0;
}

