bool same(string& a, string& b) {
  return a[a.length() - 1] == b[b.length() - 1];
}
long long sub(string& a, string& b) {
  int x = a.length() - 2;
  int y = b.length() - 2;
  long long n1 = 0, n2 = 0;
  for (int i = 0; i < x; i++) {
    n1 = n1 * 10 + a[i] - '0';
  }
  for (int i = 0; i < y; i++) {
    n2 = n2 * 10 + b[i] - '0';
  }
  return n1 - n2;
}
string add(string& a, string& b) {
  int x = a.length() - 2;
  int y = b.length() - 2;
  long long n1 = 0, n2 = 0;
  for (int i = 0; i < x; i++) {
    n1 = n1 * 10 + a[i] - '0';
  }
  for (int i = 0; i < y; i++) {
    n2 = n2 * 10 + b[i] - '0';
  }
  long long num = n1 + n2;
  string res = "";
  while (num) {
    res += (char)(num % 10 + '0');
    num /= 10;
  }
  reverse(res.begin(), res.end());
  res += a[x];
  res += a[x + 1];
