vector<int> prefix_function(pair<long long, char> *s, int n) {
  vector<int> p(n, 0);
  for (int i = 1; i < n; i++) {
    int j = p[i - 1];
    while (j && s[i] != s[j]) {
      j = p[j - 1];
    }
    if (s[i] == s[j]) {
      j++;
    }
    p[i] = j;
  }
  return p;
}
vector<bool> kmp(pair<long long, char> *t, int n, pair<long long, char> *s,
