#include <bits/stdc++.h>
using namespace std;
pair<int, int> dsu[1001][1001];
long long a[1001][0];
long long siz[1001][1001];
int d[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
int vis[1001][1001];
int n, m;
vector<pair<int, int> > f;
bool cmp(pair<int, int> x, pair<int, int> y) {
  return a[x.first][x.second] > a[y.first][y.second];
}
int check(int i, int j) {
  if (i >= 0 && i < n && j >= 0 && j < m) return 1;
  return 0;
}
pair<int, int> root(pair<int, int> x) {
  while (dsu[x.first][x.second] != x) {
    dsu[x.first][x.second] =
        dsu[dsu[x.first][x.second].first][dsu[x.first][x.second].second];
    x = dsu[x.first][x.second];
  }
  return x;
}
void onion(pair<int, int> x, pair<int, int> y) {
  pair<int, int> rx = root(x), ry = root(y);
  if (rx == ry) return;
  if (siz[rx.first][rx.second] < siz[ry.first][ry.second]) {
    dsu[rx.first][rx.second] = ry;
    siz[ry.first][ry.second] += siz[rx.first][rx.second];
  } else {
    dsu[ry.first][ry.second] = rx;
    siz[rx.first][rx.second] += siz[ry.first][ry.second];
  }
}
void dfs(int x, int y, long long g) {
  vis[x][y] = 1;
  for (int i = 0; i < 4; i++) {
    int l = d[i][0], r = d[i][1];
    if (check(x + l, y + r) && a[x + l][y + r] >= g) {
      onion({x, y}, {x + l, y + r});
      if (!vis[x + l][y + r]) dfs(x + l, y + r, g);
    }
  }
}
long long cnt = 0;
int flag[1001][1001];
void dfs2(int x, int y, long long g, long long lim) {
  vis[x][y] = 1;
  if (cnt == lim) return;
  cnt++;
  flag[x][y] = 1;
  for (int i = 0; i < 4; i++) {
    int l = d[i][0], r = d[i][1];
    if (check(x + l, y + r) && a[x + l][y + r] >= g && vis[x + l][y + r] == 0)
      dfs2(x + l, y + r, g, lim);
  }
}
void init() {
  for (int i = 0; i < 1001; i++)
    for (int j = 0; j < 1001; j++) dsu[i][j] = {i, j}, siz[i][j] = 1;
  memset((vis), (0), sizeof(vis));
}
int main() {
  init();
  scanf("%d%d", &n, &m);
  long long k;
  scanf("%lld", &k);
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) {
      scanf("%lld", &a[i][j]);
      if (k % a[i][j] == 0) f.push_back({i, j});
    }
  sort(f.begin(), f.end(), cmp);
  pair<int, int> ind = {-1, -1};
  for (pair<int, int> p : f) {
    if (!vis[p.first][p.second]) {
      dfs(p.first, p.second, a[p.first][p.second]);
      pair<int, int> r = root(p);
      if (siz[r.first][r.second] * a[p.first][p.second] >= k) {
        ind = p;
        break;
      }
    }
  }
  if (ind.first != -1) {
    memset((vis), (0), sizeof(vis));
    dfs2(ind.first, ind.second, a[ind.first][ind.second],
         k / a[ind.first][ind.second]);
    printf("YES\n");
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++)
        if (flag[i][j] == 1)
          printf("%lld", a[ind.first][ind.second]), printf(" ");
        else
          printf("%d", flag[i][j]), printf(" ");
      printf("\n");
    }
  } else
    printf("NO\n");
}

