pair<int, int> Find(pair<int, int> x) {
  if (parent[x.first][x.second] == x) return x;
  parent[x.first][x.second] = Find(parent[x.first][x.second]);
  return parent[x.first][x.second];
}
void Union(pair<int, int> u, pair<int, int> v) {
  u = Find(u);
  v = Find(v);
  if (parent[u.first][u.second] == parent[v.first][v.second]) {
    return;
  }
  if (treeSize[u.first][u.second] < treeSize[v.first][v.second]) {
    swap(u, v);
  }
  parent[v.first][v.second] = u;
  treeSize[u.first][u.second] =+ treeSize[v.first][v.second];
}
