  if (i - 1 >= 0 && a[i - 1][j] >= limit) Union({i, j}, {i - 1, j});
  if (i + 1 < n && a[i + 1][j] >= limit) Union({i, j}, {i + 1, j});
  if (j - 1 >= 0 && a[i][j - 1] >= limit) Union({i, j}, {i, j - 1});
