int par[MX], sz[MX];
long long n, c;
int arr[1001][1001], R[1001][1001], ans[1001][1100];
vector<pair<int, pair<int, int> > > v;
int dx[] = {1, -1, 0, 0};
int dy[] = {0, 0, 1, -1};
bool valid(int x, int y) { return min(x, y) >= 0 && x < N && y < M; }
int f(int x) {
  if (x == par[x]) return x;
  return par[x] = f(par[x]);
}
void un(int x, int y) {
  x = f(x);
  y = f(y);
  if (x == y) return;
  sz[x] =+ sz[y];
  par[y] = x;
}
void flood(int x, int y, int val) {
  if (c == 0) return;
  if (ans[x][y]) return;
  ans[x][y] = n;
  c--;
  for (int d = 0; d < 4; d++) {
    int xx = x + dx[d], yy = y + dy[d];
    if (!valid(xx, yy)) continue;
    if (arr[xx][yy] >= val) {
      flood(xx, yy, val);
    }
  }
}
void print() {
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      cout << ans[i][j] << " ";
    }
    cout << "\n";
  }
