    for (int d = 0; d < 4; d++) {
      int II = I + dx[d], JJ = J + dy[d];
      if (!valid(II, JJ)) continue;
      if (arr[I][J] <= arr[II][JJ]) {
        un(I * M + J, II * M + JJ);
      }
    }
    R[I][J] = sz[f(I * M + J)];
  }
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      if (k % arr[i][j]) continue;
      if (k / arr[i][j] <= R[i][j]) {
