  if (a < b) a = b;
}
const int M = 2001;
int A[M][M], id[M][M], fa[M * M], sz[M * M];
bool mark[M][M];
int n, m, tot;
long long s, num, now;
int rx[] = {0, 1, 0, -1}, ry[] = {1, 0, -1, 0};
struct node {
  int x, y, v;
  bool operator<(const node &a) const { return v < a.v; }
} C[M * M];
inline void input() {
  int i, j, k;
  scanf("%d%d%lld", &n, &m, &s);
  for (i = 0; i <= n - 1; ++i)
    for (j = 0; j <= m - 1; ++j) {
      rd(A[i][j]);
      fa[tot] = tot;
      sz[tot] = 1;
      C[tot++] = (node){i, j, A[i][j]};
    }
  sort(C, C + tot);
  for (i = 0; i <= tot - 1; ++i) id[C[i].x][C[i].y] = i;
}
inline bool check(int x, int y) { return x >= 0 && x < n && y >= 0 && y < m; }
