  num--;
  mark[x][y] = 1;
  if (num == 0) return;
  int i, nx, ny;
  for (i = 0; i <= 3; ++i) {
    nx = x + rx[i];
    ny = y + ry[i];
    if (check(nx, ny) && !mark[nx][ny] && A[nx][ny] >= v) {
      dfs(nx, ny, v);
      if (num == 0) return;
    }
  }
}
