  for (i = tot - 1; i >= 0; --i) {
    if (!C[i].v) break;
    for (j = 0; j <= 3; ++j) {
      x = C[i].x + rx[j];
      y = C[i].y + ry[j];
      if (!check(x, y) || id[x][y] < i) continue;
      combine(i, id[x][y]);
    }
    num = s / C[i].v;
    if (s % C[i].v == 0 && (long long)sz[i] >= num) {
      dfs(C[i].x, C[i].y, C[i].v);
