long long vis[1005][1005];
void create(long long x, long long y) {
  p[x][y] = {x, y};
  r[x][y] = 1;
}
pair<long long, long long> find(pair<long long, long long> x) {
  if (p[x.first][x.second] != x)
    p[x.first][x.second] = find(p[x.first][x.second]);
  return p[x.first][x.second];
}
void merge(pair<long long, long long> x, pair<long long, long long> y) {
  if (a[x.first][x.second] > a[y.first][y.second]) return;
  pair<long long, long long> px = find(x);
  pair<long long, long long> py = find(y);
  if (px == py) return;
  if (r[px.first][px.second] >= r[py.first][py.second]) {
    p[py.first][py.second] = p[px.first][px.second];
    r[px.first][px.second] += r[py.first][py.second];
  } else {
    p[px.first][px.second] = p[py.first][py.second];
    r[py.first][py.second] += r[px.first][px.second];
  }
}
void dfs(long long x, long long y) {
  if (cnt <= 0) return;
  ans[x][y] = val;
  cnt--;
  vis[x][y] = true;
  if (!vis[x - 1][y] && a[x - 1][y] >= val) dfs(x - 1, y);
  if (!vis[x + 1][y] && a[x + 1][y] >= val) dfs(x + 1, y);
  if (!vis[x][y - 1] && a[x][y - 1] >= val) dfs(x, y - 1);
  if (!vis[x][y + 1] && a[x][y + 1] >= val) dfs(x, y + 1);
}
