bool inpol(int i, int j) {
  if (i < 1 || i > n || j < 1 || j > m) return false;
  return true;
}
pair<int, int> root(int i, int j) {
  if (par[i][j] == make_pair(i, j)) return make_pair(i, j);
  return par[i][j] = root(par[i][j].first, par[i][j].second);
}
void join(int i, int j, int a, int b) {
  pair<int, int> r1 = root(i, j), r2 = root(a, b);
  if (r1 == r2) return;
  sz[r2.first][r2.second] += sz[r1.first][r1.second];
  par[r1.first][r1.second] = r2;
}
