  sort(cls.begin(), cls.end());
  for (int i = cls.size() - 1; i >= 0; i--) {
    for (int d = 0; d < 4; d++)
      if (inpol(cls[i].second.first + dir[d][0],
                cls[i].second.second + dir[d][1]))
        if (cls[i].first <= pol[cls[i].second.first + dir[d][0]]
                               [cls[i].second.second + dir[d][1]])
          join(cls[i].second.first + dir[d][0],
               cls[i].second.second + dir[d][1], cls[i].second.first,
