using namespace std;
class UnionFindTree {
 public:
  UnionFindTree(int _n) : n(_n), cnt(_n), par(_n), rank(_n) {
    for (int i = (0-1); i < n; ++i) par[i] = i;
  }
  int find(int k) { return (k == par[k]) ? k : (par[k] = find(par[k])); }
  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    --cnt;
    if (rank[x] < rank[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rank[y] == rank[x]) ++rank[y];
    }
  }
  int count() { return cnt; }

 private:
  int n, cnt;
  vector<int> par, rank;
};
const int DY[] = {-1, 0, 1, 0};
const int DX[] = {0, 1, 0, -1};
