long long ans[1001][1001];
void dfs(int y, int x, long long val, int &cnt, int goal) {
  if (y < 0 || x < 0 || y >= N || x >= M || A[y][x] < val || ans[y][x]) return;
  if (cnt == goal) return;
  cnt++;
  ans[y][x] = val;
  for (int i = 0; i < (int)4; ++i) {
    dfs(y + DY[i], x + DX[i], val, cnt, goal);
  }
}
void solve() {
  int maxLength = 1;
  map<long long, vector<pair<int, int>>> valPos;
  long long tot = 0;
  for (int y = 0; y < (int)N; ++y)
    for (int x = 0; x < (int)M; ++x) {
      valPos[-A[y][x]].emplace_back(y, x);
      tot += A[y][x];
    }
  UnionFindTree uf(N * M);
  vector<int> cnt(N * M, 1);
  for (auto &(a) : (valPos)) {
    long long val = -a.first;
    for (auto &(b) : (a.second)) {
      int r = b.first, c = b.second;
      int idx = r * M + c;
      for (int i = 0; i < (int)4; ++i) {
        int nr = r + DY[i], nc = c + DX[i];
        if (nr < 0 || nc < 0 || nr >= N || nc >= M || A[nr][nc] < val) continue;
        int nidx = nr * M + nc;
        int u = uf.find(idx), v = uf.find(nidx);
        if (u == v) continue;
        uf.unite(u, v);
        if (u != uf.find(u)) swap(u, v);
        cnt[u] += cnt[v];
        cnt[v] = 0;
        (maxLength) = max((maxLength), (cnt[u]));
      }
