      dfs(sy, sx, val, counts, goal);
      for (int y = 0; y < (int)N; ++y) {
        for (int x = 0; x < (int)M; ++x)
          cout << ans[y][x] << (x == M - 1 ? '\n' : ' ');
      }
      return;
    }
  }
  cout << "NO" << endl;
}
