  q_j.push(j);
  ans[i][j] = true;
  k--;
  while (k > 0) {
    int cur_i = q_i.front();
    int cur_j = q_j.front();
    q_i.pop();
    q_j.pop();
    if (k > 0 && cur_i - 1 >= 0 && a[cur_i - 1][cur_j] >= val &&
        !ans[cur_i - 1][cur_j]) {
      k--;
      ans[cur_i - 1][cur_j] = true;
      q_i.push(cur_i - 1);
      q_j.push(cur_j);
    }
    if (k > 0 && cur_i + 1 < n && a[cur_i + 1][cur_j] >= val &&
        !ans[cur_i + 1][cur_j]) {
      k--;
      ans[cur_i + 1][cur_j] = true;
      q_i.push(cur_i + 1);
      q_j.push(cur_j);
    }
