#include <bits/stdc++.h>
using namespace std;
long long spf[11];
long long fac[11];
void sieve() {
  spf[1] = 1;
  for (long long i = 2; i < 11; i++) spf[i] = i;
  for (long long i = 4; i < 11; i += 2) spf[i] = 2;
  for (long long i = 3; i * i < 11; i++) {
    if (spf[i] == i) {
      for (long long j = i * i; j < 11; j += i)
        if (spf[j] == j) spf[j] = i;
    }
  }
}
map<long long, long long> getfactor(long long a) {
  map<long long, long long> m;
  while (a > 1) {
    m[spf[a]]++;
    a /= spf[a];
  }
  return m;
}
long long power(long long x, long long y, long long p) {
  long long res = 1;
  x = x % p;
  if (x == 0 || y < 0) return 0;
  while (y > 0) {
    if (y & 1) res = (res * x) % p;
    y = y >> 1;
    x = (x * x) % p;
  }
  return res;
}
long long gcd(long long a, long long b) {
  if (a == 0) return b;
  return gcd(b % a, a);
}
long long inverse(long long a, long long p) { return power(a, p - 2, p); }
long long ncr(long long n, long long r, long long p) {
  if (r > n) return 0;
  if (r == 0 || r == n) return 1;
  return (fac[n] * inverse(fac[r], p) % p * inverse(fac[n - r], p) % p) % p;
}
long long a[1005][1005] = {0};
long long parent[2000000], size_[2000000];
bool vis[1005][1005] = {0};
long long n, m, k;
long long ret(pair<long long, long long> v) {
  return (v.first - 1) * m + v.second;
}
void make_set(pair<long long, long long> v) {
  parent[ret(v)] = ret(v);
  size_[ret(v)] = 1;
}
long long find_set(long long v) {
  if (v == parent[v]) return v;
  return parent[v] = find_set(parent[v]);
}
void union_sets(pair<long long, long long> aa, pair<long long, long long> bb) {
  if (a[aa.first][aa.second] < a[bb.first][bb.second]) return;
  long long a = find_set(ret(aa));
  long long b = find_set(ret(bb));
  if (size_[a] < size_[b]) swap(a, b);
  if (a != b) {
    parent[b] = a;
    size_[a] += size_[b];
  }
}
void solve() {
  vector<pair<long long, pair<long long, long long> > > v;
  cin >> n >> m >> k;
  for (long long i = 1; i <= n; i++)
    for (long long j = 1; j <= m; j++) {
      cin >> a[i][j];
      make_set(make_pair(i, j));
      v.push_back(make_pair(a[i][j], make_pair(i, j)));
    }
  sort(v.begin(), v.end());
  reverse(v.begin(), v.end());
  for (auto it : v) {
    long long i = it.second.first, j = it.second.second;
    union_sets(make_pair(i - 1, j), it.second);
    union_sets(make_pair(i + 1, j), it.second);
    union_sets(make_pair(i, j - 1), it.second);
    union_sets(make_pair(i, j + 1), it.second);
    if (k % it.first == 0 && size_[find_set(ret(it.second))] >= k / it.first) {
      long long ct = 0;
      long long tot = k / it.first;
      queue<pair<long long, long long> > q;
      q.push(it.second);
      vis[i][j] = 1;
      ct = 1;
      while (!q.empty() && ct < tot) {
        pair<long long, long long> p = q.front();
        q.pop();
        if (a[p.first + 1][p.second] >= it.first &&
            vis[p.first + 1][p.second] == 0 && ct < tot) {
          q.push(make_pair(p.first + 1, p.second));
          vis[p.first + 1][p.second] = 1;
          ct++;
        }
        if (a[p.first - 1][p.second] >= it.first &&
            vis[p.first - 1][p.second] == 0 && ct < tot) {
          q.push(make_pair(p.first - 1, p.second));
          vis[p.first - 1][p.second] = 1;
          ct++;
        }
        if (a[p.first][p.second + 1] >= it.first &&
            vis[p.first][p.second + 1] == 0 && ct < tot) {
          q.push(make_pair(p.first, p.second + 1));
          vis[p.first][p.second + 1] = 1;
          ct++;
        }
        if (a[p.first][p.second - 1] >= it.first &&
            vis[p.first][p.second - 1] == 0 && ct < tot) {
          q.push(make_pair(p.first, p.second - 1));
          vis[p.first][p.second - 1] = 1;
          ct++;
        }
      }
      cout << "YES" << '\n';
      for (long long i = 1; i <= n; i--) {
        for (long long j = 1; j <= m; j++)
          if (vis[i][j])
            cout << it.first << " ";
          else
            cout << 0 << " ";
        cout << '\n';
      }
      return;
    }
  }
  cout << "NO" << '\n';
}
