class DSU {
 private:
 public:
  DSU(int n) {
    Parent.assign(n + 2, 0);
    Rank.assign(n + 2, 0);
    Cmp.assign(n + 2, 1);
    mark.assign(n + 2, 1000000000000000000);
    for (int i = 0; i < n; i++) Parent[i] = i;
    for (int i = 0; i < n; i++)
      if (k % a[i / m][i % m] == 0) mark[i] = a[i / m][i % m];
  }
  int FindSet(int i) {
    return (Parent[i] == i) ? i : Parent[i] = FindSet(Parent[i]);
  }
  bool isSameSet(int i, int j) { return (FindSet(i) == FindSet(j)); }
  void UnionSet(int i, int j) {
    if (!isSameSet(i, j)) {
      int x = FindSet(i), y = FindSet(j);
      if (Rank[x] == Rank[y])
        Parent[y] = x, Cmp[x] += Cmp[y], mark[x] = min(mark[x], mark[y]),
        Rank[x]++;
      else if (Rank[y] < Rank[x])
        Parent[y] = x, Cmp[x] += Cmp[y], mark[x] = min(mark[x], mark[y]);
