#include <bits/stdc++.h>
using namespace std;
const int LIM = 0;
const int di[] = {-1, 1, 0, 0};
const int dj[] = {0, 0, -1, 1};
struct cell_t {
  long long val;
  int i, j;
};
bool operator>(const cell_t& a, const cell_t& b) { return a.val > b.val; }
long long f[LIM][LIM];
long long ans[LIM][LIM];
bool used[LIM][LIM];
vector<cell_t> elements;
int p[LIM * LIM];
int sz[LIM * LIM];
int n, m;
void init() {
  for (int i = 0; i < LIM * LIM; ++i) {
    p[i] = i;
    sz[i] = 1;
  }
}
int get_parent(int a) { return a == p[a] ? a : p[a] = get_parent(p[a]); }
void unite(int i, int j, int ni, int nj) {
  int a = i * LIM + j;
  int b = ni * LIM + nj;
  a = get_parent(a);
  b = get_parent(b);
  if (a == b) return;
  if (sz[b] > sz[a]) swap(a, b);
  sz[a] += sz[b];
  p[b] = a;
}
inline int get_size(int i, int j) { return sz[get_parent(i * LIM + j)]; }
void fill(int i, int j, long long val, int& left) {
  ans[i][j] = val;
  --left;
  for (int dir = 0; dir < 4 && left > 0; ++dir) {
    int ni = i + di[dir];
    int nj = j + dj[dir];
    if (ni >= 0 && ni < n && nj >= 0 && nj < m && ans[ni][nj] == 0 &&
        f[ni][nj] >= val)
      fill(ni, nj, val, left);
  }
}
void show() {
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) cout << ans[i][j] << " ";
    cout << '\n';
  }
}
int main() {
  init();
  elements.reserve(LIM * LIM);
  long long k;
  cin >> n >> m >> k;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
      cin >> f[i][j];
      elements.push_back({f[i][j], i, j});
    }
  sort(elements.begin(), elements.end(), greater<cell_t>());
  bool yes = false;
  for (cell_t& it : elements) {
    for (int dir = 0; dir < 4; ++dir) {
      int ni = it.i + di[dir];
      int nj = it.j + dj[dir];
      if (ni >= 0 && ni < n && nj >= 0 && nj < m && used[ni][nj]) {
        unite(it.i, it.j, ni, nj);
      }
    }
    int size = get_size(it.i, it.j);
    if (k % it.val == 0 && k / it.val <= size) {
      int left = k / it.val;
      fill(it.i, it.j, it.val, left);
      yes = true;
      break;
    }
    used[it.i][it.j] = true;
  }
  if (yes) {
    cout << "YES\n";
    show();
  } else {
    cout << "NO\n";
  }
  return 0;
}

