struct UnionFind {
  vector<int> comp;
  vector<int> size;
  UnionFind(int n) : comp(n), size(n, 1) {
    for (int(i) = 0; (i) < (int)(n); ++(i)) comp[i] = i;
  }
  bool merge(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return false;
    size[a] = size[b] = size[a] + size[b];
    comp[a] = b;
    return true;
  }
  int getSize(int a) { return size[find(a)]; }
  int find(int a) {
    while (comp[a] != a) a = comp[a] = comp[comp[a]];
    return a;
  }
};
