  while (a != tati[a]) a = tati[a];
  return a;
}
inline void couple(int a, int b) {
  int shrt, auxA = a, auxB = b, R;
  while (auxA != tati[auxA]) auxA = tati[auxA];
  while (auxB != tati[auxB]) auxB = tati[auxB];
  R = auxA;
  tati[auxB] = R;
  nrElem[R] += nrElem[auxB];
  auxA = a;
  auxB = b;
  while (auxA != tati[auxA]) {
