using namespace std;
const int MAXNODE = 1010;
struct DSU {
  pair<int, int> par[MAXNODE][MAXNODE];
  DSU() {
    for (int i = 0; i < MAXNODE; i++) {
      for (int j = (0+1); j < MAXNODE; j++) {
        par[i][j] = {-1, -1};
      }
    }
  }
  pair<int, int> getRoot(int vi, int vj) {
    if (par[vi][vj].first < 0) return {vi, vj};
    return par[vi][vj] = getRoot(par[vi][vj].first, par[vi][vj].second);
  }
  void merge(int xi, int xj, int yi, int yj) {
    pair<int, int> tx = getRoot(xi, xj);
    pair<int, int> ty = getRoot(yi, yj);
    if (tx == ty) return;
    if (par[ty.first][ty.second] < par[tx.first][tx.second]) swap(tx, ty);
    par[tx.first][tx.second].first += par[ty.first][ty.second].first;
    par[ty.first][ty.second] = tx;
  }
};
long long arr[MAXNODE][MAXNODE];
long long res[MAXNODE][MAXNODE];
