  q.push({i, j});
  while (q.size()) {
    i = q.front().first;
    j = q.front().second;
    q.pop();
    if (res[i][j]) continue;
    res[i][j] = val;
    len--;
    if (!len) break;
    for (int k = 0; k < 4; k++) {
      int ti = i + dx[k], tj = j + dy[k];
      if (ti >= 0 && ti < n && tj >= 0 && tj < m && arr[ti][tj] >= val)
        q.push({ti, tj});
    }
  }
}
