    if (s[i].v == 0) break;
    int X = s[i].x, Y = s[i].y;
    node tmp;
    for (int j = 0; j < 4; j++) {
      tmp.x = X + xx[j];
      tmp.y = Y + yy[j];
      tmp.v = a[tmp.x][tmp.y];
      if (tmp.v >= s[i].v) {
        Union((X - 1) * m + Y, (tmp.x - 1) * m + tmp.y);
      }
    }
    long long Num = K / s[i].v;
    if (K % s[i].v) continue;
    int u = find((X - 1) * m + Y);
    if (Num <= num[u]) {
      solve(X, Y, Num, s[i].v);
      return 0;
    }
  }
  cout << "NO" << endl;
  return 0;
}

