int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};
pair<int, int> idx[MAX][MAX];
int sze[MAX][MAX];
pair<int, int> root(pair<int, int> x) {
  while (!(x == idx[x.first][x.second])) {
    pair<int, int> ok = idx[x.first][x.second];
    idx[x.first][x.second] = idx[ok.first][ok.second];
    x = idx[x.first][x.second];
  }
  return x;
}
bool conn(pair<int, int> p, pair<int, int> q) { return root(p) == root(q); }
void join(pair<int, int> p, pair<int, int> q) {
  pair<int, int> i = root(p);
  pair<int, int> j = root(q);
  if (sze[i.first][i.second] < sze[j.first][j.second]) {
    idx[i.first][i.second] = j;
    sze[j.first][j.second] += sze[i.first][i.second];
  } else {
    idx[j.first][j.second] = i;
    sze[i.first][i.second] += sze[j.first][j.second];
  }
}
struct Trip {
  int first;
  int second;
  int t;
};
bool comp(Trip a, Trip b) { return a.t > b.t; }
int g[MAX][MAX];
int g2[MAX][MAX];
bool proc[MAX][MAX];
bool v[MAX][MAX];
bool mark[MAX][MAX];
int n, m;
long long k;
bool ok(int x, int y) { return (0 <= x && x < n && 0 <= y && y < m); }
