int limit = 0;
void dfs(int x, int y) {
  nodes++;
  v[x][y] = true;
  if (!(nodes > limit)) {
    mark[x][y] = true;
  }
  for (int i = 0; i < 4; i++) {
    int nx = dx[i] + x;
    int ny = dy[i] + y;
    if (ok(nx, ny) && !v[nx][ny] && g2[nx][ny] != 0) {
      dfs(nx, ny);
    }
  }
}
void prep(int x) {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (g[i][j] < x) {
        g2[i][j] = 0;
      } else {
        g2[i][j] = x;
      }
    }
  }
}
