  return dist[st.first.first][st.first.second][st.second];
}
pair<int, int> validDir[4];
void pD(int i) { validDir[i] = make_pair(1, 0); }
void pU(int i) { validDir[i] = make_pair(-1, 0); }
void pL(int i) { validDir[i] = make_pair(0, -1); }
void pR(int i) { validDir[i] = make_pair(0, 1); }
int getValidDir(pair<pair<int, int>, int> st) {
  int x = st.first.first;
  int y = st.first.second;
  int d = st.second;
  if (grid[x][y] == '+') {
    pD(0);
    pU(1);
    pL(2);
    pR(3);
    return 4;
  }
  if ((grid[x][y] == '-' && (d == 0 || d == 2)) ||
      (grid[x][y] == '|' && (d == 3 || d == 1))) {
    pL(0);
    pR(1);
    return 2;
  }
  if ((grid[x][y] == '-' && (d == 3 || d == 1)) ||
      (grid[x][y] == '|' && (d == 0 || d == 2))) {
    pU(0);
    pD(1);
    return 2;
  }
  if ((grid[x][y] == '^' && d == 0) || (grid[x][y] == '>' && d == 3) ||
      (grid[x][y] == 'v' && d == 2) || (grid[x][y] == '<' && d == 1)) {
    pU(0);
    return 1;
  }
  if ((grid[x][y] == '^' && d == 1) || (grid[x][y] == '>' && d == 0) ||
      (grid[x][y] == 'v' && d == 3) || (grid[x][y] == '<' && d == 2)) {
    pR(0);
    return 1;
  }
  if ((grid[x][y] == '^' && d == 2) || (grid[x][y] == '>' && d == 1) ||
      (grid[x][y] == 'v' && d == 0) || (grid[x][y] == '<' && d == 3)) {
    pD(0);
    return 1;
  }
  if ((grid[x][y] == '^' && d == 3) || (grid[x][y] == '>' && d == 2) ||
      (grid[x][y] == 'v' && d == 1) || (grid[x][y] == '<' && d == 0)) {
    pL(0);
    return 1;
  }
  if ((grid[x][y] == 'L' && d == 0) || (grid[x][y] == 'U' && d == 3) ||
      (grid[x][y] == 'R' && d == 2) || (grid[x][y] == 'D' && d == 1)) {
    pU(0);
    pR(1);
    pD(2);
    return 3;
  }
  if ((grid[x][y] == 'L' && d == 3) || (grid[x][y] == 'U' && d == 2) ||
      (grid[x][y] == 'R' && d == 1) || (grid[x][y] == 'D' && d == 0)) {
    pU(0);
    pR(1);
    pL(2);
    return 3;
  }
  if ((grid[x][y] == 'L' && d == 2) || (grid[x][y] == 'U' && d == 1) ||
      (grid[x][y] == 'R' && d == 0) || (grid[x][y] == 'D' && d == 3)) {
    pU(0);
    pD(1);
    pL(2);
    return 3;
  }
  if ((grid[x][y] == 'L' && d == 1) || (grid[x][y] == 'U' && d == 0) ||
      (grid[x][y] == 'R' && d == 3) || (grid[x][y] == 'D' && d == 2)) {
    pR(0);
    pD(1);
    pL(2);
    return 3;
  }
