char nxt(char e) {
  if (e == 'R') return 'U';
  if (e == 'U') return 'L';
  if (e == 'D') return 'R';
  if (e == 'L') return 'D';
}
bool check(char e, pair<pair<int, int>, int> st) {
  char d = grid[st.first.first][st.first.second];
  if (e == 'U') {
    return (d == '+') || (d == '|') || (d == '^') || (d == 'L') || (d == 'R') ||
           (d == 'D');
  }
  if (e == 'D') {
    return (d == '+') || (d == '|') || (d == 'v') || (d == 'L') || (d == 'R') ||
           (d == 'U');
  }
  if (e == 'R') {
    return (d == '+') || (d == '-') || (d == '>') || (d == 'L') || (d == 'D') ||
           (d == 'U');
  }
  if (e == 'L') {
    return (d == '+') || (d == '-') || (d == '<') || (d == 'R') || (d == 'D') ||
           (d == 'U');
  }
}
bool validEnter(int i, pair<pair<int, int>, int> st) {
  int d = st.second;
  char e;
  if (validDir[i].first == 0) {
    if (validDir[i].second == 1) {
      e = 'L';
    } else {
      e = 'R';
    }
  }
  if (validDir[i].second == 0) {
    if (validDir[i].first == 1) {
      e = 'U';
    } else {
      e = 'D';
    }
  }
  if (d == 0) return check(e, st);
  if (d == 1) return check(nxt(e), st);
  if (d == 2) return check(nxt(nxt(e)), st);
  if (d == 3) return check(nxt(nxt(nxt(e))), st);
}
void pprint(pair<pair<int, int>, int> st, pair<pair<int, int>, int> nst) {
  static int iter = 0;
  if (iter >= 0 && iter < 20) {
