int bfs(int x0, int y0, int xf, int yf) {
  for (int i = 0; i < MAX; i++)
    for (int j = 0; j < MAX; j++)
      for (int k = 0; k < 4; k++) dist[i][j][k] = INF;
  pair<pair<int, int>, int> ini = mst(x0, y0, 0);
  queue<pair<pair<int, int>, int> > q;
  q.push(ini);
  setDist(ini, 0);
  while (!q.empty()) {
    pair<pair<int, int>, int> st = q.front();
    q.pop();
    int t = getValidDir(st);
    for (int i = 0; i < t; i++) {
      int nx = st.first.first + validDir[i].first;
      int ny = st.first.second + validDir[i].second;
      if (nx < 0 || ny < 0 || nx >= n || ny >= m) continue;
      pair<pair<int, int>, int> nst = mst(nx, ny, st.second);
      if (validEnter(i, nst)) {
        if (getDist(nst) > getDist(st) + 1) {
          setDist(nst, getDist(st) + 1);
          q.push(nst);
        }
      }
    }
    pair<pair<int, int>, int> nst =
        mst(st.first.first, st.first.second, (st.second + 1) % 4);
    if (getDist(nst) > getDist(st) + 1) {
      setDist(nst, getDist(st) + 1);
      q.push(nst);
    }
  }
  int res = INF;
  for (int i = 0; i < 4; i++) {
    res = min(res, getDist(mst(xf, yf, i)));
  }
  return res;
}
