void bfs(vector<long long> G[], int S, long long dist[]) {
  queue<int> Q;
  Q.push(S);
  for (int i = 0; i <= h * w * 4; i++) dist[i] = 1e18;
  dist[S] = 0;
  while (Q.size()) {
    int v = Q.front(), u = v;
    long long s = u / (h * w);
    u %= (h * w);
    long long y = u / w;
    u %= w;
    long long x = u;
    Q.pop();
    long long nv = get((s - 1) % 4, x, y);
    if (dist[nv] >= 1e18 / 2) {
      Q.push(nv);
      dist[nv] = dist[v] + 1;
