map<char, string> rot = {{'+', "++++"}, {'L', "LURD"}, {'U', "URDL"},
                         {'R', "RDLU"}, {'D', "DLUR"}, {'|', "|-|-"},
                         {'-', "-|-|"}, {'^', "^>v<"}, {'>', ">v<^"},
                         {'v', "v<^>"}, {'<', "<^>v"}, {'*', "****"}};
string dc1[] = {"+LRD|^", ""};
string dc2[] = {"+URL|v", "+URD-<", "+LRD|^", "+LDU->"};
