static const std::unordered_map<char, std::vector<bool>> table = {
    {'+', {true, true, true, true}},    {'-', {false, true, false, true}},
    {'|', {true, false, true, false}},  {'^', {true, false, false, false}},
    {'>', {false, true, false, false}}, {'<', {false, false, false, true}},
