    x = xx;
    y = yy;
    rot = rrot;
  }
  str() {
    x = 0;
    y = 0;
    rot = 0;
  }
};
queue<str> q;
int d[1050][1050][4];
bool a[1050][1050][4];
int main() {
  ios::sync_with_stdio(0);
  int n, m;
  cin >> n >> m;
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) {
      char c;
      cin >> c;
      if (c == '+') a[i][j][0] = a[i][j][1] = a[i][j][2] = a[i][j][3] = true;
      if (c == '-') a[i][j][1] = a[i][j][3] = true;
      if (c == '|') a[i][j][0] = a[i][j][2] = true;
      if (c == '^') a[i][j][0] = true;
      if (c == '>') a[i][j][1] = true;
      if (c == 'v' || c == 'V') a[i][j][2] = true;
      if (c == '<') a[i][j][3] = true;
      if (c == 'L') a[i][j][0] = a[i][j][1] = a[i][j][2] = true;
      if (c == 'R') a[i][j][0] = a[i][j][2] = a[i][j][3] = true;
      if (c == 'U') a[i][j][1] = a[i][j][2] = a[i][j][3] = true;
      if (c == 'D') a[i][j][0] = a[i][j][1] = a[i][j][3] = true;
    }
