  cin >> sx >> sy;
  cin >> fx >> fy;
  for (int i = 0; i <= n + 1; i++)
    for (int j = 0; j <= m + 1; j++)
      for (int k = 0; k < 4; k++) d[i][j][k] = INF;
  d[sx][sy][0] = 0;
  q.push(str(sx, sy, 0));
  int mi = INF;
  while (!q.empty()) {
    str cur = q.front();
    q.pop();
    for (int i = 0; i < 4; i++) {
      int tox = cur.x + dx[i], toy = cur.y + dy[i], tor = (6 + i - cur.rot) % 4;
      if (a[cur.x][cur.y][(4 + i - cur.rot) % 4] && a[tox][toy][tor] &&
          d[tox][toy][cur.rot] == INF) {
        d[tox][toy][cur.rot] = d[cur.x][cur.y][cur.rot] + 1;
        q.push(str(tox, toy, cur.rot));
      }
    }
    if (d[cur.x][cur.y][(cur.rot + 1) % 4] == INF) {
      d[cur.x][cur.y][(cur.rot + 1) % 4] = d[cur.x][cur.y][cur.rot] + 1;
      q.push(str(cur.x, cur.y, (cur.rot + 1) % 4));
    }
  }
  for (int i = 0; i < 4; i++) mi = min(mi, d[fx][fy][i]);
  if (mi == INF)
    cout << -1;
  else
    cout << mi;
  return 0;
}

