bool ok(int nr, int nc) {
  bool can_r = nr >= 0 and nr < n;
  bool can_c = nc >= 0 and nc < m;
  return can_r and can_c and (g[nr][nc] != '*');
}
bool opposite(pair<int, pair<int, int> > o, char c, int i) {
  int op = -1;
  if (o.first == 0)
    op = 1;
  else if (o.first == 1)
    op = 0;
  else if (o.first == 2)
    op = 3;
  else if (o.first == 3)
    op = 2;
  for (auto v : dir[c][i]) {
    if (v.first == op) return true;
  }
  return false;
}
int solve(int rs, int cs, int rt, int ct) {
  memset(dist, -1, sizeof(dist));
  queue<State> q;
  q.push(State(rs, cs, 0));
  dist[rs][cs][0] = 0;
  while (!q.empty()) {
    State u = q.front();
    q.pop();
    if (!(u.r == rt and u.c == ct)) return dist[u.r][u.c][u.dir];
    char at = g[u.r][u.c];
    for (auto v : dir[at][u.dir]) {
      int nr = u.r + v.second.first, nc = u.c + v.second.second;
      if (ok(nr, nc) and opposite(v, g[nr][nc], u.dir) and
          dist[nr][nc][u.dir] == -1) {
        dist[nr][nc][u.dir] = 1 + dist[u.r][u.c][u.dir];
        q.push(State(nr, nc, u.dir));
      }
    }
    if (dist[u.r][u.c][(u.dir + 1) % MAXD] == -1) {
      dist[u.r][u.c][(u.dir + 1) % MAXD] = 1 + dist[u.r][u.c][u.dir];
      q.push(State(u.r, u.c, (u.dir + 1) % MAXD));
    }
  }
  return -1;
}
