  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      cin >> g[i][j];
    }
  }
  cin >> rs >> cs;
  cin >> rt >> ct;
  --rs, --cs;
  --rt, --ct;
  cout << solve(rs, cs, rt, ct) << '\n';
  return 0;
}

