namespace G {
inline int numer(int i, int j) { return i * m + j; }
struct V : vector<int> {
  int odl;
  V() : odl(INF) {}
};
V g[4 * MAX * MAX];
inline void dodaj_krawedz(int a, int b) { g[a].push_back(b); }
bool poprawny(int a, int b) { return 0 <= a && a < n && 0 <= b && b < m; }
inline bool da_sie_przejsc(int i, int j, int q, int k) {
  return drzwi[i][j][(4 + q - k) % 4];
}
void zbuduj_graf() {
  for (int i = 0; i < (n); i++)
    for (int j = 0; j < (m); j++) {
      int k = 4 * numer(i, j);
      for (int q = 0; q < (3); q++) dodaj_krawedz(k + q, k + q + 1);
      dodaj_krawedz(k + 3, k);
    }
  for (int i = 0; i < (n); i++)
    for (int j = 0; j < (m); j++) {
      int v = numer(i, j);
      for (int q = 0; q < (4); q++) {
        int x = i + T[q][0], y = j + T[q][1];
        if (poprawny(x, y)) {
          int u = numer(x, y);
          for (int k = 0; k < (4); k++)
            if (da_sie_przejsc(i, j, q, k) &&
                da_sie_przejsc(x, y, (q + 2) % 4, k))
              dodaj_krawedz(4 * v + k, 4 * u + k);
        }
      }
    }
}
