#include <bits/stdc++.h>
using namespace std;
struct pos {
  int x, y, z;
};
int n, m;
char cave[4][1005][1005];
int dist[(4-1)][1005][1005];
pos thes, mino;
queue<pos> q;
int dir[4][2] = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
char rot(char x) {
  switch (x) {
    case '-':
      return '|';
    case '|':
      return '-';
    case '^':
      return '>';
    case '>':
      return 'v';
    case 'v':
      return '<';
    case '<':
      return '^';
    case 'L':
      return 'U';
    case 'U':
      return 'R';
    case 'R':
      return 'D';
    case 'D':
      return 'L';
    default:
      return x;
  }
  return x;
}
bool has_door(char x, int d) {
  if (x == '*') return false;
  if (x == '+') return true;
  if (x == '-' && (d == 1 || d == 3)) return true;
  if (x == '|' && (d == 0 || d == 2)) return true;
  if ((x == '^' && d == 0) || (x == '>' && d == 1) || (x == 'v' && d == 2) ||
      (x == '<' && d == 3))
    return true;
  if ((x == 'U' && d != 0) || (x == 'R' && d != 1) || (x == 'D' && d != 2) ||
      (x == 'L' && d != 3))
    return true;
  return false;
}
void go(pos& p, int d) {
  pos z;
  if (d == -1) {
    z.x = p.x;
    z.y = p.y;
    z.z = (p.z + 1) % 4;
    if (dist[z.z][z.x][z.y] == 1000000000) {
      dist[z.z][z.x][z.y] = dist[p.z][p.x][p.y] + 1;
      q.push(z);
    }
    return;
  }
  z.z = p.z;
  z.x = p.x + dir[d][0];
  z.y = p.y + dir[d][1];
  if (z.x < 0 || z.x >= n || z.y < 0 || z.y >= m) return;
  if (dist[z.z][z.x][z.y] == 1000000000 && has_door(cave[p.z][p.x][p.y], d) &&
      has_door(cave[z.z][z.x][z.y], (d + 2) % 4)) {
    dist[z.z][z.x][z.y] = dist[p.z][p.x][p.y] + 1;
    q.push(z);
  }
  return;
}
int main() {
  ios::sync_with_stdio(false);
  cin >> n >> m;
  for (int i = 0; i < n; i++) {
    cin >> cave[0][i];
    for (int j = 0; j < m; j++)
      for (int k = 1; k < 4; k++) cave[k][i][j] = rot(cave[k - 1][i][j]);
  }
  cin >> thes.x >> thes.y;
  cin >> mino.x >> mino.y;
  thes.x--;
  thes.y--;
  mino.x--;
  mino.y--;
  for (int k = 0; k < 4; k++)
    for (int i = 0; i < n; i++)
      for (int j = 0; j < m; j++) dist[k][i][j] = 1000000000;
  dist[0][thes.x][thes.y] = 0;
  q.push(thes);
  while (!q.empty()) {
    pos p = q.front();
    q.pop();
    if (p.x == mino.x && p.y == mino.y) break;
    for (int d = -1; d < 4; d++) go(p, d);
  }
  int res = 1000000000;
  for (int k = 0; k < 4; k++) res = min(res, dist[k][mino.x][mino.y]);
  if (res == 1000000000) res = -1;
  cout << res << endl;
  return 0;
}

