const int MAX_N = 1005;
const int INF = 1000000000;
map<char, char> graph;
struct name {
  int x, y, i;
};
char s[4][MAX_N][MAX_N], pin[MAX_N][MAX_N];
int dist[4][MAX_N][MAX_N];
deque<name> och;
int main() {
  int n, m, xt, yt, xm, ym;
  cin >> n >> m;
  graph['+'] = '+';
  graph['*'] = '*';
  graph['-'] = '|';
  graph['|'] = '-';
  graph['^'] = '>';
  graph['>'] = 'v';
  graph['v'] = '<';
  graph['<'] = '^';
  graph['L'] = 'U';
  graph['U'] = 'R';
  graph['R'] = 'D';
  graph['D'] = 'L';
  scanf("\n");
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      scanf("%c", &pin[i][j]);
      s[0][i][j] = pin[i][j];
      s[1][i][j] = graph[s[0][i][j]];
      s[2][i][j] = graph[s[1][i][j]];
      s[3][i][j] = graph[s[2][i][j]];
    }
    scanf("\n");
  }
  cin >> xt >> yt;
  cin >> xm >> ym;
  if (xm == xt && yt == ym) {
    cout << "0";
    return 0;
  }
  xt--;
  yt--;
  xm--;
  ym--;
  for (int i = 0; i < 4; i++) {
    for (int j = 0; j < n; j++) {
      for (int k = 0; k < m; k++) dist[i][j][k] = INF;
    }
  }
  dist[0][xt][yt] = 0;
  name v;
  v.x = xt;
  v.y = yt;
  v.i = 0;
  och.push_back(v);
  while (!och.empty()) {
    v = och[0];
    och.pop_front();
    v.i = v.i % 4;
    if (dist[v.i][v.x][v.y] + 1 < dist[(v.i + 1) % 4][v.x][v.y]) {
      dist[(v.i + 1) % 4][v.x][v.y] = dist[v.i][v.x][v.y] + 1;
      v.i++;
      och.push_back(v);
      v.i--;
    }
    if (s[v.i][v.x][v.y] == '+' || s[v.i][v.x][v.y] == '|' ||
        s[v.i][v.x][v.y] == '^' || s[v.i][v.x][v.y] == 'L' ||
        s[v.i][v.x][v.y] == 'R' || (0==1)) {
      if (v.x > 0 &&
          (s[v.i][v.x - 1][v.y] == '+' || s[v.i][v.x - 1][v.y] == '|' ||
           s[v.i][v.x - 1][v.y] == 'v' || s[v.i][v.x - 1][v.y] == 'L' ||
           s[v.i][v.x - 1][v.y] == 'R' || s[v.i][v.x - 1][v.y] == 'U'))
        if (dist[v.i][v.x][v.y] + 1 < dist[v.i][v.x - 1][v.y]) {
          dist[v.i][v.x - 1][v.y] = dist[v.i][v.x][v.y] + 1;
          v.x--;
          och.push_back(v);
          v.x++;
        }
    }
    if (s[v.i][v.x][v.y] == '+' || s[v.i][v.x][v.y] == '|' ||
        s[v.i][v.x][v.y] == 'v' || s[v.i][v.x][v.y] == 'L' ||
        s[v.i][v.x][v.y] == 'R' || s[v.i][v.x][v.y] == 'U') {
      if (v.x + 1 < n &&
          (s[v.i][v.x + 1][v.y] == '+' || s[v.i][v.x + 1][v.y] == '|' ||
           s[v.i][v.x + 1][v.y] == '^' || s[v.i][v.x + 1][v.y] == 'L' ||
           s[v.i][v.x + 1][v.y] == 'R' || s[v.i][v.x + 1][v.y] == 'D'))
        if (dist[v.i][v.x][v.y] + 1 < dist[v.i][v.x + 1][v.y]) {
          dist[v.i][v.x + 1][v.y] = dist[v.i][v.x][v.y] + 1;
          v.x++;
          och.push_back(v);
          v.x--;
        }
    }
    if (s[v.i][v.x][v.y] == '+' || s[v.i][v.x][v.y] == '-' ||
        s[v.i][v.x][v.y] == '>' || s[v.i][v.x][v.y] == 'L' ||
        s[v.i][v.x][v.y] == 'U' || s[v.i][v.x][v.y] == 'D') {
      if (v.y + 1 < m &&
          (s[v.i][v.x][v.y + 1] == '+' || s[v.i][v.x][v.y + 1] == '-' ||
           s[v.i][v.x][v.y + 1] == '<' || s[v.i][v.x][v.y + 1] == 'R' ||
           s[v.i][v.x][v.y + 1] == 'U' || s[v.i][v.x][v.y + 1] == 'D'))
        if (dist[v.i][v.x][v.y] + 1 < dist[v.i][v.x][v.y + 1]) {
          dist[v.i][v.x][v.y + 1] = dist[v.i][v.x][v.y] + 1;
          v.y++;
          och.push_back(v);
          v.y--;
        }
    }
    if (s[v.i][v.x][v.y] == '+' || s[v.i][v.x][v.y] == '-' ||
        s[v.i][v.x][v.y] == '<' || s[v.i][v.x][v.y] == 'R' ||
        s[v.i][v.x][v.y] == 'U' || s[v.i][v.x][v.y] == 'D') {
      if (v.y > 0 &&
          (s[v.i][v.x][v.y - 1] == '+' || s[v.i][v.x][v.y - 1] == '-' ||
           s[v.i][v.x][v.y - 1] == '>' || s[v.i][v.x][v.y - 1] == 'L' ||
           s[v.i][v.x][v.y - 1] == 'U' || s[v.i][v.x][v.y - 1] == 'D'))
        if (dist[v.i][v.x][v.y] + 1 < dist[v.i][v.x][v.y - 1]) {
          dist[v.i][v.x][v.y - 1] = dist[v.i][v.x][v.y] + 1;
          v.y--;
          och.push_back(v);
          v.y++;
        }
    }
  }
  int ans = INF;
  for (int i = 0; i < 4; i++) {
    if (dist[i][xm][ym] < ans) ans = dist[i][xm][ym];
  }
  if (ans == INF)
    cout << "-1";
  else
    cout << ans;
  return 0;
}

