#include <bits/stdc++.h>
using namespace std;
char rotate(char ori) {
  switch (ori) {
    case '+':
      return '+';
    case '-':
      return '|';
    case '|':
      return '-';
    case '^':
      return '>';
    case '>':
      return 'v';
    case '<':
      return '^';
    case 'v':
      return '<';
    case 'L':
      return 'U';
    case 'R':
      return 'D';
    case 'U':
      return 'R';
    case 'D':
      return 'L';
    case '*':
      return '*';
  }
}
bool okVer(char u, char b) {
  bool uOk = false, bOk = false;
  if (u == '+' || u == '|' || u == 'v' || u == 'L' || u == 'R' || u == 'U')
    uOk = true;
  if (b == '+' || b == '|' || b == '^' || b == 'L' || b == 'R' || b == 'D')
    bOk = true;
  return uOk && bOk;
}
bool okHor(char l, char r) {
  bool lOk = false, rOk = false;
  if (l == '+' || l == '-' || l == '>' || l == 'U' || l == 'D' || l == 'L')
    lOk = true;
  if (r == '+' || r == '-' || r == '<' || r == 'U' || r == 'D' || r == 'R')
    rOk = true;
  return lOk && rOk;
}
