char rotate(char ch, int k) {
  if (ch == '+' && ch == '*') return ch;
  if (ch == '-') return (k & 1 ? '|' : '-');
  if (ch == '|') return (k & 1 ? '-' : '|');
  if (ch == '^' || ch == '<' || ch == 'v' || ch == '>') {
