int n, m, sX, sY, eX, eY, d[N][N][4], a[N][N];
const int mx[] = {-1, 0, 1, 0};
const int my[] = {0, 1, 0, -1};
const char D[] = {'U', 'R', 'D', 'L'};
struct data {
  int dis, x, y, k;
  data() {}
  data(int dis, int x, int y, int k) {
    this->dis = dis;
    this->x = x;
    this->y = y;
    this->k = k;
  }
};
bool operator<(const data &a, const data &b) {
  return a.dis < b.dis || (a.dis == b.dis && a.k < b.k);
}
inline int convert(const char &c) {
  int ret = 0;
  if (c == '+') ret = (1 << 4) - 1;
  if (c == '-') ret |= 1 << 1, ret |= 1 << 3;
  if (c == '|') ret |= 1 << 0, ret |= 1 << 2;
  if (c == '^') ret |= 1 << 0;
  if (c == '>') ret |= 1 << 1;
  if (c == '<') ret |= 1 << 3;
  if (c == 'v') ret |= 1 << 2;
  if (c == 'L') ret = (1 << 4) - 1, ret ^= 1 << 3;
  if (c == 'R') ret = (1 << 4) - 1, ret ^= 1 << 1;
  if (c == 'U') ret = (1 << 4) - 1, ret ^= 1 << 0;
  if (c == 'D') ret = (1 << 4) - 1, ret ^= 1 << 2;
  return ret;
}
void print(const int &x) {
  for (int i = 0; i <= 3; i++) cout << (x >> i & 1);
  exit(0);
}
inline int next(int x, int step) {
  for (int S = 1; S <= step; S++) {
    for (int i = 4; i >= 1; i--) {
      x &= ~(1 << i);
      if (x >> (i - 1) & 1) x |= 1 << i;
    }
    if (x >> 4 & 1)
      x |= 1 << 0;
    else
      x &= ~(1 << 0);
    x &= ~(1 << 4);
  }
  return x;
}
inline int merge(int XX, int YY, const char &dir) {
  for (int step = 0; step <= 3; step++) {
    if (step) XX = next(XX, 1), YY = next(YY, 1);
    bool check = false;
    if (dir == 'U') check = (XX >> 0 & 1) && (YY >> 2 & 1);
    if (dir == 'R') check = (XX >> 1 & 1) && (YY >> 3 & 1);
    if (dir == 'D') check = (XX >> 2 & 1) && (YY >> 0 & 1);
    if (dir == 'L') check = (XX >> 3 & 1) && (YY >> 1 & 1);
    if (check) return step;
  }
  return INF;
}
