    if (dis != d[x][y][K]) continue;
    for (int dir = 0; dir < 4; dir++) {
      int xx = x + mx[dir], yy = y + my[dir];
      if (xx >= 1 && xx <= m && yy >= 1 && yy <= n) {
        int C = merge(next(a[x][y], K), next(a[xx][yy], K), D[dir]);
        if (d[xx][yy][(K + C) % 4] > d[x][y][K] + C + 1) {
          d[xx][yy][(K + C) % 4] = d[x][y][K] + C + 1;
