inline int next(int x, int step) {
  for (int S = 1; S <= step; S++) {
    for (int i = 4; i >= 1; i--) {
      x &= ~(1 << i);
      if (x >> (i - 1) & 1) x |= 1 << i;
    }
    if (x >> 4 & 1)
      x |= 1 << 0;
    else
      x &= ~(1 << 0);
    x &= ~(1 << 4);
  }
  return x;
}
inline int merge(int XX, int YY, const char &dir) {
  for (int step = 0; step <= 3; step++) {
    if (step) XX = next(XX, 1), YY = next(YY, 1);
    bool check = false;
    if (dir == 'U') check = (XX >> 0 & 1) && (YY >> 2 & 1);
    if (dir == 'R') check = (XX >> 1 & 1) && (YY >> 3 & 1);
    if (dir == 'D') check = (XX >> 2 & 1) && (YY >> 0 & 1);
    if (dir == 'L') check = (XX >> 3 & 1) && (YY >> 1 & 1);
    if (check) return step;
  }
  return INF;
}
