int Rotate(int a) {
  int t = a & 1;
  a /= 2;
  a += (t << 3);
  return a;
}
bool func(int a, int b, int shf) {
  if (shf == 0) {
    return ((a & 8) && (b & 2));
  } else if (shf == 1) {
    return ((a & 4) && (b & 1));
  } else if (shf == 2) {
    return ((a & 2) && (b & 8));
  } else {
    return ((a & 1) && (b & 4));
  }
}
bool isValid(int num, int rot, int a1, int b1, int a2, int b2) {
  if (a1 < 0 || a1 > n - 1 || b1 < 0 || b1 > m - 1) return false;
  if (a2 < 0 || a2 > n - 1 || b2 < 0 || b2 > m - 1) return false;
  int t1 = arr[a1][b1], t2 = arr[a2][b2];
  for (int i = 0; i < rot; ++i) t1 = Rotate(t1), t2 = Rotate(t2);
  return func(t1, t2, num);
}
