        } else if (nuj[i][j][times - 1] == '*') {
          nuj[i][j][times] = '*';
          continue;
        }
        for (long long ii = 0; ii < 13; ii++) {
          if (nuj[i][j][times - 1] == elem[ii]) {
            nuj[i][j][times] = elem[ii + 1];
