int dist[1010][1010][4];
int S[4] = {1, 2 , 8, 4};
int d1[4] = {-1, 0, 1, 0};
int d2[4] = {0, -1, 0, 1};
int s1, s2, t1, t2;
queue<int> q;
inline bool pass(int x, int y, int t, int dir) {
  return (a[x][y] & (1 << ((t + dir) % 4)));
}
inline int geti(char c) {
  if (c == '+')
    return S[0] | S[1] | S[2] | S[3];
  else if (c == '|')
    return S[0] | S[2];
  else if (c == '-')
    return S[1] | S[3];
  else if (c == '^')
    return S[0];
  else if (c == '>')
    return S[3];
  else if (c == 'v')
    return S[2];
  else if (c == '<')
    return S[1];
  else if (c == 'U')
    return S[1] | S[2] | S[3];
  else if (c == 'R')
    return S[0] | S[1] | S[2];
  else if (c == 'D')
    return S[0] | S[1] | S[3];
  else if (c == 'L')
    return S[0] | S[2] | S[3];
  else
    return 0;
}
int main() {
  cin >> n >> m;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      char c;
