    }
  }
  cin >> s1 >> s2;
  cin >> t1 >> t2;
  s1--, s2--, t1--, t2--;
  fill((int*)dist, (int*)dist + 1010 * 1010 * 4, 1 << 27);
  dist[s1][s2][0] = 0;
  q.push(s1);
  q.push(s2);
