  while (!q.empty()) {
    int x = q.front();
    q.pop();
    int y = q.front();
    q.pop();
    int dir = q.front();
    q.pop();
    int step = dist[x][y][dir];
    if (x == t1 && y == t2) {
      cout << step;
      return 0;
    }
    if (dist[x][y][(dir + 1) % 4] > step + 1) {
      dist[x][y][(dir + 1) % 4] = step + 1;
      q.push(x);
      q.push(y);
      q.push((dir + 1) % 4);
    }
    for (int i = 0; i < 4; i++) {
      int xi = x + d1[i];
      int yi = y + d2[i];
      if (xi >= 0 && yi >= 0 && xi < n && yi < m &&
          dist[xi][yi][dir] > step + 1) {
        if (pass(x, y, i, dir) && pass(xi, yi, (i + 2) % 4, dir)) {
          dist[xi][yi][dir] = step + 1;
          q.push(xi);
          q.push(yi);
          q.push(dir);
        }
      }
