#include <bits/stdc++.h>
using namespace std;
int n, m;
int a[1010][1010];
int dist[1010][1010][(4-1)];
int S[4] = {1, 2, 4, 8};
int d1[4] = {-1, 0, 1, 0};
int d2[4] = {0, -1, 0, 1};
int s1, s2, t1, t2;
queue<int> q;
inline bool pass(int x, int y, int t, int dir) {
  return (a[x][y] & (1 << ((t + dir) % 4)));
}
inline int geti(char c) {
  if (c == '+')
    return S[0] | S[1] | S[2] | S[3];
  else if (c == '|')
    return S[0] | S[2];
  else if (c == '-')
    return S[1] | S[3];
  else if (c == '^')
    return S[0];
  else if (c == '>')
    return S[3];
  else if (c == 'v')
    return S[2];
  else if (c == '<')
    return S[1];
  else if (c == 'U')
    return S[1] | S[2] | S[3];
  else if (c == 'R')
    return S[0] | S[1] | S[2];
  else if (c == 'D')
    return S[0] | S[1] | S[3];
  else if (c == 'L')
    return S[0] | S[2] | S[3];
  else
    return 0;
}
int main() {
  cin >> n >> m;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      char c;
      cin >> c;
      a[i][j] = geti(c);
    }
  }
  cin >> s1 >> s2;
  cin >> t1 >> t2;
  s1--, s2--, t1--, t2--;
  fill((int*)dist, (int*)dist + 1010 * 1010 * 4, 1 << 27);
  dist[s1][s2][0] = 0;
  q.push(s1);
  q.push(s2);
  q.push(0);
  while (!q.empty()) {
    int x = q.front();
    q.pop();
    int y = q.front();
    q.pop();
    int dir = q.front();
    q.pop();
    int step = dist[x][y][dir];
    if (x == t1 && y == t2) {
      cout << step;
      return 0;
    }
    if (dist[x][y][(dir + 1) % 4] > step + 1) {
      dist[x][y][(dir + 1) % 4] = step + 1;
      q.push(x);
      q.push(y);
      q.push((dir + 1) % 4);
    }
    for (int i = 0; i < 4; i++) {
      int xi = x + d1[i];
      int yi = y + d2[i];
      if (xi >= 0 && yi >= 0 && xi < n && yi < m &&
          dist[xi][yi][dir] > step + 1) {
        if (pass(x, y, i, dir) && pass(xi, yi, (i + 2) % 4, dir)) {
          dist[xi][yi][dir] = step + 1;
          q.push(xi);
          q.push(yi);
          q.push(dir);
        }
      }
    }
  }
  cout << "-1";
  return 0;
}

