const int MAXN = 500;
const int dx[] = {0, 0, 1, -1};
const int dy[] = {1, -1, 0, 0};
char box[MAXN + 5][MAXN + 5];
int presum[MAXN + 5][MAXN + 5];
bool vis[MAXN + 5][MAXN + 5];
int pos[MAXN + 5][MAXN + 5];
int cnt[MAXN * MAXN + 5];
bool used[MAXN * MAXN + 5];
int n, k, tot;
bool check(int x, int y) {
  if (x < 1 || x > n || y < 1 || y > n) return false;
  if (box[x][y] == '.' && !vis[x][y]) return true;
  return false;
}
void dfs(int x, int y, int now) {
  pos[x][y] = now;
  vis[x][y] = true;
  cnt[now]++;
  for (int i = 0; i < 4; i++) {
    int nx = x + dx[i];
    int ny = y + dy[i];
    if (check(nx, ny)) dfs(nx, ny, now);
  }
}
void Init() {
  tot = 0;
  for (int i = 1; i <= n; i++) scanf("%s", box[i] + 1);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      presum[i][j] = presum[i - 1][j] + presum[i][j - 1] - presum[i - 1][j - 1];
      if (box[i][j] == 'X') presum[i][j]++;
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      if (check(i, j)) {
        dfs(i, j, ++tot);
      }
    }
  }
}
