  if (x < 1 || x > n || y < 1 || y > n) return 0;
  if (box[x][y] == '.' && used[pos[x][y]]) {
    used[pos[x][y]] = false;
    return cnt[pos[x][y]];
  }
  return 0;
}
void Clean(int x, int y) {
  if (x < 1 || x > n || y < 1 || y > n) return;
