#include <bits/stdc++.h>
using namespace std;
const int N = 0;
const int dir[2][2] = {-1, 0, 0, -1};
int n, k;
char str[N][N];
int parent[N * N], cnt[N * N], id[N][N], idx, cc[N * N];
int st[N * N], top;
int find(int x) {
  top = 0;
  while (x != parent[x]) {
    st[top++] = x;
    x = parent[x];
  }
  for (int i = 0; i < top; i++) parent[st[i]] = x;
  return x;
}
int vis[N * N], tmp[N * N], tn;
int gao(int x) {
  int p = find(x);
  if (vis[p]) return 0;
  tmp[tn++] = p;
  vis[p] = 1;
  return cnt[p];
}
int cal(int x, int y) {
  int ans = k * k;
  tn = 0;
  for (int i = x; i < x + k; i++) {
    if (y - 1 >= 1 && str[i][y - 1] == 'X') ans += gao(id[i][y - 1]);
    if (y + k <= n && str[i][y + k] == 'X') ans += gao(id[i][y + k]);
  }
  for (int i = y; i < y + k; i++) {
    if (x - 1 >= 1 && str[x - 1][i] == 'X') ans += gao(id[x - 1][i]);
    if (x + k <= n && str[x + k][i] == 'X') ans += gao(id[x + k][i]);
  }
  for (int i = 0; i < tn; i++) vis[tmp[i]] = 0;
  return ans;
}
int main() {
  scanf("%d%d", &n, &k);
  for (int i = 1; i <= n; i++) {
    scanf("%s", str[i] + 1);
    for (int j = 1; j <= n; j++) {
      if (str[i][j] == '.')
        str[i][j] = 'X';
      else
        str[i][j] = '.';
      id[i][j] = ++idx;
      parent[idx] = idx;
      cnt[idx] = 1;
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      if (str[i][j] == '.') continue;
      for (int k = 0; k < 2; k++) {
        int x = i + dir[k][0];
        int y = j + dir[k][1];
        if (x <= 0 || x > n || y <= 0 || y > n || str[x][y] == '.') continue;
        int pu = find(id[i][j]);
        int pv = find(id[x][y]);
        if (pu != pv) {
          parent[pu] = pv;
          cnt[pv] += cnt[pu];
        }
      }
    }
  }
  memcpy(cc, cnt, sizeof(cnt));
  int ans = 0;
  for (int i = 1; i <= n - k + 1; i++) {
    memcpy(cnt, cc, sizeof(cc));
    for (int x = i; x < i + k; x++) {
      for (int y = 1; y < k; y++) cnt[find(id[x][y])]--;
    }
    for (int y = 1; y <= n - k + 1; y++) {
      for (int x = i; x < i + k; x++) cnt[find(id[x][y + k - 1])]--;
      ans = max(ans, cal(i, y));
      for (int x = i; x < i + k; x++) cnt[find(id[x][y])]++;
    }
  }
  printf("%d\n", ans);
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int maxn = 510;
char g[maxn][maxn];
int col[maxn][maxn], v[maxn * maxn], b[maxn * maxn], cnt, n, k, sum;
int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};
void dfs(int x, int y, int c) {
  col[x][y] = c;
  ++cnt;
  for (int i = 0; i < 4; ++i) {
    int tx = x + dx[i], ty = y + dy[i];
    if (tx < 0 || ty < 0 || tx >= n || ty >= n || g[tx][ty] == 'X' ||
        col[tx][ty])
      continue;
    dfs(tx, ty, c);
  }
}
void add(int x, int y) {
  if (col[x][y] && ++v[col[x][y]] == 1) sum += b[col[x][y]];
}
void dec(int x, int y) {
  if (col[x][y] && --v[col[x][y]] == 0) sum -= b[col[x][y]];
}
int main() {
  scanf("%d %d", &n, &k);
  for (int i = 0; i < n; ++i) scanf("%s", g[i]);
  int c = 1;
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j)
      if (g[i][j] == '.' && !col[i][j]) {
        cnt = 0;
        dfs(i, j, c);
        b[c++] = cnt;
      }
  }
  int ans = 0;
  for (int i = 0; i + k <= n; ++i) {
    memset(v, 0, sizeof v);
    sum = 0;
    for (int x = 0; x < k; ++x) {
      for (int y = 0; y < k; ++y) {
        add(x + i, y);
        if (!col[x + i][y]) ++sum;
      }
      if (i + k < n) add(i + k, x);
      if (k < n) add(x + i, k);
      if (i) add(i - 1, x);
    }
    ans = max(ans, sum);
    for (int j = 1; j + k <= n; ++j) {
      if (i) {
        if (j - 1 >= 0) dec(i - 1, j - 1);
        add(i - 1, j + k - 1);
      }
      if (i + k < n) {
        if (j - 1 >= 0) dec(i + k, j - 1);
        add(i + k, j + k - 1);
      }
      if (j - 1 >= 0)
        for (int t = 0; t < k; ++t)
          if (!col[i + t][j - 1]) --sum;
      if (j - 2 >= 0)
        for (int t = 0; t < k; ++t) dec(i + t, j - 2);
      if (j + k - 1 < n)
        for (int t = 0; t < k; ++t)
          if (col[i + t][j + k - 1]) ++sum;
      if (j + k <= n)
        for (int t = 0; t < k; ++t) add(i + t, j + k);
      ans = max(ans, sum);
    }
  }
  printf("%d\n", ans);
  return 0;
}

