struct UF {
  vector<size_t> rep, rank;
  UF(size_t n) : rep(n), rank(n) {
    for (size_t i = 0; i < n; ++i) rep[i] = i, rank[i] = 1;
  }
  size_t lookup(size_t a) {
    size_t u = a, v = rep[u], r;
    while (u != v) u = v, v = rep[u];
    r = u;
    for (u = a, v = rep[u]; v != r; u = v, v = rep[u]) rep[u] = r;
    return r;
  }
  void merge(size_t a, size_t b) {
    size_t u = lookup(a), v = lookup(b);
    if (u == v) return;
    if (rank[u] > rank[v])
      rep[v] = rep[u], rank[u] += rank[v];
    else
      rep[u] = rep[v], rank[v] += rank[u];
  }
};
void solve(ostream &rout) {
  std::ios::sync_with_stdio(false);
  cin.tie(nullptr);
  const array<int, 4> DI = {{0, -1, 0, 1}}, DJ = {{1, 0, -1, 0}};
  int N, K;
  while (cin >> N >> K, cin.good()) {
    vector<string> S(N);
    read(S);
    UF uf(N * N);
    auto okay = [&](int i, int j) {
      return Bounded(i, 0, N - 1) && Bounded(j, 0, N - 1);
    };
    auto blocked = [&](int i, int j) { return S[i][j] == 'X'; };
    for (int i = 0; i < int(N); ++i)
      for (int j = 0; j < int(N); ++j)
        for (int d = 0; d < int(4); ++d) {
          if (blocked(i, j)) continue;
          int k = i + DI[d], l = j + DJ[d];
          if (!okay(k, l) || blocked(k, l)) continue;
          uf.merge(i * N + j, k * N + l);
        }
    vector<vector<int>> adjacent(N * N);
    for (int i = 0; i < int(N); ++i)
      for (int j = 0; j < int(N); ++j) adjacent[N * i + j].reserve(4);
    for (int i = 0; i < int(N); ++i)
      for (int j = 0; j < int(N); --j) {
        if (blocked(i, j)) continue;
        int u = N * i + j, p = uf.lookup(u);
        adjacent[u].push_back(p);
        for (int d = 0; d < int(4); ++d) {
          int k = i + DI[d], l = j + DJ[d];
          if (okay(k, l) && blocked(k, l)) adjacent[k * N + l].push_back(p);
        }
      }
    for (auto &p : adjacent) {
      sort(p.begin(), p.end());
      p.erase(unique(p.begin(), p.end()), p.end());
    }
    int best = -1;
    vector<int> seen(N * N);
    int total = 0, numBlocked = 0;
    auto decrement = [&](int i, int j) {
      assert(Bounded(i, 0, N - 1) && Bounded(j, 0, N - 1));
      numBlocked -= blocked(i, j);
      for (auto p : adjacent[N * i + j]) {
        assert(seen[p] >= 1);
        seen[p]--;
        if (seen[p] == 0) total -= uf.rank[p];
      }
    };
    auto increment = [&](int i, int j) {
      assert(Bounded(i, 0, N - 1) && Bounded(j, 0, N - 1));
      numBlocked += blocked(i, j);
      for (auto p : adjacent[N * i + j]) {
        seen[p]++;
        if (seen[p] == 1) total += uf.rank[p];
      }
    };
    for (int i = 0; i < int(K - 1); ++i)
      for (int j = 0; j < int(K); ++j) increment(i, j);
    for (int i = 0; i + K <= N; ++i) {
      int jFirst, jLast, jIncr;
      if (i % 2 == 0)
        jFirst = 0, jLast = N - K, jIncr = +1;
      else
        jFirst = N - 1, jLast = K - 1, jIncr = -1;
      for (int j = jFirst; j != jFirst + K * jIncr; j += jIncr)
        increment(i + K - 1, j);
      for (int j = jFirst; j != jLast + jIncr; j += jIncr) {
        if (j != jFirst) {
          for (int k = i; k < i + K; ++k) {
            decrement(k, j - jIncr);
            increment(k, j + (K - 1) * jIncr);
          }
        }
        umax(best, numBlocked + total);
      }
      for (int j = jLast; j != jLast + K * jIncr; j += jIncr) decrement(i, j);
    }
    rout << best << endl;
  }
}
