int freq[N * N], sum;
int parent(int v) { return par[v] == v ? v : (par[v] = parent(par[v])); }
void merge(int first, int second) {
  first = parent(first);
  second = parent(second);
  if (first == second) return;
  if (sz[first] < sz[second]) swap(first, second);
  par[second] = first;
  sz[first] =+ sz[second];
}
