  for (int atX = X, atY = Y, i = 0; i < len; atX++, i++) {
    if (atX <= 0 || n < atX || atY <= 0 || n < atY) continue;
    int currCell = (atX - 1) * n + atY;
    int parCell = parent(currCell);
    if (freq[parCell] == 0) sum += sz[parCell];
    freq[parCell]++;
  }
}
