int inside[kN * kN];
int border[kN * kN];
void BFS(int r0, int c0) {
  if (!a[r0][c0]) {
    return;
  }
  ++g_id;
  queue<pair<int, int> > q;
  q.push({r0, c0});
  used[r0][c0] = true;
  vector<pair<int, int> > qq;
  while (!q.empty()) {
    pair<int, int> pr = q.front();
    q.pop();
    qq.push_back(pr);
    int r = pr.first, c = pr.second;
    for (int t = 0; t < 4; ++t) {
      int r_ = r + dr[t];
      int c_ = c + dc[t];
      if (used[r_][c_] || !a[r_][c_]) {
        continue;
      }
      q.push({r_, c_});
      used[r_][c_] = true;
    }
  }
  int cnt = qq.size();
  for (const pair<int, int>& pr : qq) {
    nodes[pr.first][pr.second] = {cnt, g_id};
