inline void shiftRight(int &r, int &c) {
  for (int i = 0; i < k; ++i) {
    cnt[idx[r + i][c]]--;
    cnt[idx[r + i][c + k]]++;
  }
  ++c;
}
inline void shiftLeft(int &r, int &c) {
  for (int i = 0; i < k; ++i) {
    cnt[idx[r + i][c + k - 1]]--;
    cnt[idx[r + i][c - 1]]++;
  }
  --c;
}
inline void shiftDown(int &r, int &c) {
  for (int i = 0; i < k; ++i) {
    cnt[idx[r][c + i]]--;
    cnt[idx[r + k][c + i]]++;
  }
  ++r;
}
inline bool in(int r, int c) { return (r >= 0 && r < n && c >= 0 && c < n); }
inline int add(int &cur, int r, int c) {
  if (r < 0 || c < 0 || r >= n || c >= n) return 0;
  if (u[idx[r][c]]) return 0;
