    ans += add(cur, r - 1, i);
    ans += add(cur, r + k, i);
  }
  for (int i = r; i < r + k; ++i) {
    ans += add(cur, i, c - 1);
    ans += add(cur, i, c + k);
  }
  for (int i = 0; i < cur; ++i) u[tmp[i]] = 0;
