long long n;
bool OnBoard(long long r, long long c) {
  return r >= 1 && r <= n && c >= 1 && c <= n;
}
long long Dfs(long long r, long long c, long long heh) {
  wh_cc[r][c] = heh;
  long long sz = 1;
  for (long long dir = 0; dir < (4); ++dir) {
    long long nr = r + dr[dir];
    long long nc = c + dc[dir];
    if (OnBoard(nr, nc) && wh_cc[nr][nc] == 0 && board[nr][nc] == 1) {
      sz += Dfs(nr, nc, heh);
    }
  }
  return sz;
}
long long cur;
void UpdField(long long r, long long c, long long sign, long long inside) {
  if (!OnBoard(r, c)) {
    return;
  }
  if (board[r][c] == 0) {
    if (inside) {
      cur += sign;
    }
    return;
  }
  long long comp = wh_cc[r][c];
  if (cnt_comp[comp]) {
    cur -= sz_comp[comp];
  }
  cnt_comp[comp] += sign;
  if (cnt_comp[comp]) {
    cur += sz_comp[comp];
  }
}
