const int MAXN = 0;
const int di[4]{-1, 0, 1, 0};
const int dj[4]{0, 1, 0, -1};
const int inf = 1e9;
int N, K;
char a[MAXN][MAXN];
int label[MAXN][MAXN];
int lsize[MAXN * MAXN];
int sum[MAXN][MAXN], in[MAXN][MAXN];
int seen[MAXN * MAXN];
int count(int i, int j) {
  return sum[i + K - 1][j + K - 1] - sum[i - 1][j + K - 1] -
         sum[i + K - 1][j - 1] + sum[i - 1][j - 1];
}
void dfs(int i, int j, int &mini, int &maxi, int &minj, int &maxj,
         int &clabel) {
  lsize[clabel]++;
  label[i][j] = clabel;
  mini = min(mini, i);
  minj = min(minj, j);
  maxi = max(maxi, i);
  maxj = max(maxj, j);
  for (int d = 0; d < 4; d++) {
    int ni = i + di[d], nj = j + dj[d];
    if (ni < 1 || nj < 1 || ni > N || nj > N || a[ni][nj] != '.' ||
        label[ni][nj])
      continue;
    dfs(ni, nj, mini, maxi, minj, maxj, clabel);
  }
}
void add(int &count, int x, int del = 0) {
  if (del) {
    seen[x] = 0;
    return;
  }
  if (seen[x]) return;
  seen[x] = 1;
  count += lsize[x];
}
