      sum[i][j] =
          sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1] + (a[i][j] == '.');
  }
  int clabel = 1;
  for (int i = 1; i <= N; i++) {
    for (int j = 1; j <= N; j++) {
      if (label[i][j] || a[i][j] != '.') continue;
      int mini = inf, maxi = -inf, minj = inf, maxj = -inf;
      dfs(i, j, mini, maxi, minj, maxj, clabel);
      clabel++;
      if (maxi - mini + 1 <= K && maxj - minj + 1 <= K) {
        int i1 = max(maxi - K + 1, 0), i2 = mini;
        int j1 = max(maxj - K + 1, 0), j2 = minj;
        int x = lsize[clabel - 1];
        in[i1][j1] += x;
        in[i2 + 1][j1] -= x;
        in[i1][j2 + 1] -= x;
        in[i2 + 1][j2 + 1] += x;
      }
    }
  }
  for (int i = 0; i <= N; i++) {
    for (int j = 0; j <= N; j++) {
      if (i) in[i][j] += in[i - 1][j];
      if (j) in[i][j] += in[i][j - 1];
      if (i && j) in[i][j] -= in[i - 1][j - 1];
    }
  }
  int ans = 0;
  for (int i = 1; i + K - 1 <= N; i++) {
    for (int j = 1; j + K - 1 <= N; j++) {
      int csize = 0;
      for (int k = 1; k <= K; k++) {
        add(csize, label[i - 1 + k][j - 1]);
        add(csize, label[i + K][j - 1 + k]);
        add(csize, label[i + K - k][j + K]);
        add(csize, label[i - 1][j + K - k]);
      }
      int cur = csize + K * K - count(i, j) + in[i][j];
      ans = max(ans, cur);
