        add(csize, label[i - 1 + k][j - 1], 1);
        add(csize, label[i + K][j - 1 + k], 1);
        add(csize, label[i + K - k][j + K], 1);
        add(csize, label[i - 1][j + K - k], 1);
      }
    }
  }
  printf("%d\n", ans);
}

#include <bits/stdc++.h>
using namespace std;
int N, K;
int A[501][501], C[501][501];
int P[2][4] = {{1, -1, 0, 0}, {0, 0, 1, -1}};
char c;
int D[250001];
pair<int, int> cCell[250001];
int _ccCount = 0;
int G[501][501];
void Find(int i, int j) {
  C[i][j] = _ccCount;
  D[_ccCount] += 1;
  for (int k = 0; k <= 3; ++k) {
    int u = i + P[0][k];
    int v = j + P[1][k];
    if (min(u, v) > 0 && max(u, v) <= N && A[u][v] == 0 && !C[u][v]) Find(u, v);
  }
}
int res = 0;
int T[501][501];
int Times[250001];
int _curTime = 0;
void Init() {
  for (int i = 1; i <= _ccCount; ++i) {
    T[cCell[i].first][cCell[i].second] = D[i];
  }
  for (int i = 1; i <= N; ++i)
    for (int j = 1; j <= N; ++j)
      T[i][j] += T[i - 1][j] + T[i][j - 1] - T[i - 1][j - 1];
}
int Cal(int x1, int y1, int x2, int y2, int r1, int c1) {
  int ccc = C[r1][c1];
  int u = cCell[ccc].first, v = cCell[ccc].second;
  if (x1 <= u && u <= x2 && y1 <= v && v <= y2) return 0;
  if (Times[ccc] >= _curTime) return 0;
  Times[ccc] = _curTime;
  return D[ccc];
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie();
  cout.tie();
  cin >> N >> K;
  for (int i = 1; i <= N; ++i)
    for (int j = 1; j <= N; ++j) {
      cin >> c;
      if (c == '.')
        A[i][j] = 0;
      else
        A[i][j] = 1;
    }
  for (int i = 1; i <= N; ++i)
    for (int j = 1; j <= N; ++j)
      if (A[i][j] == 0 && !C[i][j]) {
        _ccCount += 1;
        cCell[_ccCount] = make_pair(i, j);
        Find(i, j);
      }
  for (int i = 1; i <= N; ++i) {
    for (int j = 1; j <= N; ++j)
      G[i][j] = G[i - 1][j] + G[i][j - 1] - G[i - 1][j - 1] + A[i][j];
  }
  Init();
  for (int i = 1; i <= N - K + 1; ++i)
    for (int j = 1; j <= N - K + 1; ++j) {
      ++_curTime;
      int u = i + K - 1;
      int v = j + K - 1;
      int rr = T[u][v] - T[i - 1][v] - T[u][j - 1] + T[i - 1][j - 1];
      rr =+ G[u][v] - G[i - 1][v] - G[u][j - 1] + G[i - 1][j - 1];
      if (i > 1)
        for (int p = j; p <= v; ++p) rr += Cal(i, j, u, v, i - 1, p);
      if (u < N)
        for (int p = j; p <= v; ++p) rr += Cal(i, j, u, v, u + 1, p);
      if (j > 1)
        for (int q = i; q <= u; ++q) rr += Cal(i, j, u, v, q, j - 1);
      if (v < N)
        for (int q = i; q <= u; ++q) rr += Cal(i, j, u, v, q, v + 1);
      res = max(res, rr);
    }
  cout << res;
  return 0;
}

