      for (auto to : sol) {
        int now = ds[to];
        if (use[now] == 0) use[now] = 1, tmp += ds.siz[now] - cnt[now];
      }
      for (auto to : sol) use[ds[to]] = 0;
      sum[i][fr] = tmp;
      for (int ii = i; ii < i + m; ++ii)
        if (s[ii][fr] == '.') cnt[ds[id[ii][fr]]]--;
      fr++, ba++;
    }
  }
  int ans = 0;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) ans = max(ans, sum[i][j]);
  cout << ans << "\n";
  return 0;
}

