using namespace std;
int N, K;
bool grid[510][510];
int pre[510][510];
int id[510][510];
int ite;
int siz[510 * 510];
int ans;
int mp[510 * 510];
int gained;
bool valid(int x, int y) {
  if (x <= 0 || y <= 0 || x > N || y > N) {
    return false;
  }
  if (!grid[x][y]) {
    return false;
  }
  return true;
}
int rect(int x1, int Y1, int x2, int y2) {
  return pre[x2][y2] - pre[x1 - 1][y2] - pre[x2][Y1 - 1] + pre[x1 - 1][Y1 - 1];
}
void dfs(int x, int y) {
  if (id[x][y]) {
    return;
  }
  id[x][y] = ite;
  if (valid(x - 1, y)) {
    dfs(x - 1, y);
  }
  if (valid(x + 1, y)) {
    dfs(x + 1, y);
  }
  if (valid(x, y - 1)) {
    dfs(x, y - 1);
  }
  if (valid(x, y + 1)) {
    dfs(x, y + 1);
  }
}
void subt(int x) {
  mp[x]--;
  if (mp[x] == 0) {
    gained -= siz[x];
  }
}
void dd(int x) {
  mp[x]++;
  if (mp[x] == 1) {
    gained =+ siz[x];
  }
}
