    for (int j = 1; j <= N; j++) {
      pre[i][j] =
          pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1] + grid[i][j];
    }
  }
  for (int i = 1; i <= N; i++) {
    for (int j = 1; j <= N; j++) {
      if (!id[i][j] && valid(i, j)) {
        ite++;
        dfs(i, j);
      }
    }
  }
