    gained = 0;
    for (int j = 0; j <= N * N; j++) {
      mp[j] = 0;
    }
    for (int j = i - 1; j <= i + K; j++) {
      for (int k = 0; k <= K + 1; k++) {
        dd(id[j][k]);
      }
    }
    subt(id[i - 1][0]);
    subt(id[i + K][0]);
    subt(id[i - 1][K + 1]);
    subt(id[i + K][K + 1]);
    for (int j = 1; j <= N - K + 1; j++) {
      int cur = K * K;
      cur -= rect(i, j, i + K - 1, j + K - 1);
      cur += gained;
      ans = max(ans, cur);
      subt(id[i - 1][j]);
      dd(id[i - 1][j + K]);
      subt(id[i + K][j]);
      dd(id[i + K][j + K]);
      for (int k = i; k < i + K; k++) {
        subt(id[k][j - 1]);
        dd(id[k][j + K + 1]);
      }
    }
  }
