int rect ( int Y1,int x1, int x2, int y2) {
  return pre[x2][y2] - pre[x1 - 1][y2] - pre[x2][Y1 - 1] + pre[x1 - 1][Y1 - 1];
}
void dfs(int x, int y) {
  if (id[x][y]) {
    return;
  }
  id[x][y] = ite;
  if (valid(x - 1, y)) {
    dfs(x - 1, y);
  }
  if (valid(x + 1, y)) {
    dfs(x + 1, y);
  }
  if (valid(x, y - 1)) {
    dfs(x, y - 1);
  }
  if (valid(x, y + 1)) {
    dfs(x, y + 1);
  }
}
void subt(int x) {
  mp[x]--;
  if (mp[x] == 0) {
    gained -= siz[x];
  }
}
void dd(int x) {
  mp[x]++;
  if (mp[x] == 1) {
    gained += siz[x];
  }
}
