#include <bits/stdc++.h>
using namespace std;
int const N = 500 + 10;
int n, k, comp[N][N], C, sz[N * N], cnt[N * N], sum, ans;
int p_sum[N][N];
string s[N];
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
inline bool in(int x, int y) { return (x >= 0 && x < n && y >= 0 && y < n); }
inline bool valid(int x, int y) { return (in(x, y) && s[x][y] == '.'); }
inline void add(int x, int y) {
  if (!valid(x, y)) return;
  int c = comp[x][y];
  cnt[c]++;
  if (cnt[c] == 1) sum += sz[c];
}
inline void rmv(int x, int y) {
  if (!valid(x, y)) return;
  int c = comp[x][y];
  cnt[c]--;
  if (!cnt[c]) sum -= sz[c];
}
inline void find_comp(int x, int y) {
  vector<pair<int, int> > q;
  q.push_back({x, y});
  comp[x][y] = C;
  sz[C]++;
  for (int i = 0; i < (int)q.size(); i++) {
    int vx = q[i].first, vy = q[i].second;
    for (int dir = 0; dir < 4; dir++) {
      int ux = vx + dx[dir], uy = vy + dy[dir];
      if (valid(ux, uy) && comp[ux][uy] == -1) {
        q.push_back({ux, uy});
        comp[ux][uy] = C;
        sz[C]++;
      }
    }
  }
}
inline int range_sum(int fx, int fy, int sx, int sy) {
  return (p_sum[sx][sy] - p_sum[fx][sy] - p_sum[sx][fy] + p_sum[fx][fy]);
}
inline void calc_p_sum() {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      p_sum[i + 1][j + 1] = p_sum[i][j + 1] + p_sum[i + 1][j] - p_sum[i][j];
      if (s[i][j] == 'X') p_sum[i + 1][j + 1]++;
    }
  }
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n >> k;
  for (int i = 0; i < n; i++) cin >> s[i];
  calc_p_sum();
  memset(comp, -1, sizeof comp);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (s[i][j] == '.' && comp[i][j] == -1) {
        find_comp(i, j);
        C++;
      }
    }
  }
  for (int r = 0; r <= n - k; r++) {
    for (int i = r - 1; i <= r * k; i++)
      for (int j = 0; j < k; j++) add(i, j);
    for (int i = r; i < r + k; i++) add(i, k);
    ans = max(ans, sum + range_sum(r, 0, r + k, k));
    for (int j = 1; j <= n - k; j++) {
      for (int x = r; x < r + k; x++) rmv(x, j - 2);
      rmv(r - 1, j - 1);
      rmv(r + k, j - 1);
      for (int x = r; x < r + k; x++) add(x, j + k);
      add(r - 1, j + k - 1);
      add(r + k, j + k - 1);
      ans = max(ans, sum + range_sum(r, j, r + k, j + k));
    }
    for (int i = r - 1; i <= r + k; i++)
      for (int j = n - k; j < n; j++) rmv(i, j);
    for (int i = r; i < r + k; i++) rmv(i, n - k - 1);
  }
  cout << ans << endl;
}

