    addtime[505 * 505];
int temp, temp2;
int n, k;
void bfs(int x, int y) {
  temp2++;
  cc[x][y] = temp;
  vis[x][y] = true;
  if (!vis[x + 1][y] and v[x + 1][y]) bfs(x + 1, y);
  if (!vis[x - 1][y] and v[x - 1][y]) bfs(x - 1, y);
  if (!vis[x][y + 1] and v[x][y + 1]) bfs(x, y + 1);
  if (!vis[x][y - 1] and v[x][y - 1]) bfs(x, y - 1);
}
