    }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (!vis[i + 1][j + 1] && v[i + 1][j + 1]) {
        temp++;
        temp2 = 0;
        bfs(i + 1, j + 1);
        cc_size[temp] = temp2;
      }
    }
  }
  int cur = 1;
  int best_answer = 0;
  for (int y = 1; y <= n - k + 1; y++) {
    for (int i = 1; i < k + 1; i++) {
      for (int j = y; j < y + k; j++) {
        if (v[i][j]) cc_size[cc[i][j]]--;
      }
    }
    for (int i = 1; i < n - k + 2; i++) {
      int answer = k * k;
      for (int j = y; j < y + k; j++) add(i - 1, j, answer, cur);
      for (int j = y; j < y + k; j++) add(i + k, j, answer, cur);
      for (int x = i; x < i + k; x++) add(x, y - 1, answer, cur);
      for (int x = i; x < i + k; x++) add(x, y + k, answer, cur);
      cur++;
      best_answer = max(best_answer, answer);
