        for (int j = y; j < y + k; j++) cc_size[cc[i + k][j]]--;
      if (i != n - k + 1)
        for (int j = y; j < y + k; j++) cc_size[cc[i][j]]++;
    }
    for (int x = n - k + 1; x <= n; ++x)
      for (int j = y; j < y + k; ++j) ++cc_size[cc[x][j]];
  }
