#include <bits/stdc++.h>
using namespace std;
int n, k, grid[505][505], vis[505][505] = {}, comp[505][505] = {};
char x;
int comps = 0, sz[505 * 505] = {}, cnt[505 * 505] = {}, ans = 0;
int main() {
  int di[4] = {0, 1, 0, -1}, dj[4] = {1, 0, -1, 0};
  std::ios::sync_with_stdio(false);
  cin.tie(NULL);
  cin >> n >> k;
  for (int i = 0, _i = (n); i < _i; ++i)
    for (int j = 0, _j = (n); j < _j; ++j) {
      cin >> x;
      grid[i][j] = x == '.';
    }
  for (int i = 0, _i = (n); i < _i; ++i) {
    for (int j = 0, _j = (n); j < _j; ++j) {
      if (!vis[i][j] && grid[i][j]) {
        queue<pair<int, int> > q({make_pair(i, j)});
        comps++;
        while (!q.empty()) {
          int r = q.front().first, c = q.front().second;
          q.pop();
          if (vis[r][c]) continue;
          comp[r][c] = comps;
          sz[comps]++;
          vis[r][c] = 1;
          for (int k = 0, _k = (4); k < _k; ++k) {
            int nr = r + di[k], nc = c + dj[k];
            if ((nr >= 0 && nc >= 0 && nr < n && nc < n) && grid[nr][nc] &&
                !vis[nr][nc]) {
              q.push(make_pair(nr, nc));
            }
          }
        }
      }
    }
  }
  int dp[505][505] = {};
