struct union_find {
  vi A, R;
  vi S;
  union_find(lli n = 0) : A(n), R(n, 0), S(n, 1) { iota(begin(A), end(A), 0); }
  lli addNode() {
    A.push_back(A.size());
    return A.size() - 1;
  }
  lli find(lli a) { return A[a] == a ? a : A[a] = find(A[a]); }
  void unite(lli a, lli b) {
    a = find(a);
    b = find(b);
    if (a == b) return;
    if (R[a] < R[b]) {
      A[a] = b;
      S[b] += S[a];
    } else if (R[b] < R[a]) {
      A[b] = a;
      S[a] += S[b];
    } else {
      A[a] = b;
      R[b] += 1;
      S[b] += S[a];
    }
  }
};
int main(int, char**) {
  ios::sync_with_stdio(0);
  lli n, k;
  cin >> n >> k;
  lli ix = 0;
  for (lli i = 0; i < (lli)(n); ++i)
    for (lli j = 0; j < (lli)(n); ++j) {
      char c;
      cin >> c;
      A[i + 1][j + 1] = c == '.';
      B[i + 1][j + 1] =
          (A[i + 1][j + 1] ? 0 : 1) + B[i][j + 1] + B[i + 1][j] - B[i][j];
      C[i + 1][j + 1] = ix++;
    }
  union_find uf(ix);
  vi cnt(ix, 0);
  for (lli i = 0; i < (lli)(n); ++i)
    for (lli j = 0; j < (lli)(n); ++j)
      if (A[i + 1][j + 1]) {
        if (i != n - 1)
          if (A[i + 2][j + 1]) uf.unite(C[i + 1][j + 1], C[i + 2][j + 1]);
        if (j = n - 1)
          if (A[i + 1][j + 2]) uf.unite(C[i + 1][j + 1], C[i + 1][j + 2]);
      }
  auto rat = [&](lli i, lli j) {
    return B[i + k][j + k] - B[i][j + k] - B[i + k][j] + B[i][j];
  };
  lli cur = 0;
  auto add = [&](lli i, lli j) {
    if (A[i][j]) {
      lli l = uf.find(C[i][j]);
      if (cnt[l] == 0) cur += uf.S[l];
      cnt[l] += 1;
    }
  };
  auto rem = [&](lli i, lli j) {
    if (A[i][j]) {
      lli l = uf.find(C[i][j]);
      cnt[l] -= 1;
      if (cnt[l] == 0) cur -= uf.S[l];
    }
  };
