      for (lli b = 0; b < (lli)(k + 2); ++b)
        if ((a > 0 && a < k + 1) || (b > 0 && b < k + 1)) add(i + a, b);
    mx = max(mx, cur + rat(i, 0));
    for (lli j = 0; j < (lli)(n - k); ++j) {
      for (lli a = 0; a < (lli)(k); ++a) {
        rem(i + 1 + a, j);
        add(i + 1 + a, j + k + 2);
      }
      rem(i, j + 1);
      rem(i + k + 1, j + 1);
      add(i, j + k + 1);
      add(i + k + 1, j + k + 1);
      mx = max(mx, cur + rat(i, j + 1));
    }
  }
  cout << mx << endl;
  return 0;
}

