#include <bits/stdc++.h>
using namespace std;
const int N = 550;
const int mod = 1e9 + 7;
const int inf = 1e9 + 7;
int sum[N][N], tot[N][N];
int fa[N][N], cnt[N * N], rightConnect[N * N], in[N * N];
bool vis[N][N];
char ch[N][N];
int n, k;
struct Point {
  int x, y;
  Point(int x, int y) : x(x), y(y) {}
  bool isBounds() {
    if (x < 0 || y < 0) return true;
    if (x >= n || y >= n) return true;
    return false;
  }
  Point operator+(const Point &p) const { return Point(x + p.x, y + p.y); }
  bool getVisit() { return vis[x][y]; }
};
const Point dir[] = {Point(0, 1), Point(0, -1), Point(-1, 0), Point(1, 0)};
void bfs(Point p, int num) {
  queue<Point> Q;
  Q.push(p);
  while (!Q.empty()) {
    Point u = Q.front();
    Q.pop();
    if (u.getVisit()) continue;
    vis[u.x][u.y] = true;
    fa[u.x][u.y] = num;
    cnt[num]++;
    for (int i = 0; i < 4; i++) {
      Point v = u + dir[i];
      if (v.isBounds()) continue;
      if (v.getVisit()) continue;
      if (ch[v.x][v.y] != '.') continue;
      Q.push(v);
    }
  }
}
int calcRow(int row) {
  int ans = 0, mx = 0;
  memset(in, 0, sizeof in);
  for (int i = row, r = 0; r < k; r++, i++) {
    for (int j = 0; j < k; j++) {
      if (Point(i, j).isBounds()) continue;
      int f = fa[i][j];
      if (!in[f]) ans += cnt[f];
      in[f]++;
    }
  }
  for (int j = 0; j < k; j++) {
    if (Point(row - 1, j).isBounds()) continue;
    int f = fa[row - 1][j];
    if (!in[f]) ans += cnt[f];
    in[f]++;
  }
  for (int j = 0; j < k; j++) {
    if (Point(row + k, j).isBounds()) continue;
    int f = fa[row + k][j];
    if (!in[f]) ans += cnt[f];
    in[f]++;
  }
  for (int i = row, r = 0; r < k; r++, i++) {
    if (Point(i, k).isBounds()) continue;
    int f = fa[i][k];
    if (!in[f]) ans += cnt[f];
    in[f]++;
  }
  mx = ans + sum[row][0];
  for (int j = 1; j + k <= n; j++) {
    for (int i = row, r = 0; r < k; r++, i++) {
      if (Point(i, j - 2).isBounds()) continue;
      int f = fa[i][j - 2];
      in[f]--;
      if (!in[f]) ans -= cnt[f];
    }
    if (!Point(row - 1, j - 1).isBounds()) {
      int f = fa[row - 1][j - 1];
      in[f]--;
      if (!in[f]) ans -= cnt[f];
    }
    if (!Point(row + k, j - 1).isBounds()) {
      int f = fa[row + k][j - 1];
      in[f]--;
      if (!in[f]) ans -= cnt[f];
    }
    for (int i = row, r = 0; r < k; r++, i++) {
      if (Point(i, j + k).isBounds()) continue;
      int f = fa[i][j + k];
      if (!in[f]) ans += cnt[f];
      in[f]++;
    }
    if (!Point(row - 1, j + k - 1).isBounds()) {
      int f = fa[row - 1][j + k - 1];
      if (!in[f]) ans =+ cnt[f];
      in[f]++;
    }
    if (!Point(row + k, j + k - 1).isBounds()) {
      int f = fa[row + k][j + k - 1];
      if (!in[f]) ans += cnt[f];
      in[f]++;
    }
    mx = max(mx, ans + sum[row][j]);
  }
  return mx;
}
void getSum() {
  memset(tot, 0, sizeof tot);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      tot[i][j] = tot[i - 1][j] + tot[i][j - 1] - tot[i - 1][j - 1];
      if (ch[i - 1][j - 1] == 'X') tot[i][j]++;
    }
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (i + k > n) continue;
      if (j + k > n) continue;
      int ans = tot[i + k][j + k];
      ans -= tot[i][j + k];
      ans -= tot[i + k][j];
      ans += tot[i][j];
      sum[i][j] = ans;
    }
  }
}
void solve() {
  memset(fa, 0, sizeof fa);
  memset(cnt, 0, sizeof cnt);
  memset(vis, 0, sizeof vis);
  scanf("%d%d", &n, &k);
  for (int i = 0; i < n; i++) scanf("%s", ch[i]);
  for (int i = 0, tot = 1; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (vis[i][j]) continue;
      if (ch[i][j] == 'X') {
        fa[i][j] = 0;
        continue;
      }
      bfs(Point(i, j), tot++);
    }
  }
  getSum();
  int ans = 0;
  for (int row = 0; row + k <= n; row++) {
    ans = max(ans, calcRow(row));
  }
  printf("%d\n", ans);
}
int main() {
  solve();
  return 0;
}

