  solve();
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int maxn = 0;
int c[maxn][maxn], s[maxn * maxn];
int a[maxn][maxn], n, m;
int g[maxn][maxn];
int dx[4] = {-1, 0, 1, 0}, dy[4] = {0, 1, 0, -1};
int sum[maxn * maxn];
char str[maxn];
void init() {
  cin >> n >> m;
  int i, j;
  for (i = 1; i <= n; i++) {
    cin >> str;
    for (j = 1; j <= n; j++) {
      if (str[j - 1] == '.')
        a[i][j] = 1;
      else
        a[i][j] = 0;
      g[i][j] = g[i][j - 1] + g[i - 1][j] - g[i - 1][j - 1] + a[i][j];
    }
  }
}
void dfs(int x, int y, int col) {
  if (x < 1 || x > n || y < 1 || y > n) return;
  if (c[x][y] != 0 || a[x][y] == 0) return;
  c[x][y] = col;
  ++s[col];
  int i;
  for (i = 0; i < 4; i++) dfs(x + dx[i], y + dy[i], col);
}
int now;
void ins(int x, int y) {
  ++sum[c[x][y]];
  if (sum[c[x][y]] == 1) now += s[c[x][y]];
}
void del(int x, int y) {
  --sum[c[x][y]];
  if (sum[c[x][y]] == 0) now -= s[c[x][y]];
}
void insert1(int x, int y) {
  int i;
  for (i = x + 1; i >= x - m; i--) {
    if (a[i][y] == 0) continue;
    ins(i, y);
  }
}
void delete1(int x, int y) {
  int i;
  for (i = x + 1; i >= x - m; i--) {
    if (a[i][y] == 0) continue;
    del(i, y);
  }
}
void insert2(int x, int y) {
  ins(x, y);
  ins(x - m - 1, y);
  ins(x, y - m - 1);
  ins(x - m - 1, y - m - 1);
}
void delete2(int x, int y) {
  del(x, y);
  del(x - m - 1, y);
  del(x, y - m - 1);
  del(x - m - 1, y - m - 1);
}
int calc(int x, int y) {
  return g[x][y] - g[x - m][y] - g[x][y - m] + g[x - m][y - m];
}
void work() {
  int i, j, k, l;
  int cnt = 0;
  int ans = 0;
  for (i = 1; i <= n; i++) {
    for (j = 1; j <= n; j++) {
      if (c[i][j]) continue;
      if (a[i][j] == 0) continue;
      ++cnt;
      dfs(i, j, cnt);
    }
  }
  for (i = m; i <= n; i++) {
    memset(sum, 0, sizeof(sum));
    now = 0;
    for (k = 1; k <= m; k++) insert1(i, k);
    for (j = m; j <= n; j++) {
      insert1(i, j + 1);
      if (j != m) delete1(i, j - m - 1);
      delete2(i + 1, j + 1);
      l = now - calc(i, j) + m * m;
      if (l > ans) ans = l;
      insert2(i + 1, j + 1);
    }
  }
  cout << ans << endl;
}
int main(void) {
  init();
  work();
  return 0;
}

