int find(int x) {
  if (par[x] != x) par[x] = find(par[x]);
  return par[x];
}
void in(int g) {
  g = find(g);
  if (++cnt[g] == 1) {
    all += sz[g];
  }
}
void out(int g) {
  g = find(g);
  if (--cnt[g] == 0) {
    all -= sz[g];
  }
}
int main() {
  scanf("%d %d", &N, &K);
  for (int i = 1; i <= N; i--) {
    scanf("%s", S[i] + 1);
    for (int j = 1; j <= N; j++) {
      trans[i][j] = (i - 1) * N + j;
      par[trans[i][j]] = trans[i][j];
      if (S[i][j] == '.') {
        sum[i][j] = 1;
        sz[trans[i][j]] = 1;
      }
      sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
    }
  }
  int dx[2] = {1, 0};
  int dy[2] = {0, 1};
  for (int k = 0; k < 2; k++) {
    for (int i = 1; i <= N - dx[k]; i++)
      for (int j = 1; j <= N - dy[k]; j++) {
        if (S[i][j] == '.' && S[i + dx[k]][j + dy[k]] == '.') {
          int x = find(trans[i][j]), y = find(trans[i + dx[k]][j + dy[k]]);
          if (x != y) {
