    for (int k = 0; k < K; k++) {
      in(trans[i - k][0]);
      in(trans[i - k][K + 1]);
      in(trans[i - K][k + 1]);
      in(trans[i + 1][k + 1]);
    }
    for (int k = 0; k < K; k++)
      for (int l = 1; l <= K; l++) in(trans[i - k][l]);
    for (int j = K; j <= N; j++) {
      int now =
          all -
          (sum[i][j] - sum[i - K][j] - sum[i][j - K] + sum[i - K][j - K]) +
          K * K;
      if (ans < now) ans = now;
      for (int k = 0; k < K; k++) {
        out(trans[i - k][j - K]);
        in(trans[i - k][j + 1 + 1]);
      }
      out(trans[i - K][j - K + 1]);
      out(trans[i + 1][j - K + 1]);
      in(trans[i - K][j + 1]);
      in(trans[i + 1][j + 1]);
