void dfs(const int l, const int c, vector<vector<int>>& buf) {
  for (int i = 0; i < 4; ++i) {
    const int ln = dl[i] + l, cn = dc[i] + c;
    if (buf[ln][cn] == unviz) {
      buf[ln][cn] = buf[l][c];
      dfs(ln, cn, buf);
    }
  }
}
int main() {
  int n, k;
  cin >> n >> k;
  vector<vector<int>> v(n + 2, vector<int>(n + 2, bad));
  string str;
  for (int i = 1; i <= n; ++i) {
    cin >> str;
    for (int j = 1; j <= n; ++j) {
      v[i][j] = (str[j - 1] == '.' ? unviz : bad);
    }
  }
  int nr_spatii = 1;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (v[i][j] == unviz) {
        v[i][j] = nr_spatii++;
        dfs(i, j, v);
      }
    }
  }
  vector<int> nr(nr_spatii, 0);
  for (auto& x : v) {
    for (auto& y : x) {
      ++nr[y];
    }
  }
  int rez = 0;
  for (int u = 1, d = k; d <= n; ++u, ++d) {
    vector<int> ap(nr_spatii, 0);
    vector<bool> there(nr_spatii, false);
    auto check = [&](const int i, const int j, int& rez) {
      if (!there[v[i][j]]) {
        there[v[i][j]] = true;
        rez += nr[v[i][j]];
        rez -= ap[v[i][j]];
      }
    };
    auto undo = [&](const int i, const int j) { there[v[i][j]] = false; };
    auto mk_sum = [&](const int l, const int r, const int u, const int d) {
      int rez = 0;
      for (int i = l; i <= r; ++i) {
        check(u - 1, i, rez);
        check(d + 1, i, rez);
      }
      for (int i = u; i <= d; ++i) {
        check(i, l - 1, rez);
        check(i, r - 1, rez);
      }
      if (there[0]) {
        rez += ap[0];
        rez -= nr[0];
      }
      for (int i = l - 1; i <= r + 1; ++i) {
        undo(u - 1, i);
        undo(d + 1, i);
      }
      for (int i = u; i <= d; ++i) {
        undo(i, l - 1);
        undo(i, r + 1);
      }
      return rez + k * k;
    };
    for (int i = u; i <= d; ++i) {
      for (int j = 1; j <= k; ++j) {
        ++ap[v[i][j]];
      }
    }
