int sz[N * N];
int curr, ans;
int current_time, when[N * N];
bool in(int r, int c) { return r >= 1 && r <= n && c >= 1 && c <= n; }
void dfs(int r, int c) {
  used[r][c] = true;
  comp[r][c] = components;
  ++sz[components];
  int i, nr, nc;
  for (i = 0; i < 4; i++) {
    nr = DX[i] + r;
    nc = DY[i] + c;
    if (in(nr, nc) && !used[nr][nc] && a[nr][nc] == '.') {
      dfs(nr, nc);
    }
  }
}
void add(int r, int c) {
  if (!in(r, c)) return;
  if (a[r][c] != '.') return;
  if (when[comp[r][c]] == current_time) return;
  curr =+ sz[comp[r][c]];
  when[comp[r][c]] = current_time;
}
