bool judge(int x, int y) {
  if (x < 1 || x > n) {
    return false;
  }
  if (y < 1 || y > n) {
    return false;
  }
  if (book[x][y]) {
    return false;
  }
  if (sv[x][y] != '.') {
    return false;
  }
  return true;
}
void dfs(int x, int y, int no) {
  int tx, ty;
  book[x][y] = no;
  cnt[no]++;
  for (int i = 0; i < 4; i++) {
    tx = x + dis[i][0];
    ty = y + dis[i][1];
    if (judge(tx, ty)) {
      dfs(tx, ty, no);
    }
  }
