      }
    }
  }
}
void up2(int x, int y, int t) {
  for (int i = x; i <= x + k - 1; i++) {
    if (book[i][y]) {
      cnt[book[i][y]] += t;
    }
  }
}
stack<int> st;
int cal(int x, int y) {
  int ret = 0;
  for (int j = y; j <= y + k - 1; j++) {
    if (book[x - 1][j] && !vis[book[x - 1][j]]) {
      st.push(book[x - 1][j]);
      vis[book[x - 1][j]] = true;
      ret += cnt[book[x - 1][j]];
    }
  }
  for (int j = y; j <= y + k - 1; j++) {
    if (book[x + k][j] && !vis[book[x + k][j]]) {
      st.push(book[x + k][j]);
      vis[book[x + k][j]] = true;
      ret += cnt[book[x + k][j]];
    }
  }
  for (int i = x; i <= x + k - 1; i++) {
    if (book[i][y - 1] && !vis[book[i][y - 1]]) {
      st.push(book[i][y - 1]);
      vis[book[i][y - 1]] = true;
      ret += cnt[book[i][y - 1]];
    }
  }
  for (int i = x; i <= x + k - 1; i++) {
    if (book[i][y + k] && !vis[book[i][y + k]]) {
      st.push(book[i][y + k]);
      vis[book[i][y + k]] = true;
      ret += cnt[book[i][y + k]];
    }
  }
  while (!st.empty()) {
    int t = st.top();
    st.pop();
    vis[t] = false;
  }
  return ret;
}
