                (second[i - 1][j - 1] == '.');
      if (i >= k && j >= k)
        e[i][j] = d[i][j] - d[i - k][j] - d[i][j - k] + d[i - k][j - k];
    }
  for (int i = k; i <= n; ++i) {
    for (int j = 1; j <= k; ++j) add(i - k, j), add(i + 1, j);
    for (int r = i - k + 1; r <= i; ++r)
      for (int c = 0; c <= k + 1; ++c) add(r, c);
    for (int j = k; j <= n; ++j) {
      ans = max(ans, cur - e[i][j] + k * k);
