      del(i + 1, j - k + 1), add(i + 1, j + 1);
      for (int l = i - k + 1; l <= i; ++l) del(l, j - k), add(l, j + 2);
    }
    memset(dis, 0, sizeof dis), cur = 0;
  }
  cout << ans;
  return 0;
}

