  for (int i = 1; i <= N; i++)
    for (int j = 1; j <= N; j++)
      sum[i][j] = sum[i][j - 1] + sum[i - 1][j] - sum[i - 1][j - 1] + !ok(i, j);
  int curr = 0;
  for (int i = 1; i <= N; i++)
    for (int j = 1; j <= N; j++)
