      sol = max(sol, tot + get(i, j));
      for (int k = 0; k < K; k++) {
        rem(comp[i + k][j - 1]);
        add(comp[i + k][j + K + 1]);
      }
      rem(comp[i - 1][j]);
      rem(comp[i + K][j]);
      add(comp[i - 1][j + K]);
      add(comp[i + K][j + K]);
    }
  }
  return sol;
}
