    n = nn;
    par.resize(n);
    h.resize(n);
    sz.resize(n);
    for (int i = 0; i < n; i++) par[i] = i, h[i] = 0, sz[i] = 1;
  }
  int find(int x) { return (x == par[x] ? x : par[x] = find(par[x])); }
  void merge(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (h[x] == h[y]) {
      par[y] = x;
      h[x]++;
      sz[x] += sz[y];
    } else {
      if (h[x] < h[y]) swap(x, y);
      par[y] = x;
      sz[x] += sz[y];
    }
  }
  Dsu& operator=(const Dsu& b) {
    n = b.n;
    par = b.par;
    h = b.h;
    sz = b.sz;
    return *this;
  }
};
