struct Rect {
  int x1, x2;
  int y1, y2;
  Rect() : x1(0), x2(0), y1(0), y2(0) {}
  Rect(int x1_, int x2_, int y1_, int y2_)
      : x1(x1_), x2(x2_), y1(y1_), y2(y2_) {}
};
inline bool isSubset(const Rect &a, const Rect &b) {
  return b.x1 <= a.x1 && a.x2 <= b.x2 && b.y1 <= a.y1 && a.y2 <= b.y2;
}
inline bool isDisjoint(const Rect &a, const Rect &b) {
  return a.x2 <= b.x1 || b.x2 <= a.x1 || a.y2 <= b.y1 || b.y2 <= a.y1;
}
Rect getChild(const Rect &a, int number) {
  int x_size = (a.x2 - a.x1) / 2;
  int y_size = (a.y2 - a.y1) / 2;
  Rect result;
  result.x1 = (number % 2 == 0) ? a.x1 : (a.x1 + x_size);
  result.x2 = result.x1 + x_size;
  result.y1 = (number < 2) ? a.y1 : (a.y1 + y_size);
  result.y2 = result.y1 + y_size;
  return result;
}
int qtree[((1 << 20) - 1) / 3];
Rect qroot(0, 1 << 9, 0, 1 << 9);
int quadGetIn(int x, int y, int index, const Rect &r) {
  if (r.x2 - r.x1 == 1) {
    return qtree[index];
  }
  int x_mid = (r.x1 + r.x2) / 2;
  int y_mid = (r.y1 + r.y2) / 2;
  int child = (y >= y_mid ? 2 : 0) + (x >= x_mid ? 1 : 0);
  return qtree[index] +
         quadGetIn(x, y, 4 * index * 1 + child, getChild(r, child));
}
int quadGet(int x, int y) { return quadGetIn(x, y, 0, qroot); }
void quadAddIn(const Rect &zone, int val, int index, const Rect &r) {
  if (isSubset(r, zone)) {
    qtree[index] += val;
  } else {
    int mid_x = (r.x1 + r.x2) / 2;
    int mid_y = (r.y1 + r.y2) / 2;
    if (zone.x1 < mid_x) {
      if (zone.y1 < mid_y) {
        quadAddIn(zone, val, 4 * index + 1, Rect(r.x1, mid_x, r.y1, mid_y));
      }
      if (zone.y2 > mid_y) {
        quadAddIn(zone, val, 4 * index + 3, Rect(r.x1, mid_x, mid_y, r.y2));
      }
    }
    if (zone.x2 > mid_x) {
      if (zone.y1 < mid_y) {
        quadAddIn(zone, val, 4 * index + 2, Rect(mid_x, r.x2, r.y1, mid_y));
      }
      if (zone.y2 > mid_y) {
        quadAddIn(zone, val, 4 * index + 4, Rect(mid_x, r.x2, mid_y, r.y2));
      }
    }
  }
}
void quadAdd(const Rect &zone, int val) { quadAddIn(zone, val, 0, qroot); }
