  int y_mid = (r.y1 + r.y2) / 2;
  int child = (y >= y_mid ? 2 : 0) + (x >= x_mid ? 1 : 0);
  return qtree[index] +
         quadGetIn(x, y, 4 * index + 1 + child, getChild(r, child));
}
