                        vector<int>& components) {
  size_t n = components_belonging.size();
  int last_comp = 1;
  int cur_comp_size = 0;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      if ((components_belonging[i][j] == 0) && (m[i][j] == '.')) {
        stack<coords> st;
