          st.pop();
          if (components_belonging[curr.first][curr.second] == 0) {
            components_belonging[curr.first][curr.second] = last_comp;
            cur_comp_size++;
            add_neighbours(curr, st, n - 1, m, components_belonging);
          }
        }
        components[last_comp] = cur_comp_size;
