inline void add_neighbours(coords& c, stack<coords>& st, int max,
                           vector<string>& mapa,
                           vector<vector<int> >& components_belonging) {
  if ((c.first != 0) && (mapa[c.first - 1][c.second] == '.') &&
      (components_belonging[c.first - 1][c.second] == 0))
    st.push(make_pair(c.first - 1, c.second));
  if ((c.second != 0) && (mapa[c.first][c.second - 1] == '.') &&
      (components_belonging[c.first][c.second - 1] == 0))
    st.push(make_pair(c.first, c.second - 1));
  if ((c.second != max) && (mapa[c.first][c.second + 1] == '.') &&
      (components_belonging[c.first][c.second + 1] == 0))
    st.push(make_pair(c.first, c.second + 1));
  if ((c.first != max) && (mapa[c.first + 1][c.second] == '.') &&
      (components_belonging[c.first + 1][c.second] == 0))
    st.push(make_pair(c.first + 1, c.second));
