void collect_components(vector<string>& m,
                        vector<vector<int> >& components_belonging,
                        vector<int>& components) {
  size_t n = components_belonging.size();
  int last_comp = 1;
  int cur_comp_size = 0;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      if ((components_belonging[i][j] == 0) && (m[i][j] == '.')) {
        stack<coords> st;
        st.push(make_pair(i, j));
        while (!st.empty()) {
          coords curr = st.top();
          st.pop();
          if (components_belonging[curr.first][curr.second] == 0) {
            components_belonging[curr.first][curr.second] = last_comp;
            cur_comp_size++;
            add_neighbours(curr, st, n - 1, m, components_belonging);
          }
        }
        components[last_comp] = cur_comp_size;
        last_comp++;
        cur_comp_size = 0;
      }
    }
}
