    cells_add -= right * update_x(maze, ii, j, down);
  }
  auto elements = {i - 1, ik};
  for (auto ii = elements.begin(); ii != elements.end(); ++ii) {
    if (*ii >= 0 && *ii < maze.size()) {
      if (jk < maze.size()) {
        cells_add += update(components, markers, state, *ii, jk, down, right);
      }
      if (j >= 0) {
        cells_add += update(components, markers, state, *ii, j, down, -right);
      }
    }
  }
  return cells_add;
}
int find_max(std::vector<std::vector<char>>& maze,
             std::vector<std::vector<int>>& components,
             std::vector<int>& markers, int k) {
  auto state = std::vector<int>(markers.size(), 0);
  int current_value = 0;
  auto inside_indices = get_inside(0, 0, k);
  for (auto it = inside_indices.begin(); it != inside_indices.end(); ++it) {
    current_value += update_x(maze, it->first, it->second, false);
  }
  auto perimeter_indices = get_outer_square(0, 0, k);
  for (auto it = perimeter_indices.begin(); it != perimeter_indices.end();
       ++it) {
    int ii = it->first;
    int jj = it->second;
    if (ii >= 0 && ii < maze.size()) {
      if (jj >= 0 && jj < maze.size()) {
        current_value += update(components, markers, state, ii, jj, false, 1);
      }
    }
  }
  int flag = -1;
  int max_values = current_value;
  int ii;
  int jj;
  for (int i = 0; i < maze.size() - k + 1; ++i) {
    for (int j = 0; j < maze.size() - k; ++j) {
      if (flag == 1) {
        ii = i;
        jj = int(maze.size() - j - k - 1);
      } else {
        ii = i;
        jj = j;
      }
      current_value += fill_components(maze, components, markers, state, ii, jj,
                                       k, false, -flag);
      max_values = max(max_values, current_value);
    }
    if (i != maze.size() - k) {
      if (flag == 1) {
        ii = 0;
        jj = i;
      } else {
        ii = int(maze.size() - k);
        jj = i;
      }
      current_value +=
          fill_components(maze, components, markers, state, ii, jj, k, true, 1);
      flag = -flag;
      max_values = max(max_values, current_value);
    }
  }
  return max_values;
}
