  std::vector<std::vector<char>> maze(n, std::vector<char>(n));
  for (int i = 0; i < n; ++i) {
    std::getline(std::cin, line);
    for (int j = 0; j < line.size(); ++j) {
      maze[i][j] = line[j];
    }
  }
