      }
    }
  }
  if (CC > 250 * 500) {
    cout << CC << endl;
    return 0;
  }
  int b = 0;
  for (int i = 0; i + K - 1 < N; ++i) {
    int j = 0;
    Window W(K, i, j);
    b = max(b, W.getSize());
    while ((j + 1) + K - 1 < N) {
      j++;
      W.moveLeft();
      b = max(b, W.getSize());
    }
  }
  cout << b << endl;
}

