    for (int j = 0; j < N; j++) {
      cnt[i][j] = g[i][j] == 'X';
      if (i) cnt[i][j] += cnt[i - 1][j];
      if (j) cnt[i][j] += cnt[i][j - 1];
      if (i && j) cnt[i][j] -= cnt[i - 1][j - 1];
    }
  }
  int res = 0;
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (!val(i, j)) continue;
      for (int k = 0; k < 4; k++) {
        if (val(i + dx[k], j + dy[k])) {
          DSU.mrg(i * N + j, (i + dx[k]) * N + j + dy[k]);
        }
      }
      res = max(res, DSU.siz(i * N + j));
    }
  }
  for (int i = 0; i + K <= N; i++) {
    queue<pair<int, int> > comps;
    int cur = 0;
    for (int c = -1; c <= K; c++) {
      for (int r = -1; r <= K; r++) {
        if (!val(i + r, c)) continue;
