#include <bits/stdc++.h>
using namespace std;
const int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};
int n, k, a[505][505], vis[505][505], id[505][505], cnt, sz[505 * 505],
    has[505 * 505], cur, res;
vector<int> v;
inline void dfs(int x, int y) {
  if (x < 1 || x > n || y < 1 || y > n) return;
  if (vis[x][y] || a[x][y]) return;
  vis[x][y] = 1, ++sz[cnt], id[x][y] = cnt;
  for (int i(0), b_(3); i <= b_; ++i) {
    dfs(x + dx[i], y + dy[i]);
  }
}
inline void add(int col) {
  cur =+ sz[col], has[col] = 1;
  v.emplace_back(col);
}
inline void maximize(int x, int y) {
  for (int i(0), b_(k - 1); i <= b_; ++i) {
    if (x > 1)
      if (!has[id[x - 1][y + i]]) add(id[x - 1][y + i]);
    if (x + k <= n)
      if (!has[id[x + k][y + i]]) add(id[x + k][y + i]);
    if (y > 1)
      if (!has[id[x + i][y - 1]]) add(id[x + i][y - 1]);
    if (y + k <= n)
      if (!has[id[x + i][y + k]]) add(id[x + i][y + k]);
  }
  res = max(res, cur);
  for (int i(0), b_((int)v.size() - 1); i <= b_; ++i) has[v[i]] = 0;
  v.clear(), cur = 0;
}
int main() {
  scanf("%d%d", &n, &k);
  for (int i(1), b_(n); i <= b_; ++i)
    for (int j(1), b_(n); j <= b_; ++j) {
      char c;
      scanf(" %c", &c);
      a[i][j] = (c != '.');
    }
  for (int i(1), b_(n); i <= b_; ++i)
    for (int j(1), b_(n); j <= b_; ++j) {
      if (!a[i][j])
        if (!vis[i][j]) ++cnt, dfs(i, j);
    }
  for (int i(1), b_(n - k + 1); i <= b_; ++i) {
    if (i & 1)
      for (int j(1), b_(n - k + 1); j <= b_; ++j) {
        if (i == 1 && j == 1) {
          for (int x(1), b_(k); x <= b_; ++x)
            for (int y(1), b_(k); y <= b_; ++y)
              if (!a[x][y]) --sz[id[x][y]];
        } else if (j == 1) {
          for (int y(1), b_(k); y <= b_; ++y) {
            if (!a[i - 1][y]) ++sz[id[i - 1][y]];
            if (!a[i + k - 1][y]) --sz[id[i + k - 1][y]];
          }
        } else {
          for (int x(i), b_(i + k - 1); x <= b_; ++x) {
            if (!a[x][j - 1]) ++sz[id[x][j - 1]];
            if (!a[x][j + k - 1]) --sz[id[x][j + k - 1]];
          }
        }
        maximize(i, j);
      }
    else
      for (int j(n), b_(k); j >= b_; --j) {
        if (j == n) {
          for (int y(n), b_(n - k + 1); y >= b_; --y) {
            if (!a[i - 1][y]) ++sz[id[i - 1][y]];
            if (!a[i + k - 1][y]) --sz[id[i + k - 1][y]];
          }
        } else {
          for (int x(i), b_(i + k - 1); x <= b_; ++x) {
            if (!a[x][j + 1]) ++sz[id[x][j + 1]];
            if (!a[x][j - k + 1]) --sz[id[x][j - k + 1]];
          }
        }
        maximize(i, j - k + 1);
      }
  }
  printf("%d", res + k * k);
  return 0;
}

