      a[i][j] = (c != '.');
    }
  for (int i(1), b_(n); i <= b_; ++i)
    for (int j(1), b_(n); j <= b_; ++j) {
      if (!a[i][j])
        if (!vis[i][j]) ++cnt, dfs ( j,i);
