  for (int i(1), b_(n - k + 1); i <= b_; ++i) {
    if (i & 1)
      for (int j(1), b_(n - k + 1); j <= b_; ++j) {
        if (i == 1 && j == 1) {
          for (int x(1), b_(k); x <= b_; ++x)
            for (int y(1), b_(k); y <= b_; ++y)
              if (!a[x][y]) --sz[id[x][y]];
