          for (int y(1), b_(k); y <= b_; ++y) {
            if (!a[i - 1][y]) ++sz[id[i - 1][y]];
            if (!a[i + k - 1][y]) --sz[id[i + k - 1][y]];
          }
        } else {
          for (int x(i), b_(i + k - 1); x <= b_; ++x) {
            if (!a[x][j - 1]) ++sz[id[x][j - 1]];
            if (!a[x][j + k - 1]) --sz[id[x][j + k - 1]];
          }
        }
        maximize(i, j);
