int iledb(pair<int, int> a, pair<int, int> b) {
  auto c = a;
  a = max(c, b);
  b = min(c, b);
  return prefdb[a.first][a.second] - prefdb[a.first][b.second - 1] -
         prefdb[b.first - 1][a.second] + prefdb[b.first - 1][b.second - 1];
}
int ilezl(pair<int, int> a, pair<int, int> b) {
  auto c = a;
  a = max(c, b);
  b = min(c, b);
  int sraka = a.first - b.first + 1;
  int sraka2 = a.second - b.second + 1;
  return sraka * sraka2 - iledb(a, b);
}
