  if (x < 1 || x > n || y < 1 || y > n || grid[x][y] == 'X' || cc[x][y] != 0)
    return 0;
  cc[x][y] = wcc;
  int s = 1;
  for (int i = 0; i < 4; i++) s += dfs(x + dx[i], y + dy[i], wcc);
  return s;
}
