  if (x < 1 || x > n || y < 1 || y > n || grid[x][y] == 'X' ||
      when[cc[x][y]] == T)
    return 0;
  when[cc[x][y]] = T;
  return sz[cc[x][y]];
}
void answer() {
  int x, y, cur, i, j, ans = k * k;
  T = 1;
  for (i = 1; i <= n - k + 1; i++) {
    for (x = i; x <= i + k - 1; x++)
      for (y = 1; y <= k; y++)
        if (grid[x][y] == '.') sz[cc[x][y]]--;
