#include <bits/stdc++.h>
using namespace std;
const int dirs = (4-1);
int dx[] = {-1, 0, 1, 0};
int dy[] = {0, -1, 0, 1};
void dfs(int x, int y, int n, const vector<string> &grid,
         vector<pair<int, int>> &pts, vector<vector<int>> &used) {
  if (x < 0 || x >= n || y < 0 || y >= n || used[x][y] || grid[x][y] == 'X')
    return;
  pts.push_back(make_pair(x, y));
  used[x][y] = 1;
  for (int d = 0; d < dirs; d++) dfs(x + dx[d], y + dy[d], n, grid, pts, used);
}
void solve(int n) {
  int k;
  cin >> k;
  vector<string> grid(n);
  for (int i = 0; i < n; i++) cin >> grid[i];
  vector<vector<int>> comp_num(n, vector<int>(n, -1));
  vector<int> comp_sz;
  vector<vector<int>> used(n, vector<int>(n, 0));
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      if (!used[i][j] && grid[i][j] != 'X') {
        vector<pair<int, int>> pts;
        dfs(i, j, n, grid, pts, used);
        for (auto x : pts) comp_num[x.first][x.second] = (int)(comp_sz).size();
        comp_sz.push_back((int)(pts).size());
      }
  const int error = -1;
  vector<int> cnt_comp((int)(comp_sz).size(), 0);
  auto get_comp_num = [&](int i, int j) -> int {
    if (i < 0 || j < 0 || i >= n || j >= n || grid[i][j] == 'X') return error;
    return comp_num[i][j];
  };
  int cur_count = 0;
  auto account = [&](int i, int j, int side) -> void {
    int num = get_comp_num(i, j);
    if (num == error) return;
    if (side == +1) {
      if (cnt_comp[num] == 0) cur_count += comp_sz[num];
      cnt_comp[num]++;
    } else {
      assert(side == -1);
      cnt_comp[num]--;
      if (cnt_comp[num] == 0) cur_count -= comp_sz[num];
    }
  };
  int ans = 0;
  for (int i = 0; i <= n - k; i++) {
    cur_count = 0;
    int cnt_bad = 0;
    for (int l = i; l < i + k; l++)
      for (int j = 0; j < k; j++) cnt_bad += (grid[l][j] == 'X');
    fill((cnt_comp).begin(), (cnt_comp).end(), 0);
    for (int l = i - 1; l <= i + k; l++) {
      int lb = -1, rb = k + 1;
      if (l == i - 1 || l == i + k) lb++, rb--;
      for (int j = lb; j < rb; j++) {
        account(l, j, +1);
      }
    }
    int cur = cnt_bad + cur_count;
    if (ans < cur) {
      ans = cur;
    }
    for (int j = 1; j <= n - k; j++) {
      int ub = i, db = i + k;
      for (int x = ub; x < db; x++) {
        account(x, j - 2, -1);
        account(x, j + k, +1);
        cnt_bad -= (grid[x][j - 1] == 'X');
        cnt_bad += (grid[x][j + k - 1] == 'X');
      }
      account(ub - 1, j - 1, -1);
      account(db, j - 1, -1);
      account(ub - 1, j + k - 1, +1);
      account(db, j + k - 1, +1);
      int cur = cnt_bad + cur_count;
      if (ans < cur) {
        ans = cur;
      }
    }
  }
  cout << ans << endl;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  long long n;
  while (cin >> n) solve(n);
}

