        if (cmp[x + j][y] != -1) inside[cmp[x + j][y]]++;
    for (int i = 0; i + k <= n; i++) {
      int add = 0;
      F++;
      for (int t = 0; t <= 1; t++) {
        for (int c = 0; c < k; c++) {
          int row[2] = {j + t * (k + 1) - 1, j + c};
