                cmp[row[g]][col[g]] != -1 && used[cmp[row[g]][col[g]]] != F) {
              add =+ all[cmp[row[g]][col[g]]] - inside[cmp[row[g]][col[g]]];
              used[cmp[row[g]][col[g]]] = F;
            }
        }
      }
      big = max(big, k * k + add);
      for (int t = 0; t < k; t++) {
        if (cmp[j + t][i] != -1) inside[cmp[j + t][i]]--;
        if (cmp[j + t][i + k] != -1) inside[cmp[j + t][i + k]]++;
      }
    }
  }
