#include <bits/stdc++.h>
using namespace std;
long long poww(long long a, long long b, long long md) {
  return (!b ? 1
             : (b & 1 ? a * poww(a * a % md, b / 2, md) % md
                      : poww(a * a % md, b / 2, md) % md));
}
const long long MAXN = 500 + 10;
const long long INF = 1e9;
const long long MOD = 1e9 + 7;
const pair<int, int> ROOT = {502, 502};
stack<pair<pair<int, int>, int>> st;
pair<int, int> par[MAXN][MAXN];
int t_s[MAXN][MAXN], t_e[MAXN][MAXN], val[MAXN][MAXN], min_x[MAXN][MAXN],
    max_x[MAXN][MAXN], min_y[MAXN][MAXN], max_y[MAXN][MAXN];
int k, n, H[MAXN][MAXN], S[MAXN][MAXN], ps[MAXN][MAXN], ans;
char G[MAXN][MAXN];
pair<int, int> Find(pair<int, int> v) {
  if (v == par[v.first][v.second]) return v;
  return Find(par[v.first][v.second]);
}
inline void Union(pair<int, int> v, pair<int, int> u, bool track = false) {
  v = Find(v);
  u = Find(u);
  if (u == v) return;
  if (H[u.first][u.second] < H[v.first][v.second]) swap(v, u);
  if (track) st.push({v, H[u.first][u.second]});
  if (H[u.first][u.second] == H[v.first][v.second]) H[u.first][u.second]++;
  par[v.first][v.second] = u;
  S[u.first][u.second] += S[v.first][v.second];
}
inline void Reset() {
  while (!st.empty()) {
    pair<int, int> v = st.top().first;
    pair<int, int> u = par[v.first][v.second];
    par[v.first][v.second] = v;
    S[u.first][u.second] -= S[v.first][v.second];
    H[u.first][u.second] = st.top().second;
    st.pop();
  }
}
inline int Sum(int x0, int y0, int x1, int y1) {
  return ps[x1][y1] - ps[x0 - 1][y1] - ps[x1][y0 - 1] + ps[x0 - 1][y0 - 1];
}
inline void BS() {
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      if (min_y[i][j] == INF || min_x[i][j] == INF) continue;
      int y0 = max(max_y[i][j] - k + 1, 1), y1 = min_y[i][j];
      for (int tk = min_x[i][j]; tk >= max(1, max_x[i][j] - k + 1); tk--) {
        t_s[tk][y0] += S[i][j];
        t_e[tk][y1] += S[i][j];
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    int t_val = 0;
    for (int j = 1; j <= n; j++) {
      t_val =+ t_s[i][j];
      val[i][j] = t_val;
      t_val -= t_e[i][j];
    }
  }
}
