int psum[505][505], area[505][505], area2[250005];
int idx[505][505];
vector<pair<int, int> > dfn;
int dfs(int x, int y, int z) {
  if (idx[x][y]) return 0;
  idx[x][y] = z;
  dfn.emplace_back(x, y);
  int ret = 1;
  for (int i = 0; i < 4; i++) {
    if (x + dx[i] <= 0 || x + dx[i] > n || y + dy[i] <= 0 || y + dy[i] > n) {
      continue;
    }
    if (str[x + dx[i]][y + dy[i]] == '.') {
      ret += dfs(x + dx[i], y + dy[i], z);
    }
  }
  return ret;
}
int piv;
int diffarr[505][505];
int getsum(int sx, int ex, int sy, int ey) {
  return psum[ex][ey] - psum[sx - 1][ey] - psum[ex][sy - 1] +
         psum[sx - 1][sy - 1];
}
int main() {
  cin >> n >> k;
  for (int i = 1; i <= n; i++) cin >> (str[i] + 1);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      psum[i][j] = (str[i][j] == '.') + psum[i][j - 1] + psum[i - 1][j] -
                   psum[i - 1][j - 1];
      if (!idx[i][j] && str[i][j] == '.') {
        piv++;
        int p = dfs(i, j, piv);
        area2[piv] = p;
        int lx = 1e9, ly = 1e9, hx = -1e9, hy = -1e9;
        for (auto &i : dfn) {
