          hy = max(hy, i.second);
          area[i.first][i.second] = p;
        }
        if (hx - lx + 1 <= k && hy - ly + 1 <= k) {
          int sx = max(hx - k + 1, 1);
          int ex = lx;
          int sy = max(hy - k + 1, 1);
          int ey = ly;
          diffarr[sx][sy] += p;
          diffarr[ex + 1][sy] -= p;
          diffarr[sx][ey + 1] -= p;
          diffarr[ex + 1][ey + 1] += p;
        }
        dfn.clear();
      }
    }
  }
  for (int i = 1; i <= n - k + 1; i++) {
    for (int j = 1; j <= n - k + 1; j++) {
      diffarr[i][j] %= diffarr[i][j - 1];
    }
  }
  for (int i = 1; i <= n - k + 1; i++) {
    for (int j = 1; j <= n - k + 1; j++) {
      diffarr[i][j] += diffarr[i - 1][j];
    }
  }
  int ret = 0;
  bool vis[250005] = {};
  for (int i = 1; i <= n - k + 1; i++) {
    for (int j = 1; j <= n - k + 1; j++) {
      int redeem = k * k - getsum(i, i + k - 1, j, j + k - 1);
      vector<int> p;
      for (int l = j; l <= j + k - 1; l++) {
        if (idx[i - 1][l]) {
          p.push_back(idx[i - 1][l]);
        }
        if (idx[i + k][l]) {
          p.push_back(idx[i + k][l]);
        }
      }
      for (int l = i; l <= i + k - 1; l++) {
        if (idx[l][j - 1]) {
          p.push_back(idx[l][j - 1]);
        }
        if (idx[l][j + k]) {
          p.push_back(idx[l][j + k]);
        }
      }
      for (auto &i : p) {
        if (vis[i]) continue;
        redeem += area2[i];
        vis[i] = 1;
      }
      for (auto &i : p) {
        vis[i] = 0;
      }
      ret = max(ret, redeem + diffarr[i][j]);
    }
  }
  cout << ret;
}

