    for (int j = 1; j < (m); ++j)
      if (j % 2 == 0)
        a[i][l++] = b[i][j];
      else
        a[i][r--] = b[i][j];
    if (i % 2 == 1) reverse(a[i].begin(), a[i].end());
  }
