using i64 = long long;
const int MAXN = 100010;
vector<int> a[MAXN];
vector<int> b[MAXN];
int p[15];
int c[15][15];
bool w[150][150];
void solve(int n, int m, bool f) {
  for (int i = 0; i < (n); ++i) {
    b[i] = vector<int>(m);
    for (int j = 0; j < (m); ++j)
      if (f)
        b[i][j] = j * n + i + 1;
      else
        b[i][j] = i * m + j + 1;
    if (m % 2 == 1 && i % 2 == 1) reverse(b[i].begin(), b[i].end());
  }
  for (int i = 0; i < (n); ++i) {
    int l = 0;
    int r = m - 1;
    a[i] = vector<int>(m);
    a[i][(m - 1) / 2] = b[i][0];
    for (int j = 1; j < (m); ++j)
      if (j % 2 == 0)
        a[i][l++] = b[i][j];
      else
        a[i][r--] = b[i][j];
    if (i % 2 == 1) reverse(a[i].begin(), a[i].end());
  }
}
void yes(int n, int m, bool f = false) {
  cout << "YES\n";
  for (int i = 0; i < (n); ++i)
    for (int j = 0; j < (m); ++j)
      cout << (f ? a[j][i] : a[i][j]) << " \n"[j + 1 == m];
  exit(0);
}
void no() {
  cout << "NO\n";
  exit(0);
}
int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(10);
  int n, m;
  cin >> n >> m;
  if (n == 1 && m == 1) {
    a[0] = vector<int>(1, 1);
    yes(n, m);
  }
  if (n <= 3 && m <= 3) {
    for (int i = 0; i < (n * m); ++i) p[i] = i + 1;
    for (int i = 0; i < (n); ++i)
      for (int j = 0; j < (m); ++j) c[i][j] = m * i + j + 1;
    for (int i = 0; i < (n); ++i)
      for (int j = 0; j < (m); ++j) {
        if (i > 0) w[c[i - 1][j]][c[i][j]] = w[c[i][j]][c[i - 1][j]] = true;
        if (j > 0) w[c[i][j - 1]][c[i][j]] = w[c[i][j]][c[i][j - 1]] = true;
      }
    do {
      for (int i = 0; i < (n); ++i)
        for (int j = 0; j < (m); ++j) c[i][j] = p[m * i + j];
      bool ok = true;
      for (int i = 0; i < (n); ++i) {
        for (int j = 0; j < (m); ++j) {
          if (i > 0 && (w[c[i - 1][j]][c[i][j]] || w[c[i][j]][c[i - 1][j]]))
            ok = false;
          if (j > 0 && (w[c[i][j - 1]][c[i][j]] || w[c[i][j]][c[i][j - 1]]))
            ok = false;
          if (!ok) break;
        }
        if (ok) break;
      }
      if (ok) {
        for (int i = 0; i < (n); ++i) {
          a[i] = vector<int>(m);
          for (int j = 0; j < (m); ++j) a[i][j] = c[i][j];
        }
        yes(n, m);
      }
    } while (next_permutation(p, p + n * m));
    no();
  }
  if (n <= m) {
    solve(n, m, false);
    yes(n, m, false);
  } else {
    solve(m, n, true);
    yes(n, m, true);
  }
  return 0;
}

