#include <bits/stdc++.h>
using namespace std;
bool flag = false;
int n, m;
int convert(int k) {
  if (!flag)
    return k;
  else {
    int row = (k - 1) / m;
    int col = k - m * row - 1;
    int rown = m - col - 1;
    int coln = row;
    return rown * n + coln + 1;
  }
}
