            ans[i][j] = m * 2 * ((n - 1) / 2) + 4 + 2 * j;
          else
            ans[i][j] = m * 2 * ((n - 1) / 2) + 1 + 2 * (j - m / 2 + 1);
        } else if ((i - 1) % 2 == 0)
          ans[i][j] = m * 2 * ((i - 1) / 2) + 1 + j * 2;
        else
          ans[i][j] = m * 2 * ((i - 1) / 2) + 4 + j * 2;
      } else {
        if (i % 2 == 0)
          ans[i][j] = m * 2 * (i / 2) + 1 + j * 2;
