  if (abs(a - b) == 1 && (a - 1) / y > (b - 1) / y) return true;
  if (abs(a - b) == y) return true;
  return false;
}
bool dfs(int cx, int cy) {
  if (cy == y + 1) {
    cy = 1;
    cx++;
  }
  if (cx == x + 1) {
    return true;
  }
  for (int i = 1; i <= x * y; i++) {
    if (!used[i] && !isadj(i, a[cx - 1][cy]) && !isadj(i, a[cx][cy - 1])) {
      used[i] = true;
