bool check(vector<vector<int> > A, vector<vector<int> > B) {
  set<pair<int, int> > g;
  for (int e = 0; e < A.size(); e++) {
    for (int f = 0; f < A[0].size(); f++) {
      for (int t = 0; t < 4; t++) {
        int ne = e + dx[t];
        int nf = f + dy[t];
        if (ne >= 0 && ne < A.size() && nf >= 0 && nf < A[0].size()) {
          g.insert({A[e][f], A[ne][nf]});
        }
      }
    }
  }
  for (int e = 0; e < A.size(); e++) {
    for (int f = 0; f < A[0].size(); f++) {
      for (int t = 0; t < 4; t++) {
        int ne = e + dx[t];
        int nf = f + dy[t];
        if (ne >= 0 && ne < A.size() && nf >= 0 && nf < A[0].size()) {
          if (g.count({B[e][f], B[ne][nf]})) return false;
        }
      }
    }
  }
  return true;
}
void brute(int n, int m) {
  vector<int> con;
  for (int e = 1; e <= n * m; e++) con.push_back(e);
  do {
    vector<vector<int> > table(n, vector<int>(m, 0));
    int cur = 1;
    for (int e = 0; e < n; e++)
      for (int f = 0; f < m; f++) table[e][f] = cur++;
    auto before = table;
    int ptr = 0;
    for (int e = 0; e < n; e++)
      for (int f = 0; f < m; f++) table[e][f] = con[ptr++];
    if (check(before, table)) {
      cout << "YES" << endl;
      for (int e = 0; e < n; e++)
        for (int f = 0; f < m; f++) {
          printf("%d%c", table[e][f], " \n"[f == m - 1]);
        }
      exit(0);
    }
  } while (next_permutation(con.begin(), con.end()));
}
