  if (tc > m) tr = r + 1, tc = 1;
  for (int i = 1; i <= n * m; ++i)
    if (!vis[i]) {
      if (tc != 1 && XL(u, i)) continue;
      if (tr > 1 && XL(a[tr - 1][tc], i)) continue;
      if (dfs(tr, tc, i)) {
        ans[r][c] = u;
        return true;
      }
    }
  a[r][c] = 0;
  vis[u] = false;
  return false;
}
