vector<int> small_transp_alt(int m) {
  vector<int> a(m, 0);
  auto nr = [&](int minus) {
    for (int j = 0; j < m - minus; j += 4) {
      int b = j;
      a[j + 0] = 2 + b;
      a[j + 1] = 0 + b;
      a[j + 2] = 3 + b;
      a[j + 3] = 1 + b;
    }
  };
  if (m % 4 == 0) {
    nr(0);
    return a;
  }
  if (m % 4 == 1) {
    nr(5);
    int b = m - 5;
    a[b + 0] = b + 2;
    a[b + 1] = b + 4;
    a[b + 2] = b + 0;
    a[b + 3] = b + 3;
    a[b + 4] = b + 1;
    return a;
  }
  if (m % 4 == 2) {
    nr(6);
    int b = m - 6;
    a[b + 0] = b + 2;
    a[b + 1] = b + 4;
    a[b + 2] = b + 0;
    a[b + 3] = b + 3;
    a[b + 4] = b + 1;
    a[b + 5] = b + 5;
    return a;
  }
  if (m % 4 == 3) {
    nr(7);
    int b = m - 7;
    a[b + 0] = b + 2;
    a[b + 1] = b + 0;
    a[b + 2] = b + 4;
    a[b + 3] = b + 1;
    a[b + 4] = b + 6;
    a[b + 5] = b + 3;
    a[b + 6] = b + 5;
    return a;
  }
  return {};
