    }
  } else {
    if (n == 4) {
      v1.push_back(1 + m);
      v1.push_back(1 + 3 * m);
      v1.push_back(1);
      v1.push_back(1 + 2 * m);
      v2 = v1;
      reverse(v2.begin(), v2.end());
