      for (int c = 1 + m; c <= n * m; c += 2 * m)
        v1.push_back(c), v2.push_back(c);
      for (int c = 1; c <= n * m; c += 2 * m) v2.push_back(c);
    }
    for (int j = 0; j < n; ++j) {
      for (int it = 0; it < m; ++it) {
        if (it & 1)
          ans.push_back(v2[j] + it);
        else
          ans.push_back(v1[j] + it);
      }
    }
  }
  finish(ans);
  return 0;
}

