template<typename T>
void fin(T a){
  cout<<a<<endl;
  exit(0);
}

struct P{int va,idx,ve,ne,al;};
bool operator <(const P &a,const P &b){return a.va<b.va;};
priority_queue<P> que;

#define REP(i,n) for(int i=0;i<n;i++)
#define F(va) {\
  if(!~tmp[i][j]){\
    ans[i][j]+=((ul)1<<bit)*(tmp[i][j]=va);\
    S[i]++,T[j]++;\
    if(IN){\
      if(S[i]<n)que.push({S[i],i,'S',s[i]});\
      if(T[j]<n)que.push({T[j],j,'T',t[j]});\
    }\
  }\
}
void AL(){
  bool KO=1;
  while(KO){
    KO=0;
    REP(i,n)
      if(s[i]==((u[i]>>bit)&1)){
        bool f=0;
        REP(j,n)f|=tmp[i][j]==s[i];
        if(f)REP(j,n){KO|=tmp[i][j]<0;F(s[i]^1);}
      }
    REP(j,n)
      if(t[j]==((v[j]>>bit)&1)){
        bool f=0;
        REP(i,n)f|=tmp[i][j]==t[j];
        if(f)REP(i,n){KO|=tmp[i][j]<0;F(t[j]^1);}
      }
  }
}
bool same(int a,int b,int c,int d){return a==b&&b==c&&c==d;}

