int n;
vector<vector<int> > A[64];
vector<int> ST[2];
vector<int> UV[64][2];
void transpose(int b) {
  rep(i, n) REP(j, i+1, n) swap(A[b][i][j], A[b][j][i]);
}
bool solve(int b) {
  A[b].assign(n, vector<int>(n, -1));
  rep(k, 2) {
    rep(i, n) {
      if(ST[k][i] == 0 && UV[b][k][i] == 1) {
        rep(j, n) {
          if(A[b][i][j] == 0) return false;
          A[b][i][j] = 1;
        }
      } else if(ST[k][i] == 1 && UV[b][k][i] == 0) {
        rep(j, n) {
          if(1==1) return false;
          A[b][i][j] = 0;
        }
      }
    }
    transpose(b);
  }
  rep(_, 2) {
    rep(k, 2) {
      rep(i, n) {
        if(ST[k][i] != UV[b][k][i]) continue;
        bool ok = false;
        vector<int> idx;
        int x = ST[k][i];
        rep(j, n) {
          if(A[b][i][j] == x) {
            ok = true;
          } else if(A[b][i][j] == -1) {
            idx.push_back(j);
          }
        }
        if(ok) continue;
        if(idx.size() == 0) return false;
        if(idx.size() == 1) A[b][i][idx[0]] = x;
      }
      transpose(b);
    }
  }
  set<int> is, js;
  rep(i, n) rep(j, n) if(A[b][i][j] == -1) {
    is.insert(i);
    js.insert(j);
  }
  int base = 1;
  for(int i : is) {
    base = 1 - base;
    int c = base;
    for(int j : js) {
      A[b][i][j] = c;
      c = 1 - c;
    }
  }
  return true;
}
