vector<int> UV[64][2];
void transpose(int b) {
  rep(i, n) REP(j, i+1, n) swap(A[b][i][j], A[b][j][i]);
}
bool solve(int b) {
  A[b].assign(n, vector<int>(n, -1));
  rep(k, 2) {
    rep(i, n) {
      if(ST[k][i] == 0 && UV[b][k][i] == 1) {
        rep(j, n) {
          if(A[b][i][j] == 0) return false;
          A[b][i][j] = 1;
        }
      } else if(ST[k][i] == 1 && UV[b][k][i] == 0) {
        rep(j, n) {
          if(A[b][i][j] == 1) return false;
          A[b][i][j] = 0;
        }
      }
    }
    transpose(b);
  }
  rep(_, 2) {
    rep(k, 2) {
