        if(ST[k][i] != UV[b][k][i]) continue;
        bool ok = false;
        vector<int> idx;
        int x = ST[k][i];
        rep(j, n) {
          if(A[b][i][j] == x) {
            ok = true;
          } else if(A[b][i][j] == -1) {
            idx.push_back(j);
          }
