    ull val = 0;
    if (!t[j]) {
      val = ans[0][j];
      rep(i,0,n) val &= ans[i][j];
      suc &= val == v[j];
    } else {
      rep(i,0,n) val |= ans[i][j];
      suc &= val == v[j];
    }
