void no() {
	cout << "-1\n"; exit(0);
}

void transp() {
	for(int i = 0; i < n; i++)
		for(int j = 0; j < i; j++) swap(mat[i][j], mat[j][i]);
	swap(s, t);
	swap(u, v);
}

void cumplands() {
	for(int i = 0; i < n; i++) {
		if(s[i]) continue;
		ll crv = ~(ll(0));
		for(int j = 0; j < n; j++) crv &= mat[i][j];
		if(crv != u[i]) no();
	}
}

const int bts = 64;
const ll un = 1;

bool isColGood(int w) {
	ll ret = ~(ll(0));
	for(int i = 0; i < n; i++)
		ret &= mat[i][w];
	return ret == v[w];
}

void otsolv() {
	vector<int> inds, tbl(bts), frq(bts);
	vector<ll> msks(n);
	for(int i = 0; i < n; i++)
		if(!t[i]) inds.push_back(i);
	for(int i = 0; i < n; i++) {
		if(!s[i]) continue;
		ll crv = 0;
		for(int j = 0; j < n; j++) crv |= mat[i][j];
		if((crv | u[i]) != u[i]) no();
		crv = u[i] ^ crv;
		msks[i] = crv;
		if(!crv) continue;
		if(inds.empty()) no();
		for(int j = 0; j < bts; j++)
			if(un << j & crv) frq[j]++;
	}

	for(int i = 0; i < n; i++) {
		if(!msks[i]) continue;
		for(int j = 0; j < bts; j++) {
			if((un << j & msks[i]) && frq[j] == 1) {
				int good = -1;
				for(auto w: inds) {
					mat[i][w] ^= un << j;
					if(isColGood(w)) {good = w; break;}
					mat[i][w] ^= un << j;
				}
				if(good == -1) no();
				msks[i] ^= un << j;
			}
		}
	}

	for(int i = 0; i < n; i++) {
		if(!msks[i]) continue;
		for(int k = 0; k < bts; k++) {
			if(un << k & msks[i]) {
				mat[i][inds[tbl[k]]] |= un << k;
				tbl[k] = (tbl[k] + 1) % inds.size();
			}
		}
	}
}

