            for (int j:AC[b]) tc[j] = 1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    u64 x = tr[i] || tc[j];
                    a[i][j] |= (b ^ x ^ 1) << k;
                }
            }

        } else {
            bool swaped = false;
            if (AC[0].size()+AC[1].size() > 0) {
                swaped = true;
                swap(AC[0], AR[0]);
                swap(AC[1], AR[1]);
                swap(EC[0], ER[0]);
                swap(EC[1], ER[1]);
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < i; j++) {
                        swap(a[i][j], a[j][i]);
                    }
                }
            }
            for (int b = 0; b < 2; b++) {
                exitif(AR[b].size() + ER[b].size() == n && ER[b].size() == 1 && EC[b^1].size() == n);
            }
            vector<bool> tr(n), tc(n);
            for (int i:AR[1]) {
                tr[i] = 1;
                for (int j = 0; j < n; j++) {
                    a[i][j] |= (u64(1))<<k;
                }
            }
            for (int i:AR[0]) tr[i]=1;
            for (int j:EC[1]) {
                for (int i = 0; i < n; i++) if(!tr[i]){
                    a[i][j] |= (u64(1))<<k;
                }
            }
            for (u64 b = 0; b < 2; b++) {
                for (int i:ER[b]) if (EC[b].empty()) {
                    a[i][i] ^= (u64(1))<<k;
                }
            }
            if (swaped) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < i; j++) {
                        swap(a[i][j], a[j][i]);
                    }
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = (0+1); j < n; j++) {
            cout << a[i][j] << ' ';
        }cout << '\n';
    }
}

