	int q = qm[sus[y]][tvs[x]];
	if (q == NG) { puts("-1"); return 0; }
	setbit(y, x, (q == ND) ? 0 : q);
      }

    for (int y = 0; y < n; y++)
      if (sus[y] == OR1 && hbs[y][1] == 0) {
	bool ok = false;
	for (int x = 0; ! ok && x < n; x++)
	  if (tvs[x] == AND0 && vbs[x][0] > 1) {
	    setbit(y, x, 1);
	    hbs[y][0]--, vbs[x][0]--;
	    ok = true;
	  }
	if (! ok) { puts("-1"); return 0; }
      }

    for (int x = 0; x < n; x++)
      if (tvs[x] == OR1 && vbs[x][1] == 0) {
	bool ok = false;
	for (int y = 0; ! ok && y < n; y++)
	  if (sus[y] == AND0 && hbs[y][0] > 1) {
	    setbit(y, x, 1);
	    hbs[y][0]--, vbs[x][0]--;
	    ok = true;
	  }
	if (! ok) { puts("-1"); return 0; }
      }

    for (int i = 0; i < n; i++)
      if ((sus[i] == AND0 && hbs[i][0] == 0) ||
	  (sus[i] == AND1 && hbs[i][0] > 0) ||
	  (sus[i] == OR0 && hbs[i][1] > 0) ||
	  (sus[i] == OR1 && hbs[i][1] == 0) ||
	  (tvs[i] == AND0 && vbs[i][0] == 0) ||
	  (tvs[i] == AND1 && vbs[i][0] > 0) ||
	  (tvs[i] == OR0 && vbs[i][1] > 0) ||
	  (tvs[i] == OR1 && vbs[i][1] == 0)) {
	puts("-1");
	return 0;
      }

    ull bk = 1ULL << k;
    for (int y = 0; y < n; y++)
      for (int x = 0; x < n; x++)
	if (fbs[y][x]) fs[y][x] |= bk;
  }

  for (int y = 0; y < n; y++) {
    for (int x = 0; x < n; x++) {
      if (x) putchar(' ');
      printf("%llu", fs[y][x]);
    }
    putchar('\n');
  }
  return 0;
}

