void transpose(ll x)
{
	for(ll i=0;i<n;i++)
	{
		swap(s[i],t[i]);
		swap(u[x][i],v[x][i]);
		for(ll j=0;j<i;j++)
		{
			swap(a[x][i][j],a[x][j][i]);
		}
	}
}
void fill(ll x)
{
	for(ll i=0;i<n;i++)
	{
		for(ll j=0;j<n;j++)
		{
			if((s[i]^u[x][i])==1)
				a[x][i][j]=u[x][i];
			if((t[j]^v[x][j])==1)
				a[x][i][j]=v[x][j];
			if(u[x][i]==v[x][j])
				a[x][i][j]=u[x][i];
		}
	}
	fill_row(x);
	transpose(x);
	fill_row(x);
	transpose(x);
}
