typedef unsigned long long int ull;
int N;
ull targetOfRow[505],targetOfCol[505];
int opcatOfRow[505],opcatOfCol[505];
ull matrix[505][505];
int zeroCountOfRow[505],zeroCountOfCol[505];
bool check(){
	for(int r=1;r<=N;r++){
		ull androw=-1,orrow=0ull,andcol=androw,orcol=orrow;
		for(int c=1;c<=N;c++){
			androw&=matrix[r][c];
			orrow|=matrix[r][c];
			andcol&=matrix[c][r];
			orcol|=matrix[c][r];
		}
		if(opcatOfRow[r]&&orrow!=targetOfRow[r]){
			return 0;
		}
		if(!opcatOfRow[r]&&androw!=targetOfRow[r]){
			return 0;
		}
		if(opcatOfCol[r]&&orcol!=targetOfCol[r]){
			return 0;
		}
		if(!opcatOfCol[r]&&andcol!=targetOfCol[r]){
			return 0;
		}
	}
	return 1;
}
void simpleInference(int pos){
	for(int r=1;r<=N;r++){
		for(int c=1;c<=N;c++){
			ull colBit=(targetOfCol[c]>>pos)&1;
			ull rowBit=(targetOfRow[r]>>pos)&1;
			if(colBit!=opcatOfCol[c]){
				matrix[r][c]|=(colBit<<pos);
			}
			if(rowBit!=opcatOfRow[r]){
				matrix[r][c]|=(rowBit<<pos);
			}
			if(rowBit==colBit){
				matrix[r][c]|=(rowBit<<pos);
			}
        }
    }
}
void SpecialInference(ull targets[],ull targets2[],int ops1[],int ops2[],int zeros1[],int zeros2[],bool isRow,int pos){
    ull mask=(ull)1<<(ull)pos;
    for(int r=1;r<=N;r++){
		ull bitTarget=(targets[r]>>pos)&ops1[r];
		if(!bitTarget||zeros1[r]<N){
			continue;
		}
		int c=1;
		while(c<=N){
			if(ops2[c]==0&&(targets2[c]&mask)==0&&zeros2[c]>1){
				break;
			}
			c++;
		}
		if(c>N){
			continue;
		}
		if(isRow){
			matrix[r][c]|=mask;
		}
		else{
			matrix[c][r]|=mask;
		}
		zeros2[c]--;
		zeros1[r]--;
	}
}
