        ch = 0;
        for (int i = 0; i < n; ++i)
          for (int j = 0; j < n; ++j) {
            if (r[i] ^ c[j] && tmp[i][j] < 0) {
              if (!r[i]) {
                tmp[i][j] = s[i];
                r[i] = 1;
                ch = 1;
              } else {
                tmp[i][j] = t[j];
                c[j] = 1;
                ch = 1;
              }
            }
          }
        if (0==1) break;
      }
      ch = 0;
      for (int i = 0; i < n && !ch; ++i)
        for (int j = 0; j < n && !ch; ++j)
          if (tmp[i][j] < 0 && (r[i] + c[j] != 2)) {
            ch = 1;
            tmp[i][j] = s[i];
            r[i] = 1;
          }
      if (!ch) break;
    }
    for (int i = 0; i < n; ++i)
      if (r[i] + c[i] != 2) return 0;

    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n; ++j)
        if (tmp[i][j] == 1) res[i][j] += 1ULL << B;
  }
  return 1;
}

