	vector<int> R,C;
	int s0=0,s1=0,t0=0,t1=0;
	rep(i,n){
		if(s[i]==AND && u[i]==1){
			rep(j,n) res[i][j]=1;
			s1++;
		}
		else if(s[i]==OR && u[i]==0){
			rep(j,n) res[i][j]=0;
			s0++;
		}
		else R.emplace_back(i);
	}
	rep(j,n){
		if(t[j]==AND && v[j]==1){
			rep(i,n) res[i][j]=1;
			t1++;
		}
		else if(t[j]==OR && v[j]==0){
			rep(i,n) res[i][j]=0;
			t0++;
		}
		else C.emplace_back(j);
	}

	if(R.size()==1){
		int x=u[R[0]];
		rep(j,C.size()){
			if((v[C[j]]==0 && s0>0) || (v[C[j]]==1 && s1>0)) res[R[0]][C[j]]=x;
			else                                             res[R[0]][C[j]]=v[C[j]];
		}
	}
	else if(C.size()==1){
		int x=v[C[0]];
		rep(i,R.size()){
			if((u[R[i]]==0 && t0>0) || (u[R[i]]==1 && t1>0)) res[R[i]][C[0]]=x;
			else                                             res[R[i]][C[0]]=u[R[i]];
		}
	}
	else if(R.size()>=2 && C.size()>=2){
		rep(i,R.size()) rep(j,C.size()) res[R[i]][C[j]]=(i+j)%2;
	}


	rep(i,n){
		int z;
		if(s[i]==AND){
			z=1;
			rep(j,n) z&=res[i][j];
		}
		else{
			z=0;
			rep(j,n) z|=res[i][j];
		}
		if(z!=u[i]) return {false,{}};
	}
	rep(j,n){
		int z;
		if(t[j]==AND){
			z=1;
			rep(i,n) z&=res[i][j];
		}
		else{
			z=0;
			rep(i,n) z|=res[i][j];
		}
		if(z!=v[j]) return {false,{}};
	}
	return {true,res};
}

